window.LSP_DATA = {"title":"Listen Up! Speak Out!","grades":[{"grade":3,"units":[{"n":1,"title":"Hello, Friends!","ar":"مرحبًا يا أصدقاء!","emoji":"👋","goals":["I can say hello and introduce myself.","I can understand names, spelling and numbers to 20.","I can follow simple classroom instructions."],"listen":[{"kind":"listen","n":1,"title":"Nice to Meet You","skill":"Listening for names and spelling","skill_ar":"الاستماع إلى الأسماء وتهجئتها","kagan":["RallyRobin","Think-Pair-Share"],"vocab":[{"w":"name","ar":"اسم","emoji":"🏷️","ex":"What's your name?","audio":"g3/u1/l1/v1.mp3"},{"w":"spell","ar":"يتهجّى","emoji":"🔤","ex":"How do you spell that?","audio":"g3/u1/l1/v2.mp3"},{"w":"friend","ar":"صديق","emoji":"🤝","ex":"Adam is my friend.","audio":"g3/u1/l1/v3.mp3"},{"w":"class","ar":"فصل دراسي","emoji":"🏫","ex":"I'm in class 3A.","audio":"g3/u1/l1/v4.mp3"},{"w":"teacher","ar":"معلّم / معلّمة","emoji":"🧑‍🏫","ex":"My teacher is Mr. Hassan.","audio":"g3/u1/l1/v5.mp3"},{"w":"bell","ar":"جرس","emoji":"🔔","ex":"The bell rings at seven.","audio":"g3/u1/l1/v6.mp3"}],"script":[{"sp":"NARRATOR","name":"Narrator","text":"It is the first day of school. Sami meets a new boy in the playground.","audio":"g3/u1/l1/01.mp3"},{"sp":"SAMI","name":"Sami","text":"Hello! I'm Sami. What's your name?","audio":"g3/u1/l1/02.mp3"},{"sp":"BEN","name":"Ben","text":"Hi, Sami. My name is Ben.","audio":"g3/u1/l1/03.mp3"},{"sp":"SAMI","name":"Sami","text":"Ben? How do you spell that?","audio":"g3/u1/l1/04.mp3"},{"sp":"BEN","name":"Ben","text":"B-E-N. Ben.","audio":"g3/u1/l1/05.mp3"},{"sp":"SAMI","name":"Sami","text":"Nice to meet you, Ben. Are you in class 3A?","audio":"g3/u1/l1/06.mp3"},{"sp":"BEN","name":"Ben","text":"No, I'm in class 3B. My teacher is Ms. Green.","audio":"g3/u1/l1/07.mp3"},{"sp":"SAMI","name":"Sami","text":"Oh! My sister Noor knows Ms. Green. Look, that's my friend Adam.","audio":"g3/u1/l1/08.mp3"},{"sp":"ADAM","name":"Adam","text":"Hi! I'm Adam. A-D-A-M.","audio":"g3/u1/l1/09.mp3"},{"sp":"BEN","name":"Ben","text":"Nice to meet you, Adam.","audio":"g3/u1/l1/10.mp3"},{"sp":"NARRATOR","name":"Narrator","text":"The bell rings. The boys go to class.","audio":"g3/u1/l1/11.mp3"}],"tasks":[{"type":"mcq","q":"What is the new boy's name?","opts":["Ben","Sami","Dan","Adam"],"ans":0},{"type":"mcq","q":"How does Ben spell his name?","opts":["B-E-A-N","B-E-N","P-E-N","B-A-N"],"ans":1},{"type":"mcq","q":"Which class is Ben in?","opts":["3A","4B","3C","3B"],"ans":3},{"type":"mcq","q":"Who is Ms. Green?","opts":["Sami's sister","Adam's mother","Ben's teacher","Sami's teacher"],"ans":2},{"type":"tf","s":"Sami and Ben meet in the playground.","ans":true},{"type":"tf","s":"Noor is Sami's sister.","ans":true},{"type":"tf","s":"The boys go home after the bell.","ans":false},{"type":"order","items":["Sami says hello to Ben.","Ben spells his name.","Adam says hi.","The boys go to class."]}],"predict":{"en":"Two boys meet on the first day of school. What do they say first?","ar":"ولدان يلتقيان في أول يوم دراسي. ماذا يقولان أولًا؟"},"tip":{"en":"Names are often spelled letter by letter. Write each letter you hear.","ar":"تُهجّأ الأسماء غالبًا حرفًا حرفًا. اكتب كل حرف تسمعه."},"speak":{"prompt":"Say hello to your partner. Say your name and spell it.","frame":"Hello! I'm ___. That's ___, ___, ___."},"teach":"Before listening, spell your own name aloud and let the class write the letters in the air. After the tasks, replay lines 5 and 9 so students write the letters on mini-whiteboards.","id":"g3u1l1","track":"g3/u1/l1/track.mp3"},{"kind":"listen","n":2,"title":"How Old Are You?","skill":"Listening for numbers 1 to 20","skill_ar":"الاستماع إلى الأعداد من 1 إلى 20","kagan":["Numbered Heads Together","RallyRobin"],"vocab":[{"w":"farm","ar":"مزرعة","emoji":"🚜","ex":"Grandpa has a farm.","audio":"g3/u1/l2/v1.mp3"},{"w":"sheep","ar":"خروف / خراف","emoji":"🐑","ex":"There are twelve sheep.","audio":"g3/u1/l2/v2.mp3"},{"w":"chicken","ar":"دجاجة","emoji":"🐔","ex":"The chicken is brown.","audio":"g3/u1/l2/v3.mp3"},{"w":"goat","ar":"ماعز","emoji":"🐐","ex":"The baby goat is small.","audio":"g3/u1/l2/v4.mp3"},{"w":"count","ar":"يعدّ","emoji":"🔢","ex":"Let's count the animals.","audio":"g3/u1/l2/v5.mp3"},{"w":"How old...?","ar":"كم عمر...؟","emoji":"🎂","ex":"How old are you?","audio":"g3/u1/l2/v6.mp3"}],"script":[{"sp":"NARRATOR","name":"Narrator","text":"Sami and Noor visit Grandpa's farm in Taif.","audio":"g3/u1/l2/01.mp3"},{"sp":"GRANDPA","name":"Grandpa","text":"Welcome, children! Sami, how old are you now?","audio":"g3/u1/l2/02.mp3"},{"sp":"SAMI","name":"Sami","text":"I'm nine, Grandpa.","audio":"g3/u1/l2/03.mp3"},{"sp":"GRANDPA","name":"Grandpa","text":"Nine! You're so tall. And Noor, how old are you?","audio":"g3/u1/l2/04.mp3"},{"sp":"NOOR","name":"Noor","text":"I'm seven. My birthday is next month.","audio":"g3/u1/l2/05.mp3"},{"sp":"GRANDPA","name":"Grandpa","text":"Let's count the animals. How many sheep can you see?","audio":"g3/u1/l2/06.mp3"},{"sp":"SAMI","name":"Sami","text":"One, two, three, four... There are twelve sheep!","audio":"g3/u1/l2/07.mp3"},{"sp":"GRANDPA","name":"Grandpa","text":"Good. And how many chickens?","audio":"g3/u1/l2/08.mp3"},{"sp":"NOOR","name":"Noor","text":"I can see fifteen chickens. Ten are brown and five are white.","audio":"g3/u1/l2/09.mp3"},{"sp":"GRANDPA","name":"Grandpa","text":"Very good! Now, how many baby goats are there?","audio":"g3/u1/l2/10.mp3"},{"sp":"SAMI","name":"Sami","text":"There are three baby goats. They're so small!","audio":"g3/u1/l2/11.mp3"},{"sp":"GRANDPA","name":"Grandpa","text":"Come inside now. Grandma has fresh bread for you.","audio":"g3/u1/l2/12.mp3"}],"tasks":[{"type":"mcq","q":"How old is Sami?","opts":["three","nine","seven","twelve"],"ans":1},{"type":"mcq","q":"How many sheep are there?","opts":["fifteen","twelve","ten","twenty"],"ans":1},{"type":"mcq","q":"How many chickens are white?","opts":["fifteen","three","ten","five"],"ans":3},{"type":"mcq","q":"Where is Grandpa's farm?","opts":["in Taif","in London","in Riyadh","in Jeddah"],"ans":0},{"type":"tf","s":"Noor is seven years old.","ans":true},{"type":"tf","s":"There are three baby goats.","ans":true},{"type":"tf","s":"Grandma has cake for the children.","ans":false},{"type":"order","items":["Grandpa says welcome.","Sami counts the sheep.","Noor counts the chickens.","Grandpa asks them to come inside."]}],"predict":{"en":"Sami and Noor visit Grandpa's farm. What animals can they see? How many?","ar":"يزور سامي ونور مزرعة الجد. ما الحيوانات التي يرونها؟ وكم عددها؟"},"tip":{"en":"Listen carefully to the end of numbers: thir-TEEN, four-TEEN, fif-TEEN.","ar":"استمع جيدًا لنهاية الأعداد مثل: thirteen وfourteen وfifteen."},"speak":{"prompt":"Ask your partner: How old are you? How many people are in your family?","frame":"I'm ___ years old. There are ___ people in my family."},"teach":"Numbers 11 to 20 are tricky. Before listening, play Number Clap: say a number up to 10 and students clap that many times; then write the teens on the board and drill the strong ending -TEEN.","id":"g3u1l2","track":"g3/u1/l2/track.mp3"},{"kind":"listen","n":3,"title":"My New Class","skill":"Following classroom instructions","skill_ar":"اتباع التعليمات الصفية","kagan":["Stand Up–Hand Up–Pair Up","RallyCoach"],"vocab":[{"w":"sit down","ar":"يجلس","emoji":"🪑","ex":"Please sit down.","audio":"g3/u1/l3/v1.mp3"},{"w":"stand up","ar":"يقف","emoji":"🧍","ex":"Stand up, please.","audio":"g3/u1/l3/v2.mp3"},{"w":"open","ar":"يفتح","emoji":"📖","ex":"Open your book.","audio":"g3/u1/l3/v3.mp3"},{"w":"close","ar":"يغلق","emoji":"📕","ex":"Close your book.","audio":"g3/u1/l3/v4.mp3"},{"w":"point to","ar":"يشير إلى","emoji":"👉","ex":"Point to the door.","audio":"g3/u1/l3/v5.mp3"},{"w":"page","ar":"صفحة","emoji":"📄","ex":"Look at page six.","audio":"g3/u1/l3/v6.mp3"}],"script":[{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"Good morning, boys. Welcome to class 3A. I'm Mr. Hassan.","audio":"g3/u1/l3/01.mp3"},{"sp":"SAMI","name":"Sami","text":"Good morning, Mr. Hassan!","audio":"g3/u1/l3/02.mp3"},{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"Please sit down. Now, open your bags and take out your English book.","audio":"g3/u1/l3/03.mp3"},{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"Open your book to page six. Page six. Look at the picture.","audio":"g3/u1/l3/04.mp3"},{"sp":"ADAM","name":"Adam","text":"Sorry, Mr. Hassan. I don't have my book.","audio":"g3/u1/l3/05.mp3"},{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"That's okay, Adam. Look with Sami today.","audio":"g3/u1/l3/06.mp3"},{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"Now, listen and point. Point to the door. Good. Point to the window. Great!","audio":"g3/u1/l3/07.mp3"},{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"Stand up, please. Turn around. Now sit down and close your book.","audio":"g3/u1/l3/08.mp3"},{"sp":"SAMI","name":"Sami","text":"Is it time for a game?","audio":"g3/u1/l3/09.mp3"},{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"Yes! Put up your hand if you are ready.","audio":"g3/u1/l3/10.mp3"}],"tasks":[{"type":"mcq","q":"What is the teacher's name?","opts":["Mr. Adam","Mr. Sami","Mr. Hassan","Ms. Green"],"ans":2},{"type":"mcq","q":"Which page do the boys open?","opts":["page six","page two","page seven","page sixteen"],"ans":0},{"type":"mcq","q":"What does Adam not have?","opts":["his pencil","his bag","his English book","his chair"],"ans":2},{"type":"mcq","q":"What do the boys point to first?","opts":["the picture","the board","the window","the door"],"ans":3},{"type":"tf","s":"Adam looks at Sami's book.","ans":true},{"type":"tf","s":"The boys stand up and turn around.","ans":true},{"type":"tf","s":"At the end, the boys open their books.","ans":false},{"type":"order","items":["The boys sit down.","They open their books to page six.","They point to the door and the window.","They stand up and turn around."]}],"predict":{"en":"It is the first lesson with a new teacher. What does the teacher ask the boys to do?","ar":"إنه الدرس الأول مع معلم جديد. ماذا يطلب المعلم من الأولاد أن يفعلوا؟"},"tip":{"en":"Listen for the action words at the start: sit, open, point, stand. Do the action in your head.","ar":"استمع إلى أفعال الأوامر في بداية الجملة مثل: sit وopen وpoint وstand، وتخيّل أنك تنفذها."},"speak":{"prompt":"Give your partner three instructions. Your partner does them.","frame":"Please ___. Open your ___. Point to the ___."},"teach":"After the tasks, play \"Mr. Hassan Says\": students move only when the instruction starts with \"please\". This turns listening into total physical response and checks understanding without speaking pressure.","id":"g3u1l3","track":"g3/u1/l3/track.mp3"}],"speak":[{"kind":"speak","n":1,"title":"Hello and Goodbye","func":"Greeting people and introducing yourself","func_ar":"إلقاء التحية والتعريف بالنفس","kagan":["Inside-Outside Circle","RallyRobin"],"model":[{"sp":"SAMI","name":"Sami","text":"Hello! Good morning!","audio":"g3/u1/s1/01.mp3"},{"sp":"BEN","name":"Ben","text":"Good morning! I'm Ben. What's your name?","audio":"g3/u1/s1/02.mp3"},{"sp":"SAMI","name":"Sami","text":"My name is Sami. How are you, Ben?","audio":"g3/u1/s1/03.mp3"},{"sp":"BEN","name":"Ben","text":"I'm fine, thank you. And you?","audio":"g3/u1/s1/04.mp3"},{"sp":"SAMI","name":"Sami","text":"I'm great, thanks! Nice to meet you.","audio":"g3/u1/s1/05.mp3"},{"sp":"BEN","name":"Ben","text":"Nice to meet you too.","audio":"g3/u1/s1/06.mp3"},{"sp":"SAMI","name":"Sami","text":"Oh, the bell! Goodbye, Ben!","audio":"g3/u1/s1/07.mp3"},{"sp":"BEN","name":"Ben","text":"Bye, Sami! See you tomorrow!","audio":"g3/u1/s1/08.mp3"}],"roles":["SAMI","BEN"],"chunks":[{"en":"Good morning!","ar":"صباح الخير!","audio":"g3/u1/s1/c1.mp3"},{"en":"How are you?","ar":"كيف حالك؟","audio":"g3/u1/s1/c2.mp3"},{"en":"I'm fine, thank you.","ar":"أنا بخير، شكرًا لك.","audio":"g3/u1/s1/c3.mp3"},{"en":"Nice to meet you.","ar":"تشرفت بمعرفتك.","audio":"g3/u1/s1/c4.mp3"},{"en":"See you tomorrow!","ar":"أراك غدًا!","audio":"g3/u1/s1/c5.mp3"}],"sound":{"type":"pairs","title":"/p/ or /b/?","en":"Arabic has no /p/ sound. For /p/, close your lips and push out a puff of air with no voice. For /b/, close your lips and use your voice.","ar":"لا يوجد صوت /p/ في العربية. لنطق /p/ أغلق شفتيك ثم أخرج دفعة هواء قوية بدون صوت، أما /b/ فننطقه مع اهتزاز الصوت.","pairs":[["pen","Ben"],["pat","bat"],["pie","buy"],["park","bark"],["pin","bin"]],"audio":[["g3/u1/s1/p1a.mp3","g3/u1/s1/p1b.mp3"],["g3/u1/s1/p2a.mp3","g3/u1/s1/p2b.mp3"],["g3/u1/s1/p3a.mp3","g3/u1/s1/p3b.mp3"],["g3/u1/s1/p4a.mp3","g3/u1/s1/p4b.mp3"],["g3/u1/s1/p5a.mp3","g3/u1/s1/p5b.mp3"]]},"task":{"prompt":"Meet three classmates. Say hello, say your name and ask how they are.","frame":"Hello! I'm ___. How are you? — I'm ___, thanks. Nice to meet you!"},"cando":["I can say hello and goodbye.","I can say my name and ask a name.","I can say the /p/ sound clearly."],"teach":"Hold a tissue in front of your mouth: it moves for /p/ but not for /b/. Let pairs test each other with the tissue before the Sound Check.","id":"g3u1s1","track":"g3/u1/s1/track.mp3"},{"kind":"speak","n":2,"title":"This Is My Friend","func":"Introducing other people","func_ar":"تقديم الآخرين والتعريف بهم","kagan":["Three-Step Interview","Mix-Pair-Share"],"model":[{"sp":"SAMI","name":"Sami","text":"Dad, this is my new friend. His name is Ben.","audio":"g3/u1/s2/01.mp3"},{"sp":"DAD","name":"Dad","text":"Hello, Ben. Nice to meet you. How old are you?","audio":"g3/u1/s2/02.mp3"},{"sp":"BEN","name":"Ben","text":"I'm nine. I'm in class 3B.","audio":"g3/u1/s2/03.mp3"},{"sp":"DAD","name":"Dad","text":"Are you from Taif?","audio":"g3/u1/s2/04.mp3"},{"sp":"BEN","name":"Ben","text":"No, I'm not. I'm from London.","audio":"g3/u1/s2/05.mp3"},{"sp":"DAD","name":"Dad","text":"Do you like Taif?","audio":"g3/u1/s2/06.mp3"},{"sp":"BEN","name":"Ben","text":"Yes, I do! It's beautiful.","audio":"g3/u1/s2/07.mp3"},{"sp":"SAMI","name":"Sami","text":"Ben, this is my sister. Her name is Noor.","audio":"g3/u1/s2/08.mp3"},{"sp":"NOOR","name":"Noor","text":"Hi, Ben! Welcome to our house!","audio":"g3/u1/s2/09.mp3"},{"sp":"BEN","name":"Ben","text":"Thank you, Noor. Nice to meet you.","audio":"g3/u1/s2/10.mp3"}],"roles":["SAMI","BEN"],"chunks":[{"en":"This is my friend, ___.","ar":"هذا صديقي ___.","audio":"g3/u1/s2/c1.mp3"},{"en":"His name is ___.","ar":"اسمه ___.","audio":"g3/u1/s2/c2.mp3"},{"en":"Her name is ___.","ar":"اسمها ___.","audio":"g3/u1/s2/c3.mp3"},{"en":"Where are you from?","ar":"من أين أنت؟","audio":"g3/u1/s2/c4.mp3"},{"en":"I'm from ___.","ar":"أنا من ___.","audio":"g3/u1/s2/c5.mp3"}],"sound":{"type":"pairs","title":"He's or she's?","en":"\"He's\" starts with a soft /h/ — just breathe out. \"She's\" starts with /ʃ/ — like the Arabic ش. Listen and choose.","ar":"تبدأ He's بصوت /h/ الخفيف مثل خروج النفس، وتبدأ She's بصوت /ʃ/ مثل حرف الشين. استمع واختر.","pairs":[["He's nine.","She's nine."],["He's my friend.","She's my friend."],["He's from Taif.","She's from Taif."],["He's tall.","She's tall."],["He's here.","She's here."]],"audio":[["g3/u1/s2/p1a.mp3","g3/u1/s2/p1b.mp3"],["g3/u1/s2/p2a.mp3","g3/u1/s2/p2b.mp3"],["g3/u1/s2/p3a.mp3","g3/u1/s2/p3b.mp3"],["g3/u1/s2/p4a.mp3","g3/u1/s2/p4b.mp3"],["g3/u1/s2/p5a.mp3","g3/u1/s2/p5b.mp3"]]},"task":{"prompt":"Introduce your partner to your group. Say his name, his age and one more thing.","frame":"This is ___. He's ___ years old. He's from ___. He likes ___."},"cando":["I can introduce a friend.","I can use his and her.","I can hear \"he's\" and \"she's\"."],"teach":"Before the role-play, model the gesture of an open palm towards the person you introduce. Introductions feel natural when students look at both people.","id":"g3u1s2","track":"g3/u1/s2/track.mp3"}],"check":[{"type":"mcq","q":"Who knows Ms. Green?","ref":"L1#8","opts":["Adam","Mr. Hassan","Noor","Ben"],"ans":2,"audio":"g3/u1/l1/08.mp3","line":"Oh! My sister Noor knows Ms. Green. Look, that's my friend Adam.","speaker":"Sami"},{"type":"mcq","q":"What does Grandpa say about Sami?","ref":"L2#4","opts":["He's seven.","He's small.","He's tall.","He's hungry."],"ans":2,"audio":"g3/u1/l2/04.mp3","line":"Nine! You're so tall. And Noor, how old are you?","speaker":"Grandpa"},{"type":"mcq","q":"When is Noor's birthday?","ref":"L2#5","opts":["next month","today","next week","tomorrow"],"ans":0,"audio":"g3/u1/l2/05.mp3","line":"I'm seven. My birthday is next month.","speaker":"Noor"},{"type":"mcq","q":"What must the boys do if they are ready?","ref":"L3#10","opts":["stand up","open the door","close their books","put up their hands"],"ans":3,"audio":"g3/u1/l3/10.mp3","line":"Yes! Put up your hand if you are ready.","speaker":"Mr. Hassan"}],"id":"g3u1"},{"n":2,"title":"My Family and Home","ar":"عائلتي وبيتي","emoji":"🏠","goals":["I can talk about my family.","I can say where things are.","I can understand people describing rooms."],"listen":[{"kind":"listen","n":1,"title":"This Is My Family","skill":"Listening for key words","skill_ar":"الاستماع إلى الكلمات المفتاحية","kagan":["Timed Pair Share","Talking Chips"],"vocab":[{"w":"family","ar":"عائلة","emoji":"👨‍👩‍👧‍👦","ex":"I have a big family.","audio":"g3/u2/l1/v1.mp3"},{"w":"photo","ar":"صورة","emoji":"📷","ex":"Look at this photo.","audio":"g3/u2/l1/v2.mp3"},{"w":"dad","ar":"أب","emoji":"👨","ex":"My dad is a doctor.","audio":"g3/u2/l1/v3.mp3"},{"w":"mom","ar":"أم","emoji":"👩","ex":"My mom is a teacher.","audio":"g3/u2/l1/v4.mp3"},{"w":"brother","ar":"أخ","emoji":"👦","ex":"My baby brother is one.","audio":"g3/u2/l1/v5.mp3"},{"w":"sister","ar":"أخت","emoji":"👧","ex":"My sister has a cat.","audio":"g3/u2/l1/v6.mp3"}],"script":[{"sp":"SAMI","name":"Sami","text":"Look, Ben. This is a photo of my family.","audio":"g3/u2/l1/01.mp3"},{"sp":"BEN","name":"Ben","text":"Wow, it's a big family! Who is this man?","audio":"g3/u2/l1/02.mp3"},{"sp":"SAMI","name":"Sami","text":"That's my dad. He's a doctor.","audio":"g3/u2/l1/03.mp3"},{"sp":"BEN","name":"Ben","text":"And who is the woman next to him?","audio":"g3/u2/l1/04.mp3"},{"sp":"SAMI","name":"Sami","text":"That's my mom. She's a teacher.","audio":"g3/u2/l1/05.mp3"},{"sp":"BEN","name":"Ben","text":"Who is the old man with the white hair?","audio":"g3/u2/l1/06.mp3"},{"sp":"SAMI","name":"Sami","text":"That's my grandpa. He has a farm.","audio":"g3/u2/l1/07.mp3"},{"sp":"BEN","name":"Ben","text":"Is this baby your brother?","audio":"g3/u2/l1/08.mp3"},{"sp":"SAMI","name":"Sami","text":"Yes! That's my baby brother, Fahd. He's one year old.","audio":"g3/u2/l1/09.mp3"},{"sp":"BEN","name":"Ben","text":"And the girl with the cat?","audio":"g3/u2/l1/10.mp3"},{"sp":"SAMI","name":"Sami","text":"That's my sister, Noor. It's Noor's cat. Its name is Snow.","audio":"g3/u2/l1/11.mp3"},{"sp":"BEN","name":"Ben","text":"I have one sister. I don't have a brother.","audio":"g3/u2/l1/12.mp3"}],"tasks":[{"type":"mcq","q":"Who is the doctor?","opts":["Ben's dad","Sami's grandpa","Sami's mom","Sami's dad"],"ans":3},{"type":"mcq","q":"What is Sami's mom's job?","opts":["farmer","teacher","driver","doctor"],"ans":1},{"type":"mcq","q":"How old is Fahd?","opts":["seven","nine","one","two"],"ans":2},{"type":"mcq","q":"What is the cat's name?","opts":["Sky","Fahd","Snow","Noor"],"ans":2},{"type":"tf","s":"Sami's grandpa has white hair.","ans":true},{"type":"tf","s":"Ben has a brother.","ans":false},{"type":"tf","s":"The cat is Sami's cat.","ans":false},{"type":"order","items":["Sami shows the photo.","Sami talks about his dad.","Sami talks about his baby brother.","Ben talks about his family."]}],"predict":{"en":"Sami shows Ben a family photo. Who is in the photo?","ar":"يُري سامي صديقه بن صورة لعائلته. من في الصورة؟"},"tip":{"en":"Listen for family words: dad, mom, grandpa, brother, sister. Then listen for one more detail about each person.","ar":"استمع لكلمات العائلة مثل dad وmom وgrandpa وbrother وsister، ثم استمع لمعلومة إضافية عن كل شخص."},"speak":{"prompt":"Draw your family or show a photo. Tell your partner who is who.","frame":"This is my ___. He's / She's ___."},"teach":"Ask students to bring a family photo or draw one. During Timed Pair Share, partner B must ask one follow-up question: \"How old is he?\" or \"What's her job?\"","id":"g3u2l1","track":"g3/u2/l1/track.mp3"},{"kind":"listen","n":2,"title":"Where Is the Cat?","skill":"Listening for places and positions","skill_ar":"الاستماع إلى الأماكن والمواقع","kagan":["RallyCoach","Showdown"],"vocab":[{"w":"in","ar":"في / داخل","emoji":"📥","ex":"The cat is in the box.","audio":"g3/u2/l2/v1.mp3"},{"w":"on","ar":"على","emoji":"🔝","ex":"The ball is on the sofa.","audio":"g3/u2/l2/v2.mp3"},{"w":"under","ar":"تحت","emoji":"⬇️","ex":"Look under the bed.","audio":"g3/u2/l2/v3.mp3"},{"w":"next to","ar":"بجانب","emoji":"↔️","ex":"The bowl is next to the fridge.","audio":"g3/u2/l2/v4.mp3"},{"w":"behind","ar":"خلف","emoji":"🚪","ex":"The box is behind the door.","audio":"g3/u2/l2/v5.mp3"},{"w":"sofa","ar":"أريكة","emoji":"🛋️","ex":"Dad sits on the sofa.","audio":"g3/u2/l2/v6.mp3"}],"script":[{"sp":"NOOR","name":"Noor","text":"Mom! Where is Snow? I can't find her.","audio":"g3/u2/l2/01.mp3"},{"sp":"MOM","name":"Mom","text":"Is she in your bedroom?","audio":"g3/u2/l2/02.mp3"},{"sp":"NOOR","name":"Noor","text":"No, she isn't. I looked under my bed.","audio":"g3/u2/l2/03.mp3"},{"sp":"MOM","name":"Mom","text":"Is she on the sofa in the living room?","audio":"g3/u2/l2/04.mp3"},{"sp":"NOOR","name":"Noor","text":"No. There's only a ball on the sofa.","audio":"g3/u2/l2/05.mp3"},{"sp":"MOM","name":"Mom","text":"Look in the kitchen. Snow likes the kitchen.","audio":"g3/u2/l2/06.mp3"},{"sp":"NOOR","name":"Noor","text":"She isn't in the kitchen. But her food bowl is next to the fridge.","audio":"g3/u2/l2/07.mp3"},{"sp":"MOM","name":"Mom","text":"Shh! Listen! What's that sound?","audio":"g3/u2/l2/08.mp3"},{"sp":"NOOR","name":"Noor","text":"I can hear her! She's in the box behind the door!","audio":"g3/u2/l2/09.mp3"},{"sp":"MOM","name":"Mom","text":"Oh, Snow! You're in Dad's new shoe box!","audio":"g3/u2/l2/10.mp3"},{"sp":"NOOR","name":"Noor","text":"Silly cat! Come on, Snow. It's dinner time.","audio":"g3/u2/l2/11.mp3"}],"tasks":[{"type":"mcq","q":"Where does Noor look first?","opts":["on the sofa","under her bed","behind the door","in the kitchen"],"ans":1},{"type":"mcq","q":"What is on the sofa?","opts":["a box","the cat","a bowl","a ball"],"ans":3},{"type":"mcq","q":"Where is the food bowl?","opts":["next to the fridge","under the bed","behind the door","on the sofa"],"ans":0},{"type":"mcq","q":"Where is Snow at the end?","opts":["in the kitchen","in a box behind the door","under the bed","on the sofa"],"ans":1},{"type":"tf","s":"Snow likes the kitchen.","ans":true},{"type":"tf","s":"The box is Mom's shoe box.","ans":false},{"type":"tf","s":"Noor hears the cat.","ans":true},{"type":"order","items":["Noor looks in her bedroom.","Mom asks about the sofa.","Noor looks in the kitchen.","Noor finds Snow in a box."]}],"predict":{"en":"Noor can't find her cat, Snow. Where can a cat hide in a house?","ar":"لا تستطيع نور أن تجد قطتها سنو. أين يمكن أن تختبئ قطة في البيت؟"},"tip":{"en":"Place words are short: in, on, under, next to, behind. Listen for the word before \"the\".","ar":"كلمات المكان قصيرة مثل in وon وunder وnext to وbehind. استمع للكلمة التي تأتي قبل the."},"speak":{"prompt":"Hide a small toy in a picture of a house. Your partner asks where it is.","frame":"Is it in / on / under the ___? Yes, it is. / No, it isn't."},"teach":"Use a real box and a soft toy before listening. Put the toy in, on, under, next to and behind the box while students say the word. This gives meaning before sound.","id":"g3u2l2","track":"g3/u2/l2/track.mp3"},{"kind":"listen","n":3,"title":"Rooms in My House","skill":"Listening for details","skill_ar":"الاستماع إلى التفاصيل","kagan":["Fan-N-Pick","RoundRobin"],"vocab":[{"w":"house","ar":"بيت","emoji":"🏠","ex":"Our house has five rooms.","audio":"g3/u2/l3/v1.mp3"},{"w":"kitchen","ar":"مطبخ","emoji":"🍳","ex":"Mom is in the kitchen.","audio":"g3/u2/l3/v2.mp3"},{"w":"bedroom","ar":"غرفة نوم","emoji":"🛏️","ex":"My bedroom is blue.","audio":"g3/u2/l3/v3.mp3"},{"w":"bathroom","ar":"حمّام","emoji":"🛁","ex":"The bathroom is small.","audio":"g3/u2/l3/v4.mp3"},{"w":"living room","ar":"غرفة الجلوس","emoji":"🛋️","ex":"Grandpa is in the living room.","audio":"g3/u2/l3/v5.mp3"},{"w":"garden","ar":"حديقة المنزل","emoji":"🌳","ex":"Dad is in the garden.","audio":"g3/u2/l3/v6.mp3"}],"script":[{"sp":"NARRATOR","name":"Narrator","text":"This is Sami's house. It has five rooms. Let's go inside.","audio":"g3/u2/l3/01.mp3"},{"sp":"SAMI","name":"Sami","text":"Hi! This is our living room. Grandpa is here with his newspaper.","audio":"g3/u2/l3/02.mp3"},{"sp":"SAMI","name":"Sami","text":"This is the kitchen. Mom is here. Mmm, it smells good!","audio":"g3/u2/l3/03.mp3"},{"sp":"SAMI","name":"Sami","text":"This is the bathroom. It's small and white.","audio":"g3/u2/l3/04.mp3"},{"sp":"SAMI","name":"Sami","text":"Upstairs, there are two bedrooms. This is Noor's bedroom. It's pink and purple. Noor is here with her cat.","audio":"g3/u2/l3/05.mp3"},{"sp":"SAMI","name":"Sami","text":"And this is my bedroom. It's blue. I have a desk, a bed and a big window.","audio":"g3/u2/l3/06.mp3"},{"sp":"SAMI","name":"Sami","text":"Where's Dad? Oh, he's in the garden with Fahd.","audio":"g3/u2/l3/07.mp3"},{"sp":"NARRATOR","name":"Narrator","text":"What a nice house!","audio":"g3/u2/l3/08.mp3"}],"tasks":[{"type":"mcq","q":"How many rooms are in Sami's house?","opts":["six","two","four","five"],"ans":3},{"type":"mcq","q":"Where is Grandpa?","opts":["in the living room","in the kitchen","in the garden","in the bedroom"],"ans":0},{"type":"mcq","q":"What color is Sami's bedroom?","opts":["blue","white","pink","purple"],"ans":0},{"type":"mcq","q":"Who is in the garden?","opts":["Noor and her cat","Mom and Noor","Dad and Fahd","Grandpa"],"ans":2},{"type":"tf","s":"The bathroom is big and white.","ans":false},{"type":"tf","s":"Noor's bedroom is upstairs.","ans":true},{"type":"tf","s":"Sami has a big window in his bedroom.","ans":true},{"type":"order","items":["the living room","the kitchen","the bathroom","Noor's bedroom"]}],"predict":{"en":"Sami shows us his house. Which rooms do you think we can see?","ar":"يُرينا سامي بيته. ما الغرف التي تتوقع أن نراها؟"},"tip":{"en":"Each time Sami says \"This is...\", a new room starts. Listen for who is in each room and its color.","ar":"كلما قال سامي \"This is...\" تبدأ غرفة جديدة. استمع لمن في كل غرفة وللونها."},"speak":{"prompt":"Draw your home. Tell your partner about two rooms.","frame":"This is the ___. It's ___. My ___ is here."},"teach":"Give each pair a blank house outline. During the first listening they only label the rooms; during the second they draw the people. Two clear purposes make two listenings meaningful.","id":"g3u2l3","track":"g3/u2/l3/track.mp3"}],"speak":[{"kind":"speak","n":1,"title":"Talking About My Family","func":"Describing your family","func_ar":"وصف العائلة","kagan":["Inside-Outside Circle","Find Someone Who"],"model":[{"sp":"ADAM","name":"Adam","text":"Sami, do you have a big family?","audio":"g3/u2/s1/01.mp3"},{"sp":"SAMI","name":"Sami","text":"Yes, I do. There are six people in my family.","audio":"g3/u2/s1/02.mp3"},{"sp":"ADAM","name":"Adam","text":"Six! Who are they?","audio":"g3/u2/s1/03.mp3"},{"sp":"SAMI","name":"Sami","text":"My mom, my dad, my grandpa, my sister, my baby brother and me. Oh, and our cat!","audio":"g3/u2/s1/04.mp3"},{"sp":"ADAM","name":"Adam","text":"Ha ha! I have a small family. My mom, my dad and me.","audio":"g3/u2/s1/05.mp3"},{"sp":"SAMI","name":"Sami","text":"Do you have a brother or a sister?","audio":"g3/u2/s1/06.mp3"},{"sp":"ADAM","name":"Adam","text":"No, I don't. But I have five cousins!","audio":"g3/u2/s1/07.mp3"},{"sp":"SAMI","name":"Sami","text":"Five cousins? That's fun!","audio":"g3/u2/s1/08.mp3"},{"sp":"ADAM","name":"Adam","text":"Yes, we play football every Friday.","audio":"g3/u2/s1/09.mp3"}],"roles":["ADAM","SAMI"],"chunks":[{"en":"Do you have a brother?","ar":"هل لديك أخ؟","audio":"g3/u2/s1/c1.mp3"},{"en":"I have one sister.","ar":"لديّ أخت واحدة.","audio":"g3/u2/s1/c2.mp3"},{"en":"There are five people in my family.","ar":"في عائلتي خمسة أشخاص.","audio":"g3/u2/s1/c3.mp3"},{"en":"Who are they?","ar":"من هم؟","audio":"g3/u2/s1/c4.mp3"},{"en":"That's fun!","ar":"هذا ممتع!","audio":"g3/u2/s1/c5.mp3"}],"sound":{"type":"pairs","title":"/f/ or /v/?","en":"Put your top teeth on your bottom lip. /f/ is only air. /v/ uses your voice — feel the buzz on your lip!","ar":"ضع أسنانك العليا على شفتك السفلى. /f/ هواء فقط، أما /v/ فيُنطق مع صوت وتشعر باهتزاز على شفتك.","pairs":[["fan","van"],["ferry","very"],["leaf","leave"],["few","view"],["safe","save"]],"audio":[["g3/u2/s1/p1a.mp3","g3/u2/s1/p1b.mp3"],["g3/u2/s1/p2a.mp3","g3/u2/s1/p2b.mp3"],["g3/u2/s1/p3a.mp3","g3/u2/s1/p3b.mp3"],["g3/u2/s1/p4a.mp3","g3/u2/s1/p4b.mp3"],["g3/u2/s1/p5a.mp3","g3/u2/s1/p5b.mp3"]]},"task":{"prompt":"Tell your group about your family. Use numbers.","frame":"There are ___ people in my family. I have ___. My ___ is ___."},"cando":["I can talk about my family.","I can ask \"Do you have a ...?\"","I can say /f/ and /v/ correctly."],"teach":"Students put a finger on their throat: no buzz for /f/, buzz for /v/. Many Arabic speakers say /f/ for both, so praise every clear /v/.","id":"g3u2s1","track":"g3/u2/s1/track.mp3"},{"kind":"speak","n":2,"title":"Where Is My Bag?","func":"Asking and saying where things are","func_ar":"السؤال عن مكان الأشياء والإجابة","kagan":["RallyRobin","Mix-Freeze-Group"],"model":[{"sp":"NOOR","name":"Noor","text":"Mom, where's my school bag?","audio":"g3/u2/s2/01.mp3"},{"sp":"MOM","name":"Mom","text":"Is it in your bedroom?","audio":"g3/u2/s2/02.mp3"},{"sp":"NOOR","name":"Noor","text":"No, it isn't. I can't find it!","audio":"g3/u2/s2/03.mp3"},{"sp":"MOM","name":"Mom","text":"Look! It's under the table in the kitchen.","audio":"g3/u2/s2/04.mp3"},{"sp":"NOOR","name":"Noor","text":"Oh, thank you! And where are my books?","audio":"g3/u2/s2/05.mp3"},{"sp":"MOM","name":"Mom","text":"They're on the sofa, next to Dad's phone.","audio":"g3/u2/s2/06.mp3"},{"sp":"NOOR","name":"Noor","text":"Thanks, Mom! Where's my water bottle?","audio":"g3/u2/s2/07.mp3"},{"sp":"MOM","name":"Mom","text":"It's in your bag, Noor.","audio":"g3/u2/s2/08.mp3"},{"sp":"NOOR","name":"Noor","text":"Oh! Silly me!","audio":"g3/u2/s2/09.mp3"}],"roles":["NOOR","MOM"],"chunks":[{"en":"Where's my bag?","ar":"أين حقيبتي؟","audio":"g3/u2/s2/c1.mp3"},{"en":"It's under the table.","ar":"إنها تحت الطاولة.","audio":"g3/u2/s2/c2.mp3"},{"en":"Where are my books?","ar":"أين كتبي؟","audio":"g3/u2/s2/c3.mp3"},{"en":"They're on the sofa.","ar":"إنها على الأريكة.","audio":"g3/u2/s2/c4.mp3"},{"en":"I can't find it.","ar":"لا أستطيع أن أجدها.","audio":"g3/u2/s2/c5.mp3"}],"sound":{"type":"sort","title":"Strong beat first or second?","cats":[{"key":"Oo","label":"Oo"},{"key":"oO","label":"oO"}],"en":"English words have one strong beat. TA-ble has the strong beat first (Oo). be-HIND has it second (oO).","ar":"في الكلمة الإنجليزية مقطع واحد قوي. في TA-ble يأتي المقطع القوي أولًا (Oo)، وفي be-HIND يأتي ثانيًا (oO).","items":[{"text":"table","key":"Oo","audio":"g3/u2/s2/i1.mp3"},{"text":"behind","key":"oO","audio":"g3/u2/s2/i2.mp3"},{"text":"kitchen","key":"Oo","audio":"g3/u2/s2/i3.mp3"},{"text":"between","key":"oO","audio":"g3/u2/s2/i4.mp3"},{"text":"under","key":"Oo","audio":"g3/u2/s2/i5.mp3"},{"text":"around","key":"oO","audio":"g3/u2/s2/i6.mp3"},{"text":"sofa","key":"Oo","audio":"g3/u2/s2/i7.mp3"},{"text":"upstairs","key":"oO","audio":"g3/u2/s2/i8.mp3"}]},"task":{"prompt":"Hide a pencil in the classroom. Your partner asks questions to find it.","frame":"Where's the pencil? Is it ___ the ___? — Yes, it is. / No, it isn't."},"cando":["I can ask where things are.","I can say where things are.","I can hear the strong beat in a word."],"teach":"Clap the beats: one big clap for the strong beat and one small clap for the weak beat. Students clap before they choose Oo or oO.","id":"g3u2s2","track":"g3/u2/s2/track.mp3"}],"check":[{"type":"mcq","q":"What does Grandpa have?","ref":"L1#7","opts":["a cat","a car","a shop","a farm"],"ans":3,"audio":"g3/u2/l1/07.mp3","line":"That's my grandpa. He has a farm.","speaker":"Sami"},{"type":"mcq","q":"What time is it at the end?","ref":"L2#11","opts":["dinner time","lunch time","school time","bed time"],"ans":0,"audio":"g3/u2/l2/11.mp3","line":"Silly cat! Come on, Snow. It's dinner time.","speaker":"Noor"},{"type":"mcq","q":"What does Grandpa have with him?","ref":"L3#2","opts":["a phone","a book","a newspaper","a cat"],"ans":2,"audio":"g3/u2/l3/02.mp3","line":"Hi! This is our living room. Grandpa is here with his newspaper.","speaker":"Sami"},{"type":"mcq","q":"What colors is Noor's bedroom?","ref":"L3#5","opts":["pink and white","pink and purple","blue and white","purple and blue"],"ans":1,"audio":"g3/u2/l3/05.mp3","line":"Upstairs, there are two bedrooms. This is Noor's bedroom. It's pink and purple. Noor is here with her cat.","speaker":"Sami"}],"id":"g3u2"},{"n":3,"title":"At School","ar":"في المدرسة","emoji":"🎒","goals":["I can name school things and colors.","I can ask for things politely.","I can understand school days and subjects."],"listen":[{"kind":"listen","n":1,"title":"Lost and Found","skill":"Listening for colors and objects","skill_ar":"الاستماع إلى الألوان والأشياء","kagan":["Quiz-Quiz-Trade","RallyRobin"],"vocab":[{"w":"ruler","ar":"مسطرة","emoji":"📏","ex":"My ruler is yellow.","audio":"g3/u3/l1/v1.mp3"},{"w":"pencil case","ar":"مقلمة","emoji":"🖍️","ex":"The pencil case is red.","audio":"g3/u3/l1/v2.mp3"},{"w":"water bottle","ar":"قارورة ماء","emoji":"🥤","ex":"My water bottle is blue.","audio":"g3/u3/l1/v3.mp3"},{"w":"eraser","ar":"ممحاة","emoji":"🧽","ex":"I need an eraser.","audio":"g3/u3/l1/v4.mp3"},{"w":"notebook","ar":"دفتر","emoji":"📓","ex":"My name is on my notebook.","audio":"g3/u3/l1/v5.mp3"},{"w":"lost and found","ar":"صندوق المفقودات","emoji":"📦","ex":"Look in the lost and found box.","audio":"g3/u3/l1/v6.mp3"}],"script":[{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"Boys, look at this box. It's the lost and found box. Whose things are these?","audio":"g3/u3/l1/01.mp3"},{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"Here's a green ruler. Is it yours, Adam?","audio":"g3/u3/l1/02.mp3"},{"sp":"ADAM","name":"Adam","text":"No, Mr. Hassan. My ruler is yellow.","audio":"g3/u3/l1/03.mp3"},{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"Okay. Here's a red pencil case. Whose is it?","audio":"g3/u3/l1/04.mp3"},{"sp":"BEN","name":"Ben","text":"It's mine! Thank you, Mr. Hassan.","audio":"g3/u3/l1/05.mp3"},{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"And here's a blue water bottle with a star on it.","audio":"g3/u3/l1/06.mp3"},{"sp":"SAMI","name":"Sami","text":"That's my water bottle! Thank you.","audio":"g3/u3/l1/07.mp3"},{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"There are two more things: a black eraser and an orange notebook.","audio":"g3/u3/l1/08.mp3"},{"sp":"ADAM","name":"Adam","text":"The orange notebook is mine. My name is on it.","audio":"g3/u3/l1/09.mp3"},{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"Great. The green ruler and the black eraser stay in the box.","audio":"g3/u3/l1/10.mp3"}],"tasks":[{"type":"mcq","q":"What color is Adam's ruler?","opts":["orange","yellow","green","black"],"ans":1},{"type":"mcq","q":"What is Ben's?","opts":["the blue water bottle","the black eraser","the red pencil case","the green ruler"],"ans":2},{"type":"mcq","q":"What is on Sami's water bottle?","opts":["a cat","a star","a flower","his name"],"ans":1},{"type":"mcq","q":"How does Adam know the notebook is his?","opts":["His name is on it.","Mr. Hassan tells him.","It has a star on it.","It is yellow."],"ans":0},{"type":"tf","s":"The pencil case is red.","ans":true},{"type":"tf","s":"Sami's water bottle is green.","ans":false},{"type":"tf","s":"Nobody takes the black eraser.","ans":true},{"type":"order","items":["the green ruler","the red pencil case","the blue water bottle","the orange notebook"]}],"predict":{"en":"The teacher has a box of lost things. What things do children often lose at school?","ar":"لدى المعلم صندوق فيه أشياء مفقودة. ما الأشياء التي يفقدها الأطفال عادةً في المدرسة؟"},"tip":{"en":"Listen for a color + a thing together: a green ruler, a red pencil case. Then listen for who says \"It's mine!\"","ar":"استمع إلى اللون مع الشيء معًا مثل a green ruler، ثم استمع لمن يقول \"It's mine!\" أي إنه لي."},"speak":{"prompt":"Show your partner three things from your bag. Say the color.","frame":"This is my ___. It's ___."},"teach":"Make a real \"lost and found\" box with classroom objects. After listening, students play the teacher: one holds up an object and says \"Here's a ___. Whose is it?\"","id":"g3u3l1","track":"g3/u3/l1/track.mp3"},{"kind":"listen","n":2,"title":"Can I Borrow a Pencil?","skill":"Listening for what people need","skill_ar":"الاستماع إلى ما يحتاجه الناس","kagan":["RallyCoach","Stand Up–Hand Up–Pair Up"],"vocab":[{"w":"borrow","ar":"يستعير","emoji":"🤲","ex":"Can I borrow a pencil?","audio":"g3/u3/l2/v1.mp3"},{"w":"pencil","ar":"قلم رصاص","emoji":"✏️","ex":"Here's a pencil.","audio":"g3/u3/l2/v2.mp3"},{"w":"sharpener","ar":"برّاية","emoji":"🔄","ex":"I don't have a sharpener.","audio":"g3/u3/l2/v3.mp3"},{"w":"paper","ar":"ورق","emoji":"📄","ex":"Can I have some paper?","audio":"g3/u3/l2/v4.mp3"},{"w":"draw","ar":"يرسم","emoji":"🖍️","ex":"We need to draw a tree.","audio":"g3/u3/l2/v5.mp3"},{"w":"Here you are.","ar":"تفضّل.","emoji":"🫴","ex":"Sure. Here you are.","audio":"g3/u3/l2/v6.mp3"}],"script":[{"sp":"BEN","name":"Ben","text":"Adam, can I borrow a pencil, please?","audio":"g3/u3/l2/01.mp3"},{"sp":"ADAM","name":"Adam","text":"Sure. Here you are.","audio":"g3/u3/l2/02.mp3"},{"sp":"BEN","name":"Ben","text":"Thanks! Oh no, I don't have a sharpener.","audio":"g3/u3/l2/03.mp3"},{"sp":"ADAM","name":"Adam","text":"Sorry, I don't have one. Ask Yusuf.","audio":"g3/u3/l2/04.mp3"},{"sp":"BEN","name":"Ben","text":"Yusuf, can I use your sharpener, please?","audio":"g3/u3/l2/05.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"Of course. Here you are.","audio":"g3/u3/l2/06.mp3"},{"sp":"BEN","name":"Ben","text":"Thank you. And can I have some paper too?","audio":"g3/u3/l2/07.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"Yes. One page or two?","audio":"g3/u3/l2/08.mp3"},{"sp":"BEN","name":"Ben","text":"Two, please. We need to draw a big tree.","audio":"g3/u3/l2/09.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"Do you need colors too?","audio":"g3/u3/l2/10.mp3"},{"sp":"BEN","name":"Ben","text":"No, thanks. I have my colors. Thank you, Yusuf!","audio":"g3/u3/l2/11.mp3"}],"tasks":[{"type":"mcq","q":"What does Ben borrow from Adam?","opts":["a sharpener","some colors","some paper","a pencil"],"ans":3},{"type":"mcq","q":"Who has a sharpener?","opts":["Ben","Yusuf","Adam","Sami"],"ans":1},{"type":"mcq","q":"How many pages of paper does Ben take?","opts":["two","three","one","four"],"ans":0},{"type":"mcq","q":"What do they need to draw?","opts":["a big tree","a big house","a school","a small cat"],"ans":0},{"type":"tf","s":"Adam has a sharpener.","ans":false},{"type":"tf","s":"Ben needs colors from Yusuf.","ans":false},{"type":"tf","s":"Ben says thank you to Yusuf.","ans":true},{"type":"order","items":["Ben borrows a pencil.","Ben asks for a sharpener.","Ben asks for paper.","Ben says he has his colors."]}],"predict":{"en":"Ben forgets some things at home. What can he do?","ar":"نسي بن بعض أشيائه في البيت. ماذا يمكنه أن يفعل؟"},"tip":{"en":"Polite questions start with \"Can I...?\". Listen for the thing after \"borrow\", \"use\" or \"have\".","ar":"الطلبات المهذبة تبدأ بـ \"Can I...?\". استمع للشيء الذي يأتي بعد borrow أو use أو have."},"speak":{"prompt":"Ask your partner for three things. Say please and thank you.","frame":"Can I borrow your ___, please? — Sure. Here you are. — Thank you!"},"teach":"Point out that English speakers almost always add \"please\" and \"thank you\". Award a \"Polite Point\" every time you hear both during the pair practice.","id":"g3u3l2","track":"g3/u3/l2/track.mp3"},{"kind":"listen","n":3,"title":"My Favorite Subject","skill":"Listening for days of the week","skill_ar":"الاستماع إلى أيام الأسبوع","kagan":["Corners","Timed Pair Share"],"vocab":[{"w":"subject","ar":"مادة دراسية","emoji":"📚","ex":"My favorite subject is science.","audio":"g3/u3/l3/v1.mp3"},{"w":"science","ar":"العلوم","emoji":"🔬","ex":"We have science on Sunday.","audio":"g3/u3/l3/v2.mp3"},{"w":"art","ar":"التربية الفنية","emoji":"🎨","ex":"I like art.","audio":"g3/u3/l3/v3.mp3"},{"w":"P.E.","ar":"التربية البدنية","emoji":"⚽","ex":"We play football in P.E.","audio":"g3/u3/l3/v4.mp3"},{"w":"favorite","ar":"مفضّل","emoji":"⭐","ex":"What's your favorite subject?","audio":"g3/u3/l3/v5.mp3"},{"w":"every day","ar":"كل يوم","emoji":"📅","ex":"We have English every day.","audio":"g3/u3/l3/v6.mp3"}],"script":[{"sp":"BEN","name":"Ben","text":"Sami, what's your favorite subject?","audio":"g3/u3/l3/01.mp3"},{"sp":"SAMI","name":"Sami","text":"I love science! We have science on Sunday and Tuesday.","audio":"g3/u3/l3/02.mp3"},{"sp":"BEN","name":"Ben","text":"I like science too. But my favorite subject is P.E.","audio":"g3/u3/l3/03.mp3"},{"sp":"SAMI","name":"Sami","text":"When do we have P.E.?","audio":"g3/u3/l3/04.mp3"},{"sp":"BEN","name":"Ben","text":"On Monday and Thursday. On Thursday we play football!","audio":"g3/u3/l3/05.mp3"},{"sp":"SAMI","name":"Sami","text":"Great! What about art?","audio":"g3/u3/l3/06.mp3"},{"sp":"BEN","name":"Ben","text":"Art is on Wednesday. I like art. I can draw animals.","audio":"g3/u3/l3/07.mp3"},{"sp":"SAMI","name":"Sami","text":"And English? We have English every day!","audio":"g3/u3/l3/08.mp3"},{"sp":"BEN","name":"Ben","text":"Yes! Five days a week. English is fun.","audio":"g3/u3/l3/09.mp3"}],"tasks":[{"type":"mcq","q":"What is Sami's favorite subject?","opts":["English","art","P.E.","science"],"ans":3},{"type":"mcq","q":"When do they have P.E.?","opts":["on Monday and Thursday","every day","on Sunday and Tuesday","on Wednesday"],"ans":0},{"type":"mcq","q":"What can Ben draw?","opts":["houses","cars","trees","animals"],"ans":3},{"type":"mcq","q":"How many days a week do they have English?","opts":["five","two","four","three"],"ans":0},{"type":"tf","s":"They have science on Sunday.","ans":true},{"type":"tf","s":"Art is on Thursday.","ans":false},{"type":"tf","s":"Ben likes art.","ans":true},{"type":"order","items":["Sami talks about science.","Ben talks about P.E.","They talk about art.","They talk about English."]}],"predict":{"en":"Sami and Ben talk about their school subjects. Which subjects do you think they like?","ar":"يتحدث سامي وبن عن موادهما الدراسية. ما المواد التي تتوقع أنهما يحبانها؟"},"tip":{"en":"Our school week is Sunday to Thursday. Listen for a day after the word \"on\": on Monday, on Thursday.","ar":"أسبوعنا الدراسي من الأحد إلى الخميس. استمع لاسم اليوم بعد كلمة on مثل on Monday."},"speak":{"prompt":"Tell your partner your favorite subject and the day you have it.","frame":"My favorite subject is ___. We have it on ___."},"teach":"Put subject names in the four corners of the room. Students walk to their favorite subject and tell the corner group why, using \"I like it because it's fun / interesting\".","id":"g3u3l3","track":"g3/u3/l3/track.mp3"}],"speak":[{"kind":"speak","n":1,"title":"Can I Have..., Please?","func":"Asking for things politely","func_ar":"طلب الأشياء بأدب","kagan":["Inside-Outside Circle","RallyRobin"],"model":[{"sp":"SAMI","name":"Sami","text":"Excuse me, Mr. Hassan. Can I have a sheet of paper, please?","audio":"g3/u3/s1/01.mp3"},{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"Sure, Sami. Here you are.","audio":"g3/u3/s1/02.mp3"},{"sp":"SAMI","name":"Sami","text":"Thank you. Can I use the green marker, please?","audio":"g3/u3/s1/03.mp3"},{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"Sorry, Sami. Adam has the green marker. You can use the blue one.","audio":"g3/u3/s1/04.mp3"},{"sp":"SAMI","name":"Sami","text":"That's okay. Can I sit next to the window, please?","audio":"g3/u3/s1/05.mp3"},{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"Yes, you can.","audio":"g3/u3/s1/06.mp3"},{"sp":"SAMI","name":"Sami","text":"Thank you very much, Mr. Hassan.","audio":"g3/u3/s1/07.mp3"},{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"You're welcome.","audio":"g3/u3/s1/08.mp3"}],"roles":["SAMI","MR_HASSAN"],"chunks":[{"en":"Excuse me.","ar":"عفوًا.","audio":"g3/u3/s1/c1.mp3"},{"en":"Can I have ___, please?","ar":"هل يمكنني الحصول على ___ من فضلك؟","audio":"g3/u3/s1/c2.mp3"},{"en":"Can I use ___?","ar":"هل يمكنني استخدام ___؟","audio":"g3/u3/s1/c3.mp3"},{"en":"Thank you very much.","ar":"شكرًا جزيلًا.","audio":"g3/u3/s1/c4.mp3"},{"en":"You're welcome.","ar":"على الرحب والسعة.","audio":"g3/u3/s1/c5.mp3"}],"sound":{"type":"pairs","title":"Short /ɪ/ or long /iː/?","en":"/ɪ/ is short and relaxed, like in \"sit\". /iː/ is long — smile and stretch it, like in \"seat\".","ar":"الصوت /ɪ/ قصير ومرتخٍ كما في sit، أما /iː/ فطويل؛ ابتسم ومدّه كما في seat.","pairs":[["sit","seat"],["ship","sheep"],["bin","bean"],["fill","feel"],["hit","heat"]],"audio":[["g3/u3/s1/p1a.mp3","g3/u3/s1/p1b.mp3"],["g3/u3/s1/p2a.mp3","g3/u3/s1/p2b.mp3"],["g3/u3/s1/p3a.mp3","g3/u3/s1/p3b.mp3"],["g3/u3/s1/p4a.mp3","g3/u3/s1/p4b.mp3"],["g3/u3/s1/p5a.mp3","g3/u3/s1/p5b.mp3"]]},"task":{"prompt":"Ask three classmates politely for things. They say yes or sorry.","frame":"Excuse me, can I have ___, please? — Here you are. / Sorry, ___."},"cando":["I can ask for things politely.","I can answer \"Here you are\" or \"Sorry\".","I can hear short /ɪ/ and long /iː/."],"teach":"Ask students to smile wide for /iː/ (sheep) and relax their face for /ɪ/ (ship). A mirror or a phone camera helps them see the difference.","id":"g3u3s1","track":"g3/u3/s1/track.mp3"},{"kind":"speak","n":2,"title":"What's in Your Bag?","func":"Describing things","func_ar":"وصف الأشياء","kagan":["Fan-N-Pick","Talking Chips"],"model":[{"sp":"ADAM","name":"Adam","text":"Ben, what's in your bag today?","audio":"g3/u3/s2/01.mp3"},{"sp":"BEN","name":"Ben","text":"I have two books, three pens and a big red pencil case.","audio":"g3/u3/s2/02.mp3"},{"sp":"ADAM","name":"Adam","text":"What's in your pencil case?","audio":"g3/u3/s2/03.mp3"},{"sp":"BEN","name":"Ben","text":"Pencils, erasers and some colors. Look, my colors are new!","audio":"g3/u3/s2/04.mp3"},{"sp":"ADAM","name":"Adam","text":"Nice! I have a lunch box with two sandwiches and some grapes.","audio":"g3/u3/s2/05.mp3"},{"sp":"BEN","name":"Ben","text":"Yum! Do you have any juice boxes?","audio":"g3/u3/s2/06.mp3"},{"sp":"ADAM","name":"Adam","text":"Yes, two juice boxes. Do you want one?","audio":"g3/u3/s2/07.mp3"},{"sp":"BEN","name":"Ben","text":"Yes, please! Thank you, Adam.","audio":"g3/u3/s2/08.mp3"}],"roles":["ADAM","BEN"],"chunks":[{"en":"What's in your bag?","ar":"ماذا يوجد في حقيبتك؟","audio":"g3/u3/s2/c1.mp3"},{"en":"I have two books.","ar":"لديّ كتابان.","audio":"g3/u3/s2/c2.mp3"},{"en":"It's big and red.","ar":"إنه كبير وأحمر.","audio":"g3/u3/s2/c3.mp3"},{"en":"Do you want one?","ar":"هل تريد واحدًا؟","audio":"g3/u3/s2/c4.mp3"},{"en":"Yes, please!","ar":"نعم، من فضلك!","audio":"g3/u3/s2/c5.mp3"}],"sound":{"type":"sort","title":"Plural -s: /s/, /z/ or /ɪz/?","cats":[{"key":"/s/","label":"/s/ books"},{"key":"/z/","label":"/z/ pens"},{"key":"/ɪz/","label":"/ɪz/ boxes"}],"en":"Plural -s has three sounds. After k, p, t it is /s/ (books). After most other sounds it is /z/ (pens). After s, x, sh, ch it is /ɪz/ — an extra beat (boxes).","ar":"لنهاية الجمع -s ثلاثة أصوات: /s/ بعد k وp وt مثل books، و/z/ بعد معظم الأصوات الأخرى مثل pens، و/ɪz/ مع مقطع إضافي بعد s وx وsh وch مثل boxes.","items":[{"text":"cats","key":"/s/","audio":"g3/u3/s2/i1.mp3"},{"text":"bags","key":"/z/","audio":"g3/u3/s2/i2.mp3"},{"text":"buses","key":"/ɪz/","audio":"g3/u3/s2/i3.mp3"},{"text":"desks","key":"/s/","audio":"g3/u3/s2/i4.mp3"},{"text":"chairs","key":"/z/","audio":"g3/u3/s2/i5.mp3"},{"text":"watches","key":"/ɪz/","audio":"g3/u3/s2/i6.mp3"},{"text":"grapes","key":"/s/","audio":"g3/u3/s2/i7.mp3"},{"text":"pencils","key":"/z/","audio":"g3/u3/s2/i8.mp3"},{"text":"classes","key":"/ɪz/","audio":"g3/u3/s2/i9.mp3"}]},"task":{"prompt":"Describe something in your bag. Your partner guesses what it is.","frame":"It's ___ and ___. I use it to ___. What is it?"},"cando":["I can describe things with color and size.","I can talk about more than one thing.","I can say plural -s endings."],"teach":"Write the three endings on cards: /s/ /z/ /ɪz/. Students hold up a card for each word before they check on the platform.","id":"g3u3s2","track":"g3/u3/s2/track.mp3"}],"check":[{"type":"mcq","q":"What is the box?","ref":"L1#1","opts":["a pencil box","the lost and found box","a lunch box","a toy box"],"ans":1,"audio":"g3/u3/l1/01.mp3","line":"Boys, look at this box. It's the lost and found box. Whose things are these?","speaker":"Mr. Hassan"},{"type":"mcq","q":"What does Adam tell Ben?","ref":"L2#4","opts":["Here you are.","Ask Yusuf.","Use my colors.","Ask Mr. Hassan."],"ans":1,"audio":"g3/u3/l2/04.mp3","line":"Sorry, I don't have one. Ask Yusuf.","speaker":"Adam"},{"type":"mcq","q":"What do the boys do in P.E. on Thursday?","ref":"L3#5","opts":["swim","read books","play football","draw animals"],"ans":2,"audio":"g3/u3/l3/05.mp3","line":"On Monday and Thursday. On Thursday we play football!","speaker":"Ben"},{"type":"mcq","q":"What does Ben say about English?","ref":"L3#9","opts":["It's hard.","It's fun.","It's on Monday.","It's boring."],"ans":1,"audio":"g3/u3/l3/09.mp3","line":"Yes! Five days a week. English is fun.","speaker":"Ben"}],"id":"g3u3"},{"n":4,"title":"Food I Like","ar":"طعام أحبه","emoji":"🍎","goals":["I can talk about food I like and don't like.","I can order food politely.","I can understand simple steps in order."],"listen":[{"kind":"listen","n":1,"title":"At the Lunch Table","skill":"Listening for likes and dislikes","skill_ar":"الاستماع إلى ما يحبه الناس وما لا يحبونه","kagan":["Find Someone Who","RallyRobin"],"vocab":[{"w":"lunch box","ar":"علبة الغداء","emoji":"🍱","ex":"What's in your lunch box?","audio":"g3/u4/l1/v1.mp3"},{"w":"sandwich","ar":"شطيرة","emoji":"🥪","ex":"I have a cheese sandwich.","audio":"g3/u4/l1/v2.mp3"},{"w":"cheese","ar":"جبن","emoji":"🧀","ex":"I like cheese.","audio":"g3/u4/l1/v3.mp3"},{"w":"carrot","ar":"جزر","emoji":"🥕","ex":"Carrots are good for your eyes.","audio":"g3/u4/l1/v4.mp3"},{"w":"dates","ar":"تمر","emoji":"🌴","ex":"I love dates!","audio":"g3/u4/l1/v5.mp3"},{"w":"dessert","ar":"حلوى بعد الطعام","emoji":"🍮","ex":"What's for dessert?","audio":"g3/u4/l1/v6.mp3"}],"script":[{"sp":"ADAM","name":"Adam","text":"Mmm, I love chicken and rice! What's in your lunch box, Ben?","audio":"g3/u4/l1/01.mp3"},{"sp":"BEN","name":"Ben","text":"A cheese sandwich and an apple. I like cheese, but I don't like apples very much.","audio":"g3/u4/l1/02.mp3"},{"sp":"SAMI","name":"Sami","text":"I love apples! Do you want my banana? Then I can have your apple.","audio":"g3/u4/l1/03.mp3"},{"sp":"BEN","name":"Ben","text":"Yes, please! I like bananas.","audio":"g3/u4/l1/04.mp3"},{"sp":"ADAM","name":"Adam","text":"Sami, do you like carrots?","audio":"g3/u4/l1/05.mp3"},{"sp":"SAMI","name":"Sami","text":"No, I don't. I don't like carrots at all.","audio":"g3/u4/l1/06.mp3"},{"sp":"ADAM","name":"Adam","text":"I like carrots. They're good for your eyes!","audio":"g3/u4/l1/07.mp3"},{"sp":"BEN","name":"Ben","text":"What's for dessert?","audio":"g3/u4/l1/08.mp3"},{"sp":"ADAM","name":"Adam","text":"My mom made dates for me. Do you want one?","audio":"g3/u4/l1/09.mp3"},{"sp":"SAMI","name":"Sami","text":"Yes, please! I love dates!","audio":"g3/u4/l1/10.mp3"}],"tasks":[{"type":"mcq","q":"What does Adam love?","opts":["cheese sandwiches","apples","chicken and rice","carrots and dates"],"ans":2},{"type":"mcq","q":"What does Ben not like very much?","opts":["bananas","dates","apples","cheese"],"ans":2},{"type":"mcq","q":"What does Sami give Ben?","opts":["a banana","an apple","a carrot","a date"],"ans":0},{"type":"mcq","q":"Why does Adam like carrots?","opts":["They're sweet.","They're orange.","They're good for your eyes.","His mom likes them."],"ans":2},{"type":"tf","s":"Sami likes carrots.","ans":false},{"type":"tf","s":"Ben has a cheese sandwich.","ans":true},{"type":"tf","s":"Adam has dates for dessert.","ans":true},{"type":"order","items":["Adam talks about chicken and rice.","Ben gets a banana.","Adam asks about carrots.","Sami takes a date."]}],"predict":{"en":"Three boys eat lunch together. What food do you think they have?","ar":"ثلاثة أولاد يتناولون الغداء معًا. ما الطعام الذي تتوقع أنهم يحملونه؟"},"tip":{"en":"\"I love\" and \"I like\" mean yes. \"I don't like\" means no. Listen for \"don't\".","ar":"عبارتا I love وI like تعنيان الإعجاب، أما I don't like فتعني عدم الإعجاب. انتبه لكلمة don't."},"speak":{"prompt":"Tell your partner two foods you like and one food you don't like.","frame":"I like ___ and ___. I don't like ___."},"teach":"Draw a smiley face and a sad face on the board. During the first listening, students show thumbs up or thumbs down for each food they hear.","id":"g3u4l1","track":"g3/u4/l1/track.mp3"},{"kind":"listen","n":2,"title":"Breakfast Time","skill":"Listening for food and numbers","skill_ar":"الاستماع إلى الأطعمة والكميات","kagan":["Numbered Heads Together","Quiz-Quiz-Trade"],"vocab":[{"w":"breakfast","ar":"فطور","emoji":"🍳","ex":"Breakfast is ready!","audio":"g3/u4/l2/v1.mp3"},{"w":"egg","ar":"بيضة","emoji":"🥚","ex":"Can I have two eggs?","audio":"g3/u4/l2/v2.mp3"},{"w":"bread","ar":"خبز","emoji":"🍞","ex":"I like bread with honey.","audio":"g3/u4/l2/v3.mp3"},{"w":"honey","ar":"عسل","emoji":"🍯","ex":"Here's the honey.","audio":"g3/u4/l2/v4.mp3"},{"w":"milk","ar":"حليب","emoji":"🥛","ex":"A big glass of milk, please.","audio":"g3/u4/l2/v5.mp3"},{"w":"juice","ar":"عصير","emoji":"🧃","ex":"Orange juice, please.","audio":"g3/u4/l2/v6.mp3"}],"script":[{"sp":"DAD","name":"Dad","text":"Good morning! It's Friday. I'm making a big breakfast.","audio":"g3/u4/l2/01.mp3"},{"sp":"NOOR","name":"Noor","text":"Yay! Can I have two eggs, please?","audio":"g3/u4/l2/02.mp3"},{"sp":"DAD","name":"Dad","text":"Of course. Sami, how many eggs do you want?","audio":"g3/u4/l2/03.mp3"},{"sp":"SAMI","name":"Sami","text":"Just one egg, please. And some bread with honey.","audio":"g3/u4/l2/04.mp3"},{"sp":"DAD","name":"Dad","text":"Here's the honey. Noor, do you want milk or orange juice?","audio":"g3/u4/l2/05.mp3"},{"sp":"NOOR","name":"Noor","text":"Milk, please. A big glass!","audio":"g3/u4/l2/06.mp3"},{"sp":"DAD","name":"Dad","text":"And you, Sami?","audio":"g3/u4/l2/07.mp3"},{"sp":"SAMI","name":"Sami","text":"Orange juice, please.","audio":"g3/u4/l2/08.mp3"},{"sp":"MOM","name":"Mom","text":"I'd like a cup of tea, please. With no sugar.","audio":"g3/u4/l2/09.mp3"},{"sp":"DAD","name":"Dad","text":"Okay. Two eggs for Noor, one egg for Sami, a big glass of milk, an orange juice and a tea with no sugar. Breakfast is ready!","audio":"g3/u4/l2/10.mp3"}],"tasks":[{"type":"mcq","q":"How many eggs does Noor want?","opts":["three","four","one","two"],"ans":3},{"type":"mcq","q":"What does Sami have with his bread?","opts":["honey","cheese","butter","jam"],"ans":0},{"type":"mcq","q":"What does Noor drink?","opts":["orange juice","water","tea","a big glass of milk"],"ans":3},{"type":"mcq","q":"How does Mom like her tea?","opts":["with no sugar","with honey","with two sugars","with milk"],"ans":0},{"type":"tf","s":"It is Friday morning.","ans":true},{"type":"tf","s":"Sami wants two eggs.","ans":false},{"type":"tf","s":"Mom makes the breakfast.","ans":false},{"type":"order","items":["Noor asks for eggs.","Sami asks for bread with honey.","Noor asks for milk.","Mom asks for tea."]}],"predict":{"en":"It's Friday morning. Dad makes breakfast for the family. What do they want?","ar":"إنه صباح الجمعة، والأب يعدّ الفطور للعائلة. ماذا يريدون أن يأكلوا ويشربوا؟"},"tip":{"en":"Listen for numbers before food: two eggs, one egg. And listen for \"or\": milk or juice?","ar":"استمع للأعداد قبل أسماء الطعام مثل two eggs، واستمع لكلمة or التي تعني الاختيار."},"speak":{"prompt":"Tell your partner about your breakfast.","frame":"For breakfast, I have ___. I drink ___."},"teach":"Make a \"breakfast menu\" on the board with pictures. Students listen and tick what each person orders in a different color: blue for Noor, green for Sami, red for Mom.","id":"g3u4l2","track":"g3/u4/l2/track.mp3"},{"kind":"listen","n":3,"title":"A Picnic in the Park","skill":"Listening for the order of events","skill_ar":"الاستماع إلى ترتيب الأحداث","kagan":["Line-Ups","RallyCoach"],"vocab":[{"w":"picnic","ar":"نزهة","emoji":"🌳","ex":"Let's have a picnic.","audio":"g3/u4/l3/v1.mp3"},{"w":"park","ar":"حديقة عامة","emoji":"🏞️","ex":"We go to the park.","audio":"g3/u4/l3/v2.mp3"},{"w":"blanket","ar":"بطانية","emoji":"🟫","ex":"Put the blanket on the grass.","audio":"g3/u4/l3/v3.mp3"},{"w":"grass","ar":"عشب","emoji":"🌱","ex":"The grass is green.","audio":"g3/u4/l3/v4.mp3"},{"w":"basket","ar":"سلة","emoji":"🧺","ex":"Open the basket.","audio":"g3/u4/l3/v5.mp3"},{"w":"rubbish","ar":"قمامة","emoji":"🗑️","ex":"Put the rubbish in the bin.","audio":"g3/u4/l3/v6.mp3"}],"script":[{"sp":"NARRATOR","name":"Narrator","text":"It's a sunny Saturday. Grandpa takes Sami and Noor to the park.","audio":"g3/u4/l3/01.mp3"},{"sp":"GRANDPA","name":"Grandpa","text":"First, let's find a good place. Look, under that big tree!","audio":"g3/u4/l3/02.mp3"},{"sp":"SAMI","name":"Sami","text":"Okay. Now, let's put the blanket on the grass.","audio":"g3/u4/l3/03.mp3"},{"sp":"GRANDPA","name":"Grandpa","text":"Good. Next, open the basket. What's inside, Noor?","audio":"g3/u4/l3/04.mp3"},{"sp":"NOOR","name":"Noor","text":"There are sandwiches, oranges and a bottle of water.","audio":"g3/u4/l3/05.mp3"},{"sp":"GRANDPA","name":"Grandpa","text":"Let's wash our hands first. Here's some water.","audio":"g3/u4/l3/06.mp3"},{"sp":"SAMI","name":"Sami","text":"Now can we eat?","audio":"g3/u4/l3/07.mp3"},{"sp":"GRANDPA","name":"Grandpa","text":"Yes! Let's eat. Then we can play football.","audio":"g3/u4/l3/08.mp3"},{"sp":"NARRATOR","name":"Narrator","text":"After lunch, they play football. Then they put the rubbish in the bin. What a great day!","audio":"g3/u4/l3/09.mp3"}],"tasks":[{"type":"mcq","q":"Where do they sit?","opts":["under a big tree","on a bench","next to the lake","in the car"],"ans":0},{"type":"mcq","q":"What do they put on the grass?","opts":["a bag","a basket","a ball","a blanket"],"ans":3},{"type":"mcq","q":"What is NOT in the basket?","opts":["cake","sandwiches","oranges","water"],"ans":0},{"type":"mcq","q":"What do they do after lunch?","opts":["go home","play football","sleep","wash their hands"],"ans":1},{"type":"tf","s":"It is a rainy day.","ans":false},{"type":"tf","s":"They wash their hands before they eat.","ans":true},{"type":"tf","s":"They leave the rubbish on the grass.","ans":false},{"type":"order","items":["They find a place under a tree.","They put the blanket on the grass.","They wash their hands.","They play football."]}],"predict":{"en":"Grandpa takes the children for a picnic. What do they do first? What do they do last?","ar":"يأخذ الجد الأطفال في نزهة. ماذا يفعلون أولًا؟ وماذا يفعلون في النهاية؟"},"tip":{"en":"Order words help you: first, next, then, after lunch. Number the actions 1, 2, 3, 4 as you listen.","ar":"كلمات الترتيب تساعدك مثل first وnext وthen وafter lunch. رقّم الأحداث 1، 2، 3، 4 أثناء الاستماع."},"speak":{"prompt":"Tell your partner about a picnic. Use first, then and after that.","frame":"First, we ___. Then, we ___. After that, we ___."},"teach":"Give each group four picture cards of the picnic steps. They put the cards in order while listening, then retell the picnic using \"first, then, after that\". Praise anyone who mentions putting the rubbish in the bin.","id":"g3u4l3","track":"g3/u4/l3/track.mp3"}],"speak":[{"kind":"speak","n":1,"title":"Do You Like...?","func":"Asking about likes and dislikes","func_ar":"السؤال عن الأشياء المحبوبة وغير المحبوبة","kagan":["Find Someone Who","Inside-Outside Circle"],"model":[{"sp":"NOOR","name":"Noor","text":"Lina, do you like pancakes?","audio":"g3/u4/s1/01.mp3"},{"sp":"LINA","name":"Lina","text":"Yes, I do! I love pancakes with honey.","audio":"g3/u4/s1/02.mp3"},{"sp":"NOOR","name":"Noor","text":"Me too! Do you like eggs?","audio":"g3/u4/s1/03.mp3"},{"sp":"LINA","name":"Lina","text":"No, I don't. I don't like eggs.","audio":"g3/u4/s1/04.mp3"},{"sp":"NOOR","name":"Noor","text":"Really? I like eggs very much. What about apples?","audio":"g3/u4/s1/05.mp3"},{"sp":"LINA","name":"Lina","text":"Yes, I do. Red apples are my favorite.","audio":"g3/u4/s1/06.mp3"},{"sp":"NOOR","name":"Noor","text":"Let's have apples and pancakes for our snack!","audio":"g3/u4/s1/07.mp3"},{"sp":"LINA","name":"Lina","text":"Great idea!","audio":"g3/u4/s1/08.mp3"}],"roles":["NOOR","LINA"],"chunks":[{"en":"Do you like ___?","ar":"هل تحب ___؟","audio":"g3/u4/s1/c1.mp3"},{"en":"Yes, I do.","ar":"نعم، أحبه.","audio":"g3/u4/s1/c2.mp3"},{"en":"No, I don't.","ar":"لا، لا أحبه.","audio":"g3/u4/s1/c3.mp3"},{"en":"___ is my favorite.","ar":"___ هو المفضّل لديّ.","audio":"g3/u4/s1/c4.mp3"},{"en":"Great idea!","ar":"فكرة رائعة!","audio":"g3/u4/s1/c5.mp3"}],"sound":{"type":"pairs","title":"/e/ or /æ/?","en":"For /e/ (bed), open your mouth a little. For /æ/ (bad), open your mouth wide and drop your jaw.","ar":"لنطق /e/ كما في bed افتح فمك قليلًا، ولنطق /æ/ كما في bad افتح فمك واسعًا وأنزل فكّك.","pairs":[["bed","bad"],["pen","pan"],["men","man"],["said","sad"],["head","had"]],"audio":[["g3/u4/s1/p1a.mp3","g3/u4/s1/p1b.mp3"],["g3/u4/s1/p2a.mp3","g3/u4/s1/p2b.mp3"],["g3/u4/s1/p3a.mp3","g3/u4/s1/p3b.mp3"],["g3/u4/s1/p4a.mp3","g3/u4/s1/p4b.mp3"],["g3/u4/s1/p5a.mp3","g3/u4/s1/p5b.mp3"]]},"task":{"prompt":"Make a class food survey. Ask five friends about three foods.","frame":"Do you like ___? — Yes, I do. / No, I don't."},"cando":["I can ask about likes.","I can answer \"Yes, I do\" or \"No, I don't\".","I can hear /e/ and /æ/."],"teach":"Put a finger under your chin: your jaw drops more for /æ/ than for /e/. Students check their own jaws as they repeat bed–bad.","id":"g3u4s1","track":"g3/u4/s1/track.mp3"},{"kind":"speak","n":2,"title":"I'd Like a Sandwich, Please","func":"Ordering food politely","func_ar":"طلب الطعام بأدب","kagan":["Fan-N-Pick","Mix-Pair-Share"],"model":[{"sp":"MAN","name":"Waiter","text":"Hello! Are you ready to order?","audio":"g3/u4/s2/01.mp3"},{"sp":"SAMI","name":"Sami","text":"Yes, please. I'd like a chicken sandwich, please.","audio":"g3/u4/s2/02.mp3"},{"sp":"MAN","name":"Waiter","text":"Anything else?","audio":"g3/u4/s2/03.mp3"},{"sp":"SAMI","name":"Sami","text":"And a small salad, please.","audio":"g3/u4/s2/04.mp3"},{"sp":"MAN","name":"Waiter","text":"Would you like a drink?","audio":"g3/u4/s2/05.mp3"},{"sp":"SAMI","name":"Sami","text":"Yes. A strawberry juice, please.","audio":"g3/u4/s2/06.mp3"},{"sp":"MAN","name":"Waiter","text":"Okay. A chicken sandwich, a small salad and a strawberry juice. Is that all?","audio":"g3/u4/s2/07.mp3"},{"sp":"SAMI","name":"Sami","text":"Yes, thank you.","audio":"g3/u4/s2/08.mp3"},{"sp":"MAN","name":"Waiter","text":"That's twenty-five riyals, please.","audio":"g3/u4/s2/09.mp3"},{"sp":"SAMI","name":"Sami","text":"Here you are.","audio":"g3/u4/s2/10.mp3"}],"roles":["SAMI","MAN"],"chunks":[{"en":"I'd like ___, please.","ar":"أريد ___ من فضلك.","audio":"g3/u4/s2/c1.mp3"},{"en":"Anything else?","ar":"هل تريد شيئًا آخر؟","audio":"g3/u4/s2/c2.mp3"},{"en":"Would you like a drink?","ar":"هل تريد مشروبًا؟","audio":"g3/u4/s2/c3.mp3"},{"en":"Is that all?","ar":"هل هذا كل شيء؟","audio":"g3/u4/s2/c4.mp3"},{"en":"That's twenty riyals.","ar":"المبلغ عشرون ريالًا.","audio":"g3/u4/s2/c5.mp3"}],"sound":{"type":"sort","title":"How many beats?","cats":[{"key":"1","label":"1 beat"},{"key":"2","label":"2 beats"},{"key":"3","label":"3 beats"}],"en":"Some English words start with two consonants, like \"sn\" or \"str\". Don't add a vowel before them: say \"snack\", not \"isnack\" or \"sinack\". Listen and count the beats.","ar":"تبدأ بعض الكلمات الإنجليزية بحرفين ساكنين مثل sn أو str. لا تضف حركة قبلهما: قل snack وليس isnack أو sinack. استمع وعدّ المقاطع.","items":[{"text":"snack","key":"1","audio":"g3/u4/s2/i1.mp3"},{"text":"salad","key":"2","audio":"g3/u4/s2/i2.mp3"},{"text":"strawberry","key":"3","audio":"g3/u4/s2/i3.mp3"},{"text":"spoon","key":"1","audio":"g3/u4/s2/i4.mp3"},{"text":"sandwich","key":"2","audio":"g3/u4/s2/i5.mp3"},{"text":"tomato","key":"3","audio":"g3/u4/s2/i6.mp3"},{"text":"plate","key":"1","audio":"g3/u4/s2/i7.mp3"},{"text":"smoothie","key":"2","audio":"g3/u4/s2/i8.mp3"},{"text":"banana","key":"3","audio":"g3/u4/s2/i9.mp3"}]},"task":{"prompt":"Role-play a café. One student is the waiter and one is the customer. Then change roles.","frame":"I'd like ___, please. — Anything else? — ___. — That's ___ riyals."},"cando":["I can order food politely.","I can answer \"Anything else?\"","I can say words that start with two consonants."],"teach":"Set up a \"café\" with a menu card and toy money. Students take turns as waiter and customer; the waiter must repeat the order back, just like in the model.","id":"g3u4s2","track":"g3/u4/s2/track.mp3"}],"check":[{"type":"mcq","q":"What does Ben ask about?","ref":"L1#8","opts":["drinks","dessert","lunch boxes","carrots"],"ans":1,"audio":"g3/u4/l1/08.mp3","line":"What's for dessert?","speaker":"Ben"},{"type":"mcq","q":"What does Sami drink?","ref":"L2#8","opts":["water","milk","tea","orange juice"],"ans":3,"audio":"g3/u4/l2/08.mp3","line":"Orange juice, please.","speaker":"Sami"},{"type":"mcq","q":"What day is it?","ref":"L3#1","opts":["Sunday","Monday","Friday","Saturday"],"ans":3,"audio":"g3/u4/l3/01.mp3","line":"It's a sunny Saturday. Grandpa takes Sami and Noor to the park.","speaker":"Narrator"},{"type":"mcq","q":"What fruit is in the basket?","ref":"L3#5","opts":["bananas","oranges","apples","grapes"],"ans":1,"audio":"g3/u4/l3/05.mp3","line":"There are sandwiches, oranges and a bottle of water.","speaker":"Noor"}],"id":"g3u4"},{"n":5,"title":"Animals Around Us","ar":"الحيوانات من حولنا","emoji":"🐘","goals":["I can describe animals.","I can talk about what animals and people can do.","I can understand information about a pet."],"listen":[{"kind":"listen","n":1,"title":"At the Zoo","skill":"Listening to descriptions","skill_ar":"الاستماع إلى الأوصاف","kagan":["Showdown","Think-Pair-Share"],"vocab":[{"w":"zoo","ar":"حديقة الحيوانات","emoji":"🦁","ex":"We visit the zoo.","audio":"g3/u5/l1/v1.mp3"},{"w":"giraffe","ar":"زرافة","emoji":"🦒","ex":"The giraffe is very tall.","audio":"g3/u5/l1/v2.mp3"},{"w":"elephant","ar":"فيل","emoji":"🐘","ex":"The elephant has big ears.","audio":"g3/u5/l1/v3.mp3"},{"w":"tiger","ar":"نمر","emoji":"🐯","ex":"The tiger has stripes.","audio":"g3/u5/l1/v4.mp3"},{"w":"monkey","ar":"قرد","emoji":"🐒","ex":"The monkey loves bananas.","audio":"g3/u5/l1/v5.mp3"},{"w":"neck","ar":"رقبة","emoji":"🦒","ex":"It has a long neck.","audio":"g3/u5/l1/v6.mp3"}],"script":[{"sp":"MAN","name":"Zookeeper","text":"Welcome to the zoo, everyone! I'm Mr. Khalid, the zookeeper. Let's see some animals.","audio":"g3/u5/l1/01.mp3"},{"sp":"MAN","name":"Zookeeper","text":"Look at this animal. It's very tall. It has a long neck and brown spots.","audio":"g3/u5/l1/02.mp3"},{"sp":"SAMI","name":"Sami","text":"It's a giraffe!","audio":"g3/u5/l1/03.mp3"},{"sp":"MAN","name":"Zookeeper","text":"That's right. It eats leaves from the tall trees. Now look over there. This animal is big and grey. It has big ears and a long nose.","audio":"g3/u5/l1/04.mp3"},{"sp":"ADAM","name":"Adam","text":"An elephant!","audio":"g3/u5/l1/05.mp3"},{"sp":"MAN","name":"Zookeeper","text":"Yes! And this animal is orange and black. It has stripes. Be careful — it's very strong!","audio":"g3/u5/l1/06.mp3"},{"sp":"BEN","name":"Ben","text":"It's a tiger!","audio":"g3/u5/l1/07.mp3"},{"sp":"MAN","name":"Zookeeper","text":"Good! The last animal is small and funny. It can climb trees and it loves bananas.","audio":"g3/u5/l1/08.mp3"},{"sp":"SAMI","name":"Sami","text":"A monkey! Can we give it a banana?","audio":"g3/u5/l1/09.mp3"},{"sp":"MAN","name":"Zookeeper","text":"No, sorry. Please don't feed the animals.","audio":"g3/u5/l1/10.mp3"}],"tasks":[{"type":"mcq","q":"Which animal has a long neck?","opts":["the tiger","the monkey","the elephant","the giraffe"],"ans":3},{"type":"mcq","q":"What color is the elephant?","opts":["orange","grey","brown","black"],"ans":1},{"type":"mcq","q":"Which animal has stripes?","opts":["the giraffe","the elephant","the tiger","the monkey"],"ans":2},{"type":"mcq","q":"Why can't Sami give the monkey a banana?","opts":["The monkey is sleeping.","Sami has no bananas.","The monkey doesn't like bananas.","The zookeeper says, \"Don't feed the animals.\""],"ans":3},{"type":"tf","s":"The giraffe eats leaves.","ans":true},{"type":"tf","s":"The monkey is big and grey.","ans":false},{"type":"tf","s":"The zookeeper's name is Mr. Khalid.","ans":true},{"type":"order","items":["the giraffe","the elephant","the tiger","the monkey"]}],"predict":{"en":"A zookeeper describes four animals. Can you guess them before the children do?","ar":"يصف حارس حديقة الحيوانات أربعة حيوانات. هل تستطيع أن تخمّنها قبل الأطفال؟"},"tip":{"en":"Listen for describing words: tall, big, small, long, and colors. Guess the animal before you hear its name!","ar":"استمع لكلمات الوصف مثل tall وbig وsmall وlong والألوان، وخمّن الحيوان قبل أن تسمع اسمه!"},"speak":{"prompt":"Choose an animal. Describe it. Your partner guesses.","frame":"It's ___. It has ___. What is it?"},"teach":"Pause the track after each description (lines 2, 4, 6 and 8) and let teams show their guess on mini-whiteboards before the children in the audio say it.","id":"g3u5l1","track":"g3/u5/l1/track.mp3"},{"kind":"listen","n":2,"title":"Animal Quiz","skill":"Listening for abilities","skill_ar":"الاستماع إلى القدرات","kagan":["Numbered Heads Together","Showdown"],"vocab":[{"w":"fly","ar":"يطير","emoji":"🕊️","ex":"A penguin can't fly.","audio":"g3/u5/l2/v1.mp3"},{"w":"swim","ar":"يسبح","emoji":"🏊","ex":"It can swim very well.","audio":"g3/u5/l2/v2.mp3"},{"w":"run","ar":"يركض","emoji":"🏃","ex":"A camel can run fast.","audio":"g3/u5/l2/v3.mp3"},{"w":"jump","ar":"يقفز","emoji":"🦘","ex":"A kangaroo can jump high.","audio":"g3/u5/l2/v4.mp3"},{"w":"climb","ar":"يتسلّق","emoji":"🧗","ex":"A fish can't climb.","audio":"g3/u5/l2/v5.mp3"},{"w":"camel","ar":"جمل","emoji":"🐪","ex":"The camel lives in the desert.","audio":"g3/u5/l2/v6.mp3"}],"script":[{"sp":"WOMAN","name":"Presenter","text":"Welcome to Animal Quiz! Today, Adam and Ben are here. Are you ready, boys?","audio":"g3/u5/l2/01.mp3"},{"sp":"ADAM","name":"Adam","text":"Yes, we are!","audio":"g3/u5/l2/02.mp3"},{"sp":"WOMAN","name":"Presenter","text":"First question, Adam. Can a penguin fly?","audio":"g3/u5/l2/03.mp3"},{"sp":"ADAM","name":"Adam","text":"No, it can't. But it can swim very well.","audio":"g3/u5/l2/04.mp3"},{"sp":"WOMAN","name":"Presenter","text":"Correct! One point for Adam. Ben, here's your question. Can a camel run fast?","audio":"g3/u5/l2/05.mp3"},{"sp":"BEN","name":"Ben","text":"Yes, it can! A camel can run fast, and it can walk for many days with no water.","audio":"g3/u5/l2/06.mp3"},{"sp":"WOMAN","name":"Presenter","text":"Excellent! One point for Ben. Adam, which animal can jump very high and has a pocket for its baby?","audio":"g3/u5/l2/07.mp3"},{"sp":"ADAM","name":"Adam","text":"A kangaroo!","audio":"g3/u5/l2/08.mp3"},{"sp":"WOMAN","name":"Presenter","text":"Yes! Two points for Adam. Last question, Ben. Can a fish climb trees?","audio":"g3/u5/l2/09.mp3"},{"sp":"BEN","name":"Ben","text":"Ha ha! No, it can't! A fish can't climb.","audio":"g3/u5/l2/10.mp3"},{"sp":"WOMAN","name":"Presenter","text":"Correct! Adam has two points and Ben has two points. It's a draw!","audio":"g3/u5/l2/11.mp3"}],"tasks":[{"type":"mcq","q":"What can a penguin do very well?","opts":["climb","jump","swim","fly"],"ans":2},{"type":"mcq","q":"What can a camel do?","opts":["climb trees","jump very high","walk for many days with no water","fly over the desert"],"ans":2},{"type":"mcq","q":"Which animal has a pocket for its baby?","opts":["a penguin","a kangaroo","a camel","a monkey"],"ans":1},{"type":"mcq","q":"Who wins the quiz?","opts":["the presenter","Nobody. It's a draw.","Ben","Adam"],"ans":1},{"type":"tf","s":"A penguin can fly.","ans":false},{"type":"tf","s":"Adam answers the kangaroo question.","ans":true},{"type":"tf","s":"Ben gets three points.","ans":false},{"type":"order","items":["the penguin question","the camel question","the kangaroo question","the fish question"]}],"predict":{"en":"Two boys are in a TV animal quiz. What questions do you think they hear?","ar":"ولدان يشاركان في مسابقة تلفزيونية عن الحيوانات. ما الأسئلة التي تتوقع أنهما يسمعانها؟"},"tip":{"en":"\"Can\" means yes, \"can't\" means no. \"Can't\" is long and strong.","ar":"can تعني نعم يستطيع، وcan't تعني لا يستطيع وتُنطق طويلة وقوية."},"speak":{"prompt":"Ask your partner three \"Can a ...?\" quiz questions about animals.","frame":"Can a ___ ___? — Yes, it can. / No, it can't."},"teach":"Run the class as a quiz show after listening: two teams, one buzzer. The presenter (a student) reads a \"Can a ...?\" question and the team must answer with \"Yes, it can\" or \"No, it can't\".","id":"g3u5l2","track":"g3/u5/l2/track.mp3"},{"kind":"listen","n":3,"title":"My Pet Parrot","skill":"Listening for specific information","skill_ar":"الاستماع إلى معلومات محددة","kagan":["Three-Step Interview","Talking Chips"],"vocab":[{"w":"pet","ar":"حيوان أليف","emoji":"🐾","ex":"Do you have a pet?","audio":"g3/u5/l3/v1.mp3"},{"w":"parrot","ar":"ببغاء","emoji":"🦜","ex":"My parrot is green.","audio":"g3/u5/l3/v2.mp3"},{"w":"cage","ar":"قفص","emoji":"🏠","ex":"I clean his cage.","audio":"g3/u5/l3/v3.mp3"},{"w":"seeds","ar":"بذور","emoji":"🌻","ex":"He eats seeds.","audio":"g3/u5/l3/v4.mp3"},{"w":"clean","ar":"ينظّف","emoji":"🧹","ex":"We clean the cage on Fridays.","audio":"g3/u5/l3/v5.mp3"},{"w":"fresh water","ar":"ماء نقي","emoji":"💧","ex":"He needs fresh water.","audio":"g3/u5/l3/v6.mp3"}],"script":[{"sp":"YUSUF","name":"Yusuf","text":"Hello, everyone. This is my pet. His name is Kiwi. He's a parrot.","audio":"g3/u5/l3/01.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"Kiwi is green and yellow. He's two years old. He can say three words: hello, Yusuf, and water!","audio":"g3/u5/l3/02.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"Every morning, I give Kiwi food and fresh water. He eats seeds and fruit. His favorite fruit is grapes.","audio":"g3/u5/l3/03.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"On Fridays, I clean his cage with my dad.","audio":"g3/u5/l3/04.mp3"},{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"Thank you, Yusuf. Does Kiwi sleep at night?","audio":"g3/u5/l3/05.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"Yes, he does. We put a blanket on his cage. Then he sleeps.","audio":"g3/u5/l3/06.mp3"},{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"Very interesting. Can he fly?","audio":"g3/u5/l3/07.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"Yes, he can. He flies in my bedroom for one hour every day.","audio":"g3/u5/l3/08.mp3"}],"tasks":[{"type":"mcq","q":"What is Kiwi?","opts":["a cat","a rabbit","a fish","a parrot"],"ans":3},{"type":"mcq","q":"How old is Kiwi?","opts":["four","two","one","three"],"ans":1},{"type":"mcq","q":"What is Kiwi's favorite fruit?","opts":["apples","oranges","bananas","grapes"],"ans":3},{"type":"mcq","q":"When does Yusuf clean the cage?","opts":["on Fridays","every morning","on Mondays","at night"],"ans":0},{"type":"tf","s":"Kiwi can say three words.","ans":true},{"type":"tf","s":"Yusuf cleans the cage with his mom.","ans":false},{"type":"tf","s":"Kiwi flies in the garden every day.","ans":false},{"type":"order","items":["Yusuf says Kiwi's name.","Yusuf talks about Kiwi's food.","Yusuf talks about the cage.","Yusuf says Kiwi can fly."]}],"predict":{"en":"Yusuf talks to his class about his pet. What do you want to know about it?","ar":"يتحدث يوسف إلى زملائه عن حيوانه الأليف. ماذا تريد أن تعرف عنه؟"},"tip":{"en":"Before you listen, read the questions. They tell you what to listen for: age, food, days.","ar":"اقرأ الأسئلة قبل الاستماع؛ فهي تخبرك بما يجب أن تستمع إليه مثل العمر والطعام والأيام."},"speak":{"prompt":"Tell your partner about a pet you have or want.","frame":"My pet is a ___. Its name is ___. It eats ___."},"teach":"Remind students that pets need care every day. After listening, groups make a \"Pet Care Poster\" with three sentences: I give it..., I clean..., It sleeps...","id":"g3u5l3","track":"g3/u5/l3/track.mp3"}],"speak":[{"kind":"speak","n":1,"title":"Guess the Animal","func":"Asking yes/no questions in a game","func_ar":"طرح أسئلة نعم/لا في لعبة","kagan":["Inside-Outside Circle","Fan-N-Pick"],"model":[{"sp":"BEN","name":"Ben","text":"Let's play a guessing game. I'm thinking of an animal.","audio":"g3/u5/s1/01.mp3"},{"sp":"SAMI","name":"Sami","text":"Okay. Is it big?","audio":"g3/u5/s1/02.mp3"},{"sp":"BEN","name":"Ben","text":"Yes, it is. It's very big and it's grey.","audio":"g3/u5/s1/03.mp3"},{"sp":"SAMI","name":"Sami","text":"Does it have a long nose?","audio":"g3/u5/s1/04.mp3"},{"sp":"BEN","name":"Ben","text":"No, it doesn't. It has a big mouth and it lives in the water.","audio":"g3/u5/s1/05.mp3"},{"sp":"SAMI","name":"Sami","text":"Hmm... Is it a hippo?","audio":"g3/u5/s1/06.mp3"},{"sp":"BEN","name":"Ben","text":"Yes! Only three questions. Great job! Now it's your turn.","audio":"g3/u5/s1/07.mp3"},{"sp":"SAMI","name":"Sami","text":"Okay. I'm thinking of a bird. It's thin and pink. It stands on one leg.","audio":"g3/u5/s1/08.mp3"},{"sp":"BEN","name":"Ben","text":"It's a flamingo!","audio":"g3/u5/s1/09.mp3"}],"roles":["BEN","SAMI"],"chunks":[{"en":"I'm thinking of an animal.","ar":"أفكّر في حيوان.","audio":"g3/u5/s1/c1.mp3"},{"en":"Is it big?","ar":"هل هو كبير؟","audio":"g3/u5/s1/c2.mp3"},{"en":"Does it have ___?","ar":"هل لديه ___؟","audio":"g3/u5/s1/c3.mp3"},{"en":"It lives in the water.","ar":"إنه يعيش في الماء.","audio":"g3/u5/s1/c4.mp3"},{"en":"Now it's your turn.","ar":"الآن دورك.","audio":"g3/u5/s1/c5.mp3"}],"sound":{"type":"pairs","title":"/θ/ or /s/?","en":"For /θ/ (think), put your tongue between your teeth and blow gently — like ث in Arabic. For /s/ (sink), keep your tongue behind your teeth.","ar":"لنطق /θ/ كما في think ضع لسانك بين أسنانك وانفخ برفق مثل حرف الثاء، أما /s/ كما في sink فيبقى اللسان خلف الأسنان.","pairs":[["think","sink"],["thick","sick"],["mouth","mouse"],["path","pass"],["thumb","sum"]],"audio":[["g3/u5/s1/p1a.mp3","g3/u5/s1/p1b.mp3"],["g3/u5/s1/p2a.mp3","g3/u5/s1/p2b.mp3"],["g3/u5/s1/p3a.mp3","g3/u5/s1/p3b.mp3"],["g3/u5/s1/p4a.mp3","g3/u5/s1/p4b.mp3"],["g3/u5/s1/p5a.mp3","g3/u5/s1/p5b.mp3"]]},"task":{"prompt":"Play Guess the Animal in your group. Answer only with \"Yes, it is / No, it isn't / Yes, it does / No, it doesn't\".","frame":"Is it ___? Does it have ___? Can it ___?"},"cando":["I can describe an animal.","I can ask yes/no questions in a game.","I can say /θ/ with my tongue between my teeth."],"teach":"Many students change /θ/ to /s/ or /t/. Make it fun: \"Show me your tongue!\" Students must see their partner's tongue tip for every /θ/ word.","id":"g3u5s1","track":"g3/u5/s1/track.mp3"},{"kind":"speak","n":2,"title":"Can You Swim?","func":"Talking about abilities","func_ar":"التحدث عن القدرات","kagan":["Find Someone Who","RallyRobin"],"model":[{"sp":"LINA","name":"Lina","text":"Noor, can you swim?","audio":"g3/u5/s2/01.mp3"},{"sp":"NOOR","name":"Noor","text":"Yes, I can. I swim every week with my mom.","audio":"g3/u5/s2/02.mp3"},{"sp":"LINA","name":"Lina","text":"Wow! I can't swim. But I can ride a bike.","audio":"g3/u5/s2/03.mp3"},{"sp":"NOOR","name":"Noor","text":"Can you ride a bike with no hands?","audio":"g3/u5/s2/04.mp3"},{"sp":"LINA","name":"Lina","text":"Ha ha! No, I can't! Can you draw?","audio":"g3/u5/s2/05.mp3"},{"sp":"NOOR","name":"Noor","text":"Yes, I can. I can draw cats and flowers. Can you?","audio":"g3/u5/s2/06.mp3"},{"sp":"LINA","name":"Lina","text":"No, I can't draw very well. But I can make pancakes with my grandma!","audio":"g3/u5/s2/07.mp3"},{"sp":"NOOR","name":"Noor","text":"Yum! Can you teach me?","audio":"g3/u5/s2/08.mp3"},{"sp":"LINA","name":"Lina","text":"Yes, of course!","audio":"g3/u5/s2/09.mp3"}],"roles":["LINA","NOOR"],"chunks":[{"en":"Can you swim?","ar":"هل تستطيع السباحة؟","audio":"g3/u5/s2/c1.mp3"},{"en":"Yes, I can.","ar":"نعم، أستطيع.","audio":"g3/u5/s2/c2.mp3"},{"en":"No, I can't.","ar":"لا، لا أستطيع.","audio":"g3/u5/s2/c3.mp3"},{"en":"I can ride a bike.","ar":"أستطيع ركوب الدراجة.","audio":"g3/u5/s2/c4.mp3"},{"en":"Can you teach me?","ar":"هل يمكنك أن تعلّمني؟","audio":"g3/u5/s2/c5.mp3"}],"sound":{"type":"pairs","title":"can or can't?","en":"In sentences, \"can\" is short and weak: /kən/. \"Can't\" is long and strong, and it ends with /t/.","ar":"في الجمل تُنطق can قصيرة وضعيفة /kən/، أما can't فتُنطق طويلة وقوية وتنتهي بصوت /t/.","pairs":[["I can swim.","I can't swim."],["She can draw.","She can't draw."],["We can jump.","We can't jump."],["He can cook.","He can't cook."],["They can climb.","They can't climb."]],"audio":[["g3/u5/s2/p1a.mp3","g3/u5/s2/p1b.mp3"],["g3/u5/s2/p2a.mp3","g3/u5/s2/p2b.mp3"],["g3/u5/s2/p3a.mp3","g3/u5/s2/p3b.mp3"],["g3/u5/s2/p4a.mp3","g3/u5/s2/p4b.mp3"],["g3/u5/s2/p5a.mp3","g3/u5/s2/p5b.mp3"]]},"task":{"prompt":"Find Someone Who: walk around and find a friend for each ability.","frame":"Can you ___? — Yes, I can. / No, I can't."},"cando":["I can talk about what I can and can't do.","I can ask \"Can you ...?\"","I can hear the difference between can and can't."],"teach":"Students show an open hand for \"can\" and a closed fist for \"can't\" while they listen. This keeps everyone active and shows you who hears the difference.","id":"g3u5s2","track":"g3/u5/s2/track.mp3"}],"check":[{"type":"mcq","q":"What does the zookeeper say about the tiger?","ref":"L1#6","opts":["It's very small.","It's very tall.","It's very funny.","It's very strong."],"ans":3,"audio":"g3/u5/l1/06.mp3","line":"Yes! And this animal is orange and black. It has stripes. Be careful — it's very strong!","speaker":"Zookeeper"},{"type":"mcq","q":"What does Ben say about a fish?","ref":"L2#10","opts":["It can run fast.","It can fly.","It can't climb.","It can jump high."],"ans":2,"audio":"g3/u5/l2/10.mp3","line":"Ha ha! No, it can't! A fish can't climb.","speaker":"Ben"},{"type":"mcq","q":"What colors is Kiwi?","ref":"L3#2","opts":["green and yellow","green and blue","blue and yellow","red and yellow"],"ans":0,"audio":"g3/u5/l3/02.mp3","line":"Kiwi is green and yellow. He's two years old. He can say three words: hello, Yusuf, and water!","speaker":"Yusuf"},{"type":"mcq","q":"What do they put on the cage at night?","ref":"L3#6","opts":["a bag","a box","a towel","a blanket"],"ans":3,"audio":"g3/u5/l3/06.mp3","line":"Yes, he does. We put a blanket on his cage. Then he sleeps.","speaker":"Yusuf"}],"id":"g3u5"},{"n":6,"title":"My Day","ar":"يومي","emoji":"⏰","goals":["I can talk about my daily routine.","I can ask and say the time.","I can understand days and plans after school."],"listen":[{"kind":"listen","n":1,"title":"Time to Get Up!","skill":"Listening for times","skill_ar":"الاستماع إلى الأوقات","kagan":["Line-Ups","Timed Pair Share"],"vocab":[{"w":"get up","ar":"يستيقظ وينهض","emoji":"⏰","ex":"I get up at six o'clock.","audio":"g3/u6/l1/v1.mp3"},{"w":"get dressed","ar":"يرتدي ملابسه","emoji":"👕","ex":"I wash my face and get dressed.","audio":"g3/u6/l1/v2.mp3"},{"w":"o'clock","ar":"تمامًا (في الساعة)","emoji":"🕖","ex":"The bus comes at seven o'clock.","audio":"g3/u6/l1/v3.mp3"},{"w":"half past","ar":"والنصف","emoji":"🕡","ex":"I have breakfast at half past six.","audio":"g3/u6/l1/v4.mp3"},{"w":"homework","ar":"واجب منزلي","emoji":"📝","ex":"I do my homework after school.","audio":"g3/u6/l1/v5.mp3"},{"w":"go to bed","ar":"يذهب إلى النوم","emoji":"🛌","ex":"I go to bed at nine o'clock.","audio":"g3/u6/l1/v6.mp3"}],"script":[{"sp":"SAMI","name":"Sami","text":"Hi! I'm Sami. Let me tell you about my school day.","audio":"g3/u6/l1/01.mp3"},{"sp":"SAMI","name":"Sami","text":"I get up at six o'clock. I wash my face and get dressed.","audio":"g3/u6/l1/02.mp3"},{"sp":"SAMI","name":"Sami","text":"At half past six, I have breakfast with my family. I usually eat eggs and bread.","audio":"g3/u6/l1/03.mp3"},{"sp":"SAMI","name":"Sami","text":"The school bus comes at seven o'clock. School starts at half past seven.","audio":"g3/u6/l1/04.mp3"},{"sp":"SAMI","name":"Sami","text":"We have lunch at twelve o'clock. I get home at two o'clock.","audio":"g3/u6/l1/05.mp3"},{"sp":"SAMI","name":"Sami","text":"After that, I do my homework and play with Noor.","audio":"g3/u6/l1/06.mp3"},{"sp":"SAMI","name":"Sami","text":"I have dinner at seven o'clock, and I go to bed at nine o'clock. Good night!","audio":"g3/u6/l1/07.mp3"}],"tasks":[{"type":"mcq","q":"What time does Sami get up?","opts":["at six o'clock","at half past six","at seven o'clock","at nine o'clock"],"ans":0},{"type":"mcq","q":"When does Sami have breakfast?","opts":["at half past seven","at seven o'clock","at six o'clock","at half past six"],"ans":3},{"type":"mcq","q":"How does Sami go to school?","opts":["by bike","by school bus","by car","on foot"],"ans":1},{"type":"mcq","q":"What time does Sami go to bed?","opts":["at eight o'clock","at seven o'clock","at nine o'clock","at ten o'clock"],"ans":2},{"type":"tf","s":"School starts at seven o'clock.","ans":false},{"type":"tf","s":"Sami gets home at two o'clock.","ans":true},{"type":"tf","s":"Sami plays with Noor after his homework.","ans":true},{"type":"order","items":["Sami gets up.","Sami has breakfast.","Sami does his homework.","Sami goes to bed."]}],"predict":{"en":"Sami tells us about his school day. What time do you think he gets up?","ar":"يحدثنا سامي عن يومه الدراسي. في أي ساعة تتوقع أنه يستيقظ؟"},"tip":{"en":"Times come after \"at\": at six o'clock, at half past six. Draw the clock hands as you listen.","ar":"يأتي الوقت بعد كلمة at مثل at six o'clock. ارسم عقارب الساعة أثناء الاستماع."},"speak":{"prompt":"Tell your partner three times in your day.","frame":"I get up at ___. I have lunch at ___. I go to bed at ___."},"teach":"Give each student a paper clock with movable hands. They show each time as they hear it; you can see at a glance who is following.","id":"g3u6l1","track":"g3/u6/l1/track.mp3"},{"kind":"listen","n":2,"title":"After School","skill":"Listening for days and plans","skill_ar":"الاستماع إلى الأيام والخطط","kagan":["RallyRobin","Mix-Pair-Share"],"vocab":[{"w":"after school","ar":"بعد المدرسة","emoji":"🏫","ex":"Can you play after school?","audio":"g3/u6/l2/v1.mp3"},{"w":"library","ar":"مكتبة","emoji":"📚","ex":"I go to the library on Sunday.","audio":"g3/u6/l2/v2.mp3"},{"w":"swimming lessons","ar":"دروس السباحة","emoji":"🏊","ex":"I have swimming lessons on Monday.","audio":"g3/u6/l2/v3.mp3"},{"w":"visit","ar":"يزور","emoji":"👵","ex":"I visit my grandma.","audio":"g3/u6/l2/v4.mp3"},{"w":"free","ar":"متفرّغ / غير مشغول","emoji":"🙌","ex":"Are you free on Wednesday?","audio":"g3/u6/l2/v5.mp3"},{"w":"week","ar":"أسبوع","emoji":"📅","ex":"I'm busy this week.","audio":"g3/u6/l2/v6.mp3"}],"script":[{"sp":"BEN","name":"Ben","text":"Adam, can you play after school this week?","audio":"g3/u6/l2/01.mp3"},{"sp":"ADAM","name":"Adam","text":"Let me think. On Sunday, I go to the library with my brother.","audio":"g3/u6/l2/02.mp3"},{"sp":"BEN","name":"Ben","text":"What about Monday?","audio":"g3/u6/l2/03.mp3"},{"sp":"ADAM","name":"Adam","text":"On Monday, I have swimming lessons. And on Tuesday, I visit my grandma.","audio":"g3/u6/l2/04.mp3"},{"sp":"BEN","name":"Ben","text":"Oh. Are you free on Wednesday?","audio":"g3/u6/l2/05.mp3"},{"sp":"ADAM","name":"Adam","text":"Yes! I'm free on Wednesday. Let's play football in the park.","audio":"g3/u6/l2/06.mp3"},{"sp":"BEN","name":"Ben","text":"Great! What time?","audio":"g3/u6/l2/07.mp3"},{"sp":"ADAM","name":"Adam","text":"At four o'clock. Is that okay?","audio":"g3/u6/l2/08.mp3"},{"sp":"BEN","name":"Ben","text":"Yes, that's perfect. See you on Wednesday at four!","audio":"g3/u6/l2/09.mp3"}],"tasks":[{"type":"mcq","q":"Where does Adam go on Sunday?","opts":["to the park","to his grandma's house","to swimming lessons","to the library"],"ans":3},{"type":"mcq","q":"When does Adam have swimming lessons?","opts":["on Sunday","on Wednesday","on Monday","on Tuesday"],"ans":2},{"type":"mcq","q":"What do the boys want to do on Wednesday?","opts":["go to the library","visit Grandma","play football in the park","go swimming"],"ans":2},{"type":"mcq","q":"What time do they meet?","opts":["at four o'clock","at three o'clock","at two o'clock","at five o'clock"],"ans":0},{"type":"tf","s":"Adam goes to the library with his brother.","ans":true},{"type":"tf","s":"Adam visits his grandma on Monday.","ans":false},{"type":"tf","s":"Ben and Adam meet on Thursday.","ans":false},{"type":"order","items":["Sunday: the library","Monday: swimming lessons","Tuesday: Grandma","Wednesday: football"]}],"predict":{"en":"Ben wants to play with Adam after school, but Adam is busy. Which day is good for them?","ar":"يريد بن أن يلعب مع آدم بعد المدرسة، لكن آدم مشغول. أي يوم يناسبهما؟"},"tip":{"en":"Make a little chart in your notebook: Sunday, Monday, Tuesday, Wednesday. Write one activity for each day.","ar":"ارسم في دفترك قائمة بالأيام: الأحد، الاثنين، الثلاثاء، الأربعاء، واكتب نشاطًا واحدًا لكل يوم."},"speak":{"prompt":"Tell your partner what you do after school on two days.","frame":"On ___, I ___. On ___, I ___."},"teach":"Ask students to draw a five-day \"After School\" diary (Sunday to Thursday). Partners compare diaries and find one free day they share, just like Ben and Adam.","id":"g3u6l2","track":"g3/u6/l2/track.mp3"},{"kind":"listen","n":3,"title":"A Busy Saturday","skill":"Listening for sequence words","skill_ar":"الاستماع إلى كلمات التسلسل","kagan":["Line-Ups","Numbered Heads Together"],"vocab":[{"w":"busy","ar":"مشغول","emoji":"🏃","ex":"Saturday is my busy day.","audio":"g3/u6/l3/v1.mp3"},{"w":"tidy","ar":"يرتّب","emoji":"🧹","ex":"I tidy my bedroom.","audio":"g3/u6/l3/v2.mp3"},{"w":"first","ar":"أولًا","emoji":"1️⃣","ex":"First, I tidy my room.","audio":"g3/u6/l3/v3.mp3"},{"w":"then","ar":"ثم","emoji":"➡️","ex":"Then, I help Mom.","audio":"g3/u6/l3/v4.mp3"},{"w":"mall","ar":"مركز تسوّق","emoji":"🛍️","ex":"We go to the mall.","audio":"g3/u6/l3/v5.mp3"},{"w":"tired","ar":"متعب","emoji":"😴","ex":"I'm very tired!","audio":"g3/u6/l3/v6.mp3"}],"script":[{"sp":"NOOR","name":"Noor","text":"Saturday is my busy day! First, I tidy my bedroom. I put my toys in the box.","audio":"g3/u6/l3/01.mp3"},{"sp":"NOOR","name":"Noor","text":"Then, I help Mom in the kitchen. We make pizza for lunch.","audio":"g3/u6/l3/02.mp3"},{"sp":"NOOR","name":"Noor","text":"After lunch, I read a story with Grandpa. Today the story is about a clever fox.","audio":"g3/u6/l3/03.mp3"},{"sp":"NOOR","name":"Noor","text":"In the afternoon, we go to the mall. I buy a new notebook for school.","audio":"g3/u6/l3/04.mp3"},{"sp":"NOOR","name":"Noor","text":"In the evening, I call my friend Lina. We talk for a long time!","audio":"g3/u6/l3/05.mp3"},{"sp":"NOOR","name":"Noor","text":"Then I have a bath, and I go to bed early. I'm very tired!","audio":"g3/u6/l3/06.mp3"}],"tasks":[{"type":"mcq","q":"What does Noor do first?","opts":["She makes pizza.","She tidies her bedroom.","She reads a story.","She goes to the mall."],"ans":1},{"type":"mcq","q":"What do Noor and Mom make?","opts":["a cake","sandwiches","pizza","pancakes"],"ans":2},{"type":"mcq","q":"What is the story about?","opts":["a small cat","a big tiger","a clever fox","a funny monkey"],"ans":2},{"type":"mcq","q":"What does Noor buy?","opts":["a bag","a notebook","a story book","a toy"],"ans":1},{"type":"tf","s":"Noor reads with Grandpa after lunch.","ans":true},{"type":"tf","s":"Noor goes to the mall in the morning.","ans":false},{"type":"tf","s":"Noor goes to bed late.","ans":false},{"type":"order","items":["She tidies her bedroom.","She helps Mom in the kitchen.","She goes to the mall.","She calls Lina."]}],"predict":{"en":"Noor says Saturday is her busy day. What do you think she does?","ar":"تقول نور إن يوم السبت هو يومها المزدحم. ماذا تتوقع أنها تفعل فيه؟"},"tip":{"en":"Listen for time words that start each sentence: first, then, after lunch, in the afternoon, in the evening.","ar":"استمع لكلمات الزمن في بداية كل جملة مثل first وthen وafter lunch وin the afternoon وin the evening."},"speak":{"prompt":"Tell your partner about your Saturday. Use first and then.","frame":"First, I ___. Then, I ___. In the evening, I ___."},"teach":"Mime each activity (tidying, cooking, reading, shopping, phoning) and let students say the sequence word that goes with it. Then they retell Noor's day in the correct order.","id":"g3u6l3","track":"g3/u6/l3/track.mp3"}],"speak":[{"kind":"speak","n":1,"title":"What Time Is It?","func":"Asking and telling the time","func_ar":"السؤال عن الوقت والإخبار به","kagan":["Quiz-Quiz-Trade","Inside-Outside Circle"],"model":[{"sp":"SAMI","name":"Sami","text":"Excuse me, Dad. What time is it?","audio":"g3/u6/s1/01.mp3"},{"sp":"DAD","name":"Dad","text":"It's half past three.","audio":"g3/u6/s1/02.mp3"},{"sp":"SAMI","name":"Sami","text":"Oh no! My chess club starts at four o'clock.","audio":"g3/u6/s1/03.mp3"},{"sp":"DAD","name":"Dad","text":"Don't worry. It's close. Put on your shoes.","audio":"g3/u6/s1/04.mp3"},{"sp":"SAMI","name":"Sami","text":"Where's my watch?","audio":"g3/u6/s1/05.mp3"},{"sp":"DAD","name":"Dad","text":"It's on the chair in the kitchen.","audio":"g3/u6/s1/06.mp3"},{"sp":"SAMI","name":"Sami","text":"Got it! What time do we leave?","audio":"g3/u6/s1/07.mp3"},{"sp":"DAD","name":"Dad","text":"In ten minutes.","audio":"g3/u6/s1/08.mp3"},{"sp":"SAMI","name":"Sami","text":"Okay. I'm ready, Dad! Let's go!","audio":"g3/u6/s1/09.mp3"}],"roles":["SAMI","DAD"],"chunks":[{"en":"What time is it?","ar":"كم الساعة؟","audio":"g3/u6/s1/c1.mp3"},{"en":"It's three o'clock.","ar":"الساعة الثالثة تمامًا.","audio":"g3/u6/s1/c2.mp3"},{"en":"It's half past three.","ar":"الساعة الثالثة والنصف.","audio":"g3/u6/s1/c3.mp3"},{"en":"What time do we leave?","ar":"متى نغادر؟","audio":"g3/u6/s1/c4.mp3"},{"en":"I'm ready!","ar":"أنا جاهز!","audio":"g3/u6/s1/c5.mp3"}],"sound":{"type":"pairs","title":"/tʃ/ or /ʃ/?","en":"/tʃ/ (chair) starts with a stop, like \"t\" + \"sh\": ch! /ʃ/ (share) is a long soft sound with no stop: shhh.","ar":"يبدأ /tʃ/ كما في chair بوقفة قصيرة مثل t ثم sh، أما /ʃ/ كما في share فصوت ناعم ممتد بلا وقفة مثل الشين.","pairs":[["chair","share"],["watch","wash"],["chip","ship"],["cheap","sheep"],["catch","cash"]],"audio":[["g3/u6/s1/p1a.mp3","g3/u6/s1/p1b.mp3"],["g3/u6/s1/p2a.mp3","g3/u6/s1/p2b.mp3"],["g3/u6/s1/p3a.mp3","g3/u6/s1/p3b.mp3"],["g3/u6/s1/p4a.mp3","g3/u6/s1/p4b.mp3"],["g3/u6/s1/p5a.mp3","g3/u6/s1/p5b.mp3"]]},"task":{"prompt":"Draw five clocks with different times. Ask your partner \"What time is it?\"","frame":"What time is it? — It's ___ o'clock. / It's half past ___."},"cando":["I can ask and say the time.","I can use \"o'clock\" and \"half past\".","I can say /tʃ/ and /ʃ/ clearly."],"teach":"For /tʃ/, students put their hand in front of their mouth and feel a quick \"explosion\" of air. For /ʃ/, the air flows softly like a long \"shhh\".","id":"g3u6s1","track":"g3/u6/s1/track.mp3"},{"kind":"speak","n":2,"title":"My Dad's Day","func":"Talking about another person's routine","func_ar":"التحدث عن روتين شخص آخر","kagan":["Three-Step Interview","RoundRobin"],"model":[{"sp":"ADAM","name":"Adam","text":"Ben, what does your dad do?","audio":"g3/u6/s2/01.mp3"},{"sp":"BEN","name":"Ben","text":"He's a pilot. He flies big planes.","audio":"g3/u6/s2/02.mp3"},{"sp":"ADAM","name":"Adam","text":"Wow! What time does he get up?","audio":"g3/u6/s2/03.mp3"},{"sp":"BEN","name":"Ben","text":"He gets up very early, at five o'clock.","audio":"g3/u6/s2/04.mp3"},{"sp":"ADAM","name":"Adam","text":"Five o'clock! Does he have breakfast?","audio":"g3/u6/s2/05.mp3"},{"sp":"BEN","name":"Ben","text":"Yes, he does. He drinks coffee and eats toast. Then he drives to the airport.","audio":"g3/u6/s2/06.mp3"},{"sp":"ADAM","name":"Adam","text":"When does he come home?","audio":"g3/u6/s2/07.mp3"},{"sp":"BEN","name":"Ben","text":"He comes home late. Sometimes he watches the news and then goes to bed.","audio":"g3/u6/s2/08.mp3"},{"sp":"ADAM","name":"Adam","text":"He's very busy!","audio":"g3/u6/s2/09.mp3"}],"roles":["ADAM","BEN"],"chunks":[{"en":"What does your dad do?","ar":"ماذا يعمل والدك؟","audio":"g3/u6/s2/c1.mp3"},{"en":"What time does he get up?","ar":"متى يستيقظ؟","audio":"g3/u6/s2/c2.mp3"},{"en":"He gets up at five o'clock.","ar":"يستيقظ في الساعة الخامسة.","audio":"g3/u6/s2/c3.mp3"},{"en":"Does he have breakfast?","ar":"هل يتناول الفطور؟","audio":"g3/u6/s2/c4.mp3"},{"en":"He comes home late.","ar":"يعود إلى البيت متأخرًا.","audio":"g3/u6/s2/c5.mp3"}],"sound":{"type":"sort","title":"He gets, he goes, he watches: /s/, /z/ or /ɪz/?","cats":[{"key":"/s/","label":"/s/ gets"},{"key":"/z/","label":"/z/ goes"},{"key":"/ɪz/","label":"/ɪz/ watches"}],"en":"Verbs with he, she and it end in -s. Like plurals, this -s has three sounds.","ar":"الأفعال مع he وshe وit تنتهي بـ -s، ولهذه النهاية ثلاثة أصوات مثل الجمع: /s/ و/z/ و/ɪz/.","items":[{"text":"eats","key":"/s/","audio":"g3/u6/s2/i1.mp3"},{"text":"plays","key":"/z/","audio":"g3/u6/s2/i2.mp3"},{"text":"washes","key":"/ɪz/","audio":"g3/u6/s2/i3.mp3"},{"text":"walks","key":"/s/","audio":"g3/u6/s2/i4.mp3"},{"text":"reads","key":"/z/","audio":"g3/u6/s2/i5.mp3"},{"text":"catches","key":"/ɪz/","audio":"g3/u6/s2/i6.mp3"},{"text":"sleeps","key":"/s/","audio":"g3/u6/s2/i7.mp3"},{"text":"drives","key":"/z/","audio":"g3/u6/s2/i8.mp3"},{"text":"fixes","key":"/ɪz/","audio":"g3/u6/s2/i9.mp3"}]},"task":{"prompt":"Interview a partner about someone in his family. Then tell the group.","frame":"What time does your ___ get up? — He gets up at ___. He ___ every day."},"cando":["I can talk about my day.","I can talk about another person's day.","I can say he/she -s endings."],"teach":"Remind students that \"he gets\" needs the -s. A fun signal: students hiss like a snake \"sss\" or buzz like a bee \"zzz\" when they hear the ending.","id":"g3u6s2","track":"g3/u6/s2/track.mp3"}],"check":[{"type":"mcq","q":"What does Sami usually eat for breakfast?","ref":"L1#3","opts":["eggs and bread","eggs and rice","cheese and bread","bread and honey"],"ans":0,"audio":"g3/u6/l1/03.mp3","line":"At half past six, I have breakfast with my family. I usually eat eggs and bread.","speaker":"Sami"},{"type":"mcq","q":"What time does Sami have lunch?","ref":"L1#5","opts":["at two o'clock","at one o'clock","at twelve o'clock","at seven o'clock"],"ans":2,"audio":"g3/u6/l1/05.mp3","line":"We have lunch at twelve o'clock. I get home at two o'clock.","speaker":"Sami"},{"type":"mcq","q":"What does Ben say at the end?","ref":"L2#9","opts":["See you on Wednesday at four!","See you on Monday!","Let's go to the library!","I'm not free."],"ans":0,"audio":"g3/u6/l2/09.mp3","line":"Yes, that's perfect. See you on Wednesday at four!","speaker":"Ben"},{"type":"mcq","q":"Where does Noor put her toys?","ref":"L3#1","opts":["on the shelf","in the box","in her bag","under the bed"],"ans":1,"audio":"g3/u6/l3/01.mp3","line":"Saturday is my busy day! First, I tidy my bedroom. I put my toys in the box.","speaker":"Noor"}],"id":"g3u6"}],"level":"A1","band":"Sky","speed":0.88},{"grade":4,"units":[{"n":1,"title":"People Around Us","ar":"الناس من حولنا","emoji":"🧑‍🤝‍🧑","goals":["I can describe what people look like and what they are like.","I can say what people are doing now.","I can understand people talking about neighbors and family."],"listen":[{"kind":"listen","n":1,"title":"Which One Is Sami?","skill":"Listening to identify people","skill_ar":"الاستماع لتحديد الأشخاص","kagan":["Showdown","RallyRobin"],"vocab":[{"w":"tall","ar":"طويل القامة","emoji":"📏","ex":"Yusuf is tall.","audio":"g4/u1/l1/v1.mp3"},{"w":"glasses","ar":"نظارة","emoji":"👓","ex":"He wears glasses.","audio":"g4/u1/l1/v2.mp3"},{"w":"short hair","ar":"شعر قصير","emoji":"💇","ex":"Sami has short black hair.","audio":"g4/u1/l1/v3.mp3"},{"w":"cap","ar":"قبعة","emoji":"🧢","ex":"Adam always wears a cap.","audio":"g4/u1/l1/v4.mp3"},{"w":"smile","ar":"ابتسامة","emoji":"😊","ex":"He has a big smile.","audio":"g4/u1/l1/v5.mp3"},{"w":"wave","ar":"يلوّح بيده","emoji":"👋","ex":"He's waving at us.","audio":"g4/u1/l1/v6.mp3"}],"script":[{"sp":"WOMAN","name":"Ben's Mom","text":"Ben, which boy is your best friend, Sami?","audio":"g4/u1/l1/01.mp3"},{"sp":"BEN","name":"Ben","text":"Look, Mom. He's over there, next to the gate.","audio":"g4/u1/l1/02.mp3"},{"sp":"WOMAN","name":"Ben's Mom","text":"There are three boys next to the gate. Is he the tall boy with glasses?","audio":"g4/u1/l1/03.mp3"},{"sp":"BEN","name":"Ben","text":"No, that's Yusuf. Sami isn't very tall. He has short black hair and brown eyes.","audio":"g4/u1/l1/04.mp3"},{"sp":"WOMAN","name":"Ben's Mom","text":"Is he the boy with the red cap?","audio":"g4/u1/l1/05.mp3"},{"sp":"BEN","name":"Ben","text":"No, that's Adam. Adam always wears a cap. Sami has a big smile. He's wearing a blue jacket, and he's carrying a green bag.","audio":"g4/u1/l1/06.mp3"},{"sp":"WOMAN","name":"Ben's Mom","text":"Oh, I can see him now. He's waving at us!","audio":"g4/u1/l1/07.mp3"},{"sp":"BEN","name":"Ben","text":"Yes! Hi, Sami! Mom, can Sami come to our house on Thursday?","audio":"g4/u1/l1/08.mp3"},{"sp":"WOMAN","name":"Ben's Mom","text":"Of course he can. Let's ask his mom.","audio":"g4/u1/l1/09.mp3"}],"tasks":[{"type":"mcq","q":"Where are the three boys?","opts":["in the playground","on the bus","next to the gate","in the classroom"],"ans":2},{"type":"mcq","q":"Who is the tall boy with glasses?","opts":["Sami","Ben","Adam","Yusuf"],"ans":3},{"type":"mcq","q":"What does Sami look like?","opts":["long brown hair","tall with glasses","red cap and long hair","short black hair and brown eyes"],"ans":3},{"type":"mcq","q":"What is Sami wearing?","opts":["glasses","a blue jacket","a green jacket","a red cap"],"ans":1},{"type":"tf","s":"Sami is very tall.","ans":false},{"type":"tf","s":"Adam always wears a cap.","ans":true},{"type":"gap","s":"Ben wants Sami to come to his house on ___.","ans":["Thursday"]},{"type":"order","items":["Ben's mom asks about Sami.","They talk about Yusuf.","They talk about Adam.","Sami waves at them."]}],"predict":{"en":"Ben's mom wants to know which boy is Sami. How can Ben describe him?","ar":"تريد والدة بن أن تعرف من هو سامي. كيف يمكن أن يصفه بن؟"},"tip":{"en":"Listen for \"has\" and \"is\": He has short hair. He is tall. Each detail helps you find the right person.","ar":"استمع لكلمتي has وis مثل: He has short hair وHe is tall. كل تفصيل يساعدك على معرفة الشخص الصحيح."},"speak":{"prompt":"Describe a classmate. Your partner guesses who it is.","frame":"He has ___ hair. He's ___. He's wearing ___."},"teach":"Before listening, show drawings of three boys and ask \"Who has glasses? Who has a cap?\" This pre-teaches the exact language of the task. Remind students to describe kindly — never make fun of how someone looks.","id":"g4u1l1","track":"g4/u1/l1/track.mp3"},{"kind":"listen","n":2,"title":"Our Neighbors","skill":"Listening for jobs and personality","skill_ar":"الاستماع إلى المهن والصفات الشخصية","kagan":["Timed Pair Share","Talking Chips"],"vocab":[{"w":"neighbor","ar":"جار","emoji":"🏘️","ex":"Mr. Saleh is our neighbor.","audio":"g4/u1/l2/v1.mp3"},{"w":"next door","ar":"في البيت المجاور","emoji":"🚪","ex":"He lives next door.","audio":"g4/u1/l2/v2.mp3"},{"w":"baker","ar":"خبّاز","emoji":"🥖","ex":"The baker makes fresh bread.","audio":"g4/u1/l2/v3.mp3"},{"w":"nurse","ar":"ممرّضة / ممرّض","emoji":"🩺","ex":"She's a nurse at the hospital.","audio":"g4/u1/l2/v4.mp3"},{"w":"kind","ar":"لطيف وطيّب","emoji":"💛","ex":"He's very kind.","audio":"g4/u1/l2/v5.mp3"},{"w":"jokes","ar":"نكات","emoji":"😂","ex":"He tells funny jokes.","audio":"g4/u1/l2/v6.mp3"}],"script":[{"sp":"LINA","name":"Lina","text":"Noor, who lives next door to you?","audio":"g4/u1/l2/01.mp3"},{"sp":"NOOR","name":"Noor","text":"Mr. Saleh lives next door. He's a baker. Every morning, he gives us fresh bread. He's very kind.","audio":"g4/u1/l2/02.mp3"},{"sp":"LINA","name":"Lina","text":"That's nice! Who lives across the street?","audio":"g4/u1/l2/03.mp3"},{"sp":"NOOR","name":"Noor","text":"Mrs. Huda. She's a nurse at the hospital. She works at night, so we play quietly in the afternoon.","audio":"g4/u1/l2/04.mp3"},{"sp":"LINA","name":"Lina","text":"Oh, I see. Is there anyone funny on your street?","audio":"g4/u1/l2/05.mp3"},{"sp":"NOOR","name":"Noor","text":"Yes! Uncle Majed. He's a taxi driver. He tells funny jokes, and he knows every street in Taif!","audio":"g4/u1/l2/06.mp3"},{"sp":"LINA","name":"Lina","text":"Ha ha! Who is your favorite neighbor?","audio":"g4/u1/l2/07.mp3"},{"sp":"NOOR","name":"Noor","text":"Old Mrs. Amal. She's eighty years old. She has a beautiful garden with roses. On Saturdays, I help her water the flowers.","audio":"g4/u1/l2/08.mp3"}],"tasks":[{"type":"mcq","q":"What is Mr. Saleh's job?","opts":["baker","farmer","nurse","taxi driver"],"ans":0},{"type":"mcq","q":"Why do the children play quietly in the afternoon?","opts":["Mrs. Huda works at night.","Mr. Saleh is busy.","Mrs. Amal is sick.","Uncle Majed is driving."],"ans":0},{"type":"mcq","q":"What does Uncle Majed tell?","opts":["stories about roses","the time","the news","funny jokes"],"ans":3},{"type":"mcq","q":"How old is Mrs. Amal?","opts":["ninety","seventy","eighty","eighteen"],"ans":2},{"type":"tf","s":"Mr. Saleh gives the family fresh bread.","ans":true},{"type":"tf","s":"Noor helps Mrs. Amal on Fridays.","ans":false},{"type":"gap","s":"Mrs. Amal has a beautiful garden with ___.","ans":["roses"]},{"type":"order","items":["Mr. Saleh","Mrs. Huda","Uncle Majed","Mrs. Amal"]}],"predict":{"en":"Noor talks about her neighbors. What jobs can neighbors have?","ar":"تتحدث نور عن جيرانها. ما المهن التي يمكن أن يعمل بها الجيران؟"},"tip":{"en":"Listen for \"He's a...\" or \"She's a...\" for jobs, and words like kind or funny for personality.","ar":"استمع إلى He's a... وShe's a... لمعرفة المهنة، وإلى كلمات مثل kind وfunny لمعرفة الصفات."},"speak":{"prompt":"Tell your partner about one neighbor or one person on your street.","frame":"___ lives ___. He's/She's a ___. He's/She's very ___."},"teach":"Question 2 needs a small inference: Mrs. Huda works at night, so she sleeps in the day. Ask \"Why quietly?\" and let students explain in English or Arabic. Discuss being good neighbors, a value we share.","id":"g4u1l2","track":"g4/u1/l2/track.mp3"},{"kind":"listen","n":3,"title":"A Family Photo","skill":"Listening for actions happening now","skill_ar":"الاستماع إلى أفعال تحدث الآن","kagan":["Fan-N-Pick","Think-Pair-Share"],"vocab":[{"w":"beach","ar":"شاطئ","emoji":"🏖️","ex":"We're at the beach.","audio":"g4/u1/l3/v1.mp3"},{"w":"barbecue","ar":"شواية","emoji":"🍖","ex":"Dad is cooking fish on the barbecue.","audio":"g4/u1/l3/v2.mp3"},{"w":"umbrella","ar":"مظلّة","emoji":"⛱️","ex":"He's reading under the umbrella.","audio":"g4/u1/l3/v3.mp3"},{"w":"sandcastle","ar":"قلعة رملية","emoji":"🏰","ex":"They're building a sandcastle.","audio":"g4/u1/l3/v4.mp3"},{"w":"take a photo","ar":"يلتقط صورة","emoji":"📸","ex":"I'm taking the photo.","audio":"g4/u1/l3/v5.mp3"},{"w":"ice cream","ar":"آيس كريم (مثلّجات)","emoji":"🍦","ex":"Fahd is eating ice cream.","audio":"g4/u1/l3/v6.mp3"}],"script":[{"sp":"BEN","name":"Ben","text":"Sami, is this the photo from your family trip to Jeddah?","audio":"g4/u1/l3/01.mp3"},{"sp":"SAMI","name":"Sami","text":"Yes! We're at the beach. Look, my dad is cooking fish on the barbecue.","audio":"g4/u1/l3/02.mp3"},{"sp":"BEN","name":"Ben","text":"And who is that? The man who is reading a book under the umbrella?","audio":"g4/u1/l3/03.mp3"},{"sp":"SAMI","name":"Sami","text":"That's my uncle Faisal. He's always reading!","audio":"g4/u1/l3/04.mp3"},{"sp":"BEN","name":"Ben","text":"Ha ha. What are Noor and Lina doing?","audio":"g4/u1/l3/05.mp3"},{"sp":"SAMI","name":"Sami","text":"They're building a big sandcastle. Lina is Noor's best friend. She came with us.","audio":"g4/u1/l3/06.mp3"},{"sp":"BEN","name":"Ben","text":"And where are you?","audio":"g4/u1/l3/07.mp3"},{"sp":"SAMI","name":"Sami","text":"I'm not in this photo. I'm taking the photo! But Fahd is here. He's sitting with Mom, and he's eating ice cream.","audio":"g4/u1/l3/08.mp3"},{"sp":"BEN","name":"Ben","text":"It looks like a great day!","audio":"g4/u1/l3/09.mp3"},{"sp":"SAMI","name":"Sami","text":"It was!","audio":"g4/u1/l3/10.mp3"}],"tasks":[{"type":"mcq","q":"Where is Sami's family in the photo?","opts":["at Grandpa's farm","at the beach in Jeddah","at a park in Taif","at a restaurant"],"ans":1},{"type":"mcq","q":"What is Dad doing?","opts":["swimming","cooking fish","reading a book","taking a photo"],"ans":1},{"type":"mcq","q":"Who is reading under the umbrella?","opts":["Sami","Grandpa","Dad","Uncle Faisal"],"ans":3},{"type":"mcq","q":"Why isn't Sami in the photo?","opts":["He's at home.","He's swimming.","He's taking the photo.","He's eating."],"ans":2},{"type":"tf","s":"Noor and Lina are building a sandcastle.","ans":true},{"type":"tf","s":"Fahd is sitting with Mom.","ans":true},{"type":"gap","s":"Fahd is eating ___.","ans":["ice cream","an ice cream"]},{"type":"order","items":["Dad","Uncle Faisal","Noor and Lina","Fahd and Mom"]}],"predict":{"en":"Sami shows Ben a photo of a family day. What are the people doing?","ar":"يُري سامي صديقه بن صورة من يوم عائلي. ماذا يفعل الأشخاص في الصورة؟"},"tip":{"en":"Actions happening now use -ing: cooking, reading, building. Listen for the person, then the -ing word.","ar":"الأفعال التي تحدث الآن تنتهي بـ -ing مثل cooking وreading. استمع إلى اسم الشخص ثم إلى الفعل المنتهي بـ -ing."},"speak":{"prompt":"Bring or draw a family photo. Tell your partner what each person is doing.","frame":"In this photo, my ___ is ___ing. My ___ is ___ing."},"teach":"Show a busy picture (a beach or a park) and play \"I spy someone who is ...ing\" before listening. It activates the -ing form and the vocabulary at the same time.","id":"g4u1l3","track":"g4/u1/l3/track.mp3"}],"speak":[{"kind":"speak","n":1,"title":"Who's That?","func":"Describing people","func_ar":"وصف الأشخاص","kagan":["Inside-Outside Circle","Three-Step Interview"],"model":[{"sp":"ADAM","name":"Adam","text":"Ben, who are those boys in the picture?","audio":"g4/u1/s1/01.mp3"},{"sp":"BEN","name":"Ben","text":"They're my cousins from London. This is Harry and that's Jack.","audio":"g4/u1/s1/02.mp3"},{"sp":"ADAM","name":"Adam","text":"They look the same! Are they twins?","audio":"g4/u1/s1/03.mp3"},{"sp":"BEN","name":"Ben","text":"Yes, they are. But Harry has curly hair and Jack has straight hair.","audio":"g4/u1/s1/04.mp3"},{"sp":"ADAM","name":"Adam","text":"Oh, I see. And who is the girl with them?","audio":"g4/u1/s1/05.mp3"},{"sp":"BEN","name":"Ben","text":"That's their sister, Emma. She's thirteen.","audio":"g4/u1/s1/06.mp3"},{"sp":"ADAM","name":"Adam","text":"What are they like?","audio":"g4/u1/s1/07.mp3"},{"sp":"BEN","name":"Ben","text":"They're really funny and friendly. They're coming to Taif next month!","audio":"g4/u1/s1/08.mp3"},{"sp":"ADAM","name":"Adam","text":"That's great!","audio":"g4/u1/s1/09.mp3"}],"roles":["ADAM","BEN"],"chunks":[{"en":"Who's that?","ar":"من ذاك؟","audio":"g4/u1/s1/c1.mp3"},{"en":"He has curly hair.","ar":"لديه شعر مجعّد.","audio":"g4/u1/s1/c2.mp3"},{"en":"She has straight hair.","ar":"لديها شعر مستقيم.","audio":"g4/u1/s1/c3.mp3"},{"en":"What are they like?","ar":"كيف هي شخصياتهم؟","audio":"g4/u1/s1/c4.mp3"},{"en":"They look the same.","ar":"إنهم يبدون متشابهين.","audio":"g4/u1/s1/c5.mp3"}],"sound":{"type":"pairs","title":"/ð/ or /d/?","en":"For /ð/ (they), put your tongue between your teeth and use your voice — like ذ in Arabic. For /d/ (day), your tongue touches the place behind your top teeth.","ar":"لنطق /ð/ كما في they ضع لسانك بين أسنانك مع إخراج الصوت مثل حرف الذال، أما /d/ كما في day فيلمس اللسان ما خلف الأسنان العليا.","pairs":[["they","day"],["then","den"],["those","doze"],["there","dare"],["though","dough"]],"audio":[["g4/u1/s1/p1a.mp3","g4/u1/s1/p1b.mp3"],["g4/u1/s1/p2a.mp3","g4/u1/s1/p2b.mp3"],["g4/u1/s1/p3a.mp3","g4/u1/s1/p3b.mp3"],["g4/u1/s1/p4a.mp3","g4/u1/s1/p4b.mp3"],["g4/u1/s1/p5a.mp3","g4/u1/s1/p5b.mp3"]]},"task":{"prompt":"Bring a photo of people you know (or a picture from a magazine). Describe two people to your partner.","frame":"This is ___. He/She has ___ hair and ___ eyes. He/She is very ___."},"cando":["I can describe what people look like.","I can describe what people are like.","I can say /ð/ in this, that and they."],"teach":"The Arabic letter ذ is a perfect anchor for /ð/. Write \"ذ = this, that, they, those\" on the board and keep it there for the whole unit.","id":"g4u1s1","track":"g4/u1/s1/track.mp3"},{"kind":"speak","n":2,"title":"What Are You Doing?","func":"Talking about actions now","func_ar":"التحدث عن أفعال تحدث الآن","kagan":["Mix-Freeze-Group","RallyRobin"],"model":[{"sp":"MOM","name":"Mom","text":"Hi, Sami. It's Mom. I'm at the supermarket. What's everyone doing?","audio":"g4/u1/s2/01.mp3"},{"sp":"SAMI","name":"Sami","text":"Hi, Mom! Noor is doing her homework in her room.","audio":"g4/u1/s2/02.mp3"},{"sp":"MOM","name":"Mom","text":"Good. And Fahd?","audio":"g4/u1/s2/03.mp3"},{"sp":"SAMI","name":"Sami","text":"He's sleeping. Grandpa is watching him.","audio":"g4/u1/s2/04.mp3"},{"sp":"MOM","name":"Mom","text":"And what are you doing?","audio":"g4/u1/s2/05.mp3"},{"sp":"SAMI","name":"Sami","text":"I'm helping Dad. We're washing the car!","audio":"g4/u1/s2/06.mp3"},{"sp":"MOM","name":"Mom","text":"Wow, thank you! Do you need anything from the supermarket?","audio":"g4/u1/s2/07.mp3"},{"sp":"SAMI","name":"Sami","text":"Yes, please. Can you buy some apples?","audio":"g4/u1/s2/08.mp3"},{"sp":"MOM","name":"Mom","text":"Okay. See you soon!","audio":"g4/u1/s2/09.mp3"}],"roles":["MOM","SAMI"],"chunks":[{"en":"What's everyone doing?","ar":"ماذا يفعل الجميع؟","audio":"g4/u1/s2/c1.mp3"},{"en":"She's doing her homework.","ar":"إنها تحلّ واجبها.","audio":"g4/u1/s2/c2.mp3"},{"en":"He's sleeping.","ar":"إنه نائم.","audio":"g4/u1/s2/c3.mp3"},{"en":"We're washing the car.","ar":"نحن نغسل السيارة.","audio":"g4/u1/s2/c4.mp3"},{"en":"See you soon!","ar":"أراك قريبًا!","audio":"g4/u1/s2/c5.mp3"}],"sound":{"type":"pairs","title":"/ŋ/ or /n/?","en":"For /ŋ/ (sing), the back of your tongue touches the top of your mouth and the sound goes through your nose. Don't add /g/ at the end: say \"sing\", not \"sing-g\".","ar":"لنطق /ŋ/ كما في sing يلمس مؤخر اللسان سقف الفم ويخرج الصوت من الأنف. لا تضف صوت /g/ في النهاية: قل sing وليس sing-g.","pairs":[["thing","thin"],["sing","sin"],["wing","win"],["rang","ran"],["bang","ban"]],"audio":[["g4/u1/s2/p1a.mp3","g4/u1/s2/p1b.mp3"],["g4/u1/s2/p2a.mp3","g4/u1/s2/p2b.mp3"],["g4/u1/s2/p3a.mp3","g4/u1/s2/p3b.mp3"],["g4/u1/s2/p4a.mp3","g4/u1/s2/p4b.mp3"],["g4/u1/s2/p5a.mp3","g4/u1/s2/p5b.mp3"]]},"task":{"prompt":"Mime an action. Your group asks questions to guess it.","frame":"Are you ___ing? — Yes, I am. / No, I'm not."},"cando":["I can say what people are doing now.","I can ask \"What are you doing?\"","I can say -ing without adding /g/."],"teach":"Students hum \"nnn\" and then \"ŋŋŋ\" with their mouths open — the tongue moves back for /ŋ/. Keep the ending soft: no /g/ \"kick\" at the end.","id":"g4u1s2","track":"g4/u1/s2/track.mp3"}],"check":[{"type":"mcq","q":"What color is Sami's bag?","ref":"L1#6","opts":["blue","green","red","black"],"ans":1,"audio":"g4/u1/l1/06.mp3","line":"No, that's Adam. Adam always wears a cap. Sami has a big smile. He's wearing a blue jacket, and he's carrying a green bag.","speaker":"Ben"},{"type":"mcq","q":"What does Ben's mom want to do?","ref":"L1#9","opts":["buy a cap","ask Sami's mom","drive Sami home","call Sami's dad"],"ans":1,"audio":"g4/u1/l1/09.mp3","line":"Of course he can. Let's ask his mom.","speaker":"Ben's Mom"},{"type":"mcq","q":"What does Uncle Majed know?","ref":"L2#6","opts":["every street in Taif","every school in Taif","every shop in Jeddah","every baker in Taif"],"ans":0,"audio":"g4/u1/l2/06.mp3","line":"Yes! Uncle Majed. He's a taxi driver. He tells funny jokes, and he knows every street in Taif!","speaker":"Noor"},{"type":"mcq","q":"Who is Lina?","ref":"L3#6","opts":["Uncle Faisal's daughter","Ben's sister","Noor's best friend","Sami's cousin"],"ans":2,"audio":"g4/u1/l3/06.mp3","line":"They're building a big sandcastle. Lina is Noor's best friend. She came with us.","speaker":"Sami"}],"id":"g4u1"},{"n":2,"title":"Around My Town","ar":"في مدينتي","emoji":"🏙️","goals":["I can name places in town.","I can ask for and follow directions.","I can understand announcements with times and floors."],"listen":[{"kind":"listen","n":1,"title":"Where Are They Going?","skill":"Listening for clues","skill_ar":"الاستماع إلى الدلائل","kagan":["Numbered Heads Together","Showdown"],"vocab":[{"w":"library","ar":"مكتبة","emoji":"📚","ex":"I need books from the library.","audio":"g4/u2/l1/v1.mp3"},{"w":"dentist","ar":"طبيب أسنان","emoji":"🦷","ex":"I need to see the dentist.","audio":"g4/u2/l1/v2.mp3"},{"w":"supermarket","ar":"سوبرماركت","emoji":"🏬","ex":"We buy food at the supermarket.","audio":"g4/u2/l1/v3.mp3"},{"w":"trolley","ar":"عربة التسوّق","emoji":"🛒","ex":"Let's take a trolley.","audio":"g4/u2/l1/v4.mp3"},{"w":"mosque","ar":"مسجد","emoji":"🕌","ex":"Let's walk to the mosque.","audio":"g4/u2/l1/v5.mp3"},{"w":"museum","ar":"متحف","emoji":"🏛️","ex":"The museum has dinosaur bones.","audio":"g4/u2/l1/v6.mp3"}],"script":[{"sp":"NARRATOR","name":"Narrator","text":"Listen to five people. Where is each person going?","audio":"g4/u2/l1/01.mp3"},{"sp":"NARRATOR","name":"Narrator","text":"Number one.","audio":"g4/u2/l1/02.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"Mom, I need some books for my project. Can we go there after school? It's quiet, and there are thousands of books.","audio":"g4/u2/l1/03.mp3"},{"sp":"NARRATOR","name":"Narrator","text":"Number two.","audio":"g4/u2/l1/04.mp3"},{"sp":"DAD","name":"Dad","text":"I have a bad toothache. I need to see the dentist at ten o'clock.","audio":"g4/u2/l1/05.mp3"},{"sp":"NARRATOR","name":"Narrator","text":"Number three.","audio":"g4/u2/l1/06.mp3"},{"sp":"LINA","name":"Lina","text":"We need bread, milk and some vegetables for dinner. Let's take a trolley.","audio":"g4/u2/l1/07.mp3"},{"sp":"NARRATOR","name":"Narrator","text":"Number four.","audio":"g4/u2/l1/08.mp3"},{"sp":"GRANDPA","name":"Grandpa","text":"It's almost time for the Dhuhr prayer. Let's walk there together, Sami.","audio":"g4/u2/l1/09.mp3"},{"sp":"NARRATOR","name":"Narrator","text":"Number five.","audio":"g4/u2/l1/10.mp3"},{"sp":"ADAM","name":"Adam","text":"I want to see the old swords and the dinosaur bones. Is it open on Saturday?","audio":"g4/u2/l1/11.mp3"}],"tasks":[{"type":"mcq","q":"Where is Yusuf going?","opts":["to the museum","to school","to the library","to the bookshop"],"ans":2},{"type":"mcq","q":"Where is Dad going?","opts":["to the hospital","to the dentist","to work","to the pharmacy"],"ans":1},{"type":"mcq","q":"Where is Lina going?","opts":["to the supermarket","to the bakery","to the market","to a restaurant"],"ans":0},{"type":"mcq","q":"Where are Grandpa and Sami going?","opts":["to the park","to the farm","to the market","to the mosque"],"ans":3},{"type":"tf","s":"Dad has a stomachache.","ans":false},{"type":"tf","s":"Adam wants to see old swords and dinosaur bones.","ans":true},{"type":"gap","s":"Adam wants to visit on ___.","ans":["Saturday"]},{"type":"order","items":["the library","the dentist","the supermarket","the mosque"]}],"predict":{"en":"Five people are going to different places in town. What places in town can you name?","ar":"خمسة أشخاص يذهبون إلى أماكن مختلفة في المدينة. ما الأماكن التي تعرف أسماءها؟"},"tip":{"en":"The speakers don't always say the place. Listen for clues: books → library, toothache → dentist.","ar":"لا يذكر المتحدثون اسم المكان دائمًا. استمع إلى الدلائل: books تدل على المكتبة، وtoothache تدل على طبيب الأسنان."},"speak":{"prompt":"Give your partner a clue. Your partner guesses the place.","frame":"I need ___. Where am I going? — You're going to the ___."},"teach":"This is the first inference task in the program. After each item, ask \"Which words helped you?\" and write the clue words on the board next to each place.","id":"g4u2l1","track":"g4/u2/l1/track.mp3"},{"kind":"listen","n":2,"title":"How Do I Get There?","skill":"Following directions","skill_ar":"اتباع الاتجاهات","kagan":["RallyCoach","Stand Up–Hand Up–Pair Up"],"vocab":[{"w":"go straight","ar":"امشِ إلى الأمام","emoji":"⬆️","ex":"Go straight along King Faisal Street.","audio":"g4/u2/l2/v1.mp3"},{"w":"turn left","ar":"انعطف يسارًا","emoji":"⬅️","ex":"Turn left at the park.","audio":"g4/u2/l2/v2.mp3"},{"w":"turn right","ar":"انعطف يمينًا","emoji":"➡️","ex":"Turn right after the mosque.","audio":"g4/u2/l2/v3.mp3"},{"w":"past","ar":"مرورًا بـ","emoji":"🚶","ex":"Walk past the bakery.","audio":"g4/u2/l2/v4.mp3"},{"w":"on the left","ar":"على اليسار","emoji":"👈","ex":"The mosque is on your left.","audio":"g4/u2/l2/v5.mp3"},{"w":"bus stop","ar":"موقف الحافلات","emoji":"🚏","ex":"I'm at the bus stop.","audio":"g4/u2/l2/v6.mp3"}],"script":[{"sp":"BEN","name":"Ben","text":"Hi, Sami. I'm at the bus stop on King Faisal Street. How do I get to your house?","audio":"g4/u2/l2/01.mp3"},{"sp":"SAMI","name":"Sami","text":"Easy! Go straight along King Faisal Street. You can see a big mosque on your left.","audio":"g4/u2/l2/02.mp3"},{"sp":"BEN","name":"Ben","text":"Okay, I can see the mosque.","audio":"g4/u2/l2/03.mp3"},{"sp":"SAMI","name":"Sami","text":"Good. Turn right after the mosque. That's Rose Street.","audio":"g4/u2/l2/04.mp3"},{"sp":"BEN","name":"Ben","text":"Turn right... okay. I'm on Rose Street now.","audio":"g4/u2/l2/05.mp3"},{"sp":"SAMI","name":"Sami","text":"Walk past the bakery and the pharmacy. Then turn left at the park.","audio":"g4/u2/l2/06.mp3"},{"sp":"BEN","name":"Ben","text":"Past the bakery, past the pharmacy, turn left at the park. Done!","audio":"g4/u2/l2/07.mp3"},{"sp":"SAMI","name":"Sami","text":"Our house is the third house on the right. It has a green door.","audio":"g4/u2/l2/08.mp3"},{"sp":"BEN","name":"Ben","text":"I can see it! I'm next to your door now.","audio":"g4/u2/l2/09.mp3"},{"sp":"SAMI","name":"Sami","text":"Great! I'm coming down!","audio":"g4/u2/l2/10.mp3"}],"tasks":[{"type":"mcq","q":"Where is Ben at the start?","opts":["at the mosque","at the park","at the bakery","at the bus stop"],"ans":3},{"type":"mcq","q":"What is on Ben's left on King Faisal Street?","opts":["a bakery","a big mosque","a pharmacy","the park"],"ans":1},{"type":"mcq","q":"Where does Ben turn left?","opts":["at the park","after the mosque","at the bus stop","at the bakery"],"ans":0},{"type":"mcq","q":"Which house is Sami's?","opts":["the third house on the right","the house next to the bakery","the first house on the left","the house next to the park"],"ans":0},{"type":"tf","s":"Ben turns right after the mosque.","ans":true},{"type":"tf","s":"Sami's house has a red door.","ans":false},{"type":"gap","s":"After the mosque, Ben walks along ___ Street.","ans":["Rose"]},{"type":"order","items":["Go straight along King Faisal Street.","Turn right after the mosque.","Walk past the bakery and the pharmacy.","Turn left at the park."]}],"predict":{"en":"Ben is going to Sami's house for the first time. How can Sami help him on the phone?","ar":"يذهب بن إلى بيت سامي لأول مرة. كيف يمكن أن يساعده سامي عبر الهاتف؟"},"tip":{"en":"Use your finger on an imaginary map. Move it every time you hear go, turn, walk or past.","ar":"استخدم إصبعك على خريطة متخيّلة، وحرّكه كلما سمعت go أو turn أو walk أو past."},"speak":{"prompt":"Draw a simple map. Give your partner directions from school to your house.","frame":"Go straight. Turn left/right at the ___. It's on the left/right."},"teach":"Practise left and right physically first: everyone stands and turns when you say \"Turn left!\" Then students draw Ben's route on a simple street map during the second listening.","id":"g4u2l2","track":"g4/u2/l2/track.mp3"},{"kind":"listen","n":3,"title":"A Visit to the Museum","skill":"Listening to announcements","skill_ar":"الاستماع إلى الإعلانات","kagan":["Numbered Heads Together","RoundRobin"],"vocab":[{"w":"visitor","ar":"زائر","emoji":"🧳","ex":"Welcome, visitors!","audio":"g4/u2/l3/v1.mp3"},{"w":"floor","ar":"طابق","emoji":"🏢","ex":"The Space Room is on the first floor.","audio":"g4/u2/l3/v2.mp3"},{"w":"ground floor","ar":"الطابق الأرضي","emoji":"⬇️","ex":"The café is on the ground floor.","audio":"g4/u2/l3/v3.mp3"},{"w":"dinosaur","ar":"ديناصور","emoji":"🦖","ex":"Don't touch the dinosaur bones.","audio":"g4/u2/l3/v4.mp3"},{"w":"free","ar":"مجّاني","emoji":"🆓","ex":"Children can visit for free.","audio":"g4/u2/l3/v5.mp3"},{"w":"Don't touch.","ar":"لا تلمس.","emoji":"🚫","ex":"Please don't touch.","audio":"g4/u2/l3/v6.mp3"}],"script":[{"sp":"ANNOUNCER","name":"Announcer","text":"Good morning, visitors, and welcome to the City Science Museum. We are open today from nine o'clock in the morning until six o'clock in the evening.","audio":"g4/u2/l3/01.mp3"},{"sp":"ANNOUNCER","name":"Announcer","text":"On the first floor, you can see the Space Room. There is a show about the planets at eleven o'clock.","audio":"g4/u2/l3/02.mp3"},{"sp":"ANNOUNCER","name":"Announcer","text":"On the second floor, there is the Dinosaur Room. Please don't touch the dinosaur bones.","audio":"g4/u2/l3/03.mp3"},{"sp":"ANNOUNCER","name":"Announcer","text":"Are you hungry? Our café is on the ground floor, next to the gift shop.","audio":"g4/u2/l3/04.mp3"},{"sp":"ANNOUNCER","name":"Announcer","text":"Today is Family Day, so children under twelve can visit for free!","audio":"g4/u2/l3/05.mp3"},{"sp":"ANNOUNCER","name":"Announcer","text":"The robot show starts at two o'clock in the Science Hall. Don't miss it!","audio":"g4/u2/l3/06.mp3"},{"sp":"ADAM","name":"Adam","text":"Dad, can we see the robot show?","audio":"g4/u2/l3/07.mp3"},{"sp":"DAD","name":"Dad","text":"Yes, Adam. But first, let's go to the Space Room.","audio":"g4/u2/l3/08.mp3"}],"tasks":[{"type":"mcq","q":"What time does the museum close today?","opts":["at eleven o'clock","at six o'clock","at two o'clock","at nine o'clock"],"ans":1},{"type":"mcq","q":"Where is the Dinosaur Room?","opts":["on the ground floor","next to the café","on the second floor","on the first floor"],"ans":2},{"type":"mcq","q":"Who can visit for free today?","opts":["children under twelve","families with babies","children over twelve","everyone"],"ans":0},{"type":"mcq","q":"Where do Adam and Dad go first?","opts":["to the Dinosaur Room","to the Space Room","to the café","to the robot show"],"ans":1},{"type":"tf","s":"The planet show is at twelve o'clock.","ans":false},{"type":"tf","s":"The café is next to the Space Room.","ans":false},{"type":"gap","s":"The robot show starts at ___ o'clock.","ans":["two","2"]},{"type":"order","items":["opening times","the Space Room","the Dinosaur Room","the café"]}],"predict":{"en":"You are visiting a science museum. What information do you need when you arrive?","ar":"أنت تزور متحفًا للعلوم. ما المعلومات التي تحتاجها عند وصولك؟"},"tip":{"en":"Announcements are full of numbers. Write the times and floors as numbers while you listen: 9, 6, 11, 2.","ar":"الإعلانات مليئة بالأرقام. اكتب الأوقات وأرقام الطوابق كأرقام أثناء الاستماع."},"speak":{"prompt":"Make a short announcement for our school. Say the opening times and one rule.","frame":"Welcome to ___. We are open from ___ to ___. Please don't ___."},"teach":"\"Free\" has two meanings: \"not busy\" (Grade 3) and \"no money\" (here). Ask students for one example sentence of each meaning.","id":"g4u2l3","track":"g4/u2/l3/track.mp3"}],"speak":[{"kind":"speak","n":1,"title":"Excuse Me, Where's the Museum?","func":"Asking for directions","func_ar":"السؤال عن الاتجاهات","kagan":["Inside-Outside Circle","RallyCoach"],"model":[{"sp":"SAMI","name":"Sami","text":"Excuse me. Where's the museum, please?","audio":"g4/u2/s1/01.mp3"},{"sp":"MAN","name":"Man","text":"The museum? Go straight and turn left at the hospital.","audio":"g4/u2/s1/02.mp3"},{"sp":"SAMI","name":"Sami","text":"Turn left at the hospital. Is it far?","audio":"g4/u2/s1/03.mp3"},{"sp":"MAN","name":"Man","text":"No, it isn't. It's about five minutes on foot.","audio":"g4/u2/s1/04.mp3"},{"sp":"SAMI","name":"Sami","text":"Is it next to the library?","audio":"g4/u2/s1/05.mp3"},{"sp":"MAN","name":"Man","text":"Yes, it is. It's opposite the bakery, too.","audio":"g4/u2/s1/06.mp3"},{"sp":"SAMI","name":"Sami","text":"Thank you very much!","audio":"g4/u2/s1/07.mp3"},{"sp":"MAN","name":"Man","text":"You're welcome. Enjoy your visit!","audio":"g4/u2/s1/08.mp3"}],"roles":["SAMI","MAN"],"chunks":[{"en":"Excuse me, where's the ___?","ar":"عفوًا، أين ___؟","audio":"g4/u2/s1/c1.mp3"},{"en":"Is it far?","ar":"هل هو بعيد؟","audio":"g4/u2/s1/c2.mp3"},{"en":"It's five minutes on foot.","ar":"إنه على بُعد خمس دقائق سيرًا.","audio":"g4/u2/s1/c3.mp3"},{"en":"It's opposite the bakery.","ar":"إنه مقابل المخبز.","audio":"g4/u2/s1/c4.mp3"},{"en":"Enjoy your visit!","ar":"استمتع بزيارتك!","audio":"g4/u2/s1/c5.mp3"}],"sound":{"type":"sort","title":"HOS-pi-tal or mu-SE-um?","cats":[{"key":"Ooo","label":"Ooo"},{"key":"oOo","label":"oOo"}],"en":"Long words have one strong beat. HOS-pi-tal has it first (Ooo). mu-SE-um has it in the middle (oOo).","ar":"للكلمات الطويلة مقطع قوي واحد. في HOS-pi-tal يكون في البداية (Ooo)، وفي mu-SE-um يكون في الوسط (oOo).","items":[{"text":"hospital","key":"Ooo","audio":"g4/u2/s1/i1.mp3"},{"text":"museum","key":"oOo","audio":"g4/u2/s1/i2.mp3"},{"text":"library","key":"Ooo","audio":"g4/u2/s1/i3.mp3"},{"text":"apartment","key":"oOo","audio":"g4/u2/s1/i4.mp3"},{"text":"bakery","key":"Ooo","audio":"g4/u2/s1/i5.mp3"},{"text":"department","key":"oOo","audio":"g4/u2/s1/i6.mp3"},{"text":"pharmacy","key":"Ooo","audio":"g4/u2/s1/i7.mp3"},{"text":"computer","key":"oOo","audio":"g4/u2/s1/i8.mp3"}]},"task":{"prompt":"Use a town map. Ask your partner for directions to three places.","frame":"Excuse me, where's the ___? — Go straight and turn ___ at the ___. It's opposite the ___."},"cando":["I can ask for directions politely.","I can give simple directions.","I can hear the strong beat in long words."],"teach":"Make a big town map on the classroom floor with tape and paper signs. Students walk the route as their partner gives directions.","id":"g4u2s1","track":"g4/u2/s1/track.mp3"},{"kind":"speak","n":2,"title":"Let's Meet at Eleven","func":"Making plans to meet","func_ar":"وضع خطط للقاء","kagan":["Mix-Pair-Share","Timed Pair Share"],"model":[{"sp":"ADAM","name":"Adam","text":"Ben, do you want to go to the new park on Saturday?","audio":"g4/u2/s2/01.mp3"},{"sp":"BEN","name":"Ben","text":"Yes! What time?","audio":"g4/u2/s2/02.mp3"},{"sp":"ADAM","name":"Adam","text":"Let's meet at ten o'clock.","audio":"g4/u2/s2/03.mp3"},{"sp":"BEN","name":"Ben","text":"Ten is too early for me. How about eleven?","audio":"g4/u2/s2/04.mp3"},{"sp":"ADAM","name":"Adam","text":"Okay, eleven o'clock is fine. Where shall we meet?","audio":"g4/u2/s2/05.mp3"},{"sp":"BEN","name":"Ben","text":"Let's meet at the bus stop near the school.","audio":"g4/u2/s2/06.mp3"},{"sp":"ADAM","name":"Adam","text":"Good idea. Can Sami come too?","audio":"g4/u2/s2/07.mp3"},{"sp":"BEN","name":"Ben","text":"Sure! I'll call him tonight.","audio":"g4/u2/s2/08.mp3"},{"sp":"ADAM","name":"Adam","text":"Great. See you on Saturday!","audio":"g4/u2/s2/09.mp3"}],"roles":["ADAM","BEN"],"chunks":[{"en":"Do you want to ___?","ar":"هل تريد أن ___؟","audio":"g4/u2/s2/c1.mp3"},{"en":"Let's meet at ten.","ar":"لنلتقِ في العاشرة.","audio":"g4/u2/s2/c2.mp3"},{"en":"How about eleven?","ar":"ما رأيك في الحادية عشرة؟","audio":"g4/u2/s2/c3.mp3"},{"en":"Where shall we meet?","ar":"أين نلتقي؟","audio":"g4/u2/s2/c4.mp3"},{"en":"Good idea!","ar":"فكرة جيدة!","audio":"g4/u2/s2/c5.mp3"}],"sound":{"type":"sort","title":"How many words?","cats":[{"key":"3","label":"3 words"},{"key":"4","label":"4 words"},{"key":"5","label":"5 words"}],"en":"In fast speech, English words join together: \"meet at eight\" sounds like one long word. Listen carefully and count the words. (it's = 1 word)","ar":"في الكلام السريع تتصل الكلمات ببعضها، فتبدو meet at eight كأنها كلمة واحدة طويلة. استمع جيدًا وعدّ الكلمات (it's كلمة واحدة).","items":[{"text":"It's at eleven.","key":"3","audio":"g4/u2/s2/i1.mp3"},{"text":"Let's meet at eight.","key":"4","audio":"g4/u2/s2/i2.mp3"},{"text":"Meet me at the park.","key":"5","audio":"g4/u2/s2/i3.mp3"},{"text":"Is it open?","key":"3","audio":"g4/u2/s2/i4.mp3"},{"text":"What time is it?","key":"4","audio":"g4/u2/s2/i5.mp3"},{"text":"Turn left at the end.","key":"5","audio":"g4/u2/s2/i6.mp3"},{"text":"Put it on.","key":"3","audio":"g4/u2/s2/i7.mp3"},{"text":"See you at four.","key":"4","audio":"g4/u2/s2/i8.mp3"},{"text":"Wait for us at noon.","key":"5","audio":"g4/u2/s2/i9.mp3"}]},"task":{"prompt":"Plan a weekend activity with your partner. Agree on a day, a time and a place.","frame":"Do you want to ___? — Yes! What time? — Let's meet at ___. — Where? — At the ___."},"cando":["I can make plans with a friend.","I can suggest a different time.","I can hear words that join together."],"teach":"Write \"meet_at_eight\" with linking marks on the board. Students say it as one smooth word: \"mee-ta-teight\". Linking makes them sound natural and helps them understand fast speech.","id":"g4u2s2","track":"g4/u2/s2/track.mp3"}],"check":[{"type":"mcq","q":"What does Lina want to take?","ref":"L1#7","opts":["a taxi","a basket","a bag","a trolley"],"ans":3,"audio":"g4/u2/l1/07.mp3","line":"We need bread, milk and some vegetables for dinner. Let's take a trolley.","speaker":"Lina"},{"type":"mcq","q":"How do Grandpa and Sami go there?","ref":"L1#9","opts":["They take a taxi.","They take a bus.","They walk.","They drive."],"ans":2,"audio":"g4/u2/l1/09.mp3","line":"It's almost time for the Dhuhr prayer. Let's walk there together, Sami.","speaker":"Grandpa"},{"type":"mcq","q":"What does Sami say at the end?","ref":"L2#10","opts":["I'm coming down!","Ring the bell!","Turn left!","Wait at the park!"],"ans":0,"audio":"g4/u2/l2/10.mp3","line":"Great! I'm coming down!","speaker":"Sami"},{"type":"mcq","q":"What is next to the café?","ref":"L3#4","opts":["the Science Hall","the main door","the Space Room","the gift shop"],"ans":3,"audio":"g4/u2/l3/04.mp3","line":"Are you hungry? Our café is on the ground floor, next to the gift shop.","speaker":"Announcer"}],"id":"g4u2"},{"n":3,"title":"Shopping and Money","ar":"التسوّق والنقود","emoji":"🛍️","goals":["I can ask about prices and understand numbers to 100.","I can buy things and clothes in a shop.","I can understand prices and offers at a market."],"listen":[{"kind":"listen","n":1,"title":"At the Toy Shop","skill":"Listening for prices","skill_ar":"الاستماع إلى الأسعار","kagan":["RallyCoach","Quiz-Quiz-Trade"],"vocab":[{"w":"present","ar":"هدية","emoji":"🎁","ex":"Let's buy a present for Fahd.","audio":"g4/u3/l1/v1.mp3"},{"w":"How much...?","ar":"بكم...؟","emoji":"💰","ex":"How much is the red car?","audio":"g4/u3/l1/v2.mp3"},{"w":"riyal","ar":"ريال","emoji":"💵","ex":"It's thirty-five riyals.","audio":"g4/u3/l1/v3.mp3"},{"w":"puzzle","ar":"أحجية تركيب","emoji":"🧩","ex":"The animal puzzle is cheap.","audio":"g4/u3/l1/v4.mp3"},{"w":"teddy bear","ar":"دبّ دمية","emoji":"🧸","ex":"The teddy bear is forty-two riyals.","audio":"g4/u3/l1/v5.mp3"},{"w":"change","ar":"الباقي (من النقود)","emoji":"🪙","ex":"Here's your change.","audio":"g4/u3/l1/v6.mp3"}],"script":[{"sp":"NOOR","name":"Noor","text":"Sami, we have fifty riyals. Let's buy a present for Fahd.","audio":"g4/u3/l1/01.mp3"},{"sp":"SAMI","name":"Sami","text":"Look at this red car. How much is it?","audio":"g4/u3/l1/02.mp3"},{"sp":"WOMAN","name":"Shop Assistant","text":"The red car is thirty-five riyals.","audio":"g4/u3/l1/03.mp3"},{"sp":"NOOR","name":"Noor","text":"That's a lot. What about the teddy bear?","audio":"g4/u3/l1/04.mp3"},{"sp":"WOMAN","name":"Shop Assistant","text":"The teddy bear is forty-two riyals.","audio":"g4/u3/l1/05.mp3"},{"sp":"SAMI","name":"Sami","text":"Hmm. And the puzzle with the animals?","audio":"g4/u3/l1/06.mp3"},{"sp":"WOMAN","name":"Shop Assistant","text":"It's only eighteen riyals. It's for children aged two to four.","audio":"g4/u3/l1/07.mp3"},{"sp":"NOOR","name":"Noor","text":"Fahd is two now. That's perfect!","audio":"g4/u3/l1/08.mp3"},{"sp":"SAMI","name":"Sami","text":"Can we have the puzzle and a small ball too?","audio":"g4/u3/l1/09.mp3"},{"sp":"WOMAN","name":"Shop Assistant","text":"The small ball is twelve riyals. So that's thirty riyals, please.","audio":"g4/u3/l1/10.mp3"},{"sp":"NOOR","name":"Noor","text":"Here's fifty riyals.","audio":"g4/u3/l1/11.mp3"},{"sp":"WOMAN","name":"Shop Assistant","text":"Thank you. Here's your change: twenty riyals.","audio":"g4/u3/l1/12.mp3"}],"tasks":[{"type":"mcq","q":"How much money do Sami and Noor have?","opts":["fifty riyals","fifteen riyals","thirty riyals","forty riyals"],"ans":0},{"type":"mcq","q":"How much is the teddy bear?","opts":["forty-two riyals","twenty-four riyals","eighteen riyals","thirty-five riyals"],"ans":0},{"type":"mcq","q":"What do they buy?","opts":["the red car","the puzzle and a small ball","the teddy bear and a ball","the red car and a puzzle"],"ans":1},{"type":"mcq","q":"How much change do they get?","opts":["twenty riyals","twelve riyals","eighteen riyals","thirty riyals"],"ans":0},{"type":"tf","s":"The puzzle is for children aged two to four.","ans":true},{"type":"tf","s":"Noor thinks the red car is expensive.","ans":true},{"type":"gap","s":"The small ball costs ___ riyals.","ans":["twelve","12"]},{"type":"order","items":["the red car","the teddy bear","the puzzle","the small ball"]}],"predict":{"en":"Sami and Noor want to buy a present for their little brother. What toys do you think they look at?","ar":"يريد سامي ونور شراء هدية لأخيهما الصغير. ما الألعاب التي تتوقع أنهما ينظران إليها؟"},"tip":{"en":"Prices are big numbers. Listen to both parts: thirty-five = 35, forty-two = 42.","ar":"الأسعار أعداد كبيرة. استمع إلى الجزأين: thirty-five تعني 35، وforty-two تعني 42."},"speak":{"prompt":"Play shop with your partner. Ask about the prices of three things.","frame":"How much is the ___? — It's ___ riyals."},"teach":"Prepare paper riyal notes. After listening, students \"buy\" toys from the board and calculate the change in pairs (RallyCoach). Noor's \"That's a lot\" is a polite way to say something is expensive — teach it as a chunk.","id":"g4u3l1","track":"g4/u3/l1/track.mp3"},{"kind":"listen","n":2,"title":"New Clothes for Eid","skill":"Listening for problems and sizes","skill_ar":"الاستماع إلى المشكلات والمقاسات","kagan":["Three-Step Interview","RallyRobin"],"vocab":[{"w":"thobe","ar":"ثوب","emoji":"👘","ex":"Let's buy you a new thobe.","audio":"g4/u3/l2/v1.mp3"},{"w":"size","ar":"مقاس","emoji":"📐","ex":"What size is he?","audio":"g4/u3/l2/v2.mp3"},{"w":"try on","ar":"يجرّب (ملابس)","emoji":"👕","ex":"Try it on, please.","audio":"g4/u3/l2/v3.mp3"},{"w":"too long","ar":"طويل جدًا","emoji":"📏","ex":"It's too long.","audio":"g4/u3/l2/v4.mp3"},{"w":"sandals","ar":"صندل","emoji":"🩴","ex":"Can I have the brown sandals?","audio":"g4/u3/l2/v5.mp3"},{"w":"changing room","ar":"غرفة القياس","emoji":"🚪","ex":"The changing room is over there.","audio":"g4/u3/l2/v6.mp3"}],"script":[{"sp":"DAD","name":"Dad","text":"Sami, Eid is next week. Let's buy you a new thobe.","audio":"g4/u3/l2/01.mp3"},{"sp":"MAN","name":"Shop Assistant","text":"Good evening. Can I help you?","audio":"g4/u3/l2/02.mp3"},{"sp":"DAD","name":"Dad","text":"Yes, please. We're looking for a white thobe for my son.","audio":"g4/u3/l2/03.mp3"},{"sp":"MAN","name":"Shop Assistant","text":"What size is he?","audio":"g4/u3/l2/04.mp3"},{"sp":"DAD","name":"Dad","text":"I think he's a size forty-eight.","audio":"g4/u3/l2/05.mp3"},{"sp":"MAN","name":"Shop Assistant","text":"Here you are. You can try it on in the changing room.","audio":"g4/u3/l2/06.mp3"},{"sp":"SAMI","name":"Sami","text":"Dad, it's too long. I need a smaller size.","audio":"g4/u3/l2/07.mp3"},{"sp":"MAN","name":"Shop Assistant","text":"Try this one. It's size forty-six.","audio":"g4/u3/l2/08.mp3"},{"sp":"SAMI","name":"Sami","text":"This one is perfect!","audio":"g4/u3/l2/09.mp3"},{"sp":"DAD","name":"Dad","text":"Great. Do you sell sandals too?","audio":"g4/u3/l2/10.mp3"},{"sp":"MAN","name":"Shop Assistant","text":"Yes, the sandals are over there. We have black and brown.","audio":"g4/u3/l2/11.mp3"},{"sp":"SAMI","name":"Sami","text":"Can I have the brown sandals, please?","audio":"g4/u3/l2/12.mp3"},{"sp":"DAD","name":"Dad","text":"Of course. And let's buy a red and white shemagh too.","audio":"g4/u3/l2/13.mp3"}],"tasks":[{"type":"mcq","q":"Why do they buy new clothes?","opts":["Sami has a party.","It's Sami's birthday.","School starts tomorrow.","Eid is next week."],"ans":3},{"type":"mcq","q":"What is the problem with the first thobe?","opts":["It's too long.","It's too short.","It's too expensive.","It's the wrong color."],"ans":0},{"type":"mcq","q":"What size is the perfect thobe?","opts":["fourteen","sixty-four","forty-six","forty-eight"],"ans":2},{"type":"mcq","q":"What color are Sami's new sandals?","opts":["white","black","red","brown"],"ans":3},{"type":"tf","s":"The first thobe is size forty-six.","ans":false},{"type":"tf","s":"Sami tries the thobe on in the changing room.","ans":true},{"type":"gap","s":"Dad also wants to buy a red and white ___.","ans":["shemagh","shimagh"]},{"type":"order","items":["Dad and Sami talk about Eid.","Sami tries on a thobe.","Sami gets a smaller size.","Sami chooses sandals."]}],"predict":{"en":"Eid is coming. Sami and his dad go to a clothes shop. What do they buy?","ar":"العيد قادم، ويذهب سامي ووالده إلى متجر ملابس. ماذا يشتريان؟"},"tip":{"en":"\"Too long\" and \"too big\" mean there is a problem. Listen for \"too\" to find the problem.","ar":"عبارات مثل too long وtoo big تعني وجود مشكلة. استمع لكلمة too لتعرف المشكلة."},"speak":{"prompt":"Tell your partner what you wear for Eid or for a special day.","frame":"For Eid, I wear ___. My favorite is ___."},"teach":"Connect the lesson to students' lives: ask what they wore last Eid. Show \"too\" with real clothes — a big T-shirt on a small student is funny and memorable.","id":"g4u3l2","track":"g4/u3/l2/track.mp3"},{"kind":"listen","n":3,"title":"School Market Day","skill":"Listening for prices and offers","skill_ar":"الاستماع إلى الأسعار والعروض","kagan":["Corners","Numbered Heads Together"],"vocab":[{"w":"sell","ar":"يبيع","emoji":"🏷️","ex":"Ben is selling books.","audio":"g4/u3/l3/v1.mp3"},{"w":"buy","ar":"يشتري","emoji":"🛒","ex":"Buy two books and get one free!","audio":"g4/u3/l3/v2.mp3"},{"w":"each","ar":"لكلّ واحد","emoji":"1️⃣","ex":"They're five riyals each.","audio":"g4/u3/l3/v3.mp3"},{"w":"popular","ar":"مرغوب ومحبوب","emoji":"🌟","ex":"Our cupcakes are very popular.","audio":"g4/u3/l3/v4.mp3"},{"w":"plant","ar":"نبتة","emoji":"🪴","ex":"Small plants are eight riyals.","audio":"g4/u3/l3/v5.mp3"},{"w":"money","ar":"نقود","emoji":"💰","ex":"All the money is for the hospital.","audio":"g4/u3/l3/v6.mp3"}],"script":[{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"Welcome to our School Market Day! All the money is for the children's hospital.","audio":"g4/u3/l3/01.mp3"},{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"At table one, Adam and Yusuf are selling cupcakes. They're five riyals each.","audio":"g4/u3/l3/02.mp3"},{"sp":"ADAM","name":"Adam","text":"Our chocolate cupcakes are very popular! We only have ten left!","audio":"g4/u3/l3/03.mp3"},{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"At table two, Ben is selling old books and comics. Every book is three riyals.","audio":"g4/u3/l3/04.mp3"},{"sp":"BEN","name":"Ben","text":"Buy two books and get one free!","audio":"g4/u3/l3/05.mp3"},{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"At table three, Sami is selling plants. Small plants are eight riyals, and big plants are fifteen riyals.","audio":"g4/u3/l3/06.mp3"},{"sp":"SAMI","name":"Sami","text":"I grew these plants at home with my grandpa!","audio":"g4/u3/l3/07.mp3"},{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"Last year, we made two thousand riyals. Let's make more this year!","audio":"g4/u3/l3/08.mp3"}],"tasks":[{"type":"mcq","q":"Who gets the money?","opts":["the students","the children's hospital","the school library","the teachers"],"ans":1},{"type":"mcq","q":"How much is one cupcake?","opts":["five riyals","eight riyals","fifteen riyals","three riyals"],"ans":0},{"type":"mcq","q":"What is Ben selling?","opts":["old books and comics","cupcakes","plants","toys"],"ans":0},{"type":"mcq","q":"How much is a big plant?","opts":["fifty riyals","eight riyals","five riyals","fifteen riyals"],"ans":3},{"type":"tf","s":"Adam and Yusuf have ten cupcakes left.","ans":true},{"type":"tf","s":"Sami bought his plants at a shop.","ans":false},{"type":"gap","s":"Last year, the school made two ___ riyals.","ans":["thousand"]},{"type":"order","items":["cupcakes","books and comics","plants","last year's money"]}],"predict":{"en":"Your school has a market day. Students sell things to help others. What can they sell?","ar":"لدى مدرستك يوم سوق خيري يبيع فيه الطلاب أشياء لمساعدة الآخرين. ماذا يمكنهم أن يبيعوا؟"},"tip":{"en":"Listen for the word \"each\" after a price: five riyals each means one cupcake costs five riyals.","ar":"استمع لكلمة each بعد السعر: five riyals each تعني أن الواحدة بخمسة ريالات."},"speak":{"prompt":"Plan your own market table. Say what you sell and the price.","frame":"At my table, I'm selling ___. They're ___ riyals each."},"teach":"Link the lesson to the value of giving (charity). Groups plan a pretend charity table and present their prices; the class \"buys\" with paper money and totals the money raised.","id":"g4u3l3","track":"g4/u3/l3/track.mp3"}],"speak":[{"kind":"speak","n":1,"title":"Fifteen or Fifty?","func":"Asking about prices","func_ar":"السؤال عن الأسعار","kagan":["Quiz-Quiz-Trade","RallyCoach"],"model":[{"sp":"NOOR","name":"Noor","text":"Excuse me. How much is this notebook?","audio":"g4/u3/s1/01.mp3"},{"sp":"WOMAN","name":"Shop Assistant","text":"It's fifteen riyals.","audio":"g4/u3/s1/02.mp3"},{"sp":"NOOR","name":"Noor","text":"Fifteen or fifty?","audio":"g4/u3/s1/03.mp3"},{"sp":"WOMAN","name":"Shop Assistant","text":"Fifteen. One, five.","audio":"g4/u3/s1/04.mp3"},{"sp":"NOOR","name":"Noor","text":"Oh, good! And how much are these colored pens?","audio":"g4/u3/s1/05.mp3"},{"sp":"WOMAN","name":"Shop Assistant","text":"They're thirteen riyals for the small box and thirty riyals for the big box.","audio":"g4/u3/s1/06.mp3"},{"sp":"NOOR","name":"Noor","text":"I'd like the small box, please.","audio":"g4/u3/s1/07.mp3"},{"sp":"WOMAN","name":"Shop Assistant","text":"So that's twenty-eight riyals, please.","audio":"g4/u3/s1/08.mp3"},{"sp":"NOOR","name":"Noor","text":"Here you are. Thank you!","audio":"g4/u3/s1/09.mp3"}],"roles":["NOOR","WOMAN"],"chunks":[{"en":"How much is this ___?","ar":"بكم هذا ___؟","audio":"g4/u3/s1/c1.mp3"},{"en":"How much are these?","ar":"بكم هذه؟","audio":"g4/u3/s1/c2.mp3"},{"en":"It's fifteen riyals.","ar":"إنه بخمسة عشر ريالًا.","audio":"g4/u3/s1/c3.mp3"},{"en":"Fifteen or fifty?","ar":"خمسة عشر أم خمسون؟","audio":"g4/u3/s1/c4.mp3"},{"en":"I'd like the small box.","ar":"أريد العلبة الصغيرة.","audio":"g4/u3/s1/c5.mp3"}],"sound":{"type":"pairs","title":"Thirteen or thirty?","en":"In -teen numbers the strong beat is at the end: thir-TEEN. In -ty numbers it is at the start: THIR-ty. Listen for the long \"teen\" and the final /n/.","ar":"في الأعداد المنتهية بـ -teen يكون المقطع القوي في النهاية thir-TEEN، وفي الأعداد المنتهية بـ -ty يكون في البداية THIR-ty. استمع لـ teen الطويلة ولصوت /n/ في آخرها.","pairs":[["thirteen","thirty"],["fourteen","forty"],["fifteen","fifty"],["sixteen","sixty"],["eighteen","eighty"]],"audio":[["g4/u3/s1/p1a.mp3","g4/u3/s1/p1b.mp3"],["g4/u3/s1/p2a.mp3","g4/u3/s1/p2b.mp3"],["g4/u3/s1/p3a.mp3","g4/u3/s1/p3b.mp3"],["g4/u3/s1/p4a.mp3","g4/u3/s1/p4b.mp3"],["g4/u3/s1/p5a.mp3","g4/u3/s1/p5b.mp3"]]},"task":{"prompt":"Make price cards for five things. Your partner asks and writes the prices. Then check together.","frame":"How much is the ___? — It's ___ riyals. — ___ or ___? — ___!"},"cando":["I can ask about prices.","I can check a number I'm not sure about.","I can hear -teen and -ty numbers."],"teach":"Students tap the strong beat on the desk: tap-TAP for thirTEEN, TAP-tap for THIRty. Checking (\"Fifteen or fifty?\") is a real-life skill — praise students who use it.","id":"g4u3s1","track":"g4/u3/s1/track.mp3"},{"kind":"speak","n":2,"title":"Can I Try It On?","func":"Buying clothes","func_ar":"شراء الملابس","kagan":["Fan-N-Pick","Inside-Outside Circle"],"model":[{"sp":"MAN","name":"Shop Assistant","text":"Good afternoon. Can I help you?","audio":"g4/u3/s2/01.mp3"},{"sp":"BEN","name":"Ben","text":"Yes, please. I'm looking for a football shirt.","audio":"g4/u3/s2/02.mp3"},{"sp":"MAN","name":"Shop Assistant","text":"What size are you?","audio":"g4/u3/s2/03.mp3"},{"sp":"BEN","name":"Ben","text":"Small, I think.","audio":"g4/u3/s2/04.mp3"},{"sp":"MAN","name":"Shop Assistant","text":"Here's a small one. Do you like this blue one?","audio":"g4/u3/s2/05.mp3"},{"sp":"BEN","name":"Ben","text":"Yes, I do. Can I try it on?","audio":"g4/u3/s2/06.mp3"},{"sp":"MAN","name":"Shop Assistant","text":"Of course. The changing room is over there.","audio":"g4/u3/s2/07.mp3"},{"sp":"BEN","name":"Ben","text":"It's a bit big. Do you have an extra small?","audio":"g4/u3/s2/08.mp3"},{"sp":"MAN","name":"Shop Assistant","text":"Yes, here you are.","audio":"g4/u3/s2/09.mp3"},{"sp":"BEN","name":"Ben","text":"Perfect! I'll take it. How much is it?","audio":"g4/u3/s2/10.mp3"},{"sp":"MAN","name":"Shop Assistant","text":"It's forty-nine riyals.","audio":"g4/u3/s2/11.mp3"}],"roles":["BEN","MAN"],"chunks":[{"en":"Can I help you?","ar":"هل يمكنني مساعدتك؟","audio":"g4/u3/s2/c1.mp3"},{"en":"I'm looking for ___.","ar":"أبحث عن ___.","audio":"g4/u3/s2/c2.mp3"},{"en":"Can I try it on?","ar":"هل يمكنني تجربته؟","audio":"g4/u3/s2/c3.mp3"},{"en":"It's a bit big.","ar":"إنه كبير قليلًا.","audio":"g4/u3/s2/c4.mp3"},{"en":"I'll take it.","ar":"سآخذه.","audio":"g4/u3/s2/c5.mp3"}],"sound":{"type":"pairs","title":"/ɜː/ or /ɔː/?","en":"/ɜː/ (shirt) is in the middle of your mouth and your lips are relaxed. /ɔː/ (short) is deeper — make your lips round.","ar":"الصوت /ɜː/ كما في shirt يخرج من وسط الفم والشفتان مرتخيتان، أما /ɔː/ كما في short فهو أعمق والشفتان مستديرتان.","pairs":[["shirt","short"],["bird","board"],["word","ward"],["fur","four"],["worm","warm"]],"audio":[["g4/u3/s2/p1a.mp3","g4/u3/s2/p1b.mp3"],["g4/u3/s2/p2a.mp3","g4/u3/s2/p2b.mp3"],["g4/u3/s2/p3a.mp3","g4/u3/s2/p3b.mp3"],["g4/u3/s2/p4a.mp3","g4/u3/s2/p4b.mp3"],["g4/u3/s2/p5a.mp3","g4/u3/s2/p5b.mp3"]]},"task":{"prompt":"Role-play buying clothes. Ask for a size and say if it's right.","frame":"I'm looking for ___. — What size? — ___. — Can I try it on? — It's a bit ___."},"cando":["I can ask for clothes in a shop.","I can say if something is too big or too small.","I can hear /ɜː/ and /ɔː/."],"teach":"Bring a few real items of clothing as props. Students sound more natural when they hold the \"shirt\" and point to the \"changing room\" in the corner of the classroom.","id":"g4u3s2","track":"g4/u3/s2/track.mp3"}],"check":[{"type":"mcq","q":"How much is the animal puzzle?","ref":"L1#7","opts":["eighty riyals","eighteen riyals","forty-two riyals","twelve riyals"],"ans":1,"audio":"g4/u3/l1/07.mp3","line":"It's only eighteen riyals. It's for children aged two to four.","speaker":"Shop Assistant"},{"type":"mcq","q":"How old is Fahd now?","ref":"L1#8","opts":["two","one","four","three"],"ans":0,"audio":"g4/u3/l1/08.mp3","line":"Fahd is two now. That's perfect!","speaker":"Noor"},{"type":"mcq","q":"What color thobe does Dad want?","ref":"L2#3","opts":["brown","blue","white","black"],"ans":2,"audio":"g4/u3/l2/03.mp3","line":"Yes, please. We're looking for a white thobe for my son.","speaker":"Dad"},{"type":"mcq","q":"What is Ben's special offer?","ref":"L3#5","opts":["Buy two books and get one free.","Buy one book and get one free.","All books are free.","Buy three books for five riyals."],"ans":0,"audio":"g4/u3/l3/05.mp3","line":"Buy two books and get one free!","speaker":"Ben"}],"id":"g4u3"},{"n":4,"title":"Weather and Clothes","ar":"الطقس والملابس","emoji":"🌦️","goals":["I can describe the weather.","I can choose clothes for the weather and give reasons.","I can understand a weather report."],"listen":[{"kind":"listen","n":1,"title":"The Weather Report","skill":"Listening for information about places","skill_ar":"الاستماع إلى معلومات عن الأماكن","kagan":["Showdown","Timed Pair Share"],"vocab":[{"w":"weather","ar":"طقس","emoji":"🌤️","ex":"Here's the weather for tomorrow.","audio":"g4/u4/l1/v1.mp3"},{"w":"sunny","ar":"مشمس","emoji":"☀️","ex":"It's hot and sunny in Riyadh.","audio":"g4/u4/l1/v2.mp3"},{"w":"cloudy","ar":"غائم","emoji":"☁️","ex":"It's cool and cloudy in Taif.","audio":"g4/u4/l1/v3.mp3"},{"w":"rain","ar":"مطر","emoji":"🌧️","ex":"There's rain in the mountains.","audio":"g4/u4/l1/v4.mp3"},{"w":"windy","ar":"عاصف / فيه رياح","emoji":"🌬️","ex":"It's cold and windy in London.","audio":"g4/u4/l1/v5.mp3"},{"w":"foggy","ar":"ضبابي","emoji":"🌫️","ex":"It's foggy in Abha.","audio":"g4/u4/l1/v6.mp3"}],"script":[{"sp":"WOMAN","name":"Weather Presenter","text":"Good evening! Here's the weather for tomorrow, Thursday.","audio":"g4/u4/l1/01.mp3"},{"sp":"WOMAN","name":"Weather Presenter","text":"In Riyadh, it's hot and sunny all day. The temperature is thirty-eight degrees.","audio":"g4/u4/l1/02.mp3"},{"sp":"WOMAN","name":"Weather Presenter","text":"In Jeddah, it's hot and humid. There's a little wind near the sea. Thirty-four degrees.","audio":"g4/u4/l1/03.mp3"},{"sp":"WOMAN","name":"Weather Presenter","text":"In Taif, it's cool and cloudy in the morning. In the afternoon, there's rain in the mountains, so take an umbrella! Twenty-two degrees.","audio":"g4/u4/l1/04.mp3"},{"sp":"WOMAN","name":"Weather Presenter","text":"In Abha, it's foggy in the morning and cold at night. Only fifteen degrees.","audio":"g4/u4/l1/05.mp3"},{"sp":"WOMAN","name":"Weather Presenter","text":"And in London, it's cold and windy, with snow at night. Just two degrees!","audio":"g4/u4/l1/06.mp3"},{"sp":"BEN","name":"Ben","text":"Snow in London? My grandma lives there! I'm sure she's wearing her coat and gloves now.","audio":"g4/u4/l1/07.mp3"}],"tasks":[{"type":"mcq","q":"What is the weather like in Riyadh?","opts":["foggy","cold and windy","hot and sunny","cool and cloudy"],"ans":2},{"type":"mcq","q":"Where is there rain in the afternoon?","opts":["in Riyadh","in Abha","in Jeddah","in Taif"],"ans":3},{"type":"mcq","q":"What is the temperature in Abha?","opts":["two degrees","fifteen degrees","fifty degrees","twenty-two degrees"],"ans":1},{"type":"mcq","q":"Who lives in London?","opts":["Ben's grandma","the weather presenter","Ben's cousin","Ben's teacher"],"ans":0},{"type":"tf","s":"It is cold and windy in Jeddah.","ans":false},{"type":"tf","s":"It is foggy in Abha in the morning.","ans":true},{"type":"gap","s":"There is ___ at night in London.","ans":["snow"]},{"type":"order","items":["Riyadh","Jeddah","Taif","Abha"]}],"predict":{"en":"Think about a map of Saudi Arabia. Is the weather the same in every city?","ar":"فكّر في خريطة المملكة العربية السعودية. هل الطقس متشابه في كل مدينة؟"},"tip":{"en":"Write the city names in a list. Next to each city, draw the weather and write the temperature.","ar":"اكتب أسماء المدن في قائمة، وارسم بجانب كل مدينة رمز الطقس واكتب درجة الحرارة."},"speak":{"prompt":"Give a weather report for your city today.","frame":"Good morning! Here's the weather in ___. It's ___ and ___. It's ___ degrees."},"teach":"Students love presenting the weather. Put a map on the board; after listening, volunteers point and present one city in the presenter's style.","id":"g4u4l1","track":"g4/u4/l1/track.mp3"},{"kind":"listen","n":2,"title":"Packing for Abha","skill":"Listening for reasons","skill_ar":"الاستماع إلى الأسباب","kagan":["RallyCoach","Talking Chips"],"vocab":[{"w":"jacket","ar":"سترة","emoji":"🧥","ex":"Take your warm jacket.","audio":"g4/u4/l2/v1.mp3"},{"w":"sweater","ar":"كنزة صوفية","emoji":"🧶","ex":"Take a sweater too.","audio":"g4/u4/l2/v2.mp3"},{"w":"trainers","ar":"حذاء رياضي","emoji":"👟","ex":"Wear your trainers.","audio":"g4/u4/l2/v3.mp3"},{"w":"warm","ar":"دافئ","emoji":"🔥","ex":"The blue jacket is warmer.","audio":"g4/u4/l2/v4.mp3"},{"w":"wet","ar":"مبلّل","emoji":"💧","ex":"It's wet in the mountains.","audio":"g4/u4/l2/v5.mp3"},{"w":"mountains","ar":"جبال","emoji":"⛰️","ex":"We're walking in the mountains.","audio":"g4/u4/l2/v6.mp3"}],"script":[{"sp":"SAMI","name":"Sami","text":"Mom, we're going to Abha tomorrow. What clothes do I need?","audio":"g4/u4/l2/01.mp3"},{"sp":"MOM","name":"Mom","text":"It's cold in Abha at night, so take your warm jacket.","audio":"g4/u4/l2/02.mp3"},{"sp":"SAMI","name":"Sami","text":"My black jacket or my blue jacket?","audio":"g4/u4/l2/03.mp3"},{"sp":"MOM","name":"Mom","text":"The blue one. It's warmer. And take a sweater too.","audio":"g4/u4/l2/04.mp3"},{"sp":"SAMI","name":"Sami","text":"Do I need my sandals?","audio":"g4/u4/l2/05.mp3"},{"sp":"MOM","name":"Mom","text":"No. Take your trainers. We're walking in the mountains, and it's wet there.","audio":"g4/u4/l2/06.mp3"},{"sp":"SAMI","name":"Sami","text":"Okay. What about my cap?","audio":"g4/u4/l2/07.mp3"},{"sp":"MOM","name":"Mom","text":"Yes, take your cap. It's sunny in the day. And don't forget your umbrella! It rains a lot in Abha in summer.","audio":"g4/u4/l2/08.mp3"},{"sp":"SAMI","name":"Sami","text":"Jacket, sweater, trainers, cap, umbrella... My bag is full!","audio":"g4/u4/l2/09.mp3"}],"tasks":[{"type":"mcq","q":"Where are they going?","opts":["Abha","Jeddah","Riyadh","London"],"ans":0},{"type":"mcq","q":"Which jacket does Mom choose?","opts":["the red one","the green one","the black one","the blue one"],"ans":3},{"type":"mcq","q":"Why does Sami need trainers?","opts":["His sandals are old.","They are walking in the mountains.","It's very hot.","They are going to the beach."],"ans":1},{"type":"mcq","q":"Why does Sami need a cap?","opts":["It's raining.","It's windy.","It's sunny in the day.","It's cold at night."],"ans":2},{"type":"tf","s":"Mom says it never rains in Abha.","ans":false},{"type":"tf","s":"Sami takes his sandals.","ans":false},{"type":"gap","s":"Mom tells Sami to take a ___ too.","ans":["sweater"]},{"type":"order","items":["the jacket","the sweater","the trainers","the cap"]}],"predict":{"en":"Sami's family is going to Abha. What clothes should he take?","ar":"تسافر عائلة سامي إلى أبها. ما الملابس التي يجب أن يأخذها سامي؟"},"tip":{"en":"Listen for \"so\" — it gives a reason: It's cold, so take your jacket.","ar":"استمع لكلمة so لأنها تقدّم سببًا: الجو بارد، لذلك خذ سترتك."},"speak":{"prompt":"Your family is going on a trip. Tell your partner what you are taking and why.","frame":"I'm taking my ___ because it's ___."},"teach":"Bring a small bag and clothes (or pictures). Students \"pack\" it while listening, then unpack it while retelling Mom's reasons with \"because\" and \"so\".","id":"g4u4l2","track":"g4/u4/l2/track.mp3"},{"kind":"listen","n":3,"title":"Four Seasons","skill":"Listening for activities in each season","skill_ar":"الاستماع إلى الأنشطة في كل فصل","kagan":["Three-Step Interview","Corners"],"vocab":[{"w":"season","ar":"فصل من فصول السنة","emoji":"🍂","ex":"What's your favorite season?","audio":"g4/u4/l3/v1.mp3"},{"w":"spring","ar":"الربيع","emoji":"🌸","ex":"There are lots of flowers in spring.","audio":"g4/u4/l3/v2.mp3"},{"w":"summer","ar":"الصيف","emoji":"🌞","ex":"In summer, I go to the beach.","audio":"g4/u4/l3/v3.mp3"},{"w":"autumn","ar":"الخريف","emoji":"🍁","ex":"The leaves turn red in autumn.","audio":"g4/u4/l3/v4.mp3"},{"w":"winter","ar":"الشتاء","emoji":"❄️","ex":"It's cold in winter.","audio":"g4/u4/l3/v5.mp3"},{"w":"leaves","ar":"أوراق الشجر","emoji":"🍃","ex":"The leaves are orange.","audio":"g4/u4/l3/v6.mp3"}],"script":[{"sp":"BEN","name":"Ben","text":"Ms. Green, can I ask you some questions for my seasons project?","audio":"g4/u4/l3/01.mp3"},{"sp":"MS_GREEN","name":"Ms. Green","text":"Of course, Ben.","audio":"g4/u4/l3/02.mp3"},{"sp":"BEN","name":"Ben","text":"What's your favorite season?","audio":"g4/u4/l3/03.mp3"},{"sp":"MS_GREEN","name":"Ms. Green","text":"I love spring. In England, spring is in March, April and May. The trees are green, and there are lots of flowers.","audio":"g4/u4/l3/04.mp3"},{"sp":"BEN","name":"Ben","text":"What do you do in summer?","audio":"g4/u4/l3/05.mp3"},{"sp":"MS_GREEN","name":"Ms. Green","text":"In summer, I go to the beach with my family. It's warm, but it isn't hot like Riyadh!","audio":"g4/u4/l3/06.mp3"},{"sp":"BEN","name":"Ben","text":"And autumn?","audio":"g4/u4/l3/07.mp3"},{"sp":"MS_GREEN","name":"Ms. Green","text":"In autumn, the leaves turn red and orange. It's windy, and I like walking in the park.","audio":"g4/u4/l3/08.mp3"},{"sp":"BEN","name":"Ben","text":"Do you like winter?","audio":"g4/u4/l3/09.mp3"},{"sp":"MS_GREEN","name":"Ms. Green","text":"Not really. It's cold, and it's dark at four o'clock! But I love drinking hot chocolate by the fire.","audio":"g4/u4/l3/10.mp3"},{"sp":"BEN","name":"Ben","text":"Thank you, Ms. Green!","audio":"g4/u4/l3/11.mp3"}],"tasks":[{"type":"mcq","q":"What is Ms. Green's favorite season?","opts":["autumn","summer","winter","spring"],"ans":3},{"type":"mcq","q":"What does she do in summer?","opts":["She plants flowers.","She drinks hot chocolate.","She goes to the beach.","She walks in the park."],"ans":2},{"type":"mcq","q":"What happens to the leaves in autumn?","opts":["They turn red and orange.","They fall in spring.","They are white with snow.","They turn green."],"ans":0},{"type":"mcq","q":"Why doesn't she like winter very much?","opts":["It's cold, and it gets dark early.","She can't go to the beach.","It rains every day.","It's too hot."],"ans":0},{"type":"tf","s":"In England, spring is in March, April and May.","ans":true},{"type":"tf","s":"Ms. Green says summer in England is hotter than in Riyadh.","ans":false},{"type":"gap","s":"In winter, Ms. Green loves drinking hot ___.","ans":["chocolate"]},{"type":"order","items":["spring","summer","autumn","winter"]}],"predict":{"en":"Ben interviews his teacher about the seasons in England. How are they different from the seasons here?","ar":"يجري بن مقابلة مع معلمته عن الفصول في إنجلترا. كيف تختلف عن الفصول هنا؟"},"tip":{"en":"Each new question from Ben starts a new season. Listen for the season, then for one activity.","ar":"كل سؤال جديد من بن يبدأ فصلًا جديدًا. استمع لاسم الفصل ثم لنشاط واحد."},"speak":{"prompt":"Tell your partner about your favorite season and what you do.","frame":"My favorite season is ___. In ___, I ___."},"teach":"Compare the seasons in Saudi Arabia and England on a Venn diagram after listening. Mention that American English says \"fall\" for autumn.","id":"g4u4l3","track":"g4/u4/l3/track.mp3"}],"speak":[{"kind":"speak","n":1,"title":"What's the Weather Like?","func":"Talking about the weather","func_ar":"التحدث عن الطقس","kagan":["RallyRobin","Inside-Outside Circle"],"model":[{"sp":"GRANDPA","name":"Grandpa","text":"Good morning, Noor! What's the weather like today?","audio":"g4/u4/s1/01.mp3"},{"sp":"NOOR","name":"Noor","text":"It's cold and cloudy, Grandpa. And it's very windy.","audio":"g4/u4/s1/02.mp3"},{"sp":"GRANDPA","name":"Grandpa","text":"Is it going to rain?","audio":"g4/u4/s1/03.mp3"},{"sp":"NOOR","name":"Noor","text":"I think so. The sky is dark grey.","audio":"g4/u4/s1/04.mp3"},{"sp":"GRANDPA","name":"Grandpa","text":"Then wear your warm coat when you go out.","audio":"g4/u4/s1/05.mp3"},{"sp":"NOOR","name":"Noor","text":"Okay. Can we still go for a walk?","audio":"g4/u4/s1/06.mp3"},{"sp":"GRANDPA","name":"Grandpa","text":"Yes, but only a short walk. Let's take an umbrella.","audio":"g4/u4/s1/07.mp3"},{"sp":"NOOR","name":"Noor","text":"I love walking in cold weather!","audio":"g4/u4/s1/08.mp3"}],"roles":["GRANDPA","NOOR"],"chunks":[{"en":"What's the weather like today?","ar":"كيف الطقس اليوم؟","audio":"g4/u4/s1/c1.mp3"},{"en":"It's cold and cloudy.","ar":"الجو بارد وغائم.","audio":"g4/u4/s1/c2.mp3"},{"en":"Is it going to rain?","ar":"هل ستمطر؟","audio":"g4/u4/s1/c3.mp3"},{"en":"I think so.","ar":"أظن ذلك.","audio":"g4/u4/s1/c4.mp3"},{"en":"Wear your warm coat.","ar":"البس معطفك الدافئ.","audio":"g4/u4/s1/c5.mp3"}],"sound":{"type":"pairs","title":"/oʊ/ or /ɔː/?","en":"For /oʊ/ (coat), your mouth moves: start with \"o\" and close to \"u\". For /ɔː/ (caught), keep your mouth still: one long open sound.","ar":"لنطق /oʊ/ كما في coat يتحرك فمك من o إلى u، أما /ɔː/ كما في caught فيبقى الفم ثابتًا في صوت واحد طويل مفتوح.","pairs":[["coat","caught"],["low","law"],["boat","bought"],["so","saw"],["woke","walk"]],"audio":[["g4/u4/s1/p1a.mp3","g4/u4/s1/p1b.mp3"],["g4/u4/s1/p2a.mp3","g4/u4/s1/p2b.mp3"],["g4/u4/s1/p3a.mp3","g4/u4/s1/p3b.mp3"],["g4/u4/s1/p4a.mp3","g4/u4/s1/p4b.mp3"],["g4/u4/s1/p5a.mp3","g4/u4/s1/p5b.mp3"]]},"task":{"prompt":"Look out of the window. Describe the weather to your partner, then compare it with yesterday.","frame":"Today it's ___. Yesterday it was ___."},"cando":["I can ask about the weather.","I can describe the weather.","I can hear /oʊ/ and /ɔː/."],"teach":"Students watch their partner's lips: they move and close for /oʊ/ in coat, but stay still and open for /ɔː/ in caught.","id":"g4u4s1","track":"g4/u4/s1/track.mp3"},{"kind":"speak","n":2,"title":"What Shall I Wear?","func":"Asking for and giving advice about clothes","func_ar":"طلب النصيحة حول الملابس وتقديمها","kagan":["Fan-N-Pick","Stand Up–Hand Up–Pair Up"],"model":[{"sp":"SAMI","name":"Sami","text":"Ben, we're going to the desert camp on Thursday. What shall I wear?","audio":"g4/u4/s2/01.mp3"},{"sp":"BEN","name":"Ben","text":"It's cold at night in the desert. Wear a warm sweater and a jacket.","audio":"g4/u4/s2/02.mp3"},{"sp":"SAMI","name":"Sami","text":"Good idea. And in the day?","audio":"g4/u4/s2/03.mp3"},{"sp":"BEN","name":"Ben","text":"In the day, it's sunny and hot. Wear a T-shirt and a cap, and bring sunglasses.","audio":"g4/u4/s2/04.mp3"},{"sp":"SAMI","name":"Sami","text":"Should I wear sandals?","audio":"g4/u4/s2/05.mp3"},{"sp":"BEN","name":"Ben","text":"No, wear boots. The sand is very hot in the day and very cold at night.","audio":"g4/u4/s2/06.mp3"},{"sp":"SAMI","name":"Sami","text":"Thanks, Ben. You're a good friend!","audio":"g4/u4/s2/07.mp3"},{"sp":"BEN","name":"Ben","text":"No problem. Don't forget your gloves!","audio":"g4/u4/s2/08.mp3"}],"roles":["SAMI","BEN"],"chunks":[{"en":"What shall I wear?","ar":"ماذا ألبس؟","audio":"g4/u4/s2/c1.mp3"},{"en":"Wear a warm sweater.","ar":"البس كنزة دافئة.","audio":"g4/u4/s2/c2.mp3"},{"en":"Should I wear sandals?","ar":"هل ألبس الصندل؟","audio":"g4/u4/s2/c3.mp3"},{"en":"Don't forget your gloves!","ar":"لا تنسَ قفازيك!","audio":"g4/u4/s2/c4.mp3"},{"en":"No problem.","ar":"لا مشكلة.","audio":"g4/u4/s2/c5.mp3"}],"sound":{"type":"sort","title":"How many beats?","cats":[{"key":"1","label":"1 beat"},{"key":"2","label":"2 beats"},{"key":"3","label":"3 beats"}],"en":"Some clothes words end with two or three consonants: clothes, gloves, boots. Don't add a vowel at the end: say \"boots\", not \"bootsa\".","ar":"تنتهي بعض كلمات الملابس بحرفين ساكنين أو أكثر مثل clothes وgloves وboots. لا تضف حركة في النهاية: قل boots وليس bootsa.","items":[{"text":"clothes","key":"1","audio":"g4/u4/s2/i1.mp3"},{"text":"jacket","key":"2","audio":"g4/u4/s2/i2.mp3"},{"text":"sunglasses","key":"3","audio":"g4/u4/s2/i3.mp3"},{"text":"gloves","key":"1","audio":"g4/u4/s2/i4.mp3"},{"text":"sweater","key":"2","audio":"g4/u4/s2/i5.mp3"},{"text":"umbrella","key":"3","audio":"g4/u4/s2/i6.mp3"},{"text":"boots","key":"1","audio":"g4/u4/s2/i7.mp3"},{"text":"trousers","key":"2","audio":"g4/u4/s2/i8.mp3"},{"text":"overcoat","key":"3","audio":"g4/u4/s2/i9.mp3"}]},"task":{"prompt":"Choose a place (the beach, the desert, the mountains or the city). Your partner tells you what to wear.","frame":"We're going to the ___. What shall I wear? — Wear ___ because it's ___."},"cando":["I can ask for advice about clothes.","I can give advice with \"wear\" and \"don't forget\".","I can say words with consonants at the end."],"teach":"Students hold up fingers for the number of beats before they choose. Remind them that \"clothes\" is one beat — a very common mistake.","id":"g4u4s2","track":"g4/u4/s2/track.mp3"}],"check":[{"type":"mcq","q":"Which day is the weather report for?","ref":"L1#1","opts":["Wednesday","today","Thursday","Friday"],"ans":2,"audio":"g4/u4/l1/01.mp3","line":"Good evening! Here's the weather for tomorrow, Thursday.","speaker":"Weather Presenter"},{"type":"mcq","q":"What does the presenter tell people in Taif to take?","ref":"L1#4","opts":["sunglasses","a coat","gloves","an umbrella"],"ans":3,"audio":"g4/u4/l1/04.mp3","line":"In Taif, it's cool and cloudy in the morning. In the afternoon, there's rain in the mountains, so take an umbrella! Twenty-two degrees.","speaker":"Weather Presenter"},{"type":"mcq","q":"What does Sami say at the end?","ref":"L2#9","opts":["Where's my cap?","Let's go now!","I'm cold!","My bag is full!"],"ans":3,"audio":"g4/u4/l2/09.mp3","line":"Jacket, sweater, trainers, cap, umbrella... My bag is full!","speaker":"Sami"},{"type":"mcq","q":"Why is Ben asking questions?","ref":"L3#1","opts":["for his seasons project","for a TV show","for his grandma","for a quiz"],"ans":0,"audio":"g4/u4/l3/01.mp3","line":"Ms. Green, can I ask you some questions for my seasons project?","speaker":"Ben"}],"id":"g4u4"},{"n":5,"title":"Weekend Fun","ar":"متعة نهاية الأسبوع","emoji":"🎡","goals":["I can say where I was and what I did.","I can understand a story about the past.","I can ask about someone's weekend."],"listen":[{"kind":"listen","n":1,"title":"Where Were You?","skill":"Listening for places in the past","skill_ar":"الاستماع إلى الأماكن في الماضي","kagan":["Mix-Pair-Share","RoundRobin"],"vocab":[{"w":"weekend","ar":"عطلة نهاية الأسبوع","emoji":"🗓️","ex":"How was your weekend?","audio":"g4/u5/l1/v1.mp3"},{"w":"was / were","ar":"كان / كانوا","emoji":"⏪","ex":"I was at home. We were at the camp.","audio":"g4/u5/l1/v2.mp3"},{"w":"stadium","ar":"ملعب","emoji":"🏟️","ex":"I was at the football stadium.","audio":"g4/u5/l1/v3.mp3"},{"w":"match","ar":"مباراة","emoji":"⚽","ex":"The match was exciting.","audio":"g4/u5/l1/v4.mp3"},{"w":"sick","ar":"مريض","emoji":"🤒","ex":"I was sick on Friday.","audio":"g4/u5/l1/v5.mp3"},{"w":"stars","ar":"نجوم","emoji":"✨","ex":"We watched the stars.","audio":"g4/u5/l1/v6.mp3"}],"script":[{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"Good morning, boys! How was your weekend? Yusuf, where were you?","audio":"g4/u5/l1/01.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"I was at my cousin's house in Makkah. We were there for two days.","audio":"g4/u5/l1/02.mp3"},{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"Lovely. And you, Adam?","audio":"g4/u5/l1/03.mp3"},{"sp":"ADAM","name":"Adam","text":"I was at the football stadium with my dad. The match was exciting, but our team lost.","audio":"g4/u5/l1/04.mp3"},{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"Oh no! Ben, what about you?","audio":"g4/u5/l1/05.mp3"},{"sp":"BEN","name":"Ben","text":"I was at home. I was sick on Friday, so I stayed in bed. I was better on Saturday.","audio":"g4/u5/l1/06.mp3"},{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"I'm glad you're better. Sami?","audio":"g4/u5/l1/07.mp3"},{"sp":"SAMI","name":"Sami","text":"We were at the desert camp! It was cold at night, but it was amazing. We watched the stars.","audio":"g4/u5/l1/08.mp3"},{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"Wonderful! I was at home too. I was busy with my garden.","audio":"g4/u5/l1/09.mp3"}],"tasks":[{"type":"mcq","q":"Where was Yusuf?","opts":["at home","at the football stadium","at his cousin's house in Makkah","at the desert camp"],"ans":2},{"type":"mcq","q":"How was the football match?","opts":["boring","easy","exciting","short"],"ans":2},{"type":"mcq","q":"Why did Ben stay in bed on Friday?","opts":["He was tired.","He was sick.","He was sad.","It was cold."],"ans":1},{"type":"mcq","q":"What did Sami's family watch at night?","opts":["the sea","a football match","the stars","a film"],"ans":2},{"type":"tf","s":"Yusuf was in Makkah for one day.","ans":false},{"type":"tf","s":"Adam's team lost the match.","ans":true},{"type":"gap","s":"Mr. Hassan was busy with his ___.","ans":["garden"]},{"type":"order","items":["Yusuf","Adam","Ben","Sami"]}],"predict":{"en":"It's the first school day of the week. The teacher asks about the weekend. Where do you think the boys were?","ar":"إنه أول يوم دراسي في الأسبوع، والمعلم يسأل عن عطلة نهاية الأسبوع. أين تتوقع أن الأولاد كانوا؟"},"tip":{"en":"\"Was\" and \"were\" tell us about the past. Listen for the place after \"I was at...\".","ar":"كلمتا was وwere تخبراننا عن الماضي. استمع للمكان بعد I was at..."},"speak":{"prompt":"Tell your partner where you were last weekend and how it was.","frame":"Last weekend, I was at ___. It was ___."},"teach":"Start with your own weekend story (\"I was at...\") before listening; students guess where you were from your clues.","id":"g4u5l1","track":"g4/u5/l1/track.mp3"},{"kind":"listen","n":2,"title":"A Day at the Beach","skill":"Listening for past actions","skill_ar":"الاستماع إلى أحداث في الماضي","kagan":["Timed Pair Share","Showdown"],"vocab":[{"w":"arrive","ar":"يصل","emoji":"📍","ex":"We arrived at nine o'clock.","audio":"g4/u5/l2/v1.mp3"},{"w":"waves","ar":"أمواج","emoji":"🌊","ex":"The waves destroyed our sandcastle.","audio":"g4/u5/l2/v2.mp3"},{"w":"shells","ar":"أصداف","emoji":"🐚","ex":"I collected twenty shells.","audio":"g4/u5/l2/v3.mp3"},{"w":"collect","ar":"يجمع","emoji":"🧺","ex":"I collected shells with Mom.","audio":"g4/u5/l2/v4.mp3"},{"w":"delicious","ar":"لذيذ","emoji":"😋","ex":"The fish was delicious.","audio":"g4/u5/l2/v5.mp3"},{"w":"Corniche","ar":"الكورنيش","emoji":"🌅","ex":"We walked along the Corniche.","audio":"g4/u5/l2/v6.mp3"}],"script":[{"sp":"NOOR","name":"Noor","text":"Last Friday, my family visited the beach in Jeddah. We arrived at nine o'clock in the morning.","audio":"g4/u5/l2/01.mp3"},{"sp":"NOOR","name":"Noor","text":"First, Sami and I played in the sand. We started a big sandcastle, but the waves destroyed it!","audio":"g4/u5/l2/02.mp3"},{"sp":"NOOR","name":"Noor","text":"Then, Dad and Sami swam in the sea, and I collected shells with Mom. I collected twenty shells!","audio":"g4/u5/l2/03.mp3"},{"sp":"NOOR","name":"Noor","text":"At lunchtime, we cooked fish on the barbecue. It smelled delicious.","audio":"g4/u5/l2/04.mp3"},{"sp":"NOOR","name":"Noor","text":"In the afternoon, it was very hot, so we rested under the umbrella and watched the boats.","audio":"g4/u5/l2/05.mp3"},{"sp":"NOOR","name":"Noor","text":"In the evening, we walked along the Corniche, and then we drove home. I was tired but very happy.","audio":"g4/u5/l2/06.mp3"}],"tasks":[{"type":"mcq","q":"What time did the family arrive?","opts":["at noon","at five o'clock","at ten o'clock","at nine o'clock"],"ans":3},{"type":"mcq","q":"What happened to the sandcastle?","opts":["It was too small.","Fahd broke it.","The waves destroyed it.","They finished it."],"ans":2},{"type":"mcq","q":"What did Noor do with Mom?","opts":["She watched the boats.","She collected shells.","She swam in the sea.","She cooked fish."],"ans":1},{"type":"mcq","q":"What did they do in the evening?","opts":["They swam in the sea.","They walked along the Corniche.","They cooked fish.","They rested under the umbrella."],"ans":1},{"type":"tf","s":"Noor collected twenty shells.","ans":true},{"type":"tf","s":"The fish smelled delicious.","ans":true},{"type":"gap","s":"In the afternoon, they rested under the ___.","ans":["umbrella"]},{"type":"order","items":["They played in the sand.","Noor collected shells.","They cooked fish.","They walked along the Corniche."]}],"predict":{"en":"Noor's family spent a day at the beach in Jeddah. What did they do?","ar":"قضت عائلة نور يومًا على شاطئ جدة. ماذا فعلوا؟"},"tip":{"en":"Many past verbs end in -ed: visited, played, cooked. Listen for -ed to know the action is finished.","ar":"كثير من أفعال الماضي تنتهي بـ -ed مثل visited وplayed وcooked. استمع إلى -ed لتعرف أن الحدث انتهى."},"speak":{"prompt":"Tell your partner about a day out with your family. Use three -ed verbs.","frame":"Last ___, we visited ___. We played ___. We watched ___."},"teach":"Write the -ed verbs from the script on cards. Students hold up a card when they hear its verb — this also prepares them for the -ed sound lesson.","id":"g4u5l2","track":"g4/u5/l2/track.mp3"},{"kind":"listen","n":3,"title":"Grandpa's Childhood","skill":"Listening to a story from the past","skill_ar":"الاستماع إلى قصة من الماضي","kagan":["Think-Pair-Share","Line-Ups"],"vocab":[{"w":"village","ar":"قرية","emoji":"🏘️","ex":"I lived in a small village.","audio":"g4/u5/l3/v1.mp3"},{"w":"different","ar":"مختلف","emoji":"🔄","ex":"Life was very different.","audio":"g4/u5/l3/v2.mp3"},{"w":"pick","ar":"يقطف","emoji":"🌹","ex":"We picked roses and grapes.","audio":"g4/u5/l3/v3.mp3"},{"w":"famous","ar":"مشهور","emoji":"⭐","ex":"Taif roses are famous.","audio":"g4/u5/l3/v4.mp3"},{"w":"cloth","ar":"قماش","emoji":"🧵","ex":"Our ball was made of old cloth.","audio":"g4/u5/l3/v5.mp3"},{"w":"childhood","ar":"الطفولة","emoji":"👶","ex":"Your childhood was amazing.","audio":"g4/u5/l3/v6.mp3"}],"script":[{"sp":"SAMI","name":"Sami","text":"Grandpa, what was your life like when you were nine?","audio":"g4/u5/l3/01.mp3"},{"sp":"GRANDPA","name":"Grandpa","text":"Oh, it was very different, Sami. There was no internet and there were no phones like today.","audio":"g4/u5/l3/02.mp3"},{"sp":"GRANDPA","name":"Grandpa","text":"I lived in a small village near Taif. Every morning, I walked to school with my brother. It was three kilometers!","audio":"g4/u5/l3/03.mp3"},{"sp":"GRANDPA","name":"Grandpa","text":"After school, I helped my father on the farm. We picked roses and grapes. Taif roses are famous, you know.","audio":"g4/u5/l3/04.mp3"},{"sp":"GRANDPA","name":"Grandpa","text":"In the evening, we listened to stories from my grandmother. She told the best stories!","audio":"g4/u5/l3/05.mp3"},{"sp":"SAMI","name":"Sami","text":"Did you play games?","audio":"g4/u5/l3/06.mp3"},{"sp":"GRANDPA","name":"Grandpa","text":"Of course! We played with a ball made of old cloth. We didn't have toys from shops.","audio":"g4/u5/l3/07.mp3"},{"sp":"SAMI","name":"Sami","text":"Wow. I think your childhood was amazing, Grandpa.","audio":"g4/u5/l3/08.mp3"}],"tasks":[{"type":"mcq","q":"Where did Grandpa live?","opts":["in a big city","on a farm in Abha","in Riyadh","in a small village near Taif"],"ans":3},{"type":"mcq","q":"How did Grandpa go to school?","opts":["His father drove him.","He went by bus.","He walked with his brother.","He rode a bike."],"ans":2},{"type":"mcq","q":"What did Grandpa's family pick on the farm?","opts":["apples and oranges","roses and grapes","dates","vegetables"],"ans":1},{"type":"mcq","q":"What was Grandpa's ball made of?","opts":["leather","paper","old cloth","plastic"],"ans":2},{"type":"tf","s":"Grandpa had a phone when he was a boy.","ans":false},{"type":"tf","s":"Grandpa's grandmother told stories.","ans":true},{"type":"gap","s":"The walk to school was three ___.","ans":["kilometers","kilometres","km"]},{"type":"order","items":["Grandpa walked to school.","He helped on the farm.","He listened to stories.","He played with a cloth ball."]}],"predict":{"en":"Grandpa talks about his life when he was nine. How was it different from your life?","ar":"يتحدث الجد عن حياته عندما كان في التاسعة. كيف كانت مختلفة عن حياتك؟"},"tip":{"en":"Stories follow time: every morning, after school, in the evening. Use these phrases to put the events in order.","ar":"تتبع القصص تسلسل الوقت مثل every morning وafter school وin the evening. استخدم هذه العبارات لترتيب الأحداث."},"speak":{"prompt":"Ask a grandparent or an older person about their childhood. Tell your partner one thing.","frame":"My grandpa/grandma lived in ___. He/She ___ every day."},"teach":"Homework idea: students interview a grandparent with three questions and report back. This builds family connection and real listening outside school.","id":"g4u5l3","track":"g4/u5/l3/track.mp3"}],"speak":[{"kind":"speak","n":1,"title":"Was It Fun?","func":"Asking and answering about the past","func_ar":"السؤال والإجابة عن الماضي","kagan":["Inside-Outside Circle","RallyRobin"],"model":[{"sp":"BEN","name":"Ben","text":"Hi, Adam! I called you yesterday. Where were you?","audio":"g4/u5/s1/01.mp3"},{"sp":"ADAM","name":"Adam","text":"Sorry, Ben. I was at my uncle's house. We were there all day.","audio":"g4/u5/s1/02.mp3"},{"sp":"BEN","name":"Ben","text":"Was it fun?","audio":"g4/u5/s1/03.mp3"},{"sp":"ADAM","name":"Adam","text":"Yes, it was! We played football in the garden, and we watched a film.","audio":"g4/u5/s1/04.mp3"},{"sp":"BEN","name":"Ben","text":"Cool! Were your cousins there?","audio":"g4/u5/s1/05.mp3"},{"sp":"ADAM","name":"Adam","text":"Yes, they were. We cooked burgers with my uncle.","audio":"g4/u5/s1/06.mp3"},{"sp":"BEN","name":"Ben","text":"That sounds great. I stayed at home and finished my project.","audio":"g4/u5/s1/07.mp3"},{"sp":"ADAM","name":"Adam","text":"Oh no! I needed to finish my project too. I forgot!","audio":"g4/u5/s1/08.mp3"}],"roles":["BEN","ADAM"],"chunks":[{"en":"Where were you?","ar":"أين كنت؟","audio":"g4/u5/s1/c1.mp3"},{"en":"I was at my uncle's house.","ar":"كنت في بيت عمي.","audio":"g4/u5/s1/c2.mp3"},{"en":"Was it fun?","ar":"هل كان ممتعًا؟","audio":"g4/u5/s1/c3.mp3"},{"en":"Yes, it was!","ar":"نعم، كان كذلك!","audio":"g4/u5/s1/c4.mp3"},{"en":"That sounds great.","ar":"يبدو ذلك رائعًا.","audio":"g4/u5/s1/c5.mp3"}],"sound":{"type":"sort","title":"-ed endings: /t/, /d/ or /ɪd/?","cats":[{"key":"/t/","label":"/t/ walked"},{"key":"/d/","label":"/d/ played"},{"key":"/ɪd/","label":"/ɪd/ visited"}],"en":"The -ed ending has three sounds. After sounds like k, p, s, sh and ch it is /t/ (walked). After most other sounds it is /d/ (played). After t or d it is /ɪd/ — an extra beat (visited).","ar":"لنهاية -ed ثلاثة أصوات: /t/ بعد أصوات مثل k وp وs وsh وch مثل walked، و/d/ بعد معظم الأصوات الأخرى مثل played، و/ɪd/ مع مقطع إضافي بعد t أو d مثل visited.","items":[{"text":"watched","key":"/t/","audio":"g4/u5/s1/i1.mp3"},{"text":"cleaned","key":"/d/","audio":"g4/u5/s1/i2.mp3"},{"text":"wanted","key":"/ɪd/","audio":"g4/u5/s1/i3.mp3"},{"text":"jumped","key":"/t/","audio":"g4/u5/s1/i4.mp3"},{"text":"stayed","key":"/d/","audio":"g4/u5/s1/i5.mp3"},{"text":"needed","key":"/ɪd/","audio":"g4/u5/s1/i6.mp3"},{"text":"cooked","key":"/t/","audio":"g4/u5/s1/i7.mp3"},{"text":"called","key":"/d/","audio":"g4/u5/s1/i8.mp3"},{"text":"started","key":"/ɪd/","audio":"g4/u5/s1/i9.mp3"}]},"task":{"prompt":"Tell your group about yesterday. Use three verbs with -ed. Your group listens for the endings.","frame":"Yesterday, I ___ed ___. Then I ___ed ___."},"cando":["I can ask where someone was.","I can talk about the past with was and were.","I can say -ed endings correctly."],"teach":"The most common mistake is saying \"walk-ed\" with two beats. Only /ɪd/ adds a beat. Clap the beats: walked = one clap, visited = three claps.","id":"g4u5s1","track":"g4/u5/s1/track.mp3"},{"kind":"speak","n":2,"title":"How Was Your Weekend?","func":"Talking about your weekend","func_ar":"التحدث عن عطلة نهاية الأسبوع","kagan":["Timed Pair Share","Mix-Pair-Share"],"model":[{"sp":"LINA","name":"Lina","text":"Noor, how was your weekend?","audio":"g4/u5/s2/01.mp3"},{"sp":"NOOR","name":"Noor","text":"It was fun! On Friday, we had lunch at my aunt's house.","audio":"g4/u5/s2/02.mp3"},{"sp":"LINA","name":"Lina","text":"What did you eat?","audio":"g4/u5/s2/03.mp3"},{"sp":"NOOR","name":"Noor","text":"We had rice and lamb. It was delicious! What about you?","audio":"g4/u5/s2/04.mp3"},{"sp":"LINA","name":"Lina","text":"I went to the fun fair with my cousins. We rode the big wheel!","audio":"g4/u5/s2/05.mp3"},{"sp":"NOOR","name":"Noor","text":"Wow! Were you scared?","audio":"g4/u5/s2/06.mp3"},{"sp":"LINA","name":"Lina","text":"A little! But it was so much fun. Then we had hot dogs.","audio":"g4/u5/s2/07.mp3"},{"sp":"NOOR","name":"Noor","text":"Lucky you! Next weekend, let's go together.","audio":"g4/u5/s2/08.mp3"},{"sp":"LINA","name":"Lina","text":"Yes! That's a great plan.","audio":"g4/u5/s2/09.mp3"}],"roles":["LINA","NOOR"],"chunks":[{"en":"How was your weekend?","ar":"كيف كانت عطلتك؟","audio":"g4/u5/s2/c1.mp3"},{"en":"It was fun!","ar":"كانت ممتعة!","audio":"g4/u5/s2/c2.mp3"},{"en":"We had lunch at ___.","ar":"تناولنا الغداء في ___.","audio":"g4/u5/s2/c3.mp3"},{"en":"Were you scared?","ar":"هل كنت خائفًا؟","audio":"g4/u5/s2/c4.mp3"},{"en":"Lucky you!","ar":"يا لك من محظوظ!","audio":"g4/u5/s2/c5.mp3"}],"sound":{"type":"pairs","title":"/ʌ/ or /æ/?","en":"/ʌ/ (cup) is a short sound in the middle of your mouth, like a surprised \"uh!\". /æ/ (cap) needs a wide mouth with your jaw down.","ar":"الصوت /ʌ/ كما في cup قصير يخرج من وسط الفم مثل \"أَه\" القصيرة، أما /æ/ كما في cap فيحتاج إلى فتح الفم واسعًا مع إنزال الفك.","pairs":[["cup","cap"],["fun","fan"],["run","ran"],["hut","hat"],["bug","bag"]],"audio":[["g4/u5/s2/p1a.mp3","g4/u5/s2/p1b.mp3"],["g4/u5/s2/p2a.mp3","g4/u5/s2/p2b.mp3"],["g4/u5/s2/p3a.mp3","g4/u5/s2/p3b.mp3"],["g4/u5/s2/p4a.mp3","g4/u5/s2/p4b.mp3"],["g4/u5/s2/p5a.mp3","g4/u5/s2/p5b.mp3"]]},"task":{"prompt":"Inside-Outside Circle: tell four classmates about your last weekend in thirty seconds each.","frame":"Last weekend was ___. On Friday, I ___. On Saturday, I ___."},"cando":["I can ask about someone's weekend.","I can talk about my weekend.","I can hear /ʌ/ and /æ/."],"teach":"Use a timer for the thirty-second turns. Partners must ask one follow-up question (\"Was it fun?\" \"Were you tired?\") before they rotate.","id":"g4u5s2","track":"g4/u5/s2/track.mp3"}],"check":[{"type":"mcq","q":"Who was at the stadium with Adam?","ref":"L1#4","opts":["his brother","his uncle","Sami","his dad"],"ans":3,"audio":"g4/u5/l1/04.mp3","line":"I was at the football stadium with my dad. The match was exciting, but our team lost.","speaker":"Adam"},{"type":"mcq","q":"What was the weather like at night at the camp?","ref":"L1#8","opts":["windy","rainy","cold","hot"],"ans":2,"audio":"g4/u5/l1/08.mp3","line":"We were at the desert camp! It was cold at night, but it was amazing. We watched the stars.","speaker":"Sami"},{"type":"mcq","q":"Who swam in the sea?","ref":"L2#3","opts":["Noor and Sami","Noor and Mom","Dad and Sami","Mom and Dad"],"ans":2,"audio":"g4/u5/l2/03.mp3","line":"Then, Dad and Sami swam in the sea, and I collected shells with Mom. I collected twenty shells!","speaker":"Noor"},{"type":"mcq","q":"What does Grandpa say about Taif roses?","ref":"L3#4","opts":["They are expensive.","They are small.","They are red.","They are famous."],"ans":3,"audio":"g4/u5/l3/04.mp3","line":"After school, I helped my father on the farm. We picked roses and grapes. Taif roses are famous, you know.","speaker":"Grandpa"}],"id":"g4u5"},{"n":6,"title":"Healthy Me","ar":"أنا بصحّة جيدة","emoji":"💪","goals":["I can say what's wrong and give simple advice.","I can talk about how often I do things.","I can understand results and announcements on Sports Day."],"listen":[{"kind":"listen","n":1,"title":"At the Doctor's","skill":"Listening for problems and advice","skill_ar":"الاستماع إلى المشكلات والنصائح","kagan":["RallyCoach","Numbered Heads Together"],"vocab":[{"w":"What's the matter?","ar":"ما المشكلة؟","emoji":"🤕","ex":"What's the matter, Adam?","audio":"g4/u6/l1/v1.mp3"},{"w":"sore throat","ar":"التهاب الحلق","emoji":"😷","ex":"I have a sore throat.","audio":"g4/u6/l1/v2.mp3"},{"w":"headache","ar":"صداع","emoji":"🤯","ex":"I have a headache too.","audio":"g4/u6/l1/v3.mp3"},{"w":"fever","ar":"حُمّى","emoji":"🌡️","ex":"He has a fever at night.","audio":"g4/u6/l1/v4.mp3"},{"w":"rest","ar":"يرتاح","emoji":"🛌","ex":"You should rest at home.","audio":"g4/u6/l1/v5.mp3"},{"w":"medicine","ar":"دواء","emoji":"💊","ex":"Take this medicine after meals.","audio":"g4/u6/l1/v6.mp3"}],"script":[{"sp":"WOMAN","name":"Doctor","text":"Hello, Adam. Come in and sit down. What's the matter?","audio":"g4/u6/l1/01.mp3"},{"sp":"ADAM","name":"Adam","text":"I have a sore throat, and I have a headache too.","audio":"g4/u6/l1/02.mp3"},{"sp":"WOMAN","name":"Doctor","text":"I'm sorry to hear that. When did it start?","audio":"g4/u6/l1/03.mp3"},{"sp":"DAD","name":"Dad","text":"It started two days ago. He has a fever at night.","audio":"g4/u6/l1/04.mp3"},{"sp":"WOMAN","name":"Doctor","text":"Let me look. Open your mouth and say \"aah\". Hmm, your throat is red.","audio":"g4/u6/l1/05.mp3"},{"sp":"WOMAN","name":"Doctor","text":"Don't worry, Adam. It's a cold. You should rest at home for two days and drink lots of warm water.","audio":"g4/u6/l1/06.mp3"},{"sp":"ADAM","name":"Adam","text":"Can I go to school tomorrow?","audio":"g4/u6/l1/07.mp3"},{"sp":"WOMAN","name":"Doctor","text":"No, not tomorrow. Stay at home. Take this medicine three times a day, after meals.","audio":"g4/u6/l1/08.mp3"},{"sp":"DAD","name":"Dad","text":"Thank you, Doctor.","audio":"g4/u6/l1/09.mp3"}],"tasks":[{"type":"mcq","q":"What is the matter with Adam?","opts":["a toothache","a sore throat and a headache","a broken arm","a stomachache"],"ans":1},{"type":"mcq","q":"When did it start?","opts":["this morning","two days ago","last week","yesterday"],"ans":1},{"type":"mcq","q":"What should Adam drink?","opts":["lots of warm water","cold juice","tea with sugar","milk"],"ans":0},{"type":"mcq","q":"How often should Adam take the medicine?","opts":["four times a day","three times a day","once a day","two times a day"],"ans":1},{"type":"tf","s":"Adam has a fever at night.","ans":true},{"type":"tf","s":"The doctor says Adam can go to school tomorrow.","ans":false},{"type":"gap","s":"Adam should take the medicine after ___.","ans":["meals"]},{"type":"order","items":["Adam says what the problem is.","Dad says when it started.","The doctor looks at Adam's throat.","The doctor gives medicine."]}],"predict":{"en":"Adam feels ill. He goes to the doctor with his dad. What do you think is wrong?","ar":"يشعر آدم بالمرض فيذهب إلى الطبيبة مع والده. ما الذي تتوقع أنه يعاني منه؟"},"tip":{"en":"The doctor's advice starts with \"You should...\" or \"Take...\". Listen for these words to answer the advice questions.","ar":"تبدأ نصيحة الطبيبة بـ You should... أو Take... استمع لهذه الكلمات لتجيب عن أسئلة النصائح."},"speak":{"prompt":"Role-play: one student is the doctor and one is the patient.","frame":"What's the matter? — I have a ___. — You should ___."},"teach":"Teach \"I have a + problem\" with mime: hold your head (headache), your throat (sore throat), your stomach (stomachache). Students mime when they hear the words.","id":"g4u6l1","track":"g4/u6/l1/track.mp3"},{"kind":"listen","n":2,"title":"Healthy Habits","skill":"Listening for how often","skill_ar":"الاستماع إلى معدّل التكرار","kagan":["Line-Ups","Find Someone Who"],"vocab":[{"w":"healthy","ar":"صحّي","emoji":"🥗","ex":"How can we be healthy?","audio":"g4/u6/l2/v1.mp3"},{"w":"always","ar":"دائمًا","emoji":"💯","ex":"Always eat breakfast.","audio":"g4/u6/l2/v2.mp3"},{"w":"sometimes","ar":"أحيانًا","emoji":"🌗","ex":"I sometimes eat sweets.","audio":"g4/u6/l2/v3.mp3"},{"w":"never","ar":"أبدًا","emoji":"🚫","ex":"I never drink fizzy drinks.","audio":"g4/u6/l2/v4.mp3"},{"w":"exercise","ar":"يمارس الرياضة","emoji":"🏃","ex":"How often do you exercise?","audio":"g4/u6/l2/v5.mp3"},{"w":"energy","ar":"طاقة","emoji":"⚡","ex":"Breakfast gives you energy.","audio":"g4/u6/l2/v6.mp3"}],"script":[{"sp":"YUSUF","name":"Yusuf","text":"Good morning, everyone! This is School Radio. Today, I'm talking to our P.E. teacher, Coach Omar. Coach, how can we be healthy?","audio":"g4/u6/l2/01.mp3"},{"sp":"MAN","name":"Coach Omar","text":"Great question, Yusuf. First, always eat breakfast. It gives you energy for the day.","audio":"g4/u6/l2/02.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"Do you eat sweets?","audio":"g4/u6/l2/03.mp3"},{"sp":"MAN","name":"Coach Omar","text":"Sometimes, at the weekend. But I never drink fizzy drinks. I usually drink water — about eight glasses a day.","audio":"g4/u6/l2/04.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"How often do you exercise?","audio":"g4/u6/l2/05.mp3"},{"sp":"MAN","name":"Coach Omar","text":"I run every morning, and I play basketball twice a week, on Mondays and Wednesdays.","audio":"g4/u6/l2/06.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"What about sleep?","audio":"g4/u6/l2/07.mp3"},{"sp":"MAN","name":"Coach Omar","text":"Sleep is very important! Children should sleep for ten hours every night. And never play video games before bed.","audio":"g4/u6/l2/08.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"Thank you, Coach Omar!","audio":"g4/u6/l2/09.mp3"}],"tasks":[{"type":"mcq","q":"Why should you always eat breakfast?","opts":["It's quick.","Your teacher says so.","It's delicious.","It gives you energy."],"ans":3},{"type":"mcq","q":"When does Coach Omar eat sweets?","opts":["sometimes, at the weekend","every day","never","after every meal"],"ans":0},{"type":"mcq","q":"How many glasses of water does he drink a day?","opts":["about four","about two","about eight","about ten"],"ans":2},{"type":"mcq","q":"How many hours should children sleep?","opts":["eight","twelve","six","ten"],"ans":3},{"type":"tf","s":"Coach Omar plays basketball every day.","ans":false},{"type":"tf","s":"Coach Omar never drinks fizzy drinks.","ans":true},{"type":"gap","s":"Coach Omar plays basketball on Mondays and ___.","ans":["Wednesdays","Wednesday"]},{"type":"order","items":["breakfast","sweets and drinks","exercise","sleep"]}],"predict":{"en":"A student interviews the P.E. teacher on the school radio. What healthy habits do you think the teacher talks about?","ar":"يحاور طالبٌ معلمَ التربية البدنية في الإذاعة المدرسية. ما العادات الصحية التي تتوقع أن يتحدث عنها؟"},"tip":{"en":"Listen for how often: always, usually, sometimes, never, twice a week. These words change the meaning a lot!","ar":"استمع لكلمات التكرار مثل always وusually وsometimes وnever وtwice a week، فهي تغيّر المعنى كثيرًا!"},"speak":{"prompt":"Tell your partner about your healthy and unhealthy habits.","frame":"I always ___. I sometimes ___. I never ___."},"teach":"Make a \"frequency line\" on the classroom floor from never (0%) to always (100%). Students stand on the line to show how often they eat vegetables, sleep early or exercise (Line-Ups).","id":"g4u6l2","track":"g4/u6/l2/track.mp3"},{"kind":"listen","n":3,"title":"Sports Day","skill":"Listening for results","skill_ar":"الاستماع إلى النتائج","kagan":["Numbered Heads Together","Showdown"],"vocab":[{"w":"race","ar":"سباق","emoji":"🏁","ex":"Yusuf won the race.","audio":"g4/u6/l3/v1.mp3"},{"w":"first place","ar":"المركز الأول","emoji":"🥇","ex":"In first place is Yusuf.","audio":"g4/u6/l3/v2.mp3"},{"w":"team","ar":"فريق","emoji":"👥","ex":"Ben is in the Green Team.","audio":"g4/u6/l3/v3.mp3"},{"w":"long jump","ar":"الوثب الطويل","emoji":"🦘","ex":"Sami won the long jump.","audio":"g4/u6/l3/v4.mp3"},{"w":"record","ar":"رقم قياسي","emoji":"📈","ex":"That's a new school record!","audio":"g4/u6/l3/v5.mp3"},{"w":"points","ar":"نقاط","emoji":"🔢","ex":"The Blue Team has forty points.","audio":"g4/u6/l3/v6.mp3"}],"script":[{"sp":"ANNOUNCER","name":"Announcer","text":"Welcome, everyone, to our school Sports Day!","audio":"g4/u6/l3/01.mp3"},{"sp":"ANNOUNCER","name":"Announcer","text":"Here are the results of the one hundred meter race. In first place, from the Blue Team: Yusuf!","audio":"g4/u6/l3/02.mp3"},{"sp":"ANNOUNCER","name":"Announcer","text":"In second place, from the Red Team: Adam. And in third place, from the Green Team: Ben. Well done, boys!","audio":"g4/u6/l3/03.mp3"},{"sp":"ANNOUNCER","name":"Announcer","text":"Now the long jump. Sami from the Blue Team jumped three meters and ten centimeters! That's a new school record!","audio":"g4/u6/l3/04.mp3"},{"sp":"ANNOUNCER","name":"Announcer","text":"Next is the sack race. Please go to the football field.","audio":"g4/u6/l3/05.mp3"},{"sp":"ANNOUNCER","name":"Announcer","text":"After the sack race, there is a break for juice and fruit near the main gate.","audio":"g4/u6/l3/06.mp3"},{"sp":"ANNOUNCER","name":"Announcer","text":"At the moment, the Blue Team has forty points, the Red Team has thirty-five points and the Green Team has twenty-eight points. Good luck, everyone!","audio":"g4/u6/l3/07.mp3"}],"tasks":[{"type":"mcq","q":"Who came first in the race?","opts":["Adam","Ben","Yusuf","Sami"],"ans":2},{"type":"mcq","q":"Which team is Ben in?","opts":["the Yellow Team","the Green Team","the Red Team","the Blue Team"],"ans":1},{"type":"mcq","q":"What did Sami do?","opts":["He won the race.","He came second in the sack race.","He came third in the long jump.","He set a new school record in the long jump."],"ans":3},{"type":"mcq","q":"Where is the break?","opts":["near the main gate","in the classroom","in the gym","on the football field"],"ans":0},{"type":"tf","s":"The sack race is in the gym.","ans":false},{"type":"tf","s":"The Red Team has the most points.","ans":false},{"type":"gap","s":"The Green Team has ___ points.","ans":["twenty-eight","28"]},{"type":"order","items":["the race results","the long jump","the sack race","the break"]}],"predict":{"en":"It's Sports Day at school. What information do you hear from the announcer?","ar":"إنه يوم الرياضة في المدرسة. ما المعلومات التي تسمعها من المذيع؟"},"tip":{"en":"Listen for first, second and third, and for team colors. Write the names next to 1st, 2nd and 3rd.","ar":"استمع لكلمات first وsecond وthird ولألوان الفرق، واكتب الأسماء بجانب الأول والثاني والثالث."},"speak":{"prompt":"Be the announcer! Give the results of a race in your class.","frame":"In first place is ___. In second place is ___. In third place is ___."},"teach":"After listening, run a thirty-second \"mini sports day\" in class (for example, who can name the most body parts in thirty seconds) and let students announce the results.","id":"g4u6l3","track":"g4/u6/l3/track.mp3"}],"speak":[{"kind":"speak","n":1,"title":"What's the Matter?","func":"Saying what's wrong and giving advice","func_ar":"قول ما المشكلة وتقديم النصيحة","kagan":["RallyCoach","Inside-Outside Circle"],"model":[{"sp":"MS_GREEN","name":"Ms. Green","text":"Ben, you look tired. What's the matter?","audio":"g4/u6/s1/01.mp3"},{"sp":"BEN","name":"Ben","text":"I have a pain in my eye, Ms. Green. It hurts.","audio":"g4/u6/s1/02.mp3"},{"sp":"MS_GREEN","name":"Ms. Green","text":"Oh dear. Did you play video games late last night?","audio":"g4/u6/s1/03.mp3"},{"sp":"BEN","name":"Ben","text":"Yes, I did. I played until eleven o'clock.","audio":"g4/u6/s1/04.mp3"},{"sp":"MS_GREEN","name":"Ms. Green","text":"That's very late. You should rest your eyes. You shouldn't look at a screen for a long time.","audio":"g4/u6/s1/05.mp3"},{"sp":"BEN","name":"Ben","text":"Okay. Can I go to the school nurse?","audio":"g4/u6/s1/06.mp3"},{"sp":"MS_GREEN","name":"Ms. Green","text":"Yes, of course. Take Sami with you.","audio":"g4/u6/s1/07.mp3"},{"sp":"BEN","name":"Ben","text":"Thank you, Ms. Green. I'll go to bed early tonight.","audio":"g4/u6/s1/08.mp3"}],"roles":["MS_GREEN","BEN"],"chunks":[{"en":"What's the matter?","ar":"ما الأمر؟","audio":"g4/u6/s1/c1.mp3"},{"en":"I have a pain in my ___.","ar":"عندي ألم في ___.","audio":"g4/u6/s1/c2.mp3"},{"en":"It hurts.","ar":"إنه يؤلمني.","audio":"g4/u6/s1/c3.mp3"},{"en":"You should rest.","ar":"يجب أن ترتاح.","audio":"g4/u6/s1/c4.mp3"},{"en":"You shouldn't ___.","ar":"لا ينبغي أن ___.","audio":"g4/u6/s1/c5.mp3"}],"sound":{"type":"pairs","title":"/eɪ/ or /aɪ/?","en":"/eɪ/ (pain) starts with \"e\" and moves to \"i\". /aɪ/ (pine) starts with a wide-open \"a\" and moves to \"i\".","ar":"يبدأ الصوت /eɪ/ كما في pain بـ e ثم ينتقل إلى i، أما /aɪ/ كما في pine فيبدأ بـ a مفتوحة واسعة ثم ينتقل إلى i.","pairs":[["pain","pine"],["wait","white"],["lake","like"],["main","mine"],["lane","line"]],"audio":[["g4/u6/s1/p1a.mp3","g4/u6/s1/p1b.mp3"],["g4/u6/s1/p2a.mp3","g4/u6/s1/p2b.mp3"],["g4/u6/s1/p3a.mp3","g4/u6/s1/p3b.mp3"],["g4/u6/s1/p4a.mp3","g4/u6/s1/p4b.mp3"],["g4/u6/s1/p5a.mp3","g4/u6/s1/p5b.mp3"]]},"task":{"prompt":"Role-play with a partner: one has a health problem, the other gives two pieces of advice.","frame":"What's the matter? — I have a ___. — You should ___. You shouldn't ___."},"cando":["I can ask \"What's the matter?\"","I can give advice with should and shouldn't.","I can hear /eɪ/ and /aɪ/."],"teach":"Show the mouth opening with your hand: a small opening for /eɪ/ and a big opening for /aɪ/. Students copy it with their own hand under their chin.","id":"g4u6s1","track":"g4/u6/s1/track.mp3"},{"kind":"speak","n":2,"title":"How Often Do You...?","func":"Asking about habits","func_ar":"السؤال عن العادات","kagan":["Find Someone Who","Three-Step Interview"],"model":[{"sp":"ADAM","name":"Adam","text":"Sami, let's do our health survey. How often do you eat vegetables?","audio":"g4/u6/s2/01.mp3"},{"sp":"SAMI","name":"Sami","text":"I eat vegetables every day. My mom makes salad for lunch.","audio":"g4/u6/s2/02.mp3"},{"sp":"ADAM","name":"Adam","text":"Good! How often do you eat fast food?","audio":"g4/u6/s2/03.mp3"},{"sp":"SAMI","name":"Sami","text":"Sometimes. Maybe once a week, on Thursday.","audio":"g4/u6/s2/04.mp3"},{"sp":"ADAM","name":"Adam","text":"How often do you brush your teeth?","audio":"g4/u6/s2/05.mp3"},{"sp":"SAMI","name":"Sami","text":"Twice a day — in the morning and before bed.","audio":"g4/u6/s2/06.mp3"},{"sp":"ADAM","name":"Adam","text":"And how often do you exercise?","audio":"g4/u6/s2/07.mp3"},{"sp":"SAMI","name":"Sami","text":"I swim three times a week. I'm in the swimming club!","audio":"g4/u6/s2/08.mp3"},{"sp":"ADAM","name":"Adam","text":"Wow! Your answers are very healthy. You get ten out of ten!","audio":"g4/u6/s2/09.mp3"}],"roles":["ADAM","SAMI"],"chunks":[{"en":"How often do you ___?","ar":"كم مرة ___؟","audio":"g4/u6/s2/c1.mp3"},{"en":"every day","ar":"كل يوم","audio":"g4/u6/s2/c2.mp3"},{"en":"once a week","ar":"مرة في الأسبوع","audio":"g4/u6/s2/c3.mp3"},{"en":"twice a day","ar":"مرتين في اليوم","audio":"g4/u6/s2/c4.mp3"},{"en":"three times a week","ar":"ثلاث مرات في الأسبوع","audio":"g4/u6/s2/c5.mp3"}],"sound":{"type":"pairs","title":"/s/ or /ʃ/?","en":"For /s/ (sip), smile and push air between your teeth: sss. For /ʃ/ (ship), make your lips round and push them forward: shhh.","ar":"لنطق /s/ كما في sip ابتسم وادفع الهواء بين أسنانك، ولنطق /ʃ/ كما في ship اجعل شفتيك مستديرتين ومدفوعتين إلى الأمام.","pairs":[["sip","ship"],["see","she"],["sort","short"],["sell","shell"],["save","shave"]],"audio":[["g4/u6/s2/p1a.mp3","g4/u6/s2/p1b.mp3"],["g4/u6/s2/p2a.mp3","g4/u6/s2/p2b.mp3"],["g4/u6/s2/p3a.mp3","g4/u6/s2/p3b.mp3"],["g4/u6/s2/p4a.mp3","g4/u6/s2/p4b.mp3"],["g4/u6/s2/p5a.mp3","g4/u6/s2/p5b.mp3"]]},"task":{"prompt":"Do a health survey in your group. Ask four \"How often...?\" questions and report the results to the class.","frame":"How often do you ___? — I ___ every day / once a week / never."},"cando":["I can ask \"How often...?\"","I can talk about my habits.","I can hear /s/ and /ʃ/."],"teach":"After the survey, groups report with numbers: \"Three students eat vegetables every day.\" This connects speaking with simple maths and makes reporting meaningful.","id":"g4u6s2","track":"g4/u6/s2/track.mp3"}],"check":[{"type":"mcq","q":"What does the doctor ask Adam to say?","ref":"L1#5","opts":["yes","ouch","hello","aah"],"ans":3,"audio":"g4/u6/l1/05.mp3","line":"Let me look. Open your mouth and say \"aah\". Hmm, your throat is red.","speaker":"Doctor"},{"type":"mcq","q":"How long should Adam rest at home?","ref":"L1#6","opts":["three days","two days","one day","one week"],"ans":1,"audio":"g4/u6/l1/06.mp3","line":"Don't worry, Adam. It's a cold. You should rest at home for two days and drink lots of warm water.","speaker":"Doctor"},{"type":"mcq","q":"What should you never do before bed?","ref":"L2#8","opts":["brush your teeth","drink water","play video games","read a book"],"ans":2,"audio":"g4/u6/l2/08.mp3","line":"Sleep is very important! Children should sleep for ten hours every night. And never play video games before bed.","speaker":"Coach Omar"},{"type":"mcq","q":"What can students have in the break?","ref":"L3#6","opts":["ice cream","juice and fruit","water and cake","sandwiches"],"ans":1,"audio":"g4/u6/l3/06.mp3","line":"After the sack race, there is a break for juice and fruit near the main gate.","speaker":"Announcer"}],"id":"g4u6"}],"level":"A1+","band":"Ocean","speed":0.92},{"grade":5,"units":[{"n":1,"title":"Free Time and Hobbies","ar":"وقت الفراغ والهوايات","emoji":"🎨","goals":["I can talk about my hobbies and interests.","I can make, accept and refuse suggestions.","I can understand an interview and a simple plan."],"listen":[{"kind":"listen","n":1,"title":"Hobby Week","skill":"Listening for key details about people","skill_ar":"الاستماع إلى التفاصيل الأساسية عن الأشخاص","kagan":["Timed Pair Share","Corners"],"vocab":[{"w":"hobby","ar":"هواية","emoji":"🎯","ex":"My hobby is taking photos.","audio":"g5/u1/l1/v1.mp3"},{"w":"free time","ar":"وقت الفراغ","emoji":"⏳","ex":"What do you do in your free time?","audio":"g5/u1/l1/v2.mp3"},{"w":"camera","ar":"كاميرا","emoji":"📷","ex":"My uncle gave me an old camera.","audio":"g5/u1/l1/v3.mp3"},{"w":"be into","ar":"يهتم كثيرًا بـ","emoji":"💙","ex":"I'm really into cooking.","audio":"g5/u1/l1/v4.mp3"},{"w":"model","ar":"مجسّم","emoji":"🏗️","ex":"I'm building a model of a tower.","audio":"g5/u1/l1/v5.mp3"},{"w":"adventure","ar":"مغامرة","emoji":"🗺️","ex":"I love adventure stories.","audio":"g5/u1/l1/v6.mp3"}],"script":[{"sp":"NARRATOR","name":"Narrator","text":"It's Hobby Week at school. Four students talk about their hobbies.","audio":"g5/u1/l1/01.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"I'm Yusuf. In my free time, I like taking photos. I started two years ago, when my uncle gave me his old camera. My favorite photos are of the birds in our garden.","audio":"g5/u1/l1/02.mp3"},{"sp":"ADAM","name":"Adam","text":"Hi, I'm Adam. I'm really into cooking. Every Friday, I help my mom make lunch for the whole family. Last week, I made chicken kabsa on my own, and everybody loved it!","audio":"g5/u1/l1/03.mp3"},{"sp":"BEN","name":"Ben","text":"Hello! I'm Ben. My hobby is building models. At the moment, I'm making a model of the Kingdom Centre in Riyadh. It has more than three hundred small pieces, so it's taking a long time.","audio":"g5/u1/l1/04.mp3"},{"sp":"SAMI","name":"Sami","text":"I'm Sami. I love reading, especially adventure stories. I usually read for thirty minutes before bed. This month, I'm reading a book about a boy who sails around the world.","audio":"g5/u1/l1/05.mp3"},{"sp":"NARRATOR","name":"Narrator","text":"Which hobby do you like best?","audio":"g5/u1/l1/06.mp3"}],"tasks":[{"type":"mcq","q":"Who gave Yusuf his first camera?","opts":["his uncle","his grandpa","his teacher","his father"],"ans":0},{"type":"mcq","q":"What did Adam cook on his own last week?","opts":["pizza","fish","pancakes","chicken kabsa"],"ans":3},{"type":"mcq","q":"Why is Ben's model taking a long time?","opts":["He lost some pieces.","It has more than three hundred pieces.","It's his first model.","He's very busy at school."],"ans":1},{"type":"mcq","q":"What is Sami's book about?","opts":["a boy who builds a tower","a boy who sails around the world","birds in a garden","a famous cook"],"ans":1},{"type":"tf","s":"Yusuf likes taking photos of birds.","ans":true},{"type":"tf","s":"Sami reads for an hour before bed.","ans":false},{"type":"gap","s":"Yusuf started his hobby ___ years ago.","ans":["two","2"]},{"type":"gap","s":"Ben is making a model of the Kingdom ___ in Riyadh.","ans":["Centre","Center"]}],"predict":{"en":"Four students talk about their hobbies during Hobby Week. What hobbies are popular with boys your age?","ar":""},"tip":{"en":"Each speaker gives three things: the hobby, how it started, and one detail. Make three notes for each person.","ar":"يذكر كل متحدث ثلاثة أشياء: الهواية، وكيف بدأت، وتفصيلًا عنها. دوّن ثلاث ملاحظات لكل شخص."},"speak":{"prompt":"Tell your group about your hobby: what it is, how you started and why you like it.","frame":"My hobby is ___. I started when ___. I like it because ___."},"teach":"Before listening, students rank four hobbies (photography, cooking, model building, reading) from most to least interesting. After listening, they re-rank and explain any change.","id":"g5u1l1","track":"g5/u1/l1/track.mp3"},{"kind":"listen","n":2,"title":"A Young Chess Champion","skill":"Listening to an interview","skill_ar":"الاستماع إلى مقابلة","kagan":["Three-Step Interview","Numbered Heads Together"],"vocab":[{"w":"champion","ar":"بطل","emoji":"🏆","ex":"He's the junior chess champion.","audio":"g5/u1/l2/v1.mp3"},{"w":"championship","ar":"بطولة","emoji":"🥇","ex":"He won the national championship.","audio":"g5/u1/l2/v2.mp3"},{"w":"practice","ar":"يتدرّب","emoji":"♟️","ex":"He practices for two hours a day.","audio":"g5/u1/l2/v3.mp3"},{"w":"final","ar":"المباراة النهائية","emoji":"🏁","ex":"The final lasted three hours.","audio":"g5/u1/l2/v4.mp3"},{"w":"give up","ar":"يستسلم","emoji":"🏳️","ex":"I didn't give up.","audio":"g5/u1/l2/v5.mp3"},{"w":"patient","ar":"صبور","emoji":"⏳","ex":"Be patient and learn from your mistakes.","audio":"g5/u1/l2/v6.mp3"}],"script":[{"sp":"WOMAN","name":"Radio Host","text":"Welcome back to Young Stars Radio. With me today is Faris. He's eleven years old, and last month he won the National Junior Chess Championship. Congratulations, Faris!","audio":"g5/u1/l2/01.mp3"},{"sp":"YUSUF","name":"Faris","text":"Thank you! I'm still very excited.","audio":"g5/u1/l2/02.mp3"},{"sp":"WOMAN","name":"Radio Host","text":"When did you start playing chess?","audio":"g5/u1/l2/03.mp3"},{"sp":"YUSUF","name":"Faris","text":"When I was six. My grandfather taught me. We played every evening after dinner.","audio":"g5/u1/l2/04.mp3"},{"sp":"WOMAN","name":"Radio Host","text":"How many hours do you practice now?","audio":"g5/u1/l2/05.mp3"},{"sp":"YUSUF","name":"Faris","text":"About two hours a day on school days, and four hours at the weekend. I also solve chess puzzles on my tablet.","audio":"g5/u1/l2/06.mp3"},{"sp":"WOMAN","name":"Radio Host","text":"That's a lot! What was the hardest game in the championship?","audio":"g5/u1/l2/07.mp3"},{"sp":"YUSUF","name":"Faris","text":"The final. It lasted nearly three hours! I was losing at first, but I didn't give up.","audio":"g5/u1/l2/08.mp3"},{"sp":"WOMAN","name":"Radio Host","text":"What advice do you have for young players?","audio":"g5/u1/l2/09.mp3"},{"sp":"YUSUF","name":"Faris","text":"Be patient, and learn from your mistakes. Every time I lose, I learn something new.","audio":"g5/u1/l2/10.mp3"},{"sp":"WOMAN","name":"Radio Host","text":"Wonderful advice. Good luck in the Asian Championship next year!","audio":"g5/u1/l2/11.mp3"}],"tasks":[{"type":"mcq","q":"How old is Faris?","opts":["twelve","nine","eleven","six"],"ans":2},{"type":"mcq","q":"Who taught Faris to play chess?","opts":["his father","his older brother","his grandfather","his teacher"],"ans":2},{"type":"mcq","q":"How long does he practice on school days?","opts":["about three hours","about two hours","about four hours","about one hour"],"ans":1},{"type":"mcq","q":"What does Faris say about the final?","opts":["He lost the game.","It lasted one hour.","It was very easy.","He was losing at first, but he didn't give up."],"ans":3},{"type":"tf","s":"Faris thinks you should never make mistakes.","ans":false},{"type":"tf","s":"Faris solves chess puzzles on his tablet.","ans":true},{"type":"gap","s":"The final lasted nearly ___ hours.","ans":["three","3"]},{"type":"gap","s":"Next year, Faris is playing in the ___ Championship.","ans":["Asian"]}],"predict":{"en":"A radio host interviews a young chess champion. What questions do you think she asks him?","ar":""},"tip":{"en":"In interviews, the question tells you what comes next. Read the task questions first and wait for the host's matching question.","ar":"في المقابلات يخبرك السؤال بما سيأتي بعده. اقرأ الأسئلة أولًا وانتظر سؤال المذيعة المطابق."},"speak":{"prompt":"Interview your partner about something he is good at.","frame":"When did you start ___? How often do you practice? What advice do you have?"},"teach":"Play the radio host with a real student \"champion\" from your class (football, Quran recitation, drawing). Real interviews make the language memorable.","id":"g5u1l2","track":"g5/u1/l2/track.mp3"},{"kind":"listen","n":3,"title":"Planning Club Day","skill":"Completing notes","skill_ar":"إكمال الملاحظات","kagan":["RallyCoach","Numbered Heads Together"],"vocab":[{"w":"plan","ar":"خطة","emoji":"📋","ex":"Let's finish the plan.","audio":"g5/u1/l3/v1.mp3"},{"w":"opening","ar":"الافتتاح","emoji":"🎉","ex":"The opening is at eight o'clock.","audio":"g5/u1/l3/v2.mp3"},{"w":"principal","ar":"مدير المدرسة","emoji":"👨‍💼","ex":"The principal is going to give a speech.","audio":"g5/u1/l3/v3.mp3"},{"w":"speech","ar":"كلمة / خطاب","emoji":"🎤","ex":"He gives a short speech.","audio":"g5/u1/l3/v4.mp3"},{"w":"competition","ar":"مسابقة","emoji":"🏅","ex":"After the break, there's a competition.","audio":"g5/u1/l3/v5.mp3"},{"w":"prize","ar":"جائزة","emoji":"🎁","ex":"The best club wins a prize.","audio":"g5/u1/l3/v6.mp3"}],"script":[{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"Okay, team. We need to finish the plan for Club Day next Tuesday. Let's start with the times.","audio":"g5/u1/l3/01.mp3"},{"sp":"SAMI","name":"Sami","text":"The opening is at eight o'clock in the school hall. The principal is going to give a short speech.","audio":"g5/u1/l3/02.mp3"},{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"Good. What's next?","audio":"g5/u1/l3/03.mp3"},{"sp":"BEN","name":"Ben","text":"From eight thirty to ten, students can visit the clubs. The Art Club is in Room 12, and the Science Club is in the lab.","audio":"g5/u1/l3/04.mp3"},{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"And the Chess Club?","audio":"g5/u1/l3/05.mp3"},{"sp":"SAMI","name":"Sami","text":"The Chess Club is in the library this year, because Room 5 is too small.","audio":"g5/u1/l3/06.mp3"},{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"Right. At ten o'clock, there's a break. Ben, did you order the snacks?","audio":"g5/u1/l3/07.mp3"},{"sp":"BEN","name":"Ben","text":"Yes, I did. We have juice and sandwiches for two hundred students.","audio":"g5/u1/l3/08.mp3"},{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"Excellent. After the break, there's the big competition. Each club has fifteen minutes to show its best work.","audio":"g5/u1/l3/09.mp3"},{"sp":"SAMI","name":"Sami","text":"And at the end, we give the prizes. The best club wins a trip to the science museum!","audio":"g5/u1/l3/10.mp3"},{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"Perfect. I think we're ready.","audio":"g5/u1/l3/11.mp3"}],"tasks":[{"type":"mcq","q":"When is Club Day?","opts":["this Tuesday","next Tuesday","next Thursday","next Sunday"],"ans":1},{"type":"mcq","q":"Who gives a speech at the opening?","opts":["the principal","the science teacher","Sami","Mr. Hassan"],"ans":0},{"type":"mcq","q":"Why is the Chess Club in the library?","opts":["The hall is closed.","The lab is busy.","The library is quiet.","Room 5 is too small."],"ans":3},{"type":"mcq","q":"What does the best club win?","opts":["a new computer","a trip to the science museum","free snacks","two hundred riyals"],"ans":1},{"type":"tf","s":"The Science Club is in Room 12.","ans":false},{"type":"tf","s":"Ben ordered snacks for two hundred students.","ans":true},{"type":"gap","s":"Students can visit the clubs from eight thirty to ___ o'clock.","ans":["ten","10"]},{"type":"gap","s":"Each club has ___ minutes to show its best work.","ans":["fifteen","15"]}],"predict":{"en":"A teacher and two students are planning a school Club Day. What do they need to plan?","ar":""},"tip":{"en":"Before listening, look at the gaps. Is the missing word a time, a number, a place or a name?","ar":"قبل الاستماع انظر إلى الفراغات: هل الكلمة الناقصة وقت أم عدد أم مكان أم اسم؟"},"speak":{"prompt":"Plan a class event with your group. Agree on the time, the place and one activity.","frame":"Let's start at ___. The ___ is in ___. After that, ___."},"teach":"Give students a blank timetable outline before the second listening. Completing it is real note-taking practice for later exams such as STEP and IELTS.","id":"g5u1l3","track":"g5/u1/l3/track.mp3"}],"speak":[{"kind":"speak","n":1,"title":"I'm Really Into Football","func":"Talking about hobbies and interests","func_ar":"التحدث عن الهوايات والاهتمامات","kagan":["Find Someone Who","Inside-Outside Circle"],"model":[{"sp":"ADAM","name":"Adam","text":"Ben, what do you do in your free time?","audio":"g5/u1/s1/01.mp3"},{"sp":"BEN","name":"Ben","text":"I'm really into football. I play with a club near my house.","audio":"g5/u1/s1/02.mp3"},{"sp":"ADAM","name":"Adam","text":"Cool! How often do you play?","audio":"g5/u1/s1/03.mp3"},{"sp":"BEN","name":"Ben","text":"Three times a week. What about you? What are you interested in?","audio":"g5/u1/s1/04.mp3"},{"sp":"ADAM","name":"Adam","text":"I'm interested in cooking. I love looking at recipe books and trying new food.","audio":"g5/u1/s1/05.mp3"},{"sp":"BEN","name":"Ben","text":"That's great! What's the best thing you can cook?","audio":"g5/u1/s1/06.mp3"},{"sp":"ADAM","name":"Adam","text":"I make a really good pasta. You should come and try it!","audio":"g5/u1/s1/07.mp3"},{"sp":"BEN","name":"Ben","text":"I'd love to! Maybe I can teach you some football tricks too.","audio":"g5/u1/s1/08.mp3"}],"roles":["ADAM","BEN"],"chunks":[{"en":"What do you do in your free time?","ar":"ماذا تفعل في وقت فراغك؟","audio":"g5/u1/s1/c1.mp3"},{"en":"I'm really into ___.","ar":"أنا مهتم جدًا بـ ___.","audio":"g5/u1/s1/c2.mp3"},{"en":"I'm interested in ___.","ar":"أنا مهتم بـ ___.","audio":"g5/u1/s1/c3.mp3"},{"en":"How often do you ___?","ar":"كم مرة ___؟","audio":"g5/u1/s1/c4.mp3"},{"en":"I'd love to!","ar":"يسعدني ذلك!","audio":"g5/u1/s1/c5.mp3"}],"sound":{"type":"sort","title":"Short /ʊ/ like \"book\" or long /uː/ like \"moon\"?","cats":[{"key":"/ʊ/","label":"/ʊ/ book"},{"key":"/uː/","label":"/uː/ moon"}],"en":"/ʊ/ is short with relaxed lips (book, good). /uː/ is long — push your lips forward, as if you're blowing out a candle (moon, food).","ar":"الصوت /ʊ/ قصير والشفتان مرتخيتان كما في book وgood، أما /uː/ فطويل مع دفع الشفتين إلى الأمام كأنك تطفئ شمعة كما في moon وfood.","items":[{"text":"football","key":"/ʊ/","audio":"g5/u1/s1/i1.mp3"},{"text":"food","key":"/uː/","audio":"g5/u1/s1/i2.mp3"},{"text":"cook","key":"/ʊ/","audio":"g5/u1/s1/i3.mp3"},{"text":"school","key":"/uː/","audio":"g5/u1/s1/i4.mp3"},{"text":"look","key":"/ʊ/","audio":"g5/u1/s1/i5.mp3"},{"text":"pool","key":"/uː/","audio":"g5/u1/s1/i6.mp3"},{"text":"good","key":"/ʊ/","audio":"g5/u1/s1/i7.mp3"},{"text":"soon","key":"/uː/","audio":"g5/u1/s1/i8.mp3"}]},"task":{"prompt":"Find two classmates who share a hobby with you. Ask how often they do it and why they like it.","frame":"What are you into? — I'm into ___. — Me too! How often do you ___?"},"cando":["I can talk about my hobbies and interests.","I can ask follow-up questions.","I can hear short /ʊ/ and long /uː/."],"teach":"Follow-up questions keep a conversation alive. Award a point every time a student asks a second question after the first answer.","id":"g5u1s1","track":"g5/u1/s1/track.mp3"},{"kind":"speak","n":2,"title":"Why Don't We...?","func":"Making and responding to suggestions","func_ar":"تقديم الاقتراحات والرد عليها","kagan":["Talking Chips","Mix-Pair-Share"],"model":[{"sp":"SAMI","name":"Sami","text":"It's Thursday! What shall we do this weekend?","audio":"g5/u1/s2/01.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"Why don't we go to the go-kart track?","audio":"g5/u1/s2/02.mp3"},{"sp":"SAMI","name":"Sami","text":"Hmm, it's very expensive. How about going to the new library? It has a gaming room.","audio":"g5/u1/s2/03.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"I'd like to see it, but I'd prefer to do something outside. The weather is lovely.","audio":"g5/u1/s2/04.mp3"},{"sp":"SAMI","name":"Sami","text":"Okay. Let's go cycling in Al-Rudaf Park, then.","audio":"g5/u1/s2/05.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"Great idea! Shall we ask Adam to come?","audio":"g5/u1/s2/06.mp3"},{"sp":"SAMI","name":"Sami","text":"Yes. And we could have a picnic after cycling.","audio":"g5/u1/s2/07.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"Perfect. I'll bring some sandwiches.","audio":"g5/u1/s2/08.mp3"}],"roles":["SAMI","YUSUF"],"chunks":[{"en":"Why don't we ___?","ar":"لماذا لا ___؟","audio":"g5/u1/s2/c1.mp3"},{"en":"How about ___ing?","ar":"ما رأيك في ___؟","audio":"g5/u1/s2/c2.mp3"},{"en":"Let's ___.","ar":"هيا ___.","audio":"g5/u1/s2/c3.mp3"},{"en":"Shall we ___?","ar":"هل ___؟","audio":"g5/u1/s2/c4.mp3"},{"en":"I'd prefer to ___.","ar":"أفضّل أن ___.","audio":"g5/u1/s2/c5.mp3"}],"sound":{"type":"pairs","title":"\"I like\" or \"I'd like\"?","en":"\"I'd\" is the short form of \"I would\". It sounds like \"I\" with a tiny /d/ at the end. Listen carefully, because the meaning changes: \"I like tea\" (always) — \"I'd like tea\" (now, please).","ar":"كلمة I'd اختصار I would، وتُنطق مثل I مع صوت /d/ صغير في آخرها. انتبه فالمعنى يتغير: I like tea تعني أحب الشاي دائمًا، وI'd like tea تعني أريد شايًا الآن.","pairs":[["I like tea.","I'd like tea."],["We go by car.","We'd go by car."],["I like to swim.","I'd like to swim."],["They play outside.","They'd play outside."],["I love a picnic.","I'd love a picnic."]],"audio":[["g5/u1/s2/p1a.mp3","g5/u1/s2/p1b.mp3"],["g5/u1/s2/p2a.mp3","g5/u1/s2/p2b.mp3"],["g5/u1/s2/p3a.mp3","g5/u1/s2/p3b.mp3"],["g5/u1/s2/p4a.mp3","g5/u1/s2/p4b.mp3"],["g5/u1/s2/p5a.mp3","g5/u1/s2/p5b.mp3"]]},"task":{"prompt":"Plan a weekend with your group. Make two suggestions, refuse one politely, then agree on a plan.","frame":"Why don't we ___? — Hmm, ___. How about ___? — Great idea!"},"cando":["I can make suggestions.","I can say no politely and suggest something else.","I can hear \"I like\" and \"I'd like\"."],"teach":"Teach the polite \"Hmm, ...\" before a refusal. Students practise saying no with a reason (\"it's very expensive\") instead of a flat \"No\".","id":"g5u1s2","track":"g5/u1/s2/track.mp3"}],"check":[{"type":"mcq","q":"When does Adam help his mom?","ref":"L1#3","opts":["after school","on Saturdays","every Friday","every evening"],"ans":2,"audio":"g5/u1/l1/03.mp3","line":"Hi, I'm Adam. I'm really into cooking. Every Friday, I help my mom make lunch for the whole family. Last week, I made chicken kabsa on my own, and everybody loved it!","speaker":"Adam"},{"type":"mcq","q":"When does Sami usually read?","ref":"L1#5","opts":["in the morning","before bed","at the weekend","after school"],"ans":1,"audio":"g5/u1/l1/05.mp3","line":"I'm Sami. I love reading, especially adventure stories. I usually read for thirty minutes before bed. This month, I'm reading a book about a boy who sails around the world.","speaker":"Sami"},{"type":"mcq","q":"When did Faris and his grandfather play?","ref":"L2#4","opts":["after school","at the weekend","every evening after dinner","every morning"],"ans":2,"audio":"g5/u1/l2/04.mp3","line":"When I was six. My grandfather taught me. We played every evening after dinner.","speaker":"Faris"},{"type":"mcq","q":"Where is the opening?","ref":"L3#2","opts":["in the library","in the school hall","in the lab","in Room 12"],"ans":1,"audio":"g5/u1/l3/02.mp3","line":"The opening is at eight o'clock in the school hall. The principal is going to give a short speech.","speaker":"Sami"}],"id":"g5u1"},{"n":2,"title":"Travel and Transport","ar":"السفر والمواصلات","emoji":"✈️","goals":["I can understand travel announcements.","I can compare ways to travel.","I can buy a ticket and ask about times."],"listen":[{"kind":"listen","n":1,"title":"At the Airport","skill":"Listening to announcements","skill_ar":"الاستماع إلى الإعلانات","kagan":["Showdown","RallyCoach"],"vocab":[{"w":"flight","ar":"رحلة جوية","emoji":"✈️","ex":"Our flight is delayed.","audio":"g5/u2/l1/v1.mp3"},{"w":"gate","ar":"بوابة","emoji":"🚪","ex":"The flight leaves from Gate 9.","audio":"g5/u2/l1/v2.mp3"},{"w":"boarding pass","ar":"بطاقة صعود الطائرة","emoji":"🎫","ex":"Have your boarding pass ready.","audio":"g5/u2/l1/v3.mp3"},{"w":"delayed","ar":"متأخّر","emoji":"⏰","ex":"The flight is delayed by forty-five minutes.","audio":"g5/u2/l1/v4.mp3"},{"w":"departure","ar":"المغادرة","emoji":"🛫","ex":"The new departure time is six o'clock.","audio":"g5/u2/l1/v5.mp3"},{"w":"passenger","ar":"مسافر / راكب","emoji":"🧳","ex":"Passengers, please don't leave your bags.","audio":"g5/u2/l1/v6.mp3"}],"script":[{"sp":"ANNOUNCER","name":"Announcer","text":"Good afternoon, ladies and gentlemen. Flight SV 1025 to Riyadh is now boarding at Gate 14.","audio":"g5/u2/l1/01.mp3"},{"sp":"ANNOUNCER","name":"Announcer","text":"Passengers for Flight SV 1025, please have your boarding pass ready.","audio":"g5/u2/l1/02.mp3"},{"sp":"DAD","name":"Dad","text":"That's not our flight. We're going to Dubai.","audio":"g5/u2/l1/03.mp3"},{"sp":"NOOR","name":"Noor","text":"Look, Dad! The screen says our flight is delayed.","audio":"g5/u2/l1/04.mp3"},{"sp":"DAD","name":"Dad","text":"You're right. It was at five fifteen, but now it's at six o'clock.","audio":"g5/u2/l1/05.mp3"},{"sp":"ANNOUNCER","name":"Announcer","text":"Attention, please. Flight EK 818 to Dubai is delayed by forty-five minutes because of bad weather. The new departure time is six o'clock, from Gate 9.","audio":"g5/u2/l1/06.mp3"},{"sp":"SAMI","name":"Sami","text":"We have time! Can we get something to eat?","audio":"g5/u2/l1/07.mp3"},{"sp":"DAD","name":"Dad","text":"Okay, but we need to be at the gate by half past five. Let's find a café near Gate 9.","audio":"g5/u2/l1/08.mp3"},{"sp":"ANNOUNCER","name":"Announcer","text":"A reminder to all passengers: please do not leave your bags alone in the airport.","audio":"g5/u2/l1/09.mp3"},{"sp":"NOOR","name":"Noor","text":"Sami, don't forget your backpack!","audio":"g5/u2/l1/10.mp3"}],"tasks":[{"type":"mcq","q":"Where is Flight SV 1025 going?","opts":["to London","to Jeddah","to Riyadh","to Dubai"],"ans":2},{"type":"mcq","q":"Why is the Dubai flight delayed?","opts":["a problem with the plane","a busy airport","the pilot is late","bad weather"],"ans":3},{"type":"mcq","q":"How long is the delay?","opts":["forty-five minutes","fifteen minutes","thirty minutes","one hour"],"ans":0},{"type":"mcq","q":"What does Noor remind Sami to take?","opts":["his boarding pass","his ticket","his backpack","his phone"],"ans":2},{"type":"tf","s":"Flight SV 1025 is boarding at Gate 14.","ans":true},{"type":"tf","s":"The family must be at the gate by six o'clock.","ans":false},{"type":"gap","s":"The new departure time for the Dubai flight is ___.","ans":["six o'clock","6:00","six","6","6 o'clock"]},{"type":"gap","s":"The Dubai flight leaves from Gate ___.","ans":["nine","9"]}],"predict":{"en":"Sami's family is at the airport. What kind of announcements do you hear at an airport?","ar":""},"tip":{"en":"Announcements repeat key information. If you miss a number the first time, wait — it often comes again.","ar":"تكرر الإعلانات المعلومات المهمة. إذا فاتك رقم في المرة الأولى فانتظر، فغالبًا سيتكرر."},"speak":{"prompt":"You are an airport announcer. Announce a flight to your partner; he writes the details.","frame":"Flight ___ to ___ is now boarding at Gate ___. It's delayed by ___ minutes."},"teach":"Show a picture of a real departures board before listening and teach \"boarding\", \"delayed\" and \"gate\" from it. The family must be at the gate by half past five, not six — a classic exam trap.","id":"g5u2l1","track":"g5/u2/l1/track.mp3"},{"kind":"listen","n":2,"title":"How Do You Get to School?","skill":"Listening and comparing","skill_ar":"الاستماع والمقارنة","kagan":["Line-Ups","Numbered Heads Together"],"vocab":[{"w":"journey","ar":"رحلة / مشوار","emoji":"🛣️","ex":"Adam has the longest journey.","audio":"g5/u2/l2/v1.mp3"},{"w":"take (time)","ar":"يستغرق","emoji":"⏱️","ex":"It takes fifteen minutes.","audio":"g5/u2/l2/v2.mp3"},{"w":"traffic","ar":"زحمة المرور","emoji":"🚗","ex":"There's always traffic near the school.","audio":"g5/u2/l2/v3.mp3"},{"w":"close","ar":"قريب","emoji":"📍","ex":"We live very close to school.","audio":"g5/u2/l2/v4.mp3"},{"w":"the slowest","ar":"الأبطأ","emoji":"🐢","ex":"The bus is the slowest way.","audio":"g5/u2/l2/v5.mp3"},{"w":"the cheapest","ar":"الأرخص","emoji":"💲","ex":"Walking is the cheapest way.","audio":"g5/u2/l2/v6.mp3"}],"script":[{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"For our math project, let's find out how everyone gets to school. Ben, you first.","audio":"g5/u2/l2/01.mp3"},{"sp":"BEN","name":"Ben","text":"I ride my bike. It takes about fifteen minutes. I love it because it's good exercise, and the mornings in Taif are cool.","audio":"g5/u2/l2/02.mp3"},{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"Very healthy! Adam?","audio":"g5/u2/l2/03.mp3"},{"sp":"ADAM","name":"Adam","text":"I come by school bus. It's the slowest way — thirty-five minutes! But it's fun, because I chat with my friends.","audio":"g5/u2/l2/04.mp3"},{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"And you, Yusuf?","audio":"g5/u2/l2/05.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"I walk with my older brother. We live very close, so it only takes ten minutes. It's the cheapest way, too!","audio":"g5/u2/l2/06.mp3"},{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"Sami?","audio":"g5/u2/l2/07.mp3"},{"sp":"SAMI","name":"Sami","text":"My dad drives me. Without traffic, it's twelve minutes, but there's always traffic near the school, so it usually takes twenty minutes.","audio":"g5/u2/l2/08.mp3"},{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"Interesting! So, who has the shortest journey?","audio":"g5/u2/l2/09.mp3"},{"sp":"BEN","name":"Ben","text":"Yusuf does! And Adam has the longest.","audio":"g5/u2/l2/10.mp3"}],"tasks":[{"type":"mcq","q":"Why does Ben like riding his bike?","opts":["It's good exercise, and the mornings are cool.","It's the fastest way.","His friends ride bikes too.","It's cheaper than the bus."],"ans":0},{"type":"mcq","q":"How long is Adam's journey?","opts":["ten minutes","thirty-five minutes","twenty minutes","fifteen minutes"],"ans":1},{"type":"mcq","q":"Who does Yusuf walk with?","opts":["his friends","his dad","Sami","his older brother"],"ans":3},{"type":"mcq","q":"Why does Sami's journey usually take twenty minutes?","opts":["There's always traffic near the school.","They live far away.","His dad drives slowly.","They stop at a shop."],"ans":0},{"type":"tf","s":"Adam thinks the bus is boring.","ans":false},{"type":"tf","s":"Yusuf has the shortest journey.","ans":true},{"type":"gap","s":"Without traffic, Sami's journey takes ___ minutes.","ans":["twelve","12"]},{"type":"gap","s":"The class is finding out about transport for their ___ project.","ans":["math","maths","mathematics"]}],"predict":{"en":"Four boys say how they get to school. Which way is the fastest? Which is the healthiest?","ar":""},"tip":{"en":"Listen for comparing words: the slowest, the cheapest, the shortest. They help you answer \"who\" questions.","ar":"استمع لكلمات المقارنة مثل the slowest وthe cheapest وthe shortest، فهي تساعدك في الإجابة عن أسئلة \"من\"."},"speak":{"prompt":"Ask three classmates how they get to school and how long it takes. Who has the longest journey?","frame":"How do you get to school? — I ___. — How long does it take? — It takes ___ minutes."},"teach":"Turn the class answers into a quick bar graph on the board. Students describe it: \"Most students come by car. The bus is the slowest.\"","id":"g5u2l2","track":"g5/u2/l2/track.mp3"},{"kind":"listen","n":3,"title":"A Trip to AlUla","skill":"Listening to travel plans","skill_ar":"الاستماع إلى خطط السفر","kagan":["Line-Ups","Think-Pair-Share"],"vocab":[{"w":"ancient","ar":"قديم / أثري","emoji":"🏺","ex":"Hegra is an ancient city.","audio":"g5/u2/l3/v1.mp3"},{"w":"tomb","ar":"مقبرة منحوتة","emoji":"⚱️","ex":"There are more than one hundred tombs.","audio":"g5/u2/l3/v2.mp3"},{"w":"rock","ar":"صخرة","emoji":"🪨","ex":"The tombs are cut into the rocks.","audio":"g5/u2/l3/v3.mp3"},{"w":"sunset","ar":"غروب الشمس","emoji":"🌇","ex":"We can watch the sunset.","audio":"g5/u2/l3/v4.mp3"},{"w":"sunrise","ar":"شروق الشمس","emoji":"🌅","ex":"The view at sunrise is amazing.","audio":"g5/u2/l3/v5.mp3"},{"w":"hot-air balloon","ar":"منطاد","emoji":"🎈","ex":"We're going on a hot-air balloon ride.","audio":"g5/u2/l3/v6.mp3"}],"script":[{"sp":"DAD","name":"Dad","text":"Okay, everyone, here's the plan for our trip to AlUla next week.","audio":"g5/u2/l3/01.mp3"},{"sp":"NOOR","name":"Noor","text":"How do we get there?","audio":"g5/u2/l3/02.mp3"},{"sp":"DAD","name":"Dad","text":"We're flying from Taif to Madinah on Wednesday morning. Then we're driving to AlUla. The drive takes about four hours.","audio":"g5/u2/l3/03.mp3"},{"sp":"SAMI","name":"Sami","text":"What are we going to see?","audio":"g5/u2/l3/04.mp3"},{"sp":"DAD","name":"Dad","text":"On Thursday, we're visiting Hegra. It's an ancient city with more than one hundred tombs cut into the rocks. It's about two thousand years old!","audio":"g5/u2/l3/05.mp3"},{"sp":"NOOR","name":"Noor","text":"Wow! Can we see Elephant Rock too?","audio":"g5/u2/l3/06.mp3"},{"sp":"DAD","name":"Dad","text":"Yes, on Thursday evening. It looks just like an elephant. We can watch the sunset there.","audio":"g5/u2/l3/07.mp3"},{"sp":"SAMI","name":"Sami","text":"What about Friday?","audio":"g5/u2/l3/08.mp3"},{"sp":"DAD","name":"Dad","text":"On Friday, we're going on a hot-air balloon ride over the desert. We need to wake up at five o'clock in the morning!","audio":"g5/u2/l3/09.mp3"},{"sp":"NOOR","name":"Noor","text":"Five o'clock? That's so early!","audio":"g5/u2/l3/10.mp3"},{"sp":"DAD","name":"Dad","text":"Trust me. The view at sunrise is amazing. Then, on Saturday, we fly home.","audio":"g5/u2/l3/11.mp3"}],"tasks":[{"type":"mcq","q":"How do they get from Madinah to AlUla?","opts":["by bus","by plane","by train","by car"],"ans":3},{"type":"mcq","q":"How old is Hegra?","opts":["about one hundred years old","about two thousand years old","about one thousand years old","about two hundred years old"],"ans":1},{"type":"mcq","q":"When can they watch the sunset at Elephant Rock?","opts":["on Saturday","on Wednesday evening","on Thursday evening","on Friday morning"],"ans":2},{"type":"mcq","q":"Why do they need to wake up at five o'clock on Friday?","opts":["for a hot-air balloon ride","to visit Hegra","to catch a plane","to drive home"],"ans":0},{"type":"tf","s":"The drive to AlUla takes about four hours.","ans":true},{"type":"tf","s":"Dad says the view at sunrise is amazing.","ans":true},{"type":"gap","s":"Hegra has more than one hundred ___ cut into the rocks.","ans":["tombs"]},{"type":"gap","s":"The family flies home on ___.","ans":["Saturday"]},{"type":"order","items":["They fly to Madinah and drive to AlUla.","They visit Hegra.","They watch the sunset at Elephant Rock.","They go on a balloon ride."]}],"predict":{"en":"Sami's family is planning a trip to AlUla. What do you know about AlUla?","ar":""},"tip":{"en":"Future plans often use \"We're ___ing\" with a time: On Thursday, we're visiting... Write each day and its plan.","ar":"تُعبَّر الخطط المستقبلية بصيغة We're ___ing مع وقت محدد مثل On Thursday, we're visiting... اكتب كل يوم وخطته."},"speak":{"prompt":"Plan a three-day trip to a place in Saudi Arabia. Tell your partner your plan.","frame":"On the first day, we're ___. On the second day, we're ___. On the last day, ___."},"teach":"Show photos of Hegra and Elephant Rock before listening. This is a good moment to talk about Saudi heritage sites and why we protect them.","id":"g5u2l3","track":"g5/u2/l3/track.mp3"}],"speak":[{"kind":"speak","n":1,"title":"Two Tickets, Please","func":"Buying a ticket","func_ar":"شراء تذكرة","kagan":["RallyCoach","Inside-Outside Circle"],"model":[{"sp":"WOMAN","name":"Ticket Officer","text":"Good morning. Welcome to Jeddah Station. How can I help you?","audio":"g5/u2/s1/01.mp3"},{"sp":"SAMI","name":"Sami","text":"Good morning. I'd like two tickets to Madinah, please.","audio":"g5/u2/s1/02.mp3"},{"sp":"WOMAN","name":"Ticket Officer","text":"Single or return?","audio":"g5/u2/s1/03.mp3"},{"sp":"SAMI","name":"Sami","text":"Return, please. We're coming back on Sunday.","audio":"g5/u2/s1/04.mp3"},{"sp":"WOMAN","name":"Ticket Officer","text":"The next train leaves at ten thirty. Is that okay?","audio":"g5/u2/s1/05.mp3"},{"sp":"SAMI","name":"Sami","text":"Yes, that's fine. How long does the journey take?","audio":"g5/u2/s1/06.mp3"},{"sp":"WOMAN","name":"Ticket Officer","text":"About two hours. Here are your tickets. Your train leaves from platform three.","audio":"g5/u2/s1/07.mp3"},{"sp":"SAMI","name":"Sami","text":"Thank you. Where can I get information about hotels in Madinah?","audio":"g5/u2/s1/08.mp3"},{"sp":"WOMAN","name":"Ticket Officer","text":"The information desk is next to the main entrance.","audio":"g5/u2/s1/09.mp3"}],"roles":["SAMI","WOMAN"],"chunks":[{"en":"I'd like two tickets to ___, please.","ar":"أريد تذكرتين إلى ___ من فضلك.","audio":"g5/u2/s1/c1.mp3"},{"en":"Single or return?","ar":"ذهاب فقط أم ذهاب وعودة؟","audio":"g5/u2/s1/c2.mp3"},{"en":"How long does the journey take?","ar":"كم تستغرق الرحلة؟","audio":"g5/u2/s1/c3.mp3"},{"en":"Which platform is it?","ar":"من أي رصيف؟","audio":"g5/u2/s1/c4.mp3"},{"en":"Where's the information desk?","ar":"أين مكتب الاستعلامات؟","audio":"g5/u2/s1/c5.mp3"}],"sound":{"type":"sort","title":"Where is the strong beat in -tion words?","cats":[{"key":"Oo","label":"Oo"},{"key":"oOo","label":"oOo"},{"key":"ooOo","label":"ooOo"}],"en":"In words ending in -tion, the strong beat is always just before -tion: STA-tion, di-REC-tion, des-ti-NA-tion.","ar":"في الكلمات المنتهية بـ -tion يقع المقطع القوي دائمًا قبل -tion مباشرةً، مثل STA-tion وdi-REC-tion وdes-ti-NA-tion.","items":[{"text":"station","key":"Oo","audio":"g5/u2/s1/i1.mp3"},{"text":"direction","key":"oOo","audio":"g5/u2/s1/i2.mp3"},{"text":"destination","key":"ooOo","audio":"g5/u2/s1/i3.mp3"},{"text":"nation","key":"Oo","audio":"g5/u2/s1/i4.mp3"},{"text":"connection","key":"oOo","audio":"g5/u2/s1/i5.mp3"},{"text":"information","key":"ooOo","audio":"g5/u2/s1/i6.mp3"},{"text":"question","key":"Oo","audio":"g5/u2/s1/i7.mp3"},{"text":"vacation","key":"oOo","audio":"g5/u2/s1/i8.mp3"},{"text":"reservation","key":"ooOo","audio":"g5/u2/s1/i9.mp3"}]},"task":{"prompt":"Role-play at a train station or a bus station. Buy a ticket and ask two questions.","frame":"I'd like a ___ ticket to ___. — What time does it leave? — Which platform?"},"cando":["I can buy a ticket.","I can ask about times and platforms.","I can stress -tion words correctly."],"teach":"Give students the rule as a \"secret code\": the strong beat is always right before -tion. They can now stress hundreds of words correctly.","id":"g5u2s1","track":"g5/u2/s1/track.mp3"},{"kind":"speak","n":2,"title":"Car or Plane?","func":"Comparing and giving opinions","func_ar":"المقارنة وإبداء الرأي","kagan":["Think-Pair-Share","Corners"],"model":[{"sp":"NOOR","name":"Noor","text":"Lina, which is better for a trip to Riyadh: the car or the plane?","audio":"g5/u2/s2/01.mp3"},{"sp":"LINA","name":"Lina","text":"I think the plane is better. It's much faster than the car.","audio":"g5/u2/s2/02.mp3"},{"sp":"NOOR","name":"Noor","text":"That's true, but the plane is more expensive.","audio":"g5/u2/s2/03.mp3"},{"sp":"LINA","name":"Lina","text":"Yes, and the car is more comfortable. You can stop when you're hungry!","audio":"g5/u2/s2/04.mp3"},{"sp":"NOOR","name":"Noor","text":"But the journey by car is very long — about nine hours!","audio":"g5/u2/s2/05.mp3"},{"sp":"LINA","name":"Lina","text":"Nine hours? That's the worst! I prefer the plane, even if it's more expensive.","audio":"g5/u2/s2/06.mp3"},{"sp":"NOOR","name":"Noor","text":"Okay, the plane is the best for long trips. But for short trips, the car is easier.","audio":"g5/u2/s2/07.mp3"},{"sp":"LINA","name":"Lina","text":"I agree with you!","audio":"g5/u2/s2/08.mp3"}],"roles":["NOOR","LINA"],"chunks":[{"en":"Which is better, ___ or ___?","ar":"أيهما أفضل، ___ أم ___؟","audio":"g5/u2/s2/c1.mp3"},{"en":"It's much faster than ___.","ar":"إنه أسرع بكثير من ___.","audio":"g5/u2/s2/c2.mp3"},{"en":"It's more expensive.","ar":"إنه أغلى.","audio":"g5/u2/s2/c3.mp3"},{"en":"That's true, but ___.","ar":"هذا صحيح، لكن ___.","audio":"g5/u2/s2/c4.mp3"},{"en":"I agree with you!","ar":"أوافقك الرأي!","audio":"g5/u2/s2/c5.mp3"}],"sound":{"type":"sort","title":"/ɜː/ like \"bird\" or /ɑː/ like \"car\"?","cats":[{"key":"/ɜː/","label":"/ɜː/ bird"},{"key":"/ɑː/","label":"/ɑː/ car"}],"en":"/ɜː/ (bird, first) is made in the middle of your mouth with relaxed lips. /ɑː/ (car, far) is made with a wide-open mouth, deep in the throat.","ar":"الصوت /ɜː/ كما في bird وfirst يخرج من وسط الفم والشفتان مرتخيتان، أما /ɑː/ كما في car وfar فيخرج والفم مفتوح واسعًا من عمق الحلق.","items":[{"text":"first","key":"/ɜː/","audio":"g5/u2/s2/i1.mp3"},{"text":"car","key":"/ɑː/","audio":"g5/u2/s2/i2.mp3"},{"text":"journey","key":"/ɜː/","audio":"g5/u2/s2/i3.mp3"},{"text":"far","key":"/ɑː/","audio":"g5/u2/s2/i4.mp3"},{"text":"world","key":"/ɜː/","audio":"g5/u2/s2/i5.mp3"},{"text":"start","key":"/ɑː/","audio":"g5/u2/s2/i6.mp3"},{"text":"turn","key":"/ɜː/","audio":"g5/u2/s2/i7.mp3"},{"text":"park","key":"/ɑː/","audio":"g5/u2/s2/i8.mp3"}]},"task":{"prompt":"Compare two ways to travel to a city you know. Give three reasons for your choice.","frame":"I prefer ___ because it's ___er than ___. It's also more ___."},"cando":["I can compare two things.","I can agree and disagree politely.","I can hear /ɜː/ and /ɑː/."],"teach":"Put \"car\" and \"plane\" signs in two corners. Students walk to their choice and prepare three reasons with their corner group before a short class debate.","id":"g5u2s2","track":"g5/u2/s2/track.mp3"}],"check":[{"type":"mcq","q":"Where do they want to eat?","ref":"L1#8","opts":["at a restaurant near Gate 14","on the plane","at a café near Gate 9","at home"],"ans":2,"audio":"g5/u2/l1/08.mp3","line":"Okay, but we need to be at the gate by half past five. Let's find a café near Gate 9.","speaker":"Dad"},{"type":"mcq","q":"What must passengers not do?","ref":"L1#9","opts":["leave their bags alone","run in the airport","use their phones","eat at the gate"],"ans":0,"audio":"g5/u2/l1/09.mp3","line":"A reminder to all passengers: please do not leave your bags alone in the airport.","speaker":"Announcer"},{"type":"mcq","q":"Why does Adam like the bus?","ref":"L2#4","opts":["It's fast.","It's cheap.","It's quiet.","He chats with his friends."],"ans":3,"audio":"g5/u2/l2/04.mp3","line":"I come by school bus. It's the slowest way — thirty-five minutes! But it's fun, because I chat with my friends.","speaker":"Adam"},{"type":"mcq","q":"When do they fly to Madinah?","ref":"L3#3","opts":["on Wednesday morning","on Saturday","on Friday morning","on Thursday evening"],"ans":0,"audio":"g5/u2/l3/03.mp3","line":"We're flying from Taif to Madinah on Wednesday morning. Then we're driving to AlUla. The drive takes about four hours.","speaker":"Dad"}],"id":"g5u2"},{"n":3,"title":"Stories from the Past","ar":"قصص من الماضي","emoji":"📜","goals":["I can follow and retell a story.","I can ask and answer questions about the past.","I can understand dates and facts about a famous person."],"listen":[{"kind":"listen","n":1,"title":"The Lost Camel","skill":"Following a story and making inferences","skill_ar":"تتبع قصة واستنتاج المعاني","kagan":["Think-Pair-Share","RoundRobin"],"vocab":[{"w":"merchant","ar":"تاجر","emoji":"🧔","ex":"The merchant lost a camel.","audio":"g5/u3/l1/v1.mp3"},{"w":"desert","ar":"صحراء","emoji":"🏜️","ex":"He was crossing the desert.","audio":"g5/u3/l1/v2.mp3"},{"w":"blind","ar":"أعمى","emoji":"🙈","ex":"The camel was blind in one eye.","audio":"g5/u3/l1/v3.mp3"},{"w":"judge","ar":"قاضٍ","emoji":"⚖️","ex":"They went to the judge.","audio":"g5/u3/l1/v4.mp3"},{"w":"thief","ar":"لص","emoji":"🦹","ex":"The brothers were not thieves.","audio":"g5/u3/l1/v5.mp3"},{"w":"oasis","ar":"واحة","emoji":"🌴","ex":"They found the camel near the oasis.","audio":"g5/u3/l1/v6.mp3"}],"script":[{"sp":"NARRATOR","name":"Narrator","text":"Long ago, a merchant was crossing the desert with his camels. One morning, he woke up and saw that one camel was missing. He walked for hours, and then he met three brothers sitting under a palm tree.","audio":"g5/u3/l1/01.mp3"},{"sp":"MAN","name":"Merchant","text":"Excuse me! Did you see a camel? I lost one of my camels last night.","audio":"g5/u3/l1/02.mp3"},{"sp":"MR_HASSAN","name":"First Brother","text":"Was your camel blind in one eye?","audio":"g5/u3/l1/03.mp3"},{"sp":"MAN","name":"Merchant","text":"Yes, it was!","audio":"g5/u3/l1/04.mp3"},{"sp":"DAD","name":"Second Brother","text":"Was it carrying honey on one side and wheat on the other side?","audio":"g5/u3/l1/05.mp3"},{"sp":"MAN","name":"Merchant","text":"Yes! So you saw it! Where is it?","audio":"g5/u3/l1/06.mp3"},{"sp":"ANNOUNCER","name":"Third Brother","text":"We didn't see your camel.","audio":"g5/u3/l1/07.mp3"},{"sp":"NARRATOR","name":"Narrator","text":"The merchant was angry. He thought the brothers had his camel, so he took them to the judge.","audio":"g5/u3/l1/08.mp3"},{"sp":"GRANDPA","name":"Judge","text":"How did you know about the camel?","audio":"g5/u3/l1/09.mp3"},{"sp":"MR_HASSAN","name":"First Brother","text":"The camel ate the grass on only one side of the road. So it could only see with one eye.","audio":"g5/u3/l1/10.mp3"},{"sp":"DAD","name":"Second Brother","text":"We saw flies on one side of the road. Flies love honey. And on the other side, birds were eating wheat.","audio":"g5/u3/l1/11.mp3"},{"sp":"NARRATOR","name":"Narrator","text":"The judge smiled. The brothers were clever, not thieves. The merchant said sorry, and the brothers helped him find his camel near the oasis.","audio":"g5/u3/l1/12.mp3"}],"tasks":[{"type":"mcq","q":"Where did the merchant meet the brothers?","opts":["at the judge's house","under a palm tree","at the market","near the oasis"],"ans":1},{"type":"mcq","q":"How did the first brother know the camel was blind in one eye?","opts":["The merchant told him.","He saw the camel's face.","It ate grass on only one side of the road.","It walked into a tree."],"ans":2},{"type":"mcq","q":"Why were there flies on one side of the road?","opts":["There was water there.","The camel was carrying honey.","The camel was sick.","There was a dead bird."],"ans":1},{"type":"mcq","q":"Why was the merchant angry?","opts":["The judge was late.","The brothers didn't help him.","He thought the brothers had his camel.","He was tired and hungry."],"ans":2},{"type":"tf","s":"The brothers saw the camel.","ans":false},{"type":"tf","s":"The judge thought the brothers were clever.","ans":true},{"type":"gap","s":"The camel was carrying honey and ___.","ans":["wheat"]},{"type":"gap","s":"In the end, they found the camel near the ___.","ans":["oasis"]},{"type":"order","items":["The merchant lost a camel.","He met three brothers.","They went to the judge.","They found the camel."]}],"predict":{"en":"This is an old Arab story about a lost camel and three clever brothers. How can someone describe a camel without seeing it?","ar":""},"tip":{"en":"Stories have clues. Listen to the answers to \"How did you know?\" — they explain the clues.","ar":"للقصص دلائل. استمع للإجابة عن سؤال \"How did you know?\" فهي تشرح الدلائل."},"speak":{"prompt":"Retell the story to your partner in five sentences. Use first, then, after that and in the end.","frame":"First, ___. Then, ___. After that, ___. In the end, ___."},"teach":"Stop the track after line 7 and ask: \"Did the brothers see the camel? How do they know so much?\" Let groups predict before they hear the explanation. This builds inference skills.","id":"g5u3l1","track":"g5/u3/l1/track.mp3"},{"kind":"listen","n":2,"title":"A School Trip Surprise","skill":"Listening for reasons in a story","skill_ar":"الاستماع إلى الأسباب في قصة","kagan":["Timed Pair Share","Showdown"],"vocab":[{"w":"mountain road","ar":"طريق جبلي","emoji":"🛣️","ex":"The bus stopped on the mountain road.","audio":"g5/u3/l2/v1.mp3"},{"w":"engine","ar":"محرّك","emoji":"⚙️","ex":"There was a problem with the engine.","audio":"g5/u3/l2/v2.mp3"},{"w":"wait","ar":"ينتظر","emoji":"⏳","ex":"We waited for almost an hour.","audio":"g5/u3/l2/v3.mp3"},{"w":"tractor","ar":"جرّار زراعي","emoji":"🚜","ex":"A farmer arrived with a tractor.","audio":"g5/u3/l2/v4.mp3"},{"w":"bumpy","ar":"وعر ومهتزّ","emoji":"〰️","ex":"The ride was slow and bumpy.","audio":"g5/u3/l2/v5.mp3"},{"w":"rose water","ar":"ماء الورد","emoji":"🌹","ex":"We learned how they make rose water.","audio":"g5/u3/l2/v6.mp3"}],"script":[{"sp":"ADAM","name":"Adam","text":"Last month, our class went on a trip to a rose farm in Al-Hada.","audio":"g5/u3/l2/01.mp3"},{"sp":"ADAM","name":"Adam","text":"We left school at seven thirty. Everyone was excited, and we played word games on the bus.","audio":"g5/u3/l2/02.mp3"},{"sp":"ADAM","name":"Adam","text":"But after twenty minutes, the bus stopped on the mountain road. There was a problem with the engine!","audio":"g5/u3/l2/03.mp3"},{"sp":"ADAM","name":"Adam","text":"Mr. Hassan called the farm, and we waited by the road for almost an hour. It was cold, so we put on our jackets.","audio":"g5/u3/l2/04.mp3"},{"sp":"ADAM","name":"Adam","text":"Then we heard a loud noise. A farmer arrived with a big tractor and a trailer! He drove us to the farm. It was slow and bumpy, but it was the best part of the day.","audio":"g5/u3/l2/05.mp3"},{"sp":"ADAM","name":"Adam","text":"At the farm, we learned how they make rose water. We picked roses, and each student took home a small bottle of rose oil for his mom.","audio":"g5/u3/l2/06.mp3"},{"sp":"ADAM","name":"Adam","text":"We got back to school at two o'clock — late, but very happy.","audio":"g5/u3/l2/07.mp3"}],"tasks":[{"type":"mcq","q":"Where did the class go?","opts":["to a zoo","to a factory in Jeddah","to a museum in Taif","to a rose farm in Al-Hada"],"ans":3},{"type":"mcq","q":"Why did the bus stop?","opts":["The road was closed.","There was a problem with the engine.","It was too cold.","A student was sick."],"ans":1},{"type":"mcq","q":"How did the class get to the farm?","opts":["They walked.","Another bus came.","A farmer drove them on a tractor and trailer.","Their parents drove them."],"ans":2},{"type":"mcq","q":"What did each student take home?","opts":["a photo","some rose water","some roses","a small bottle of rose oil"],"ans":3},{"type":"tf","s":"The students waited for almost an hour.","ans":true},{"type":"tf","s":"Adam thought the tractor ride was the worst part of the day.","ans":false},{"type":"gap","s":"The class left school at seven ___.","ans":["thirty","30"]},{"type":"gap","s":"They got back to school at ___ o'clock.","ans":["two","2"]}],"predict":{"en":"Adam's class went on a school trip, but something unexpected happened. What do you think it was?","ar":""},"tip":{"en":"For \"why\" questions, listen for \"because\", \"so\" and \"there was a problem with...\".","ar":"في أسئلة \"لماذا\" استمع لكلمات مثل because وso وthere was a problem with..."},"speak":{"prompt":"Tell your partner about a trip when something unexpected happened.","frame":"Last ___, we went to ___. Suddenly, ___. In the end, ___."},"teach":"Taif's roses and rose water are a source of local pride. Bring a small bottle of rose water to class; the smell makes the story real.","id":"g5u3l2","track":"g5/u3/l2/track.mp3"},{"kind":"listen","n":3,"title":"Ibn Battuta's Journey","skill":"Listening for dates and facts","skill_ar":"الاستماع إلى التواريخ والحقائق","kagan":["Numbered Heads Together","Fan-N-Pick"],"vocab":[{"w":"traveler","ar":"رحّالة","emoji":"🧭","ex":"Ibn Battuta was a famous traveler.","audio":"g5/u3/l3/v1.mp3"},{"w":"born","ar":"وُلِد","emoji":"👶","ex":"He was born in Tangier.","audio":"g5/u3/l3/v2.mp3"},{"w":"Hajj","ar":"الحج","emoji":"🕋","ex":"He left home to go on Hajj.","audio":"g5/u3/l3/v3.mp3"},{"w":"cross","ar":"يعبُر","emoji":"🐪","ex":"He crossed deserts on camels.","audio":"g5/u3/l3/v4.mp3"},{"w":"dangerous","ar":"خطير","emoji":"⚠️","ex":"His journeys were dangerous.","audio":"g5/u3/l3/v5.mp3"},{"w":"sink (sank)","ar":"تغرق (غرقت)","emoji":"🚢","ex":"His ship sank near India.","audio":"g5/u3/l3/v6.mp3"}],"script":[{"sp":"MS_GREEN","name":"Ms. Green","text":"Today, we're learning about a famous traveler: Ibn Battuta. He was born in Tangier, in Morocco, in 1304.","audio":"g5/u3/l3/01.mp3"},{"sp":"MS_GREEN","name":"Ms. Green","text":"When he was twenty-one years old, he left home to go on Hajj to Makkah. He planned to travel for a year or two, but he didn't come home for almost twenty-four years!","audio":"g5/u3/l3/02.mp3"},{"sp":"MS_GREEN","name":"Ms. Green","text":"He traveled to more than forty countries, including Egypt, India and China. He crossed deserts on camels and seas on wooden ships.","audio":"g5/u3/l3/03.mp3"},{"sp":"MS_GREEN","name":"Ms. Green","text":"His journeys were very dangerous. Once, his ship sank near India, and he lost everything he had.","audio":"g5/u3/l3/04.mp3"},{"sp":"MS_GREEN","name":"Ms. Green","text":"He traveled about one hundred and twenty thousand kilometers. That's three times around the world!","audio":"g5/u3/l3/05.mp3"},{"sp":"MS_GREEN","name":"Ms. Green","text":"When he finally returned to Morocco, the Sultan asked him to tell his stories. A writer wrote them down in a famous book called Ar-Rihla, which means \"The Journey\".","audio":"g5/u3/l3/06.mp3"}],"tasks":[{"type":"mcq","q":"Where was Ibn Battuta born?","opts":["in India","in Cairo, Egypt","in Tangier, Morocco","in Makkah"],"ans":2},{"type":"mcq","q":"Why did he first leave home?","opts":["to find a job","to buy a ship","to go on Hajj to Makkah","to visit China"],"ans":2},{"type":"mcq","q":"What happened near India?","opts":["He got married.","He met the Sultan.","He found treasure.","His ship sank."],"ans":3},{"type":"mcq","q":"Who asked him to tell his stories?","opts":["the Sultan","a ship captain","his family","his teacher"],"ans":0},{"type":"tf","s":"Ibn Battuta planned to travel for twenty-four years.","ans":false},{"type":"tf","s":"He traveled to more than forty countries.","ans":true},{"type":"gap","s":"Ibn Battuta was born in ___.","ans":["1304","thirteen oh four"]},{"type":"gap","s":"He traveled about one hundred and twenty thousand ___.","ans":["kilometers","kilometres","km"]}],"predict":{"en":"Ibn Battuta was a famous traveler from long ago. What was traveling like seven hundred years ago?","ar":""},"tip":{"en":"Write numbers and dates as digits while you listen: 1304, 21, 24, 40. Then check them with a partner.","ar":"اكتب الأعداد والتواريخ بالأرقام أثناء الاستماع، ثم راجعها مع زميلك."},"speak":{"prompt":"Tell your partner about a place you want to travel to and why.","frame":"I'd like to travel to ___ because ___. I want to see ___."},"teach":"Use a world map: students trace Ibn Battuta's route with string from Morocco to Makkah, India and China. Connect the lesson to the Arabic tradition of travel writing.","id":"g5u3l3","track":"g5/u3/l3/track.mp3"}],"speak":[{"kind":"speak","n":1,"title":"Guess What Happened!","func":"Telling a short story","func_ar":"سرد قصة قصيرة","kagan":["Timed Pair Share","Inside-Outside Circle"],"model":[{"sp":"BEN","name":"Ben","text":"Guess what happened to me yesterday!","audio":"g5/u3/s1/01.mp3"},{"sp":"SAMI","name":"Sami","text":"What? Tell me!","audio":"g5/u3/s1/02.mp3"},{"sp":"BEN","name":"Ben","text":"Well, first, I walked to the shop to buy some milk. Then I wanted to cross the road, so I waited at the traffic lights.","audio":"g5/u3/s1/03.mp3"},{"sp":"SAMI","name":"Sami","text":"Okay...","audio":"g5/u3/s1/04.mp3"},{"sp":"BEN","name":"Ben","text":"Suddenly, a small cat jumped onto my shoulder from a wall!","audio":"g5/u3/s1/05.mp3"},{"sp":"SAMI","name":"Sami","text":"No way! What did you do?","audio":"g5/u3/s1/06.mp3"},{"sp":"BEN","name":"Ben","text":"I shouted, and I dropped my bag! But the cat just looked at me and started to purr.","audio":"g5/u3/s1/07.mp3"},{"sp":"SAMI","name":"Sami","text":"Ha ha! What happened in the end?","audio":"g5/u3/s1/08.mp3"},{"sp":"BEN","name":"Ben","text":"In the end, I carried it home, and now it's our new pet!","audio":"g5/u3/s1/09.mp3"}],"roles":["BEN","SAMI"],"chunks":[{"en":"Guess what happened!","ar":"خمّن ماذا حدث!","audio":"g5/u3/s1/c1.mp3"},{"en":"Suddenly, ___.","ar":"فجأةً، ___.","audio":"g5/u3/s1/c2.mp3"},{"en":"No way!","ar":"غير معقول!","audio":"g5/u3/s1/c3.mp3"},{"en":"What happened in the end?","ar":"ماذا حدث في النهاية؟","audio":"g5/u3/s1/c4.mp3"},{"en":"In the end, ___.","ar":"في النهاية، ___.","audio":"g5/u3/s1/c5.mp3"}],"sound":{"type":"sort","title":"One beat or two beats?","cats":[{"key":"1","label":"1 beat"},{"key":"2","label":"2 beats"}],"en":"Most -ed verbs do NOT add a beat: walked = 1, jumped = 1. We add a beat only after t or d: wanted = 2, shouted = 2.","ar":"معظم أفعال -ed لا تضيف مقطعًا: walked مقطع واحد وjumped مقطع واحد. نضيف مقطعًا فقط بعد t أو d مثل wanted وshouted.","items":[{"text":"walked","key":"1","audio":"g5/u3/s1/i1.mp3"},{"text":"wanted","key":"2","audio":"g5/u3/s1/i2.mp3"},{"text":"jumped","key":"1","audio":"g5/u3/s1/i3.mp3"},{"text":"shouted","key":"2","audio":"g5/u3/s1/i4.mp3"},{"text":"dropped","key":"1","audio":"g5/u3/s1/i5.mp3"},{"text":"waited","key":"2","audio":"g5/u3/s1/i6.mp3"},{"text":"looked","key":"1","audio":"g5/u3/s1/i7.mp3"},{"text":"landed","key":"2","audio":"g5/u3/s1/i8.mp3"}]},"task":{"prompt":"Tell your partner a short story (true or invented). Use four past verbs and the story words. Your partner reacts.","frame":"Guess what happened! First, ___. Then, ___. Suddenly, ___. In the end, ___."},"cando":["I can tell a short story in the past.","I can react to a story.","I can say -ed verbs with the right number of beats."],"teach":"Good listeners react! Teach \"No way!\", \"Really?\" and \"What happened next?\" and require partners to use at least two reactions during each story.","id":"g5u3s1","track":"g5/u3/s1/track.mp3"},{"kind":"speak","n":2,"title":"When Did You First...?","func":"Asking questions about the past","func_ar":"طرح أسئلة عن الماضي","kagan":["Three-Step Interview","Team Interview"],"model":[{"sp":"NOOR","name":"Noor","text":"Grandpa, when did you first travel by plane?","audio":"g5/u3/s2/01.mp3"},{"sp":"GRANDPA","name":"Grandpa","text":"Let me think... It was in nineteen seventy-five. I was twenty years old.","audio":"g5/u3/s2/02.mp3"},{"sp":"NOOR","name":"Noor","text":"Where did you go?","audio":"g5/u3/s2/03.mp3"},{"sp":"GRANDPA","name":"Grandpa","text":"I went to Riyadh for a new job.","audio":"g5/u3/s2/04.mp3"},{"sp":"NOOR","name":"Noor","text":"Did you feel scared?","audio":"g5/u3/s2/05.mp3"},{"sp":"GRANDPA","name":"Grandpa","text":"Yes, I did! I held my seat very tightly.","audio":"g5/u3/s2/06.mp3"},{"sp":"NOOR","name":"Noor","text":"What did you eat on the plane?","audio":"g5/u3/s2/07.mp3"},{"sp":"GRANDPA","name":"Grandpa","text":"They gave us dates and Arabic coffee. It was delicious.","audio":"g5/u3/s2/08.mp3"},{"sp":"NOOR","name":"Noor","text":"Did you like flying?","audio":"g5/u3/s2/09.mp3"},{"sp":"GRANDPA","name":"Grandpa","text":"In the end, yes. I looked out of the window the whole time!","audio":"g5/u3/s2/10.mp3"}],"roles":["NOOR","GRANDPA"],"chunks":[{"en":"When did you first ___?","ar":"متى ___ لأول مرة؟","audio":"g5/u3/s2/c1.mp3"},{"en":"Where did you go?","ar":"إلى أين ذهبت؟","audio":"g5/u3/s2/c2.mp3"},{"en":"Did you feel scared?","ar":"هل شعرت بالخوف؟","audio":"g5/u3/s2/c3.mp3"},{"en":"What did you eat?","ar":"ماذا أكلت؟","audio":"g5/u3/s2/c4.mp3"},{"en":"Did you like it?","ar":"هل أعجبك ذلك؟","audio":"g5/u3/s2/c5.mp3"}],"sound":{"type":"sort","title":"How many words?","cats":[{"key":"3","label":"3 words"},{"key":"4","label":"4 words"},{"key":"5","label":"5 words"}],"en":"In fast questions, \"did you\" often sounds like \"didja\", and the words join together. Count carefully!","ar":"في الأسئلة السريعة تُنطق did you غالبًا مثل \"didja\" وتتصل الكلمات ببعضها. عُدّ بعناية!","items":[{"text":"Did you go?","key":"3","audio":"g5/u3/s2/i1.mp3"},{"text":"What did he say?","key":"4","audio":"g5/u3/s2/i2.mp3"},{"text":"Where did you go yesterday?","key":"5","audio":"g5/u3/s2/i3.mp3"},{"text":"Did they win?","key":"3","audio":"g5/u3/s2/i4.mp3"},{"text":"When did it start?","key":"4","audio":"g5/u3/s2/i5.mp3"},{"text":"Who did you see there?","key":"5","audio":"g5/u3/s2/i6.mp3"},{"text":"Was it good?","key":"3","audio":"g5/u3/s2/i7.mp3"},{"text":"Did you like it?","key":"4","audio":"g5/u3/s2/i8.mp3"},{"text":"What did you buy there?","key":"5","audio":"g5/u3/s2/i9.mp3"}]},"task":{"prompt":"Interview an older person in your family about a \"first time\" (first car, first trip, first school day). Report back to the class.","frame":"When did you first ___? Where did you ___? How did you feel?"},"cando":["I can ask questions about the past.","I can answer with past verbs.","I can hear \"did you\" in fast questions."],"teach":"Students prepare their interview questions in class and record the answers at home (with permission). Listening to family stories is authentic, meaningful practice.","id":"g5u3s2","track":"g5/u3/s2/track.mp3"}],"check":[{"type":"mcq","q":"When did the merchant notice that a camel was missing?","ref":"L1#1","opts":["one evening","at night","at lunchtime","one morning"],"ans":3,"audio":"g5/u3/l1/01.mp3","line":"Long ago, a merchant was crossing the desert with his camels. One morning, he woke up and saw that one camel was missing. He walked for hours, and then he met three brothers sitting under a palm tree.","speaker":"Narrator"},{"type":"mcq","q":"What were the birds eating?","ref":"L1#11","opts":["wheat","dates","honey","grass"],"ans":0,"audio":"g5/u3/l1/11.mp3","line":"We saw flies on one side of the road. Flies love honey. And on the other side, birds were eating wheat.","speaker":"Second Brother"},{"type":"mcq","q":"What did the students do on the bus?","ref":"L2#2","opts":["They read books.","They slept.","They played word games.","They watched a film."],"ans":2,"audio":"g5/u3/l2/02.mp3","line":"We left school at seven thirty. Everyone was excited, and we played word games on the bus.","speaker":"Adam"},{"type":"mcq","q":"What does \"Ar-Rihla\" mean?","ref":"L3#6","opts":["The Journey","The Ship","The Sultan","The Traveler"],"ans":0,"audio":"g5/u3/l3/06.mp3","line":"When he finally returned to Morocco, the Sultan asked him to tell his stories. A writer wrote them down in a famous book called Ar-Rihla, which means \"The Journey\".","speaker":"Ms. Green"}],"id":"g5u3"},{"n":4,"title":"Our Amazing Planet","ar":"كوكبنا المدهش","emoji":"🌍","goals":["I can compare animals, places and things.","I can describe a place and say what it's famous for.","I can understand facts in a documentary and a quiz."],"listen":[{"kind":"listen","n":1,"title":"Desert Life","skill":"Listening for facts and reasons","skill_ar":"الاستماع إلى الحقائق والأسباب","kagan":["Numbered Heads Together","RallyRobin"],"vocab":[{"w":"oryx","ar":"المها العربي","emoji":"🦌","ex":"The Arabian oryx is white.","audio":"g5/u4/l1/v1.mp3"},{"w":"horns","ar":"قرون","emoji":"🦬","ex":"It has long, straight horns.","audio":"g5/u4/l1/v2.mp3"},{"w":"reflect","ar":"يعكس","emoji":"🪞","ex":"Its white coat reflects the sun.","audio":"g5/u4/l1/v3.mp3"},{"w":"heat","ar":"الحرارة","emoji":"🔥","ex":"Big ears help it to lose heat.","audio":"g5/u4/l1/v4.mp3"},{"w":"hunt","ar":"يصطاد","emoji":"🎯","ex":"The fox hunts at night.","audio":"g5/u4/l1/v5.mp3"},{"w":"protect","ar":"يحمي","emoji":"🛡️","ex":"Long eyelashes protect its eyes.","audio":"g5/u4/l1/v6.mp3"}],"script":[{"sp":"NARRATOR","name":"Narrator","text":"The Arabian Desert is one of the hottest places on Earth. In summer, the sand can be hotter than seventy degrees! But many animals live here. How do they do it?","audio":"g5/u4/l1/01.mp3"},{"sp":"NARRATOR","name":"Narrator","text":"The Arabian oryx is a beautiful white animal with long, straight horns. Its white coat reflects the sun, so it stays cooler than darker animals. The oryx can live for weeks without drinking. It gets water from the plants it eats.","audio":"g5/u4/l1/02.mp3"},{"sp":"NARRATOR","name":"Narrator","text":"The fennec fox is smaller than a cat, but its ears are bigger than its face! Its big ears help it to lose heat. It sleeps underground in the day, where it's cooler, and it hunts at night.","audio":"g5/u4/l1/03.mp3"},{"sp":"NARRATOR","name":"Narrator","text":"The camel is the most famous desert animal. It can drink more than one hundred liters of water in ten minutes. Its long eyelashes protect its eyes from the sand.","audio":"g5/u4/l1/04.mp3"},{"sp":"NARRATOR","name":"Narrator","text":"In 1972, the Arabian oryx almost disappeared from the wild. Today, thanks to protection programs, there are more than a thousand oryx in the wild again.","audio":"g5/u4/l1/05.mp3"}],"tasks":[{"type":"mcq","q":"How hot can the desert sand be in summer?","opts":["more than seventy degrees","about forty degrees","one hundred degrees","about fifty degrees"],"ans":0},{"type":"mcq","q":"Why does the oryx stay cooler than darker animals?","opts":["It drinks a lot of water.","It lives underground.","Its white coat reflects the sun.","It sleeps in the day."],"ans":2},{"type":"mcq","q":"Where does the fennec fox sleep in the day?","opts":["underground","under a tree","near water","in the sun"],"ans":0},{"type":"mcq","q":"What protects the camel's eyes?","opts":["its white coat","its long eyelashes","its big ears","its long neck"],"ans":1},{"type":"tf","s":"The fennec fox is bigger than a cat.","ans":false},{"type":"tf","s":"The oryx gets water from the plants it eats.","ans":true},{"type":"gap","s":"A camel can drink more than one hundred ___ of water in ten minutes.","ans":["liters","litres","l"]},{"type":"gap","s":"In ___, the Arabian oryx almost disappeared from the wild.","ans":["1972","nineteen seventy-two"]}],"predict":{"en":"The desert is very hot and dry. How do animals live there?","ar":""},"tip":{"en":"Listen for comparing words like hotter, smaller, bigger and the most. They often answer \"why\" and \"how\" questions.","ar":"استمع لكلمات المقارنة مثل hotter وsmaller وbigger وthe most، فهي غالبًا تجيب عن أسئلة لماذا وكيف."},"speak":{"prompt":"Choose a desert animal. Tell your partner two ways it survives in the desert.","frame":"The ___ can ___. Its ___ helps it to ___."},"teach":"Show a photo of the Arabian oryx. Explain that Saudi Arabia protects it in nature reserves — a good link to caring for our environment and wildlife.","id":"g5u4l1","track":"g5/u4/l1/track.mp3"},{"kind":"listen","n":2,"title":"Planet Quiz","skill":"Listening for superlatives","skill_ar":"الاستماع إلى صيغ التفضيل","kagan":["Showdown","Numbered Heads Together"],"vocab":[{"w":"the largest","ar":"الأكبر","emoji":"🌊","ex":"The Pacific is the largest ocean.","audio":"g5/u4/l2/v1.mp3"},{"w":"ocean","ar":"محيط","emoji":"🌐","ex":"What is the largest ocean?","audio":"g5/u4/l2/v2.mp3"},{"w":"the longest","ar":"الأطول","emoji":"📏","ex":"The Nile is the longest river.","audio":"g5/u4/l2/v3.mp3"},{"w":"river","ar":"نهر","emoji":"🏞️","ex":"The river is about six thousand kilometers long.","audio":"g5/u4/l2/v4.mp3"},{"w":"planet","ar":"كوكب","emoji":"🪐","ex":"Venus is the hottest planet.","audio":"g5/u4/l2/v5.mp3"},{"w":"the smallest","ar":"الأصغر","emoji":"🐦","ex":"The hummingbird is the smallest bird.","audio":"g5/u4/l2/v6.mp3"}],"script":[{"sp":"WOMAN","name":"Quiz Host","text":"Welcome to Planet Quiz! Our players today are Ben and Yusuf. Question one, for Ben: what is the largest ocean in the world?","audio":"g5/u4/l2/01.mp3"},{"sp":"BEN","name":"Ben","text":"I think it's the Pacific Ocean.","audio":"g5/u4/l2/02.mp3"},{"sp":"WOMAN","name":"Quiz Host","text":"Correct! Yusuf, question two: what is the longest river in the world? Is it the Amazon or the Nile?","audio":"g5/u4/l2/03.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"It's the Nile. It's about six thousand six hundred kilometers long.","audio":"g5/u4/l2/04.mp3"},{"sp":"WOMAN","name":"Quiz Host","text":"That's right! Ben, question three: which is the hottest planet, Mercury or Venus?","audio":"g5/u4/l2/05.mp3"},{"sp":"BEN","name":"Ben","text":"Mercury, because it's the closest to the sun.","audio":"g5/u4/l2/06.mp3"},{"sp":"WOMAN","name":"Quiz Host","text":"Oh, sorry, Ben! It's Venus. Its thick clouds keep the heat in. Yusuf, here's a bonus question. What is the smallest bird in the world?","audio":"g5/u4/l2/07.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"The hummingbird! Some hummingbirds are only five centimeters long.","audio":"g5/u4/l2/08.mp3"},{"sp":"WOMAN","name":"Quiz Host","text":"Excellent! So, the final score: Ben has one point, and Yusuf has three points. Yusuf is our winner today!","audio":"g5/u4/l2/09.mp3"}],"tasks":[{"type":"mcq","q":"What is the largest ocean in the world?","opts":["the Atlantic Ocean","the Indian Ocean","the Arctic Ocean","the Pacific Ocean"],"ans":3},{"type":"mcq","q":"Why did Ben choose Mercury?","opts":["It's the closest planet to the sun.","It's his favorite planet.","It's the biggest planet.","It has thick clouds."],"ans":0},{"type":"mcq","q":"Why is Venus the hottest planet?","opts":["It has no water.","Its thick clouds keep the heat in.","It's the biggest planet.","It's the closest to the sun."],"ans":1},{"type":"mcq","q":"Who wins the quiz?","opts":["the host","Ben","nobody","Yusuf"],"ans":3},{"type":"tf","s":"The quiz says the Nile is the longest river in the world.","ans":true},{"type":"tf","s":"Ben answered all his questions correctly.","ans":false},{"type":"gap","s":"Some hummingbirds are only ___ centimeters long.","ans":["five","5"]},{"type":"gap","s":"The Nile is about six thousand six hundred ___ long.","ans":["kilometers","kilometres","km"]}],"predict":{"en":"Two boys answer questions in a quiz about our planet. Do you know the largest ocean or the longest river?","ar":""},"tip":{"en":"Quiz questions often give two choices: \"Is it A or B?\" Listen to which choice the player says and whether the host says \"correct\".","ar":"غالبًا ما تعطي أسئلة المسابقات خيارين: Is it A or B? استمع للخيار الذي يقوله المتسابق، ولما إذا قالت المذيعة correct."},"speak":{"prompt":"Write three \"biggest, smallest or longest\" quiz questions. Ask your partner.","frame":"What is the ___est ___ in the world? — I think it's ___."},"teach":"Ben's mistake is a great teaching moment: the closest planet is not the hottest. Ask \"Why was Ben wrong?\" to practise explaining reasons.","id":"g5u4l2","track":"g5/u4/l2/track.mp3"},{"kind":"listen","n":3,"title":"Under the Red Sea","skill":"Completing notes from a talk","skill_ar":"إكمال الملاحظات من محاضرة","kagan":["RallyCoach","Talking Chips"],"vocab":[{"w":"coral reef","ar":"الشعاب المرجانية","emoji":"🪸","ex":"The coral reef is beautiful.","audio":"g5/u4/l3/v1.mp3"},{"w":"tiny","ar":"صغير جدًا","emoji":"🔬","ex":"Coral is made of tiny animals.","audio":"g5/u4/l3/v2.mp3"},{"w":"poisonous","ar":"سامّ","emoji":"☠️","ex":"The lionfish has poisonous spines.","audio":"g5/u4/l3/v3.mp3"},{"w":"pollution","ar":"التلوّث","emoji":"🏭","ex":"Pollution is dangerous for the reef.","audio":"g5/u4/l3/v4.mp3"},{"w":"turtle","ar":"سلحفاة","emoji":"🐢","ex":"Let's go and see the turtles.","audio":"g5/u4/l3/v5.mp3"},{"w":"in danger","ar":"في خطر","emoji":"⚠️","ex":"Coral reefs are in danger.","audio":"g5/u4/l3/v6.mp3"}],"script":[{"sp":"MAN","name":"Guide","text":"Welcome to the Red Sea Marine Center. The Red Sea is about two thousand two hundred kilometers long, and it's home to more than one thousand two hundred kinds of fish.","audio":"g5/u4/l3/01.mp3"},{"sp":"MAN","name":"Guide","text":"The most important part of the Red Sea is the coral reef. Coral looks like colorful rocks or plants, but it's actually made of tiny animals!","audio":"g5/u4/l3/02.mp3"},{"sp":"MAN","name":"Guide","text":"Red Sea coral is special. It can live in warmer water than most coral in the world. Scientists from many countries come here to study it.","audio":"g5/u4/l3/03.mp3"},{"sp":"MAN","name":"Guide","text":"Some of the fish you can see here are the clownfish, the parrotfish and the lionfish. Be careful with the lionfish — it has poisonous spines!","audio":"g5/u4/l3/04.mp3"},{"sp":"MAN","name":"Guide","text":"Coral reefs are in danger because of pollution and plastic. One plastic bag can kill a sea turtle, because the turtle thinks it's a jellyfish.","audio":"g5/u4/l3/05.mp3"},{"sp":"MAN","name":"Guide","text":"So please, never leave rubbish on the beach. Now, let's go and see the turtles!","audio":"g5/u4/l3/06.mp3"}],"tasks":[{"type":"mcq","q":"What is coral made of?","opts":["tiny animals","colorful rocks","sea plants","sand"],"ans":0},{"type":"mcq","q":"Why do scientists come to study Red Sea coral?","opts":["It's very old.","It changes color at night.","It's the biggest coral in the world.","It can live in warmer water than most coral."],"ans":3},{"type":"mcq","q":"Which fish has poisonous spines?","opts":["the lionfish","the parrotfish","the jellyfish","the clownfish"],"ans":0},{"type":"mcq","q":"Why can a plastic bag kill a sea turtle?","opts":["The bag is poisonous.","The bag hits the turtle.","The turtle can't see it.","The turtle thinks it's a jellyfish."],"ans":3},{"type":"tf","s":"Coral is a kind of plant.","ans":false},{"type":"tf","s":"Coral reefs are in danger because of fishing boats only.","ans":false},{"type":"gap","s":"The Red Sea is about two thousand two hundred ___ long.","ans":["kilometers","kilometres","km"]},{"type":"gap","s":"After the talk, the students are going to see the ___.","ans":["turtles"]}],"predict":{"en":"A guide talks to students at a marine center in Jeddah. What lives under the Red Sea?","ar":""},"tip":{"en":"Read the gaps before listening. Numbers and nouns are the most common missing words in note completion.","ar":"اقرأ الفراغات قبل الاستماع. الأعداد والأسماء هي أكثر الكلمات الناقصة شيوعًا في تمارين إكمال الملاحظات."},"speak":{"prompt":"Plan a poster: \"Protect the Red Sea\". Tell your partner three rules.","frame":"Never ___. Always ___. Don't ___ because ___."},"teach":"Coral \"looks like\" a plant but \"is actually\" an animal — teach \"actually\" as a signal word that corrects a wrong idea. Students write a class promise about plastic and the beach.","id":"g5u4l3","track":"g5/u4/l3/track.mp3"}],"speak":[{"kind":"speak","n":1,"title":"Which One Is Better?","func":"Comparing things","func_ar":"مقارنة الأشياء","kagan":["RallyCoach","Think-Pair-Share"],"model":[{"sp":"SAMI","name":"Sami","text":"Look at these two phones. Which one should we buy for Grandpa?","audio":"g5/u4/s1/01.mp3"},{"sp":"NOOR","name":"Noor","text":"This one is bigger. Grandpa can see the screen better.","audio":"g5/u4/s1/02.mp3"},{"sp":"SAMI","name":"Sami","text":"True. But it's heavier than the small one.","audio":"g5/u4/s1/03.mp3"},{"sp":"NOOR","name":"Noor","text":"The small one is lighter, but the buttons are smaller too.","audio":"g5/u4/s1/04.mp3"},{"sp":"SAMI","name":"Sami","text":"Hmm. Which one is cheaper?","audio":"g5/u4/s1/05.mp3"},{"sp":"NOOR","name":"Noor","text":"The big one is cheaper — only four hundred riyals.","audio":"g5/u4/s1/06.mp3"},{"sp":"SAMI","name":"Sami","text":"Then the big phone is better for Grandpa. It's cheaper and easier to use.","audio":"g5/u4/s1/07.mp3"},{"sp":"NOOR","name":"Noor","text":"I agree. Let's buy the big one!","audio":"g5/u4/s1/08.mp3"}],"roles":["SAMI","NOOR"],"chunks":[{"en":"This one is bigger.","ar":"هذا أكبر.","audio":"g5/u4/s1/c1.mp3"},{"en":"It's heavier than ___.","ar":"إنه أثقل من ___.","audio":"g5/u4/s1/c2.mp3"},{"en":"Which one is cheaper?","ar":"أيهما أرخص؟","audio":"g5/u4/s1/c3.mp3"},{"en":"It's easier to use.","ar":"إنه أسهل في الاستخدام.","audio":"g5/u4/s1/c4.mp3"},{"en":"I agree.","ar":"أوافق.","audio":"g5/u4/s1/c5.mp3"}],"sound":{"type":"pairs","title":"tall or taller?","en":"The -er ending is very weak: /ə/. \"Taller\" sounds like \"tall-uh\". Listen carefully for this small sound at the end — it changes the meaning!","ar":"نهاية -er ضعيفة جدًا وتُنطق /ə/، فتبدو taller مثل \"tall-uh\". استمع جيدًا لهذا الصوت الصغير في النهاية، فهو يغيّر المعنى!","pairs":[["The camel is fast.","The camel is faster."],["It's hot today.","It's hotter today."],["This tree is tall.","This tree is taller."],["The river is long.","The river is longer."],["My bag is big.","My bag is bigger."]],"audio":[["g5/u4/s1/p1a.mp3","g5/u4/s1/p1b.mp3"],["g5/u4/s1/p2a.mp3","g5/u4/s1/p2b.mp3"],["g5/u4/s1/p3a.mp3","g5/u4/s1/p3b.mp3"],["g5/u4/s1/p4a.mp3","g5/u4/s1/p4b.mp3"],["g5/u4/s1/p5a.mp3","g5/u4/s1/p5b.mp3"]]},"task":{"prompt":"Bring two pictures (two phones, two cars or two animals). Compare them with your partner and choose the better one.","frame":"The ___ is ___er than the ___. But the ___ is more ___. I think ___ is better."},"cando":["I can compare two things.","I can explain my choice.","I can hear the weak -er ending."],"teach":"The weak /ə/ is the most common sound in English. Draw a small \"uh\" face on the board and point to it every time students hear the -er ending.","id":"g5u4s1","track":"g5/u4/s1/track.mp3"},{"kind":"speak","n":2,"title":"It's Famous for Its Mountains","func":"Describing a place","func_ar":"وصف مكان","kagan":["Timed Pair Share","Carousel Feedback"],"model":[{"sp":"BEN","name":"Ben","text":"Adam, you visited Abha last summer. What was it like?","audio":"g5/u4/s2/01.mp3"},{"sp":"ADAM","name":"Adam","text":"It was amazing! It's a beautiful city in the mountains.","audio":"g5/u4/s2/02.mp3"},{"sp":"BEN","name":"Ben","text":"Is it famous for anything?","audio":"g5/u4/s2/03.mp3"},{"sp":"ADAM","name":"Adam","text":"Yes, it's famous for its green mountains and its colorful houses. There's also a cable car with an incredible view.","audio":"g5/u4/s2/04.mp3"},{"sp":"BEN","name":"Ben","text":"Was the weather hot?","audio":"g5/u4/s2/05.mp3"},{"sp":"ADAM","name":"Adam","text":"No, it was cool and foggy. It's much cooler than Riyadh in summer.","audio":"g5/u4/s2/06.mp3"},{"sp":"BEN","name":"Ben","text":"What's the best thing to do there?","audio":"g5/u4/s2/07.mp3"},{"sp":"ADAM","name":"Adam","text":"You must visit the old village of Rijal Almaa. It's really interesting.","audio":"g5/u4/s2/08.mp3"},{"sp":"BEN","name":"Ben","text":"It sounds wonderful. I'd love to go!","audio":"g5/u4/s2/09.mp3"}],"roles":["BEN","ADAM"],"chunks":[{"en":"What was it like?","ar":"كيف كان؟","audio":"g5/u4/s2/c1.mp3"},{"en":"It's famous for ___.","ar":"إنه مشهور بـ ___.","audio":"g5/u4/s2/c2.mp3"},{"en":"There's a ___ with an incredible view.","ar":"يوجد ___ بإطلالة مذهلة.","audio":"g5/u4/s2/c3.mp3"},{"en":"You must visit ___.","ar":"يجب أن تزور ___.","audio":"g5/u4/s2/c4.mp3"},{"en":"It sounds wonderful!","ar":"يبدو ذلك رائعًا!","audio":"g5/u4/s2/c5.mp3"}],"sound":{"type":"sort","title":"a-MA-zing or BEAU-ti-ful?","cats":[{"key":"oOo","label":"oOo"},{"key":"Ooo","label":"Ooo"}],"en":"Describing words have one strong beat. a-MA-zing has it in the middle (oOo). BEAU-ti-ful has it at the start (Ooo).","ar":"لصفات الوصف مقطع قوي واحد. في a-MA-zing يكون في الوسط (oOo)، وفي BEAU-ti-ful يكون في البداية (Ooo).","items":[{"text":"amazing","key":"oOo","audio":"g5/u4/s2/i1.mp3"},{"text":"beautiful","key":"Ooo","audio":"g5/u4/s2/i2.mp3"},{"text":"important","key":"oOo","audio":"g5/u4/s2/i3.mp3"},{"text":"dangerous","key":"Ooo","audio":"g5/u4/s2/i4.mp3"},{"text":"enormous","key":"oOo","audio":"g5/u4/s2/i5.mp3"},{"text":"wonderful","key":"Ooo","audio":"g5/u4/s2/i6.mp3"},{"text":"delicious","key":"oOo","audio":"g5/u4/s2/i7.mp3"},{"text":"popular","key":"Ooo","audio":"g5/u4/s2/i8.mp3"}]},"task":{"prompt":"Describe a place you visited to your group. Say what it's famous for and what visitors must do.","frame":"Last ___, I visited ___. It's famous for ___. It's ___ and ___. You must ___."},"cando":["I can describe a place.","I can recommend things to do.","I can stress describing words correctly."],"teach":"Students make a \"travel postcard\" with a drawing and three sentences, then do Carousel Feedback: groups walk around and leave one kind comment and one question on each postcard.","id":"g5u4s2","track":"g5/u4/s2/track.mp3"}],"check":[{"type":"mcq","q":"How long can the oryx live without drinking?","ref":"L1#2","opts":["for days","for weeks","for months","for hours"],"ans":1,"audio":"g5/u4/l1/02.mp3","line":"The Arabian oryx is a beautiful white animal with long, straight horns. Its white coat reflects the sun, so it stays cooler than darker animals. The oryx can live for weeks without drinking. It gets water from the plants it eats.","speaker":"Narrator"},{"type":"mcq","q":"When does the fennec fox hunt?","ref":"L1#3","opts":["in the afternoon","in the morning","at noon","at night"],"ans":3,"audio":"g5/u4/l1/03.mp3","line":"The fennec fox is smaller than a cat, but its ears are bigger than its face! Its big ears help it to lose heat. It sleeps underground in the day, where it's cooler, and it hunts at night.","speaker":"Narrator"},{"type":"mcq","q":"How many points does Ben have at the end?","ref":"L2#9","opts":["one","two","three","none"],"ans":0,"audio":"g5/u4/l2/09.mp3","line":"Excellent! So, the final score: Ben has one point, and Yusuf has three points. Yusuf is our winner today!","speaker":"Quiz Host"},{"type":"mcq","q":"Which fish does the guide NOT mention?","ref":"L3#4","opts":["the lionfish","the parrotfish","the clownfish","the swordfish"],"ans":3,"audio":"g5/u4/l3/04.mp3","line":"Some of the fish you can see here are the clownfish, the parrotfish and the lionfish. Be careful with the lionfish — it has poisonous spines!","speaker":"Guide"}],"id":"g5u4"},{"n":5,"title":"Jobs and Future Plans","ar":"المهن وخطط المستقبل","emoji":"👩‍🚀","goals":["I can describe jobs and what people do.","I can talk about my future plans with \"going to\".","I can understand people talking about their work."],"listen":[{"kind":"listen","n":1,"title":"Guess the Job","skill":"Making inferences from clues","skill_ar":"الاستنتاج من الدلائل","kagan":["Showdown","Fan-N-Pick"],"vocab":[{"w":"look after","ar":"يعتني بـ","emoji":"🤲","ex":"I look after sick children.","audio":"g5/u5/l1/v1.mp3"},{"w":"calm","ar":"هادئ","emoji":"😌","ex":"I help them feel calm.","audio":"g5/u5/l1/v2.mp3"},{"w":"control tower","ar":"برج المراقبة","emoji":"🗼","ex":"I talk to the control tower.","audio":"g5/u5/l1/v3.mp3"},{"w":"design","ar":"يصمّم","emoji":"✏️","ex":"I design buildings and bridges.","audio":"g5/u5/l1/v4.mp3"},{"w":"building site","ar":"موقع بناء","emoji":"🏗️","ex":"I visit building sites.","audio":"g5/u5/l1/v5.mp3"},{"w":"safety","ar":"السلامة","emoji":"🦺","ex":"Safety is the most important part of my job.","audio":"g5/u5/l1/v6.mp3"}],"script":[{"sp":"NARRATOR","name":"Narrator","text":"Listen to four people talking about their jobs. Can you guess what each job is?","audio":"g5/u5/l1/01.mp3"},{"sp":"NARRATOR","name":"Narrator","text":"Speaker one.","audio":"g5/u5/l1/02.mp3"},{"sp":"WOMAN","name":"Speaker 1","text":"I work in a hospital, but I'm not a doctor. I look after children when they are sick. I check their temperature, give them their medicine and help them feel calm. I often work at night.","audio":"g5/u5/l1/03.mp3"},{"sp":"NARRATOR","name":"Narrator","text":"Speaker two.","audio":"g5/u5/l1/04.mp3"},{"sp":"MAN","name":"Speaker 2","text":"My office is in the sky! I check the weather before every flight, and I talk to the control tower. Last week, I flew from Jeddah to Kuala Lumpur.","audio":"g5/u5/l1/05.mp3"},{"sp":"NARRATOR","name":"Narrator","text":"Speaker three.","audio":"g5/u5/l1/06.mp3"},{"sp":"DAD","name":"Speaker 3","text":"I design buildings and bridges. I use a computer to draw plans, and I visit building sites to check the work. Safety is the most important part of my job.","audio":"g5/u5/l1/07.mp3"},{"sp":"NARRATOR","name":"Narrator","text":"Speaker four.","audio":"g5/u5/l1/08.mp3"},{"sp":"MS_GREEN","name":"Speaker 4","text":"My patients can't tell me where it hurts! I take care of cats, dogs, horses and sometimes camels. Yesterday, I helped a cat with a broken leg.","audio":"g5/u5/l1/09.mp3"}],"tasks":[{"type":"mcq","q":"What is speaker one's job?","opts":["a doctor","a nurse","a pharmacist","a teacher"],"ans":1},{"type":"mcq","q":"What is speaker two's job?","opts":["a flight attendant","a weather presenter","a travel agent","a pilot"],"ans":3},{"type":"mcq","q":"What is speaker three's job?","opts":["a builder","a computer programmer","an artist","an engineer"],"ans":3},{"type":"mcq","q":"What is speaker four's job?","opts":["a zookeeper","a vet","a farmer","a doctor"],"ans":1},{"type":"tf","s":"Speaker two flew to Kuala Lumpur last week.","ans":true},{"type":"tf","s":"Speaker three says money is the most important part of the job.","ans":false},{"type":"gap","s":"Speaker one often works at ___.","ans":["night"]},{"type":"gap","s":"Yesterday, speaker four helped a cat with a broken ___.","ans":["leg"]}],"predict":{"en":"Four people describe their jobs, but they don't say the job's name. What clues can help you guess?","ar":""},"tip":{"en":"Don't wait for the name of the job. Collect clues: the place of work, the tools, the people they help.","ar":"لا تنتظر اسم المهنة. اجمع الدلائل: مكان العمل، والأدوات، والأشخاص الذين يساعدونهم."},"speak":{"prompt":"Describe a job without saying its name. Your group guesses.","frame":"I work in/at ___. I use ___. I help ___. What's my job?"},"teach":"Ask \"Which word told you?\" after each speaker: \"office in the sky\" → pilot, \"patients can't tell me where it hurts\" → vet. Students learn to collect clues instead of waiting for one key word.","id":"g5u5l1","track":"g5/u5/l1/track.mp3"},{"kind":"listen","n":2,"title":"Career Day","skill":"Listening to talks and answers","skill_ar":"الاستماع إلى العروض والإجابات","kagan":["Three-Step Interview","Numbered Heads Together"],"vocab":[{"w":"career","ar":"مهنة / مسيرة مهنية","emoji":"💼","ex":"Welcome to Career Day!","audio":"g5/u5/l2/v1.mp3"},{"w":"software engineer","ar":"مهندس برمجيات","emoji":"💻","ex":"He's a software engineer.","audio":"g5/u5/l2/v2.mp3"},{"w":"solve problems","ar":"يحلّ المشكلات","emoji":"🧩","ex":"You need to love solving problems.","audio":"g5/u5/l2/v3.mp3"},{"w":"firefighter","ar":"رجل إطفاء","emoji":"🧑‍🚒","ex":"Captain Nasser is a firefighter.","audio":"g5/u5/l2/v4.mp3"},{"w":"accident","ar":"حادث","emoji":"🚑","ex":"We help people in car accidents.","audio":"g5/u5/l2/v5.mp3"},{"w":"smoke alarm","ar":"جهاز إنذار الدخان","emoji":"🚨","ex":"Make sure your home has a smoke alarm.","audio":"g5/u5/l2/v6.mp3"}],"script":[{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"Good morning, boys. Welcome to Career Day! Our first visitor is Mr. Turki. He's a software engineer.","audio":"g5/u5/l2/01.mp3"},{"sp":"MAN","name":"Mr. Turki","text":"Thank you. I make apps for phones. My team is making an app that helps farmers know when to water their plants. To do my job, you need to be good at math, and you need to love solving problems.","audio":"g5/u5/l2/02.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"How many hours do you work every day?","audio":"g5/u5/l2/03.mp3"},{"sp":"MAN","name":"Mr. Turki","text":"About eight hours. But I can work from home two days a week.","audio":"g5/u5/l2/04.mp3"},{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"Thank you, Mr. Turki. Our second visitor is Captain Nasser. He's a firefighter.","audio":"g5/u5/l2/05.mp3"},{"sp":"DAD","name":"Captain Nasser","text":"Hello, everyone! Being a firefighter isn't only about fires. We also help people in car accidents and floods. We train every day to stay strong and fast.","audio":"g5/u5/l2/06.mp3"},{"sp":"ADAM","name":"Adam","text":"Is it dangerous?","audio":"g5/u5/l2/07.mp3"},{"sp":"DAD","name":"Captain Nasser","text":"Sometimes. That's why teamwork is so important. We always work together and look after each other.","audio":"g5/u5/l2/08.mp3"},{"sp":"SAMI","name":"Sami","text":"How can we stay safe at home?","audio":"g5/u5/l2/09.mp3"},{"sp":"DAD","name":"Captain Nasser","text":"Great question! Never play with matches, and make sure your home has a smoke alarm. And remember the emergency number: 998.","audio":"g5/u5/l2/10.mp3"}],"tasks":[{"type":"mcq","q":"What does Mr. Turki make?","opts":["computers","farm machines","apps for phones","websites for schools"],"ans":2},{"type":"mcq","q":"What does his team's new app help farmers do?","opts":["check the weather in other countries","sell their vegetables","know when to water their plants","find new workers"],"ans":2},{"type":"mcq","q":"How many days a week can Mr. Turki work from home?","opts":["five","two","eight","one"],"ans":1},{"type":"mcq","q":"Why is teamwork so important for firefighters?","opts":["They travel a lot.","Their job is sometimes dangerous.","They have many fire trucks.","They work long hours."],"ans":1},{"type":"tf","s":"Firefighters only help with fires.","ans":false},{"type":"tf","s":"Captain Nasser's team trains every day.","ans":true},{"type":"gap","s":"To be a software engineer, you need to be good at ___.","ans":["math","maths","mathematics"]},{"type":"gap","s":"The emergency number is ___.","ans":["998","nine nine eight"]}],"predict":{"en":"Two visitors come to school for Career Day. What questions would you like to ask them?","ar":""},"tip":{"en":"Each visitor answers a student's question. Listen to the question first, then focus on the answer that follows.","ar":"يجيب كل زائر عن سؤال من أحد الطلاب. استمع للسؤال أولًا ثم ركّز على الإجابة التي تليه."},"speak":{"prompt":"You are a visitor at Career Day. Tell the class about your job. Your classmates ask questions.","frame":"I'm a ___. In my job, I ___. To do this job, you need to ___."},"teach":"Make sure every student knows the Saudi Civil Defense emergency number, 998. Invite a parent with an interesting job to visit after this lesson.","id":"g5u5l2","track":"g5/u5/l2/track.mp3"},{"kind":"listen","n":3,"title":"My Future Plans","skill":"Listening for plans and intentions","skill_ar":"الاستماع إلى الخطط والنوايا","kagan":["Mix-Pair-Share","RoundRobin"],"vocab":[{"w":"future","ar":"المستقبل","emoji":"🔮","ex":"What are you going to be in the future?","audio":"g5/u5/l3/v1.mp3"},{"w":"marine biologist","ar":"عالم أحياء بحرية","emoji":"🐠","ex":"I'm going to be a marine biologist.","audio":"g5/u5/l3/v2.mp3"},{"w":"course","ar":"دورة تدريبية","emoji":"📘","ex":"I'm going to take a computer course.","audio":"g5/u5/l3/v3.mp3"},{"w":"company","ar":"شركة","emoji":"🏢","ex":"I'm going to start my own company.","audio":"g5/u5/l3/v4.mp3"},{"w":"ambitious","ar":"طموح","emoji":"🚀","ex":"That's very ambitious!","audio":"g5/u5/l3/v5.mp3"},{"w":"dream","ar":"حلم","emoji":"💭","ex":"Big dreams need hard work.","audio":"g5/u5/l3/v6.mp3"}],"script":[{"sp":"MS_GREEN","name":"Ms. Green","text":"Right, class, our topic today is plans. Ben, what are you going to do this summer?","audio":"g5/u5/l3/01.mp3"},{"sp":"BEN","name":"Ben","text":"I'm going to visit my grandma in London. We're going to stay for three weeks. And I'm going to see the Science Museum again!","audio":"g5/u5/l3/02.mp3"},{"sp":"MS_GREEN","name":"Ms. Green","text":"Lovely. And what about the future? What are you going to be?","audio":"g5/u5/l3/03.mp3"},{"sp":"BEN","name":"Ben","text":"I'm going to be a marine biologist, because I love the sea. I'm going to study the coral reefs in the Red Sea.","audio":"g5/u5/l3/04.mp3"},{"sp":"MS_GREEN","name":"Ms. Green","text":"Great. Yusuf?","audio":"g5/u5/l3/05.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"This summer, I'm going to take a computer course. I'm going to learn how to make games. In the future, I'm going to start my own game company!","audio":"g5/u5/l3/06.mp3"},{"sp":"MS_GREEN","name":"Ms. Green","text":"How ambitious! Sami?","audio":"g5/u5/l3/07.mp3"},{"sp":"SAMI","name":"Sami","text":"I'm not going to travel this summer. I'm going to help my grandpa on his farm and learn about plants. In the future, I'm going to be a doctor, like my dad.","audio":"g5/u5/l3/08.mp3"},{"sp":"MS_GREEN","name":"Ms. Green","text":"Wonderful plans, boys. Remember: big dreams need hard work!","audio":"g5/u5/l3/09.mp3"}],"tasks":[{"type":"mcq","q":"How long is Ben going to stay in London?","opts":["one month","two weeks","three weeks","three months"],"ans":2},{"type":"mcq","q":"Why does Ben want to be a marine biologist?","opts":["He loves the sea.","His grandma is a scientist.","He likes London.","He wants to travel."],"ans":0},{"type":"mcq","q":"What is Yusuf going to learn this summer?","opts":["how to fix computers","how to cook","how to make games","how to swim"],"ans":2},{"type":"mcq","q":"What is Sami's dad's job?","opts":["He's a doctor.","He's a farmer.","He's an engineer.","He's a teacher."],"ans":0},{"type":"tf","s":"Sami is going to travel this summer.","ans":false},{"type":"tf","s":"Yusuf wants to start his own company.","ans":true},{"type":"gap","s":"Ben is going to see the ___ Museum again.","ans":["Science"]},{"type":"gap","s":"Ms. Green says big dreams need hard ___.","ans":["work"]}],"predict":{"en":"Three boys talk about their plans for the summer and for the future. What are your plans?","ar":""},"tip":{"en":"Listen for two time frames: \"this summer\" (soon) and \"in the future\" (when they're older). Make two notes for each boy.","ar":"استمع لإطارين زمنيين: this summer أي قريبًا، وin the future أي عندما يكبرون. دوّن ملاحظتين لكل ولد."},"speak":{"prompt":"Tell your partner about your plans for this summer and for the future.","frame":"This summer, I'm going to ___. In the future, I'm going to be a ___ because ___."},"teach":"Students make a \"Future Me\" card with a drawing and two \"going to\" sentences, then display the cards on a class wall. Return to them at the end of the year.","id":"g5u5l3","track":"g5/u5/l3/track.mp3"}],"speak":[{"kind":"speak","n":1,"title":"What Does Your Uncle Do?","func":"Talking about jobs","func_ar":"التحدث عن المهن","kagan":["Inside-Outside Circle","Three-Step Interview"],"model":[{"sp":"LINA","name":"Lina","text":"Noor, what does your uncle do?","audio":"g5/u5/s1/01.mp3"},{"sp":"NOOR","name":"Noor","text":"He's a journalist. He writes news stories for a newspaper in Jeddah.","audio":"g5/u5/s1/02.mp3"},{"sp":"LINA","name":"Lina","text":"Wow! Does he enjoy his job?","audio":"g5/u5/s1/03.mp3"},{"sp":"NOOR","name":"Noor","text":"Yes, he loves it. He meets interesting people every day. What about your aunt?","audio":"g5/u5/s1/04.mp3"},{"sp":"LINA","name":"Lina","text":"She's a judge. She works in a big building in the city.","audio":"g5/u5/s1/05.mp3"},{"sp":"NOOR","name":"Noor","text":"That sounds like a serious job!","audio":"g5/u5/s1/06.mp3"},{"sp":"LINA","name":"Lina","text":"It is. She has to read lots of documents. But she's very fair and kind.","audio":"g5/u5/s1/07.mp3"},{"sp":"NOOR","name":"Noor","text":"I'd like a job like that one day.","audio":"g5/u5/s1/08.mp3"}],"roles":["LINA","NOOR"],"chunks":[{"en":"What does your uncle do?","ar":"ماذا يعمل عمّك؟","audio":"g5/u5/s1/c1.mp3"},{"en":"He's a journalist.","ar":"إنه صحفي.","audio":"g5/u5/s1/c2.mp3"},{"en":"Does he enjoy his job?","ar":"هل يستمتع بعمله؟","audio":"g5/u5/s1/c3.mp3"},{"en":"She works in ___.","ar":"إنها تعمل في ___.","audio":"g5/u5/s1/c4.mp3"},{"en":"I'd like a job like that.","ar":"أودّ أن أعمل في وظيفة كهذه.","audio":"g5/u5/s1/c5.mp3"}],"sound":{"type":"pairs","title":"/dʒ/ or /j/?","en":"/dʒ/ (jam) is like the Arabic ج in Fusha — your tongue touches the top of your mouth. /j/ (yam) is like ي — your tongue doesn't touch. Some Gulf speakers say ي for ج, so practise both!","ar":"الصوت /dʒ/ كما في jam يشبه الجيم الفصحى ويلمس فيه اللسان سقف الفم، أما /j/ كما في yam فيشبه الياء ولا يلمس اللسان سقف الفم. بعض المتحدثين في الخليج ينطقون الجيم ياءً، فتدرّب على الصوتين!","pairs":[["jam","yam"],["jet","yet"],["joke","yolk"],["Jess","yes"],["juice","use"]],"audio":[["g5/u5/s1/p1a.mp3","g5/u5/s1/p1b.mp3"],["g5/u5/s1/p2a.mp3","g5/u5/s1/p2b.mp3"],["g5/u5/s1/p3a.mp3","g5/u5/s1/p3b.mp3"],["g5/u5/s1/p4a.mp3","g5/u5/s1/p4b.mp3"],["g5/u5/s1/p5a.mp3","g5/u5/s1/p5b.mp3"]]},"task":{"prompt":"Interview your partner about two people in his family and their jobs.","frame":"What does your ___ do? — He's/She's a ___. — Does he/she enjoy it? — ___."},"cando":["I can ask and talk about jobs.","I can say what people do in their jobs.","I can hear /dʒ/ and /j/."],"teach":"Use the Arabic anchor: \"jam\" starts like جمل, \"yam\" starts like يمين. Students say both Arabic words first, then the English pair.","id":"g5u5s1","track":"g5/u5/s1/track.mp3"},{"kind":"speak","n":2,"title":"What Are You Going to Be?","func":"Talking about future plans","func_ar":"التحدث عن خطط المستقبل","kagan":["Mix-Pair-Share","Talking Chips"],"model":[{"sp":"YUSUF","name":"Yusuf","text":"Sami, what are you going to be when you grow up?","audio":"g5/u5/s2/01.mp3"},{"sp":"SAMI","name":"Sami","text":"I'm going to be a doctor. I want to help people.","audio":"g5/u5/s2/02.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"That's a great career. You'll need to study for many years.","audio":"g5/u5/s2/03.mp3"},{"sp":"SAMI","name":"Sami","text":"I know! What about you?","audio":"g5/u5/s2/04.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"I'm going to be an engineer. I'm going to build the tallest tower in the world, here in Saudi Arabia!","audio":"g5/u5/s2/05.mp3"},{"sp":"SAMI","name":"Sami","text":"Ha ha! That's a big dream. Where are you going to study?","audio":"g5/u5/s2/06.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"Maybe at a university in Riyadh, or maybe abroad. I'm not sure yet.","audio":"g5/u5/s2/07.mp3"},{"sp":"SAMI","name":"Sami","text":"Well, good luck! Let's meet here in twenty years and see!","audio":"g5/u5/s2/08.mp3"}],"roles":["YUSUF","SAMI"],"chunks":[{"en":"What are you going to be?","ar":"ماذا ستصبح؟","audio":"g5/u5/s2/c1.mp3"},{"en":"I'm going to be a ___.","ar":"سأصبح ___.","audio":"g5/u5/s2/c2.mp3"},{"en":"I want to help people.","ar":"أريد أن أساعد الناس.","audio":"g5/u5/s2/c3.mp3"},{"en":"I'm not sure yet.","ar":"لست متأكدًا بعد.","audio":"g5/u5/s2/c4.mp3"},{"en":"Good luck!","ar":"بالتوفيق!","audio":"g5/u5/s2/c5.mp3"}],"sound":{"type":"pairs","title":"/ɪə/ or /eə/?","en":"/ɪə/ (here, fear) starts with \"i\". /eə/ (hair, fair) starts with \"e\", and your mouth is more open.","ar":"يبدأ الصوت /ɪə/ كما في here وfear بـ i، أما /eə/ كما في hair وfair فيبدأ بـ e والفم أكثر انفتاحًا.","pairs":[["here","hair"],["fear","fair"],["dear","dare"],["cheer","chair"],["steer","stair"]],"audio":[["g5/u5/s2/p1a.mp3","g5/u5/s2/p1b.mp3"],["g5/u5/s2/p2a.mp3","g5/u5/s2/p2b.mp3"],["g5/u5/s2/p3a.mp3","g5/u5/s2/p3b.mp3"],["g5/u5/s2/p4a.mp3","g5/u5/s2/p4b.mp3"],["g5/u5/s2/p5a.mp3","g5/u5/s2/p5b.mp3"]]},"task":{"prompt":"Mix-Pair-Share: ask three classmates about their future plans. Report one interesting plan to the class.","frame":"What are you going to be? — I'm going to be a ___. — Why? — Because ___."},"cando":["I can talk about my future plans.","I can give reasons for my plans.","I can hear /ɪə/ and /eə/."],"teach":"Encourage big dreams linked to Saudi Arabia's future: new cities, space, renewable energy, tourism. Ask \"How will your job help our country?\"","id":"g5u5s2","track":"g5/u5/s2/track.mp3"}],"check":[{"type":"mcq","q":"What does speaker two check before every flight?","ref":"L1#5","opts":["the food","the tickets","the passengers","the weather"],"ans":3,"audio":"g5/u5/l1/05.mp3","line":"My office is in the sky! I check the weather before every flight, and I talk to the control tower. Last week, I flew from Jeddah to Kuala Lumpur.","speaker":"Speaker 2"},{"type":"mcq","q":"Which animal does speaker four NOT mention?","ref":"L1#9","opts":["camels","cats","horses","sheep"],"ans":3,"audio":"g5/u5/l1/09.mp3","line":"My patients can't tell me where it hurts! I take care of cats, dogs, horses and sometimes camels. Yesterday, I helped a cat with a broken leg.","speaker":"Speaker 4"},{"type":"mcq","q":"What should children never play with?","ref":"L2#10","opts":["knives","balls","matches","phones"],"ans":2,"audio":"g5/u5/l2/10.mp3","line":"Great question! Never play with matches, and make sure your home has a smoke alarm. And remember the emergency number: 998.","speaker":"Captain Nasser"},{"type":"mcq","q":"What is Sami going to learn about this summer?","ref":"L3#8","opts":["animals","plants","the sea","computers"],"ans":1,"audio":"g5/u5/l3/08.mp3","line":"I'm not going to travel this summer. I'm going to help my grandpa on his farm and learn about plants. In the future, I'm going to be a doctor, like my dad.","speaker":"Sami"}],"id":"g5u5"},{"n":6,"title":"Inventions and Technology","ar":"الاختراعات والتقنية","emoji":"💡","goals":["I can understand a presentation about inventions.","I can explain how something works.","I can give and support my opinion about technology."],"listen":[{"kind":"listen","n":1,"title":"Inventions That Changed the World","skill":"Following a presentation","skill_ar":"متابعة عرض تقديمي","kagan":["Line-Ups","Numbered Heads Together"],"vocab":[{"w":"invention","ar":"اختراع","emoji":"💡","ex":"Paper is a great invention.","audio":"g5/u6/l1/v1.mp3"},{"w":"invent","ar":"يخترع","emoji":"🛠️","ex":"Paper was invented in China.","audio":"g5/u6/l1/v2.mp3"},{"w":"printing press","ar":"آلة الطباعة","emoji":"🖨️","ex":"Gutenberg made the printing press.","audio":"g5/u6/l1/v3.mp3"},{"w":"share","ar":"يشارك / يتبادل","emoji":"🤝","ex":"Paper helped people share ideas.","audio":"g5/u6/l1/v4.mp3"},{"w":"billion","ar":"مليار","emoji":"🔢","ex":"Five billion people use the internet.","audio":"g5/u6/l1/v5.mp3"},{"w":"change the world","ar":"يغيّر العالم","emoji":"🌍","ex":"Four inventions changed the world.","audio":"g5/u6/l1/v6.mp3"}],"script":[{"sp":"BEN","name":"Ben","text":"Good morning, everyone. My presentation is about four inventions that changed the world.","audio":"g5/u6/l1/01.mp3"},{"sp":"BEN","name":"Ben","text":"The first invention is paper. It was invented in China about two thousand years ago. Before paper, people wrote on stone, wood and animal skins.","audio":"g5/u6/l1/02.mp3"},{"sp":"BEN","name":"Ben","text":"The second is the printing press. A German man called Gutenberg made it in about 1440. Books became cheaper, and more people learned to read.","audio":"g5/u6/l1/03.mp3"},{"sp":"BEN","name":"Ben","text":"The third is the telephone. In 1876, Alexander Graham Bell made the first phone call. He said, \"Come here, I want to see you.\"","audio":"g5/u6/l1/04.mp3"},{"sp":"BEN","name":"Ben","text":"The last invention is the internet. It started in the 1960s, but most people only started using it in the 1990s. Today, more than five billion people use it!","audio":"g5/u6/l1/05.mp3"},{"sp":"BEN","name":"Ben","text":"Which invention is the most important? I think it's paper, because without paper, people couldn't share ideas for hundreds of years. What do you think?","audio":"g5/u6/l1/06.mp3"}],"tasks":[{"type":"mcq","q":"Where was paper invented?","opts":["in Egypt","in England","in China","in Germany"],"ans":2},{"type":"mcq","q":"What happened after the printing press was invented?","opts":["Phones became popular.","Books became cheaper.","Paper became expensive.","People stopped writing."],"ans":1},{"type":"mcq","q":"When did most people start using the internet?","opts":["in the 1990s","in 1876","in the 1960s","in the 2000s"],"ans":0},{"type":"mcq","q":"Why does Ben think paper is the most important invention?","opts":["It's very cheap.","It's the oldest invention.","It helped people share ideas for hundreds of years.","It comes from China."],"ans":2},{"type":"tf","s":"Before paper, people wrote on stone and wood.","ans":true},{"type":"tf","s":"Bell made the first phone call in 1440.","ans":false},{"type":"gap","s":"The printing press was made by a man called ___.","ans":["Gutenberg"]},{"type":"gap","s":"Today, more than five ___ people use the internet.","ans":["billion"]},{"type":"order","items":["paper","the printing press","the telephone","the internet"]}],"predict":{"en":"Ben gives a presentation about four inventions that changed the world. Which inventions do you think he chooses?","ar":""},"tip":{"en":"Presentations have signpost words: the first, the second, the third, the last. They help you follow the order.","ar":"تحتوي العروض على كلمات إرشادية مثل the first وthe second وthe third وthe last، فهي تساعدك على تتبّع الترتيب."},"speak":{"prompt":"Which invention do you think is the most important? Tell your group and give two reasons.","frame":"I think ___ is the most important invention because ___. Also, ___."},"teach":"Mention Muslim inventors too — for example, Al-Jazari's machines and the paper mills of Baghdad. Students can research one Muslim inventor for homework and present it in the next lesson.","id":"g5u6l1","track":"g5/u6/l1/track.mp3"},{"kind":"listen","n":2,"title":"Staying Safe Online","skill":"Listening for advice","skill_ar":"الاستماع إلى النصائح","kagan":["RallyRobin","Numbered Heads Together"],"vocab":[{"w":"online","ar":"على الإنترنت","emoji":"🌐","ex":"We need to be careful online.","audio":"g5/u6/l2/v1.mp3"},{"w":"password","ar":"كلمة المرور","emoji":"🔑","ex":"Never share your password.","audio":"g5/u6/l2/v2.mp3"},{"w":"personal information","ar":"معلومات شخصية","emoji":"🪪","ex":"Don't share personal information.","audio":"g5/u6/l2/v3.mp3"},{"w":"screenshot","ar":"لقطة شاشة","emoji":"📱","ex":"Take a screenshot and show an adult.","audio":"g5/u6/l2/v4.mp3"},{"w":"post","ar":"ينشر","emoji":"📤","ex":"Think before you post.","audio":"g5/u6/l2/v5.mp3"},{"w":"delete","ar":"يحذف","emoji":"🗑️","ex":"It's difficult to delete a photo forever.","audio":"g5/u6/l2/v6.mp3"}],"script":[{"sp":"MS_GREEN","name":"Ms. Green","text":"Today, we're talking about staying safe online. The internet is amazing, but we need to be careful. Here are my top tips.","audio":"g5/u6/l2/01.mp3"},{"sp":"MS_GREEN","name":"Ms. Green","text":"Tip number one: never share your password, not even with your best friend. Only your parents should know it.","audio":"g5/u6/l2/02.mp3"},{"sp":"MS_GREEN","name":"Ms. Green","text":"Tip number two: don't share personal information, like your address, your school or your phone number, with people you don't know.","audio":"g5/u6/l2/03.mp3"},{"sp":"BEN","name":"Ben","text":"What if someone sends me a mean message?","audio":"g5/u6/l2/04.mp3"},{"sp":"MS_GREEN","name":"Ms. Green","text":"Good question, Ben. Don't answer it. Take a screenshot and show it to a parent or a teacher. That's tip number three.","audio":"g5/u6/l2/05.mp3"},{"sp":"MS_GREEN","name":"Ms. Green","text":"Tip number four: think before you post. Once a photo is online, it's very difficult to delete it forever.","audio":"g5/u6/l2/06.mp3"},{"sp":"ADAM","name":"Adam","text":"How long should we use screens every day?","audio":"g5/u6/l2/07.mp3"},{"sp":"MS_GREEN","name":"Ms. Green","text":"Many doctors say children your age should spend no more than two hours a day on screens for fun. So, tip number five: take breaks, go outside and play!","audio":"g5/u6/l2/08.mp3"}],"tasks":[{"type":"mcq","q":"Who should know your password?","opts":["only your parents","your best friend","your teacher","nobody at all"],"ans":0},{"type":"mcq","q":"What should you do if someone sends you a mean message?","opts":["Take a screenshot and show an adult.","Send a mean message back.","Answer the message.","Delete your account."],"ans":0},{"type":"mcq","q":"Why should you think before you post a photo?","opts":["It takes a long time.","Your friends might copy it.","It's very difficult to delete it forever.","Photos are expensive."],"ans":2},{"type":"mcq","q":"How much screen time for fun does Ms. Green suggest?","opts":["no more than three hours a day","no more than four hours a day","no more than two hours a day","no more than one hour a week"],"ans":2},{"type":"tf","s":"You can share your address with people you don't know online.","ans":false},{"type":"tf","s":"Ms. Green gives five tips.","ans":true},{"type":"gap","s":"Never share your ___, not even with your best friend.","ans":["password"]},{"type":"gap","s":"Tip five is to take ___ and go outside.","ans":["breaks"]}],"predict":{"en":"Ms. Green gives tips about staying safe on the internet. What tips do you already know?","ar":""},"tip":{"en":"Count the tips on your fingers as you listen: number one, number two... One tip comes after a student's question.","ar":"عُدّ النصائح على أصابعك أثناء الاستماع. إحدى النصائح تأتي بعد سؤال أحد الطلاب."},"speak":{"prompt":"Make an \"Online Safety Poster\" with your partner. Agree on your top three rules.","frame":"Rule one: never ___. Rule two: always ___. Rule three: if ___, ___."},"teach":"This is an important safeguarding lesson. Remind students who they can talk to at school if something online worries them, and that asking for help is always the right thing to do.","id":"g5u6l2","track":"g5/u6/l2/track.mp3"},{"kind":"listen","n":3,"title":"The Robot Competition","skill":"Listening for specific information","skill_ar":"الاستماع إلى معلومات محددة","kagan":["Three-Step Interview","Showdown"],"vocab":[{"w":"robot","ar":"روبوت","emoji":"🤖","ex":"Our robot is called Sahm.","audio":"g5/u6/l3/v1.mp3"},{"w":"elderly","ar":"كبار السن","emoji":"👴","ex":"It helps elderly people.","audio":"g5/u6/l3/v2.mp3"},{"w":"screen","ar":"شاشة","emoji":"🖥️","ex":"Sahm has a small screen.","audio":"g5/u6/l3/v3.mp3"},{"w":"speaker","ar":"مكبّر صوت","emoji":"🔊","ex":"We changed the speaker.","audio":"g5/u6/l3/v4.mp3"},{"w":"on time","ar":"في الوقت المحدد","emoji":"⏰","ex":"They take their medicine on time.","audio":"g5/u6/l3/v5.mp3"},{"w":"judges","ar":"لجنة التحكيم","emoji":"⚖️","ex":"The judges will announce the winners.","audio":"g5/u6/l3/v6.mp3"}],"script":[{"sp":"ANNOUNCER","name":"Announcer","text":"Welcome to the final of the Young Inventors Robot Competition! Ten school teams built robots that help people in everyday life.","audio":"g5/u6/l3/01.mp3"},{"sp":"ANNOUNCER","name":"Announcer","text":"Our next team is from Taif: Sami and Yusuf. Tell us about your robot.","audio":"g5/u6/l3/02.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"Our robot is called Sahm. It helps elderly people take their medicine on time.","audio":"g5/u6/l3/03.mp3"},{"sp":"SAMI","name":"Sami","text":"Sahm has a small screen and a speaker. At medicine time, it says, \"It's time for your medicine,\" and it opens the right box.","audio":"g5/u6/l3/04.mp3"},{"sp":"ANNOUNCER","name":"Announcer","text":"Brilliant! How long did it take to build?","audio":"g5/u6/l3/05.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"Three months. We worked on it every Tuesday and Thursday after school.","audio":"g5/u6/l3/06.mp3"},{"sp":"ANNOUNCER","name":"Announcer","text":"What was the most difficult part?","audio":"g5/u6/l3/07.mp3"},{"sp":"SAMI","name":"Sami","text":"The voice. At first, it was too quiet, so we changed the speaker. Now it's loud and clear.","audio":"g5/u6/l3/08.mp3"},{"sp":"ANNOUNCER","name":"Announcer","text":"And who gave you the idea?","audio":"g5/u6/l3/09.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"Sami's grandpa! He sometimes forgets his medicine, so we wanted to help him.","audio":"g5/u6/l3/10.mp3"},{"sp":"ANNOUNCER","name":"Announcer","text":"What a kind idea. The judges will announce the winners at four o'clock. Good luck!","audio":"g5/u6/l3/11.mp3"}],"tasks":[{"type":"mcq","q":"What do all the robots in the competition do?","opts":["teach English","help people in everyday life","play football","clean schools"],"ans":1},{"type":"mcq","q":"What does Sahm help elderly people do?","opts":["walk safely","read books","cook food","take their medicine on time"],"ans":3},{"type":"mcq","q":"What was the problem with the voice at first?","opts":["It was too quiet.","It was too fast.","It was in the wrong language.","It was too loud."],"ans":0},{"type":"mcq","q":"Who gave the boys the idea?","opts":["Sami's grandpa","a doctor","Yusuf's mom","their teacher"],"ans":0},{"type":"tf","s":"Ten teams are in the final.","ans":true},{"type":"tf","s":"The boys built the robot in three weeks.","ans":false},{"type":"gap","s":"The boys worked on the robot every Tuesday and ___.","ans":["Thursday","Thursdays"]},{"type":"gap","s":"The winners will be announced at ___ o'clock.","ans":["four","4"]}],"predict":{"en":"Sami and Yusuf are in a robot competition. What kind of robot do you think they built?","ar":""},"tip":{"en":"Gap answers are often said only once. Listen for days, times and names, and write them quickly in short form.","ar":"غالبًا ما تُقال إجابات الفراغات مرة واحدة. استمع للأيام والأوقات والأسماء واكتبها بسرعة بشكل مختصر."},"speak":{"prompt":"Invent a robot that helps people. Tell your group what it does and who it helps.","frame":"My robot is called ___. It helps ___ to ___. It has ___."},"teach":"\"Judges\" here are the people who choose the winners — compare with the judge in the camel story (Unit 3). One word, two contexts.","id":"g5u6l3","track":"g5/u6/l3/track.mp3"}],"speak":[{"kind":"speak","n":1,"title":"How Does It Work?","func":"Explaining how to use something","func_ar":"شرح طريقة استخدام شيء ما","kagan":["RallyCoach","Stand Up–Hand Up–Pair Up"],"model":[{"sp":"GRANDPA","name":"Grandpa","text":"Sami, can you help me with this new tablet? How does it work?","audio":"g5/u6/s1/01.mp3"},{"sp":"SAMI","name":"Sami","text":"Sure, Grandpa. First, press this button on the top to turn it on.","audio":"g5/u6/s1/02.mp3"},{"sp":"GRANDPA","name":"Grandpa","text":"Okay. It's on. What next?","audio":"g5/u6/s1/03.mp3"},{"sp":"SAMI","name":"Sami","text":"Next, touch the picture of the camera. Then you can make a video call.","audio":"g5/u6/s1/04.mp3"},{"sp":"GRANDPA","name":"Grandpa","text":"Like this? Oh, I can see Noor!","audio":"g5/u6/s1/05.mp3"},{"sp":"SAMI","name":"Sami","text":"Yes! When you finish, touch the red button to stop the call.","audio":"g5/u6/s1/06.mp3"},{"sp":"GRANDPA","name":"Grandpa","text":"That's so simple. Thank you, Sami. You're a good teacher!","audio":"g5/u6/s1/07.mp3"},{"sp":"SAMI","name":"Sami","text":"You're welcome, Grandpa. Call me if you have any problems.","audio":"g5/u6/s1/08.mp3"}],"roles":["SAMI","GRANDPA"],"chunks":[{"en":"How does it work?","ar":"كيف يعمل؟","audio":"g5/u6/s1/c1.mp3"},{"en":"First, press this button.","ar":"أولًا، اضغط هذا الزر.","audio":"g5/u6/s1/c2.mp3"},{"en":"Next, touch the ___.","ar":"بعد ذلك، المس ___.","audio":"g5/u6/s1/c3.mp3"},{"en":"When you finish, ___.","ar":"عندما تنتهي، ___.","audio":"g5/u6/s1/c4.mp3"},{"en":"That's so simple!","ar":"هذا سهل جدًا!","audio":"g5/u6/s1/c5.mp3"}],"sound":{"type":"sort","title":"/ɑ/ like \"clock\" or /ʌ/ like \"cup\"?","cats":[{"key":"/ɑ/","label":"/ɑ/ clock"},{"key":"/ʌ/","label":"/ʌ/ cup"}],"en":"/ɑ/ (clock, stop) is long, with a wide-open mouth. /ʌ/ (cup, button) is short, with a relaxed mouth.","ar":"الصوت /ɑ/ كما في clock وstop طويل والفم مفتوح واسعًا، أما /ʌ/ كما في cup وbutton فقصير والفم مرتخٍ.","items":[{"text":"clock","key":"/ɑ/","audio":"g5/u6/s1/i1.mp3"},{"text":"button","key":"/ʌ/","audio":"g5/u6/s1/i2.mp3"},{"text":"box","key":"/ɑ/","audio":"g5/u6/s1/i3.mp3"},{"text":"plug","key":"/ʌ/","audio":"g5/u6/s1/i4.mp3"},{"text":"shop","key":"/ɑ/","audio":"g5/u6/s1/i5.mp3"},{"text":"sun","key":"/ʌ/","audio":"g5/u6/s1/i6.mp3"},{"text":"stop","key":"/ɑ/","audio":"g5/u6/s1/i7.mp3"},{"text":"touch","key":"/ʌ/","audio":"g5/u6/s1/i8.mp3"}]},"task":{"prompt":"Explain to your partner how to use something (a phone app, a microwave, a game). Use sequence words.","frame":"First, ___. Next, ___. Then, ___. When you finish, ___."},"cando":["I can explain how something works.","I can give instructions in order.","I can hear /ɑ/ and /ʌ/."],"teach":"Bring a real object (a stopwatch, a calculator). One partner explains and the other follows the instructions exactly — if the instructions are unclear, the device doesn't work!","id":"g5u6s1","track":"g5/u6/s1/track.mp3"},{"kind":"speak","n":2,"title":"In My Opinion...","func":"Giving and supporting opinions","func_ar":"إبداء الرأي ودعمه","kagan":["Talking Chips","Corners"],"model":[{"sp":"BEN","name":"Ben","text":"Adam, what do you think about tablets in class?","audio":"g5/u6/s2/01.mp3"},{"sp":"ADAM","name":"Adam","text":"I think they're really useful. We can find information quickly.","audio":"g5/u6/s2/02.mp3"},{"sp":"BEN","name":"Ben","text":"I agree, but in my opinion, books are better for reading long stories.","audio":"g5/u6/s2/03.mp3"},{"sp":"ADAM","name":"Adam","text":"That's a good point. But tablets are lighter than ten books in your bag!","audio":"g5/u6/s2/04.mp3"},{"sp":"BEN","name":"Ben","text":"Ha ha, that's true! What about robots in schools?","audio":"g5/u6/s2/05.mp3"},{"sp":"ADAM","name":"Adam","text":"Hmm, I don't think robots can be good teachers. A teacher understands how we feel.","audio":"g5/u6/s2/06.mp3"},{"sp":"BEN","name":"Ben","text":"I agree with you. Robots can help, but people are more important.","audio":"g5/u6/s2/07.mp3"},{"sp":"ADAM","name":"Adam","text":"Exactly!","audio":"g5/u6/s2/08.mp3"}],"roles":["BEN","ADAM"],"chunks":[{"en":"What do you think about ___?","ar":"ما رأيك في ___؟","audio":"g5/u6/s2/c1.mp3"},{"en":"I think ___.","ar":"أعتقد أن ___.","audio":"g5/u6/s2/c2.mp3"},{"en":"In my opinion, ___.","ar":"في رأيي، ___.","audio":"g5/u6/s2/c3.mp3"},{"en":"That's a good point.","ar":"هذه نقطة جيدة.","audio":"g5/u6/s2/c4.mp3"},{"en":"I don't think ___.","ar":"لا أعتقد أن ___.","audio":"g5/u6/s2/c5.mp3"}],"sound":{"type":"sort","title":"How many words?","cats":[{"key":"4","label":"4 words"},{"key":"5","label":"5 words"},{"key":"6","label":"6 words"}],"en":"When we give opinions quickly, words link together: \"I think it's an amazing idea\" sounds like one smooth line. Count the words you hear.","ar":"عندما نعبّر عن آرائنا بسرعة تتصل الكلمات ببعضها، فتبدو الجملة سطرًا واحدًا متصلًا. عدّ الكلمات التي تسمعها.","items":[{"text":"I think it's useful.","key":"4","audio":"g5/u6/s2/i1.mp3"},{"text":"I don't agree with you.","key":"5","audio":"g5/u6/s2/i2.mp3"},{"text":"I think it's a good idea.","key":"6","audio":"g5/u6/s2/i3.mp3"},{"text":"It's an amazing idea.","key":"4","audio":"g5/u6/s2/i4.mp3"},{"text":"In my opinion, it's great.","key":"5","audio":"g5/u6/s2/i5.mp3"},{"text":"We should use it at school.","key":"6","audio":"g5/u6/s2/i6.mp3"},{"text":"That's a great point.","key":"4","audio":"g5/u6/s2/i7.mp3"},{"text":"Robots can help us learn.","key":"5","audio":"g5/u6/s2/i8.mp3"},{"text":"Tablets are good for learning English.","key":"6","audio":"g5/u6/s2/i9.mp3"}]},"task":{"prompt":"Discuss with your group: \"Should every student have a tablet at school?\" Each person gives an opinion and a reason.","frame":"I think ___ because ___. — I agree / I don't agree, because ___."},"cando":["I can give my opinion with a reason.","I can agree and disagree politely.","I can hear words that link together."],"teach":"With Talking Chips, each student puts a chip in the middle when he speaks; nobody speaks twice until everyone has used a chip. This gives quieter students a guaranteed turn.","id":"g5u6s2","track":"g5/u6/s2/track.mp3"}],"check":[{"type":"mcq","q":"What did Bell say in the first phone call?","ref":"L1#4","opts":["Good morning!","Hello, can you hear me?","This is amazing!","Come here, I want to see you."],"ans":3,"audio":"g5/u6/l1/04.mp3","line":"The third is the telephone. In 1876, Alexander Graham Bell made the first phone call. He said, \"Come here, I want to see you.\"","speaker":"Ben"},{"type":"mcq","q":"Which of these is personal information?","ref":"L2#3","opts":["the weather","your address","your teacher's name","your favorite color"],"ans":1,"audio":"g5/u6/l2/03.mp3","line":"Tip number two: don't share personal information, like your address, your school or your phone number, with people you don't know.","speaker":"Ms. Green"},{"type":"mcq","q":"Where are Sami and Yusuf from?","ref":"L3#2","opts":["Abha","Jeddah","Riyadh","Taif"],"ans":3,"audio":"g5/u6/l3/02.mp3","line":"Our next team is from Taif: Sami and Yusuf. Tell us about your robot.","speaker":"Announcer"},{"type":"mcq","q":"What does Sahm say at medicine time?","ref":"L3#4","opts":["Good morning!","It's time for your medicine.","Please drink water.","Call the doctor."],"ans":1,"audio":"g5/u6/l3/04.mp3","line":"Sahm has a small screen and a speaker. At medicine time, it says, \"It's time for your medicine,\" and it opens the right box.","speaker":"Sami"}],"id":"g5u6"}],"level":"A2","band":"Forest","speed":0.96},{"grade":6,"units":[{"n":1,"title":"Amazing Places","ar":"أماكن مدهشة","emoji":"🗺️","goals":["I can talk about my experiences with \"Have you ever...?\".","I can recommend places and give reasons.","I can understand a tour guide and a documentary with big numbers."],"listen":[{"kind":"listen","n":1,"title":"Young Travelers","skill":"Listening for experiences","skill_ar":"الاستماع إلى التجارب","kagan":["Find Someone Who","Three-Step Interview"],"vocab":[{"w":"abroad","ar":"في الخارج","emoji":"🌍","ex":"I haven't traveled abroad yet.","audio":"g6/u1/l1/v1.mp3"},{"w":"experience","ar":"تجربة","emoji":"🎒","ex":"Tell us about your travel experiences.","audio":"g6/u1/l1/v2.mp3"},{"w":"Northern Lights","ar":"الشفق القطبي","emoji":"🌌","ex":"We saw the Northern Lights.","audio":"g6/u1/l1/v3.mp3"},{"w":"impressive","ar":"مثير للإعجاب","emoji":"👏","ex":"That's impressive!","audio":"g6/u1/l1/v4.mp3"},{"w":"camp","ar":"يخيّم","emoji":"⛺","ex":"I've camped in the Empty Quarter.","audio":"g6/u1/l1/v5.mp3"},{"w":"twice","ar":"مرتين","emoji":"✌️","ex":"I've been there twice.","audio":"g6/u1/l1/v6.mp3"}],"script":[{"sp":"WOMAN","name":"Radio Host","text":"Welcome to Young Travelers. I'm here with three students who love traveling. Noor, which countries have you been to?","audio":"g6/u1/l1/01.mp3"},{"sp":"NOOR","name":"Noor","text":"I've been to Egypt, Malaysia and Japan. Japan was my favorite. I've never seen such clean streets! And I've tried sushi — it was delicious.","audio":"g6/u1/l1/02.mp3"},{"sp":"WOMAN","name":"Radio Host","text":"Wonderful. Ben, have you ever been somewhere really cold?","audio":"g6/u1/l1/03.mp3"},{"sp":"BEN","name":"Ben","text":"Yes, I have! I've been to Norway with my family. We saw the Northern Lights. The sky was green and purple. It was the most amazing thing I've ever seen.","audio":"g6/u1/l1/04.mp3"},{"sp":"WOMAN","name":"Radio Host","text":"Wow! Yusuf, what about you?","audio":"g6/u1/l1/05.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"I haven't traveled abroad yet, but I've visited many places in Saudi Arabia. I've climbed Jabal Sawda, the highest mountain in the Kingdom, and I've camped in the Empty Quarter.","audio":"g6/u1/l1/06.mp3"},{"sp":"WOMAN","name":"Radio Host","text":"That's impressive! Is there anywhere you haven't been but really want to visit?","audio":"g6/u1/l1/07.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"Yes. I've always wanted to see the pyramids in Egypt.","audio":"g6/u1/l1/08.mp3"},{"sp":"NOOR","name":"Noor","text":"Oh, you must go! I've been there twice.","audio":"g6/u1/l1/09.mp3"}],"tasks":[{"type":"mcq","q":"Which country was Noor's favorite?","opts":["Egypt","Norway","Japan","Malaysia"],"ans":2},{"type":"mcq","q":"What did Ben see in Norway?","opts":["a volcano","a snow leopard","the pyramids","the Northern Lights"],"ans":3},{"type":"mcq","q":"What colors was the sky in Norway?","opts":["green and blue","green and purple","blue and pink","red and orange"],"ans":1},{"type":"mcq","q":"Which sentence about Yusuf is true?","opts":["He has never camped.","He hasn't traveled abroad yet.","He has been to Norway.","He has been to Egypt twice."],"ans":1},{"type":"mcq","q":"What has Yusuf always wanted to see?","opts":["the streets of Japan","the Empty Quarter","the pyramids in Egypt","the Northern Lights"],"ans":2},{"type":"tf","s":"Noor has tried sushi.","ans":true},{"type":"tf","s":"Noor has been to Egypt once.","ans":false},{"type":"gap","s":"Jabal Sawda is the ___ mountain in the Kingdom.","ans":["highest"]},{"type":"gap","s":"Yusuf has camped in the Empty ___.","ans":["Quarter"]}],"predict":{"en":"Three students talk about places they have visited. Which places in the world would you most like to visit?","ar":""},"tip":{"en":"\"I've been\" and \"I've never\" talk about experiences. Listen for \"never\" and \"haven't\" — they change the answer!","ar":"عبارتا I've been وI've never تتحدثان عن التجارب. انتبه لكلمتي never وhaven't فهما تغيّران الإجابة!"},"speak":{"prompt":"Ask your partner about three experiences.","frame":"Have you ever ___? — Yes, I have. I ___ last ___. / No, I haven't, but I'd like to."},"teach":"The difference between \"Have you ever been...?\" (experience, no time) and \"When did you go...?\" (finished time) is a key A2+ point. Students move from one to the other in their follow-up questions.","id":"g6u1l1","track":"g6/u1/l1/track.mp3"},{"kind":"listen","n":2,"title":"A Tour of Diriyah","skill":"Listening to a tour guide","skill_ar":"الاستماع إلى مرشد سياحي","kagan":["Numbered Heads Together","Fan-N-Pick"],"vocab":[{"w":"capital","ar":"عاصمة","emoji":"🏛️","ex":"Diriyah was the first capital.","audio":"g6/u1/l2/v1.mp3"},{"w":"district","ar":"حيّ","emoji":"🏘️","ex":"At-Turaif is the old district.","audio":"g6/u1/l2/v2.mp3"},{"w":"heritage","ar":"تراث","emoji":"🏺","ex":"It's a World Heritage Site.","audio":"g6/u1/l2/v3.mp3"},{"w":"mud bricks","ar":"الطوب الطيني","emoji":"🧱","ex":"The buildings are made of mud bricks.","audio":"g6/u1/l2/v4.mp3"},{"w":"damage","ar":"يُتلف / يُلحق الضرر","emoji":"💥","ex":"The walls are easy to damage.","audio":"g6/u1/l2/v5.mp3"},{"w":"traditional","ar":"تقليدي","emoji":"🫖","ex":"We'll have traditional coffee.","audio":"g6/u1/l2/v6.mp3"}],"script":[{"sp":"MAN","name":"Tour Guide","text":"Good morning, everyone, and welcome to Diriyah. My name is Abdullah, and I'm your guide today.","audio":"g6/u1/l2/01.mp3"},{"sp":"MAN","name":"Tour Guide","text":"Diriyah is very important in our history. It was the first capital of the Saudi state, which started almost three hundred years ago, in 1727.","audio":"g6/u1/l2/02.mp3"},{"sp":"MAN","name":"Tour Guide","text":"We're standing in At-Turaif, the old district. In 2010, UNESCO made it a World Heritage Site.","audio":"g6/u1/l2/03.mp3"},{"sp":"MAN","name":"Tour Guide","text":"Look at the buildings. They're made of mud bricks, which keep the houses cool in summer and warm in winter.","audio":"g6/u1/l2/04.mp3"},{"sp":"MAN","name":"Tour Guide","text":"The tour takes about ninety minutes. First, we'll visit Salwa Palace. Then we'll walk to the museum, where you can see old weapons and coins.","audio":"g6/u1/l2/05.mp3"},{"sp":"MAN","name":"Tour Guide","text":"Please stay with the group, and don't climb on the old walls. They're very old and easy to damage.","audio":"g6/u1/l2/06.mp3"},{"sp":"MAN","name":"Tour Guide","text":"At the end of the tour, there's traditional coffee and dates at the visitor center. Any questions?","audio":"g6/u1/l2/07.mp3"},{"sp":"BEN","name":"Ben","text":"Can we take photos inside the palace?","audio":"g6/u1/l2/08.mp3"},{"sp":"MAN","name":"Tour Guide","text":"Yes, you can, but please don't use the flash.","audio":"g6/u1/l2/09.mp3"}],"tasks":[{"type":"mcq","q":"What was Diriyah in the past?","opts":["a port","the first capital of the Saudi state","a small farming village","a famous market"],"ans":1},{"type":"mcq","q":"Why are the buildings made of mud bricks?","opts":["They are quick to build.","Stone was hard to find.","They keep the houses cool in summer and warm in winter.","Mud is cheap."],"ans":2},{"type":"mcq","q":"Where will the group go first?","opts":["the old walls","the visitor center","the museum","Salwa Palace"],"ans":3},{"type":"mcq","q":"Why shouldn't visitors climb on the walls?","opts":["The guide is tired.","They're too high.","They're very old and easy to damage.","They're very hot."],"ans":2},{"type":"mcq","q":"What can visitors do inside the palace?","opts":["climb the walls","eat dates","touch the coins","take photos without the flash"],"ans":3},{"type":"tf","s":"The tour takes about two hours.","ans":false},{"type":"tf","s":"At-Turaif became a World Heritage Site in 2010.","ans":true},{"type":"gap","s":"The first Saudi state started in ___.","ans":["1727","seventeen twenty-seven"]},{"type":"gap","s":"In the museum, you can see old weapons and ___.","ans":["coins"]}],"predict":{"en":"A guide shows students around Diriyah, near Riyadh. What do you know about Diriyah?","ar":""},"tip":{"en":"Tour guides give lots of facts and some rules. Listen for \"Please...\" and \"don't...\" for the rules.","ar":"يقدّم المرشدون حقائق كثيرة وبعض القواعد. استمع لكلمتي Please... وdon't... لمعرفة القواعد."},"speak":{"prompt":"You are a tour guide for a place in your city. Give three facts and one rule.","frame":"Welcome to ___. It was built in ___. It's famous for ___. Please don't ___."},"teach":"Connect the lesson with Founding Day (22 February), which celebrates the start of the first Saudi state in Diriyah in 1727. Ninety minutes is an hour and a half, not two hours — a useful trap to discuss.","id":"g6u1l2","track":"g6/u1/l2/track.mp3"},{"kind":"listen","n":3,"title":"Wonders of the World","skill":"Listening for big numbers","skill_ar":"الاستماع إلى الأعداد الكبيرة","kagan":["Showdown","RallyCoach"],"vocab":[{"w":"wonder","ar":"أعجوبة","emoji":"🌟","ex":"The pyramids are a wonder of the world.","audio":"g6/u1/l3/v1.mp3"},{"w":"carve","ar":"ينحت","emoji":"🪓","ex":"They carved the city into rock.","audio":"g6/u1/l3/v2.mp3"},{"w":"block","ar":"كتلة","emoji":"🧱","ex":"It has millions of stone blocks.","audio":"g6/u1/l3/v3.mp3"},{"w":"worker","ar":"عامل","emoji":"👷","ex":"Millions of workers helped.","audio":"g6/u1/l3/v4.mp3"},{"w":"million","ar":"مليون","emoji":"🔢","ex":"Two point three million blocks.","audio":"g6/u1/l3/v5.mp3"},{"w":"tourist","ar":"سائح","emoji":"📸","ex":"Millions of tourists visit every year.","audio":"g6/u1/l3/v6.mp3"}],"script":[{"sp":"NARRATOR","name":"Narrator","text":"Some places are so amazing that people call them \"wonders of the world\". Let's visit three of them.","audio":"g6/u1/l3/01.mp3"},{"sp":"NARRATOR","name":"Narrator","text":"Our first wonder is the Great Wall of China. With all its parts, it's more than twenty-one thousand kilometers long. It took about two thousand years to build, and millions of workers helped.","audio":"g6/u1/l3/02.mp3"},{"sp":"NARRATOR","name":"Narrator","text":"Our second wonder is the Great Pyramid of Giza, in Egypt. It was built about four thousand five hundred years ago. It was one hundred and forty-six meters tall, and it was the tallest building in the world for almost four thousand years! It has about two point three million stone blocks.","audio":"g6/u1/l3/03.mp3"},{"sp":"NARRATOR","name":"Narrator","text":"Our last wonder is Petra, in Jordan. The Nabataeans carved this city into pink rock about two thousand years ago. They were the same people who built Hegra, in AlUla.","audio":"g6/u1/l3/04.mp3"},{"sp":"NARRATOR","name":"Narrator","text":"Today, millions of tourists visit these places every year. That's why it's so important to protect them for the future.","audio":"g6/u1/l3/05.mp3"}],"tasks":[{"type":"mcq","q":"How long did the Great Wall take to build?","opts":["about twenty years","about two hundred years","about four thousand years","about two thousand years"],"ans":3},{"type":"mcq","q":"How tall was the Great Pyramid?","opts":["one hundred and sixty-four meters","one hundred and forty-six meters","forty-six meters","four hundred and sixty meters"],"ans":1},{"type":"mcq","q":"For how long was the Great Pyramid the tallest building in the world?","opts":["almost forty years","almost four thousand years","almost four hundred years","almost two thousand years"],"ans":1},{"type":"mcq","q":"What is Petra carved into?","opts":["white stone","mud bricks","pink rock","sand"],"ans":2},{"type":"mcq","q":"What connects Petra and Hegra?","opts":["They are as old as the pyramids.","They are in the same country.","They are both next to the sea.","The same people built them."],"ans":3},{"type":"tf","s":"The Great Wall is more than twenty-one thousand kilometers long.","ans":true},{"type":"tf","s":"Very few tourists visit these places today.","ans":false},{"type":"gap","s":"The Great Pyramid has about two point three ___ stone blocks.","ans":["million"]},{"type":"gap","s":"Petra was carved by the ___.","ans":["Nabataeans"]}],"predict":{"en":"A documentary describes three \"wonders of the world\". Which famous places do you think it talks about?","ar":""},"tip":{"en":"Big numbers come in parts: twenty-one thousand = 21,000; two point three million = 2,300,000. Write them as digits.","ar":"تأتي الأعداد الكبيرة على أجزاء: twenty-one thousand تعني 21,000، وtwo point three million تعني 2,300,000. اكتبها بالأرقام."},"speak":{"prompt":"Which wonder would you like to visit most? Tell your partner why.","frame":"I'd most like to visit ___ because ___. I'd like to see ___."},"teach":"Before listening, play Number Dictation: say 146, 4,500, 21,000 and 2.3 million; students write them as digits. The link to Hegra recycles Grade 5 (the AlUla trip).","id":"g6u1l3","track":"g6/u1/l3/track.mp3"}],"speak":[{"kind":"speak","n":1,"title":"Have You Ever...?","func":"Talking about experiences","func_ar":"التحدث عن التجارب","kagan":["Find Someone Who","Inside-Outside Circle"],"model":[{"sp":"ADAM","name":"Adam","text":"Ben, have you ever been to Abha?","audio":"g6/u1/s1/01.mp3"},{"sp":"BEN","name":"Ben","text":"Yes, I have. I went there last summer with my family.","audio":"g6/u1/s1/02.mp3"},{"sp":"ADAM","name":"Adam","text":"Lucky you! Have you ever tried the cable car there?","audio":"g6/u1/s1/03.mp3"},{"sp":"BEN","name":"Ben","text":"Yes! It was a bit scary, but the view was incredible. Have you ever been on a plane?","audio":"g6/u1/s1/04.mp3"},{"sp":"ADAM","name":"Adam","text":"No, I haven't. I've never flown anywhere. We always travel by car.","audio":"g6/u1/s1/05.mp3"},{"sp":"BEN","name":"Ben","text":"Really? You should try it one day. It's much faster.","audio":"g6/u1/s1/06.mp3"},{"sp":"ADAM","name":"Adam","text":"I'd love to. My dad says we're going to fly to Jeddah in the spring.","audio":"g6/u1/s1/07.mp3"},{"sp":"BEN","name":"Ben","text":"That's great! You'll love it.","audio":"g6/u1/s1/08.mp3"}],"roles":["ADAM","BEN"],"chunks":[{"en":"Have you ever been to ___?","ar":"","audio":"g6/u1/s1/c1.mp3"},{"en":"Yes, I have. I went there last ___.","ar":"","audio":"g6/u1/s1/c2.mp3"},{"en":"No, I haven't.","ar":"","audio":"g6/u1/s1/c3.mp3"},{"en":"I've never ___.","ar":"","audio":"g6/u1/s1/c4.mp3"},{"en":"You should try it one day.","ar":"","audio":"g6/u1/s1/c5.mp3"}],"sound":{"type":"sort","title":"How many words?","cats":[{"key":"5","label":"5 words"},{"key":"6","label":"6 words"},{"key":"7","label":"7 words"}],"en":"In questions with \"have you\", the words join and \"have\" becomes weak: \"Have you ever\" sounds like \"havyu-ever\". Count every word you hear.","ar":"في الأسئلة التي تبدأ بـ have you تتصل الكلمات وتضعف have، فتُسمع Have you ever مثل \"havyu-ever\". عُدّ كل كلمة تسمعها.","items":[{"text":"Have you ever been there?","key":"5","audio":"g6/u1/s1/i1.mp3"},{"text":"Have you ever been to Abha?","key":"6","audio":"g6/u1/s1/i2.mp3"},{"text":"Have you ever tried the cable car?","key":"7","audio":"g6/u1/s1/i3.mp3"},{"text":"I've never been to Jeddah.","key":"5","audio":"g6/u1/s1/i4.mp3"},{"text":"I have been there three times.","key":"6","audio":"g6/u1/s1/i5.mp3"},{"text":"We have visited it with our family.","key":"7","audio":"g6/u1/s1/i6.mp3"},{"text":"Has he tried it yet?","key":"5","audio":"g6/u1/s1/i7.mp3"},{"text":"She's never flown on a plane.","key":"6","audio":"g6/u1/s1/i8.mp3"},{"text":"I've always wanted to see the sea.","key":"7","audio":"g6/u1/s1/i9.mp3"}]},"task":{"prompt":"Find Someone Who: walk around and find a classmate for each experience. Ask one more question each time.","frame":"Have you ever ___? — Yes, I have. — When did you ___? — Last ___."},"cando":["I can ask about experiences with \"Have you ever...?\"","I can answer and give extra details.","I can hear weak forms in questions."],"teach":"The follow-up question is where the grammar changes: \"Have you ever...?\" → \"When did you...?\" Model this switch clearly and praise students who make it.","id":"g6u1s1","track":"g6/u1/s1/track.mp3"},{"kind":"speak","n":2,"title":"You Should Visit AlUla","func":"Recommending places","func_ar":"التوصية بزيارة أماكن","kagan":["Timed Pair Share","Carousel Feedback"],"model":[{"sp":"LINA","name":"Lina","text":"Noor, my cousin is visiting Saudi Arabia next month. Where should she go?","audio":"g6/u1/s2/01.mp3"},{"sp":"NOOR","name":"Noor","text":"She should definitely visit AlUla. It's amazing, especially at sunset.","audio":"g6/u1/s2/02.mp3"},{"sp":"LINA","name":"Lina","text":"What else is worth seeing?","audio":"g6/u1/s2/03.mp3"},{"sp":"NOOR","name":"Noor","text":"If she likes the sea, I'd recommend the Red Sea coast. The water is clear, and the fish are beautiful.","audio":"g6/u1/s2/04.mp3"},{"sp":"LINA","name":"Lina","text":"Great idea! And what's the best place to taste traditional food?","audio":"g6/u1/s2/05.mp3"},{"sp":"NOOR","name":"Noor","text":"Try a restaurant in old Jeddah — Al-Balad. The food is delicious, and the old buildings are wonderful.","audio":"g6/u1/s2/06.mp3"},{"sp":"LINA","name":"Lina","text":"Thanks, Noor. I'll send her your recommendations today.","audio":"g6/u1/s2/07.mp3"},{"sp":"NOOR","name":"Noor","text":"Tell her not to wait! Winter is the best time to visit.","audio":"g6/u1/s2/08.mp3"}],"roles":["LINA","NOOR"],"chunks":[{"en":"Where should she go?","ar":"","audio":"g6/u1/s2/c1.mp3"},{"en":"She should definitely visit ___.","ar":"","audio":"g6/u1/s2/c2.mp3"},{"en":"What else is worth seeing?","ar":"","audio":"g6/u1/s2/c3.mp3"},{"en":"I'd recommend ___.","ar":"","audio":"g6/u1/s2/c4.mp3"},{"en":"___ is the best time to visit.","ar":"","audio":"g6/u1/s2/c5.mp3"}],"sound":{"type":"pairs","title":"/eɪ/ or /e/?","en":"/eɪ/ (late) is a long sound that moves: e→i. /e/ (let) is short and doesn't move.","ar":"الصوت /eɪ/ كما في late طويل ويتحرك من e إلى i، أما /e/ كما في let فقصير ولا يتحرك.","pairs":[["late","let"],["wait","wet"],["pain","pen"],["sale","sell"],["taste","test"]],"audio":[["g6/u1/s2/p1a.mp3","g6/u1/s2/p1b.mp3"],["g6/u1/s2/p2a.mp3","g6/u1/s2/p2b.mp3"],["g6/u1/s2/p3a.mp3","g6/u1/s2/p3b.mp3"],["g6/u1/s2/p4a.mp3","g6/u1/s2/p4b.mp3"],["g6/u1/s2/p5a.mp3","g6/u1/s2/p5b.mp3"]]},"task":{"prompt":"Recommend three places in Saudi Arabia to a visitor (your partner). Give a reason for each one.","frame":"You should visit ___ because ___. I'd recommend ___. The best time to go is ___."},"cando":["I can recommend places.","I can give reasons for my recommendations.","I can hear /eɪ/ and /e/."],"teach":"Groups create a \"Visit Saudi\" mini-guide with three recommendations. During Carousel Feedback, other groups add one more reason to each recommendation.","id":"g6u1s2","track":"g6/u1/s2/track.mp3"}],"check":[{"type":"mcq","q":"What did Noor notice in Japan?","ref":"L1#2","opts":["very tall mountains","very cold weather","very clean streets","very old buildings"],"ans":2,"audio":"g6/u1/l1/02.mp3","line":"I've been to Egypt, Malaysia and Japan. Japan was my favorite. I've never seen such clean streets! And I've tried sushi — it was delicious.","speaker":"Noor"},{"type":"mcq","q":"What is the guide's name?","ref":"L2#1","opts":["Abdullah","Ben","Faisal","Salwa"],"ans":0,"audio":"g6/u1/l2/01.mp3","line":"Good morning, everyone, and welcome to Diriyah. My name is Abdullah, and I'm your guide today.","speaker":"Tour Guide"},{"type":"mcq","q":"What can visitors have at the end of the tour?","ref":"L2#7","opts":["coffee and dates","juice and cake","water and fruit","tea and biscuits"],"ans":0,"audio":"g6/u1/l2/07.mp3","line":"At the end of the tour, there's traditional coffee and dates at the visitor center. Any questions?","speaker":"Tour Guide"},{"type":"mcq","q":"Who helped build the Great Wall?","ref":"L3#2","opts":["the Nabataeans","millions of workers","a few hundred soldiers","only farmers"],"ans":1,"audio":"g6/u1/l3/02.mp3","line":"Our first wonder is the Great Wall of China. With all its parts, it's more than twenty-one thousand kilometers long. It took about two thousand years to build, and millions of workers helped.","speaker":"Narrator"}],"id":"g6u1"},{"n":2,"title":"Sports and Teamwork","ar":"الرياضة والعمل الجماعي","emoji":"⚽","goals":["I can follow a sports commentary.","I can agree and disagree politely.","I can give and understand advice and instructions."],"listen":[{"kind":"listen","n":1,"title":"The Big Match","skill":"Following a fast commentary","skill_ar":"متابعة تعليق رياضي سريع","kagan":["Showdown","Talking Chips"],"vocab":[{"w":"shoot","ar":"يسدّد","emoji":"⚽","ex":"Sami shoots... and it hits the post!","audio":"g6/u2/l1/v1.mp3"},{"w":"score","ar":"يسجّل هدفًا","emoji":"🥅","ex":"Omar scores!","audio":"g6/u2/l1/v2.mp3"},{"w":"lead","ar":"يتقدّم","emoji":"📈","ex":"The Eagles lead one-nil.","audio":"g6/u2/l1/v3.mp3"},{"w":"half-time","ar":"الاستراحة بين الشوطين","emoji":"⏸️","ex":"It's half-time.","audio":"g6/u2/l1/v4.mp3"},{"w":"crowd","ar":"الجمهور","emoji":"👥","ex":"The crowd is on its feet.","audio":"g6/u2/l1/v5.mp3"},{"w":"whistle","ar":"صافرة","emoji":"📣","ex":"There's the final whistle!","audio":"g6/u2/l1/v6.mp3"}],"script":[{"sp":"ANNOUNCER","name":"Announcer","text":"Good evening, and welcome to the final of the Taif Schools Football Cup! It's the Falcons against the Eagles, and the stadium is full tonight.","audio":"g6/u2/l1/01.mp3"},{"sp":"ANNOUNCER","name":"Announcer","text":"Twenty minutes into the game, and the Falcons have the ball. Yusuf passes to Sami... Sami shoots... Oh, it hits the post! So close!","audio":"g6/u2/l1/02.mp3"},{"sp":"ANNOUNCER","name":"Announcer","text":"Thirty-five minutes now, and the Eagles are attacking. Their captain, Omar, runs past two players... and scores! The Eagles lead one-nil.","audio":"g6/u2/l1/03.mp3"},{"sp":"ANNOUNCER","name":"Announcer","text":"It's half-time. The Falcons look tired, and their coach is not happy.","audio":"g6/u2/l1/04.mp3"},{"sp":"ANNOUNCER","name":"Announcer","text":"The second half has started, and what a change! The Falcons are playing much faster now. Adam crosses the ball... Ben jumps... and heads it in! Goal! It's one-all!","audio":"g6/u2/l1/05.mp3"},{"sp":"ANNOUNCER","name":"Announcer","text":"Only two minutes left. The crowd is on its feet. Sami has the ball again... he dribbles past the goalkeeper... and scores! The Falcons are winning two-one!","audio":"g6/u2/l1/06.mp3"},{"sp":"ANNOUNCER","name":"Announcer","text":"And there's the final whistle! The Falcons are the champions!","audio":"g6/u2/l1/07.mp3"}],"tasks":[{"type":"mcq","q":"What happened with Sami's first shot?","opts":["It went over the goal.","The goalkeeper caught it.","It hit the post.","It was a goal."],"ans":2},{"type":"mcq","q":"Who scored the first goal of the match?","opts":["Omar","Sami","Ben","Yusuf"],"ans":0},{"type":"mcq","q":"How did the Falcons look at half-time?","opts":["angry","happy","confident","tired"],"ans":3},{"type":"mcq","q":"How did Ben score?","opts":["He shot from far away.","He took a penalty.","He dribbled past the goalkeeper.","He headed a cross from Adam."],"ans":3},{"type":"mcq","q":"Why is the crowd \"on its feet\" near the end?","opts":["The game is very exciting.","It's half-time.","The game has finished.","People are leaving."],"ans":0},{"type":"tf","s":"The Eagles were winning at half-time.","ans":true},{"type":"tf","s":"The Falcons won the match two-one.","ans":true},{"type":"gap","s":"The match is the final of the Taif Schools Football ___.","ans":["Cup"]},{"type":"gap","s":"Sami scored the winning goal with only ___ minutes left.","ans":["two","2"]}],"predict":{"en":"Listen to a radio commentary of a school football final. How do commentators make a match exciting?","ar":""},"tip":{"en":"Commentators speak quickly. Focus on names, the words \"scores\" and \"goal\", and the score: one-nil, one-all, two-one.","ar":"يتحدث المعلّقون بسرعة. ركّز على الأسماء وعلى كلمتي scores وgoal وعلى النتيجة مثل one-nil وone-all وtwo-one."},"speak":{"prompt":"Be a commentator! Describe a short moment from a game you know.","frame":"___ has the ball. He passes to ___... he shoots... and scores!"},"teach":"Question 5 needs inference: \"on its feet\" means the crowd is standing because the moment is exciting. Ask students to find other clues for excitement in the commentary (So close! What a change!).","id":"g6u2l1","track":"g6/u2/l1/track.mp3"},{"kind":"listen","n":2,"title":"The Coach's Advice","skill":"Listening for advice and reasons","skill_ar":"الاستماع إلى النصائح وأسبابها","kagan":["RallyRobin","Numbered Heads Together"],"vocab":[{"w":"tournament","ar":"دورة رياضية","emoji":"🏆","ex":"Tomorrow's tournament is important.","audio":"g6/u2/l2/v1.mp3"},{"w":"recover","ar":"يستعيد نشاطه","emoji":"🔋","ex":"Your body needs sleep to recover.","audio":"g6/u2/l2/v2.mp3"},{"w":"teammate","ar":"زميل الفريق","emoji":"🤝","ex":"Call your teammate's name.","audio":"g6/u2/l2/v3.mp3"},{"w":"communicate","ar":"يتواصل","emoji":"💬","ex":"Good teams communicate.","audio":"g6/u2/l2/v4.mp3"},{"w":"referee","ar":"حَكَم","emoji":"🧑‍⚖️","ex":"Don't argue with the referee.","audio":"g6/u2/l2/v5.mp3"},{"w":"argue","ar":"يجادل","emoji":"😤","ex":"Never argue in a game.","audio":"g6/u2/l2/v6.mp3"}],"script":[{"sp":"MAN","name":"Coach Omar","text":"Okay, team, listen carefully. Tomorrow's tournament is the most important event of the year, so here's my advice.","audio":"g6/u2/l2/01.mp3"},{"sp":"MAN","name":"Coach Omar","text":"First, sleep early tonight. Your body needs at least nine hours of sleep to recover.","audio":"g6/u2/l2/02.mp3"},{"sp":"MAN","name":"Coach Omar","text":"Second, eat a good breakfast — eggs, bread and fruit — but don't eat a big meal just before the game. You'll feel heavy and slow.","audio":"g6/u2/l2/03.mp3"},{"sp":"MAN","name":"Coach Omar","text":"Third, drink water all day. In this hot weather, you can lose more than a liter of water in one game.","audio":"g6/u2/l2/04.mp3"},{"sp":"MAN","name":"Coach Omar","text":"During the game, keep talking to each other. Call your teammate's name before you pass the ball. Good teams communicate.","audio":"g6/u2/l2/05.mp3"},{"sp":"MAN","name":"Coach Omar","text":"And remember: if we lose a point, don't argue with the referee. Stay calm and focus on the next play.","audio":"g6/u2/l2/06.mp3"},{"sp":"ADAM","name":"Adam","text":"What time should we arrive, Coach?","audio":"g6/u2/l2/07.mp3"},{"sp":"MAN","name":"Coach Omar","text":"Be at the sports hall at eight o'clock. The first game starts at nine, against Al-Faisal School.","audio":"g6/u2/l2/08.mp3"},{"sp":"BEN","name":"Ben","text":"What if we lose the first game?","audio":"g6/u2/l2/09.mp3"},{"sp":"MAN","name":"Coach Omar","text":"Then we learn from it and play better in the next one. Winning is great, but teamwork is what makes us champions.","audio":"g6/u2/l2/10.mp3"}],"tasks":[{"type":"mcq","q":"How many hours of sleep does the coach say players need?","opts":["at least seven","at least nine","at least ten","at least eight"],"ans":1},{"type":"mcq","q":"Why shouldn't players eat a big meal just before the game?","opts":["They'll feel heavy and slow.","It's against the rules.","They won't have time.","They'll get thirsty."],"ans":0},{"type":"mcq","q":"What should players do before they pass the ball?","opts":["call their teammate's name","shout \"pass\"","look at the coach","wait for the referee"],"ans":0},{"type":"mcq","q":"What should players do if they lose a point?","opts":["argue with the referee","stay calm and focus on the next play","change their position","stop and rest"],"ans":1},{"type":"mcq","q":"According to the coach, what makes the team champions?","opts":["practice","teamwork","speed","winning"],"ans":1},{"type":"tf","s":"Players can lose more than a liter of water in one game.","ans":true},{"type":"tf","s":"The first game starts at eight o'clock.","ans":false},{"type":"gap","s":"The team's first game is against Al-Faisal ___.","ans":["School"]},{"type":"gap","s":"Players should be at the sports ___ at eight o'clock.","ans":["hall"]}],"predict":{"en":"A basketball coach gives his team advice before a tournament. What advice do you think he gives?","ar":""},"tip":{"en":"Advice often comes with a reason. After each piece of advice, listen for \"so\", \"because\" or a result like \"You'll feel...\".","ar":"غالبًا ما تأتي النصيحة مع سبب. بعد كل نصيحة استمع لكلمات مثل so وbecause أو لنتيجة مثل You'll feel..."},"speak":{"prompt":"Give advice to a friend before an important day (an exam, a match or a competition).","frame":"First, ___. Second, ___. Don't ___, or you'll ___."},"teach":"Students list the coach's advice under two headings, \"before the game\" and \"during the game\", then add one piece of advice of their own to each list.","id":"g6u2l2","track":"g6/u2/l2/track.mp3"},{"kind":"listen","n":3,"title":"Choosing a Team Captain","skill":"Comparing speakers' ideas","skill_ar":"المقارنة بين أفكار المتحدثين","kagan":["Corners","Think-Pair-Share"],"vocab":[{"w":"captain","ar":"قائد الفريق","emoji":"🧢","ex":"We're choosing a sports captain.","audio":"g6/u2/l3/v1.mp3"},{"w":"vote","ar":"يصوّت","emoji":"🗳️","ex":"Listen, and then you'll vote.","audio":"g6/u2/l3/v2.mp3"},{"w":"the key","ar":"المفتاح / السرّ","emoji":"🔑","ex":"Practice is the key to winning.","audio":"g6/u2/l3/v3.mp3"},{"w":"positive","ar":"إيجابي","emoji":"➕","ex":"A captain should be positive.","audio":"g6/u2/l3/v4.mp3"},{"w":"organize","ar":"ينظّم","emoji":"📋","ex":"I want to organize a match.","audio":"g6/u2/l3/v5.mp3"},{"w":"chance","ar":"فرصة","emoji":"🎲","ex":"Everyone gets a chance to play.","audio":"g6/u2/l3/v6.mp3"}],"script":[{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"Today, we're choosing our class sports captain. Three students want the job. Listen to their speeches, and then you'll vote.","audio":"g6/u2/l3/01.mp3"},{"sp":"ADAM","name":"Adam","text":"Hello, everyone. I've played football for five years, and I know a lot about the game. As captain, I'll make sure we train hard every week. I believe that practice is the key to winning.","audio":"g6/u2/l3/02.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"Hi, everyone. I'm not the best player in our class, but I'm a good listener. A captain needs to understand every player, not only the strongest ones. If you choose me, I'll make sure everyone gets a chance to play.","audio":"g6/u2/l3/03.mp3"},{"sp":"BEN","name":"Ben","text":"Hello! I think a captain should be positive. When we lose, I'll be the first to say, \"Don't worry, we'll do better next time.\" I also have a plan: I want to organize a match against the teachers at the end of the year!","audio":"g6/u2/l3/04.mp3"},{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"Thank you, boys. Now, please write your choice on a piece of paper and put it in the box.","audio":"g6/u2/l3/05.mp3"}],"tasks":[{"type":"mcq","q":"How long has Adam played football?","opts":["five years","three years","ten years","one year"],"ans":0},{"type":"mcq","q":"What does Adam think is the key to winning?","opts":["being positive","listening","practice","teamwork"],"ans":2},{"type":"mcq","q":"What does Yusuf say about himself?","opts":["He has the most experience.","He isn't the best player, but he's a good listener.","He's very funny.","He's the strongest player."],"ans":1},{"type":"mcq","q":"What will Yusuf make sure of?","opts":["They play against the teachers.","The team wins every match.","Everyone gets a chance to play.","The team trains every day."],"ans":2},{"type":"mcq","q":"What is Ben's special plan?","opts":["a match against the teachers","new team shirts","a trip to a stadium","extra training on Fridays"],"ans":0},{"type":"tf","s":"Ben thinks a captain should always win.","ans":false},{"type":"tf","s":"The students vote by raising their hands.","ans":false},{"type":"gap","s":"Yusuf says a captain needs to understand every ___.","ans":["player"]},{"type":"gap","s":"Ben wants to organize the match at the end of the ___.","ans":["year"]}],"predict":{"en":"Three students give speeches because they want to be class sports captain. What makes a good captain?","ar":""},"tip":{"en":"When speakers compete, listen for each person's main idea and write one key word for each: Adam = practice, Yusuf = ?, Ben = ?","ar":"عندما يتنافس المتحدثون، استمع للفكرة الرئيسية لكل شخص واكتب كلمة مفتاحية واحدة لكل منهم."},"speak":{"prompt":"Who would you vote for? Tell your group and explain why.","frame":"I'd vote for ___ because he ___. I think a captain should ___."},"teach":"Hold a real class vote after the lesson using the same paper-and-box method. Discuss fair voting and respecting the result — a small lesson in citizenship.","id":"g6u2l3","track":"g6/u2/l3/track.mp3"}],"speak":[{"kind":"speak","n":1,"title":"I See Your Point, But...","func":"Agreeing and disagreeing politely","func_ar":"الموافقة والاعتراض بأدب","kagan":["Corners","Talking Chips"],"model":[{"sp":"SAMI","name":"Sami","text":"I think football is the best sport in the world. Do you agree?","audio":"g6/u2/s1/01.mp3"},{"sp":"BEN","name":"Ben","text":"I see your point, but I don't agree. I think basketball is more exciting. There are more goals — sorry, more points!","audio":"g6/u2/s1/02.mp3"},{"sp":"SAMI","name":"Sami","text":"Ha ha! Maybe, but football is more popular. Billions of people watch the World Cup.","audio":"g6/u2/s1/03.mp3"},{"sp":"BEN","name":"Ben","text":"That's true. But popular doesn't always mean better.","audio":"g6/u2/s1/04.mp3"},{"sp":"SAMI","name":"Sami","text":"Fair enough. What about tennis?","audio":"g6/u2/s1/05.mp3"},{"sp":"BEN","name":"Ben","text":"I agree with you there — tennis is boring to watch.","audio":"g6/u2/s1/06.mp3"},{"sp":"SAMI","name":"Sami","text":"Really? I think it's okay, but I won't argue about it!","audio":"g6/u2/s1/07.mp3"},{"sp":"BEN","name":"Ben","text":"Ha ha. Let's agree that all sports are good for us!","audio":"g6/u2/s1/08.mp3"}],"roles":["SAMI","BEN"],"chunks":[{"en":"Do you agree?","ar":"","audio":"g6/u2/s1/c1.mp3"},{"en":"I see your point, but ___.","ar":"","audio":"g6/u2/s1/c2.mp3"},{"en":"That's true.","ar":"","audio":"g6/u2/s1/c3.mp3"},{"en":"Fair enough.","ar":"","audio":"g6/u2/s1/c4.mp3"},{"en":"I agree with you there.","ar":"","audio":"g6/u2/s1/c5.mp3"}],"sound":{"type":"pairs","title":"/oʊ/ or /ɑ/?","en":"/oʊ/ (won't, coat) moves from \"o\" to \"u\", and your lips get rounder. /ɑ/ (want, cot) is short and open, and your lips don't move.","ar":"الصوت /oʊ/ كما في won't وcoat يتحرك من o إلى u وتستدير الشفتان، أما /ɑ/ كما في want وcot فقصير ومفتوح ولا تتحرك الشفتان.","pairs":[["won't","want"],["coat","cot"],["note","not"],["hope","hop"],["road","rod"]],"audio":[["g6/u2/s1/p1a.mp3","g6/u2/s1/p1b.mp3"],["g6/u2/s1/p2a.mp3","g6/u2/s1/p2b.mp3"],["g6/u2/s1/p3a.mp3","g6/u2/s1/p3b.mp3"],["g6/u2/s1/p4a.mp3","g6/u2/s1/p4b.mp3"],["g6/u2/s1/p5a.mp3","g6/u2/s1/p5b.mp3"]]},"task":{"prompt":"Debate in groups: \"Football is the best sport.\" Each student agrees or disagrees politely and gives a reason.","frame":"I agree because ___. — I see your point, but ___. — That's true, but ___."},"cando":["I can agree and disagree politely.","I can give reasons for my opinion.","I can hear \"won't\" and \"want\"."],"teach":"Disagreeing politely is a life skill. Ban \"You're wrong!\" for the lesson and give a point for every \"I see your point, but...\" you hear.","id":"g6u2s1","track":"g6/u2/s1/track.mp3"},{"kind":"speak","n":2,"title":"Make Sure You...","func":"Giving instructions and rules","func_ar":"إعطاء التعليمات والقواعد","kagan":["RallyCoach","Stand Up–Hand Up–Pair Up"],"model":[{"sp":"MAN","name":"Coach Omar","text":"Okay, Yusuf. You're the new referee for the school volleyball match. Are you ready?","audio":"g6/u2/s2/01.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"I think so, Coach. What do I need to do?","audio":"g6/u2/s2/02.mp3"},{"sp":"MAN","name":"Coach Omar","text":"First, make sure both teams have six players on the court.","audio":"g6/u2/s2/03.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"Six players. Got it.","audio":"g6/u2/s2/04.mp3"},{"sp":"MAN","name":"Coach Omar","text":"Blow the whistle to start every point. And don't forget to count the points out loud.","audio":"g6/u2/s2/05.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"What if a player touches the net?","audio":"g6/u2/s2/06.mp3"},{"sp":"MAN","name":"Coach Omar","text":"Then the other team gets the point. And remember, be fair to both teams, even if your friends are playing.","audio":"g6/u2/s2/07.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"Of course. Can I use a card if a player is rude?","audio":"g6/u2/s2/08.mp3"},{"sp":"MAN","name":"Coach Omar","text":"Yes, you can. But try to stay calm and explain the rules first.","audio":"g6/u2/s2/09.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"Thanks, Coach. I'll do my best!","audio":"g6/u2/s2/10.mp3"}],"roles":["YUSUF","MAN"],"chunks":[{"en":"Make sure you ___.","ar":"","audio":"g6/u2/s2/c1.mp3"},{"en":"Don't forget to ___.","ar":"","audio":"g6/u2/s2/c2.mp3"},{"en":"What if ___?","ar":"","audio":"g6/u2/s2/c3.mp3"},{"en":"Remember to be fair.","ar":"","audio":"g6/u2/s2/c4.mp3"},{"en":"I'll do my best!","ar":"","audio":"g6/u2/s2/c5.mp3"}],"sound":{"type":"sort","title":"Where's the strong beat?","cats":[{"key":"Oo","label":"Oo"},{"key":"Ooo","label":"Ooo"},{"key":"ooO","label":"ooO"}],"en":"Sports words have different stress patterns: FOOT-ball (Oo), BAS-ket-ball (Ooo), ref-er-EE (ooO).","ar":"لكلمات الرياضة أنماط نبر مختلفة: FOOT-ball بنمط Oo، وBAS-ket-ball بنمط Ooo، وref-er-EE بنمط ooO.","items":[{"text":"football","key":"Oo","audio":"g6/u2/s2/i1.mp3"},{"text":"basketball","key":"Ooo","audio":"g6/u2/s2/i2.mp3"},{"text":"referee","key":"ooO","audio":"g6/u2/s2/i3.mp3"},{"text":"tennis","key":"Oo","audio":"g6/u2/s2/i4.mp3"},{"text":"volleyball","key":"Ooo","audio":"g6/u2/s2/i5.mp3"},{"text":"volunteer","key":"ooO","audio":"g6/u2/s2/i6.mp3"},{"text":"captain","key":"Oo","audio":"g6/u2/s2/i7.mp3"},{"text":"champion","key":"Ooo","audio":"g6/u2/s2/i8.mp3"},{"text":"afternoon","key":"ooO","audio":"g6/u2/s2/i9.mp3"}]},"task":{"prompt":"Explain the rules of a game you know to your partner. Use \"make sure\", \"don't forget\" and \"if\".","frame":"In this game, make sure you ___. Don't forget to ___. If ___, ___."},"cando":["I can give clear instructions and rules.","I can ask \"What if...?\"","I can stress sports words correctly."],"teach":"Students teach the class a simple playground game in English using only the lesson chunks. The class plays it for two minutes to test whether the instructions were clear.","id":"g6u2s2","track":"g6/u2/s2/track.mp3"}],"check":[{"type":"mcq","q":"Which two teams are playing?","ref":"L1#1","opts":["the Falcons and the Eagles","the Lions and the Eagles","the Eagles and the Tigers","the Falcons and the Lions"],"ans":0,"audio":"g6/u2/l1/01.mp3","line":"Good evening, and welcome to the final of the Taif Schools Football Cup! It's the Falcons against the Eagles, and the stadium is full tonight.","speaker":"Announcer"},{"type":"mcq","q":"How many players did Omar run past?","ref":"L1#3","opts":["three","two","four","one"],"ans":1,"audio":"g6/u2/l1/03.mp3","line":"Thirty-five minutes now, and the Eagles are attacking. Their captain, Omar, runs past two players... and scores! The Eagles lead one-nil.","speaker":"Announcer"},{"type":"mcq","q":"What does the coach recommend for breakfast?","ref":"L2#3","opts":["rice and chicken","dates and coffee","cereal and milk","eggs, bread and fruit"],"ans":3,"audio":"g6/u2/l2/03.mp3","line":"Second, eat a good breakfast — eggs, bread and fruit — but don't eat a big meal just before the game. You'll feel heavy and slow.","speaker":"Coach Omar"},{"type":"mcq","q":"What will Adam make sure of as captain?","ref":"L3#2","opts":["The team plays the teachers.","Everyone gets a chance to play.","The team trains hard every week.","The team is always positive."],"ans":2,"audio":"g6/u2/l3/02.mp3","line":"Hello, everyone. I've played football for five years, and I know a lot about the game. As captain, I'll make sure we train hard every week. I believe that practice is the key to winning.","speaker":"Adam"}],"id":"g6u2"},{"n":3,"title":"Media and News","ar":"الإعلام والأخبار","emoji":"📻","goals":["I can understand the main idea of news stories.","I can tell facts from opinions.","I can report news and react to it."],"listen":[{"kind":"listen","n":1,"title":"School Radio News","skill":"Listening for main ideas","skill_ar":"الاستماع إلى الأفكار الرئيسية","kagan":["Numbered Heads Together","Fan-N-Pick"],"vocab":[{"w":"top stories","ar":"أبرز الأخبار","emoji":"📰","ex":"Here are today's top stories.","audio":"g6/u3/l1/v1.mp3"},{"w":"headline","ar":"عنوان رئيسي","emoji":"🗞️","ex":"Write a headline for each story.","audio":"g6/u3/l1/v2.mp3"},{"w":"beat","ar":"يتغلّب على","emoji":"🏅","ex":"They beat Al-Faisal School.","audio":"g6/u3/l1/v3.mp3"},{"w":"message","ar":"رسالة","emoji":"📩","ex":"Here's a message from the school nurse.","audio":"g6/u3/l1/v4.mp3"},{"w":"sign up","ar":"يسجّل اسمه","emoji":"✍️","ex":"Please sign up before Sunday.","audio":"g6/u3/l1/v5.mp3"},{"w":"water fountain","ar":"برّادة مياه","emoji":"🚰","ex":"There are water fountains on every floor.","audio":"g6/u3/l1/v6.mp3"}],"script":[{"sp":"YUSUF","name":"Yusuf","text":"Good morning, and welcome to the School Radio News. I'm Yusuf.","audio":"g6/u3/l1/01.mp3"},{"sp":"ADAM","name":"Adam","text":"And I'm Adam. Here are today's top stories.","audio":"g6/u3/l1/02.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"Our first story: the school library has opened a new reading corner. It has more than five hundred new books in English and Arabic, and some comfortable bean bags. It's open every day during break.","audio":"g6/u3/l1/03.mp3"},{"sp":"ADAM","name":"Adam","text":"In sports news, our basketball team won the city tournament last Thursday. They beat Al-Faisal School by forty-two points to thirty-eight. Congratulations, team!","audio":"g6/u3/l1/04.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"Next, an important message from the school nurse. Because the weather is getting hotter, please bring a water bottle to school every day. There are water fountains on every floor.","audio":"g6/u3/l1/05.mp3"},{"sp":"ADAM","name":"Adam","text":"And finally, some exciting news: Grade 6 students are planting fifty trees in the school garden next week. If you'd like to help, please sign up with Mr. Hassan before Sunday.","audio":"g6/u3/l1/06.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"That's all for today. Have a great day!","audio":"g6/u3/l1/07.mp3"}],"tasks":[{"type":"mcq","q":"What is the main idea of the first story?","opts":["The library has a new reading corner.","The library is closed for repairs.","Students must return their books.","The library has new computers."],"ans":0},{"type":"mcq","q":"What was the final score of the basketball game?","opts":["forty-eight to forty-two","thirty-eight to thirty-two","forty-two to twenty-eight","forty-two to thirty-eight"],"ans":3},{"type":"mcq","q":"Why does the nurse want students to bring water bottles?","opts":["The water fountains are broken.","The weather is getting hotter.","It's a new school rule.","Students are often sick."],"ans":1},{"type":"mcq","q":"How many trees are Grade 6 students planting?","opts":["five hundred","fifty","fifteen","forty"],"ans":1},{"type":"mcq","q":"What should students do if they want to help plant trees?","opts":["go to the school garden at break","tell the school nurse","sign up with Mr. Hassan before Sunday","bring a tree from home"],"ans":2},{"type":"tf","s":"The basketball team lost the tournament.","ans":false},{"type":"tf","s":"The reading corner is open every day during break.","ans":true},{"type":"gap","s":"The reading corner has more than five ___ new books.","ans":["hundred"]},{"type":"gap","s":"There are water fountains on every ___.","ans":["floor"]}],"predict":{"en":"Two students present the news on the school radio. What kind of news is on a school radio?","ar":""},"tip":{"en":"Each news story starts with a signal: \"Our first story\", \"In sports news\", \"Next\", \"And finally\". The first sentence after the signal usually gives the main idea.","ar":"تبدأ كل قصة إخبارية بإشارة مثل Our first story وIn sports news وNext وAnd finally، والجملة الأولى بعد الإشارة تعطي غالبًا الفكرة الرئيسية."},"speak":{"prompt":"Write and present one news story about your class.","frame":"In today's news, ___. This happened ___. ___ said that ___."},"teach":"Students write a headline (six words maximum) for each story after listening. Writing headlines trains them to find the main idea quickly.","id":"g6u3l1","track":"g6/u3/l1/track.mp3"},{"kind":"listen","n":2,"title":"The Weekend Forecast","skill":"Listening for certainty and possibility","skill_ar":"الاستماع إلى ما هو مؤكد وما هو محتمل","kagan":["RallyCoach","Showdown"],"vocab":[{"w":"forecast","ar":"توقعات الطقس","emoji":"📺","ex":"Here's the weather forecast.","audio":"g6/u3/l2/v1.mp3"},{"w":"temperature","ar":"درجة الحرارة","emoji":"🌡️","ex":"Temperatures will drop at night.","audio":"g6/u3/l2/v2.mp3"},{"w":"drop","ar":"ينخفض","emoji":"📉","ex":"It will drop to five degrees.","audio":"g6/u3/l2/v3.mp3"},{"w":"dust","ar":"غبار","emoji":"🌪️","ex":"Strong winds will cause dust.","audio":"g6/u3/l2/v4.mp3"},{"w":"rough","ar":"هائج (البحر)","emoji":"🌊","ex":"The sea will be rough.","audio":"g6/u3/l2/v5.mp3"},{"w":"flooding","ar":"سيول وفيضانات","emoji":"💦","ex":"There may be flooding in some valleys.","audio":"g6/u3/l2/v6.mp3"}],"script":[{"sp":"WOMAN","name":"Weather Presenter","text":"Good evening. Here's the weather forecast for the weekend.","audio":"g6/u3/l2/01.mp3"},{"sp":"WOMAN","name":"Weather Presenter","text":"A cold wind from the north will bring cooler temperatures to most of the Kingdom. In Tabuk, temperatures will drop to five degrees at night, and there may be snow on the mountains of Jabal Al-Lawz.","audio":"g6/u3/l2/02.mp3"},{"sp":"WOMAN","name":"Weather Presenter","text":"In Riyadh, it will be sunny but cool, with a high of nineteen degrees. Strong winds in the afternoon will cause dust, so drivers should be careful.","audio":"g6/u3/l2/03.mp3"},{"sp":"WOMAN","name":"Weather Presenter","text":"On the west coast, Jeddah will be warm and humid, with a high of twenty-nine degrees. The sea will be rough on Saturday, so swimming isn't a good idea.","audio":"g6/u3/l2/04.mp3"},{"sp":"WOMAN","name":"Weather Presenter","text":"In the south, Abha and Al-Baha will have heavy rain on Friday afternoon. There may be flooding in some valleys, so please stay away from them.","audio":"g6/u3/l2/05.mp3"},{"sp":"WOMAN","name":"Weather Presenter","text":"Next week, the weather will be warmer again everywhere. Have a lovely weekend!","audio":"g6/u3/l2/06.mp3"}],"tasks":[{"type":"mcq","q":"What will bring cooler temperatures?","opts":["rain from the south","snow from the west","a cold wind from the north","clouds from the sea"],"ans":2},{"type":"mcq","q":"Where may there be snow?","opts":["in Abha","on the mountains of Jabal Al-Lawz","in Riyadh","in Jeddah"],"ans":1},{"type":"mcq","q":"Why should drivers in Riyadh be careful?","opts":["It will be foggy.","The roads will be icy.","There will be heavy rain.","Strong winds will cause dust."],"ans":3},{"type":"mcq","q":"Why isn't swimming in Jeddah a good idea on Saturday?","opts":["The beaches will be closed.","There will be a storm.","The sea will be rough.","It will be too cold."],"ans":2},{"type":"mcq","q":"What will the weather be like next week?","opts":["warmer everywhere","rainy in Riyadh","snowy in Tabuk","colder in the north"],"ans":0},{"type":"tf","s":"The high in Riyadh will be nineteen degrees.","ans":true},{"type":"tf","s":"There will be heavy rain in Abha on Saturday morning.","ans":false},{"type":"gap","s":"At night in Tabuk, temperatures will drop to ___ degrees.","ans":["five","5"]},{"type":"gap","s":"People should stay away from valleys because there may be ___.","ans":["flooding","floods","a flood"]}],"predict":{"en":"A presenter gives the weekend forecast for different parts of Saudi Arabia. Is the weather the same everywhere in winter?","ar":""},"tip":{"en":"Forecasts use \"will\" and \"may\". \"Will\" = sure. \"May\" = possible. Listen carefully for the difference!","ar":"تستخدم توقعات الطقس will وmay. كلمة will تعني أن الأمر مؤكد، وmay تعني أنه محتمل. استمع جيدًا للفرق!"},"speak":{"prompt":"Give a weather forecast for tomorrow in your city. Use \"will\" and \"may\".","frame":"Tomorrow, it will be ___. There may be ___. People should ___."},"teach":"Use a map of Saudi Arabia's regions. Students place weather symbols on each region during the second listening, then present the forecast to their partner. Stress safety: never go near valleys during heavy rain.","id":"g6u3l2","track":"g6/u3/l2/track.mp3"},{"kind":"listen","n":3,"title":"The Science Fair Advert","skill":"Telling facts from opinions","skill_ar":"التمييز بين الحقائق والآراء","kagan":["Corners","Think-Pair-Share"],"vocab":[{"w":"curious","ar":"محبّ للمعرفة","emoji":"🤔","ex":"Are you curious about the world?","audio":"g6/u3/l3/v1.mp3"},{"w":"fair","ar":"معرض","emoji":"🎪","ex":"Don't miss the science fair!","audio":"g6/u3/l3/v2.mp3"},{"w":"entry","ar":"الدخول","emoji":"🎟️","ex":"Entry is free for all students.","audio":"g6/u3/l3/v3.mp3"},{"w":"project","ar":"مشروع","emoji":"🔬","ex":"There will be eighty projects.","audio":"g6/u3/l3/v4.mp3"},{"w":"virtual reality","ar":"الواقع الافتراضي","emoji":"🥽","ex":"Try our virtual reality rocket ride.","audio":"g6/u3/l3/v5.mp3"},{"w":"opinion","ar":"رأي","emoji":"💬","ex":"\"Amazing\" is an opinion.","audio":"g6/u3/l3/v6.mp3"}],"script":[{"sp":"ANNOUNCER","name":"Announcer","text":"Are you curious about the world? Do you love asking \"How?\" and \"Why?\" Then don't miss the Taif Young Scientists Fair!","audio":"g6/u3/l3/01.mp3"},{"sp":"ANNOUNCER","name":"Announcer","text":"This year's fair is on the fourteenth and fifteenth of March, at the King Fahd Cultural Center. Entry is free for all students.","audio":"g6/u3/l3/02.mp3"},{"sp":"NOOR","name":"Noor","text":"I went last year, and it was the best day ever! I made my own slime and learned why it's sticky.","audio":"g6/u3/l3/03.mp3"},{"sp":"ANNOUNCER","name":"Announcer","text":"There will be more than eighty projects from schools all over the city, plus live science shows every hour.","audio":"g6/u3/l3/04.mp3"},{"sp":"SAMI","name":"Sami","text":"The robot show is amazing. You have to see it!","audio":"g6/u3/l3/05.mp3"},{"sp":"ANNOUNCER","name":"Announcer","text":"Visit the space zone and try our virtual reality rocket ride — it's the most exciting ride in town!","audio":"g6/u3/l3/06.mp3"},{"sp":"ANNOUNCER","name":"Announcer","text":"Doors open at four p.m. and close at ten p.m. Bring your family and your questions!","audio":"g6/u3/l3/07.mp3"},{"sp":"ANNOUNCER","name":"Announcer","text":"The Taif Young Scientists Fair: where curious minds come alive!","audio":"g6/u3/l3/08.mp3"}],"tasks":[{"type":"mcq","q":"Where is the science fair?","opts":["at Sami's school","at the King Fahd Cultural Center","in Al-Rudaf Park","at the science museum"],"ans":1},{"type":"mcq","q":"How much does it cost for students?","opts":["It's free.","twenty riyals","ten riyals","five riyals"],"ans":0},{"type":"mcq","q":"How many projects will there be?","opts":["about eighteen","more than eight","more than eighty","exactly forty"],"ans":2},{"type":"mcq","q":"Which sentence is an OPINION?","opts":["Doors open at four p.m.","The robot show is amazing.","Entry is free for all students.","There are live shows every hour."],"ans":1},{"type":"mcq","q":"What did Noor do at the fair last year?","opts":["She made her own slime.","She won a prize.","She rode a rocket.","She built a robot."],"ans":0},{"type":"tf","s":"The fair is on two days.","ans":true},{"type":"tf","s":"Noor went to the fair last year.","ans":true},{"type":"gap","s":"The fair is in the month of ___.","ans":["March"]},{"type":"gap","s":"In the space zone, you can try a virtual reality ___ ride.","ans":["rocket"]}],"predict":{"en":"Listen to a radio advert for a science fair. How do adverts try to make people come?","ar":""},"tip":{"en":"Adverts mix facts (dates, prices, places) with opinions (amazing, the best). Facts can be checked; opinions are feelings.","ar":"تخلط الإعلانات بين الحقائق مثل التواريخ والأسعار والأماكن، والآراء مثل amazing وthe best. الحقائق يمكن التحقق منها، أما الآراء فهي مشاعر."},"speak":{"prompt":"Make a short radio advert for a school event. Include two facts and one opinion.","frame":"Don't miss ___! It's on ___ at ___. It's the most ___ event of the year!"},"teach":"Students sort the advert's sentences into two lists, \"Fact\" and \"Opinion\". This critical-listening skill helps them understand advertising in everyday life.","id":"g6u3l3","track":"g6/u3/l3/track.mp3"}],"speak":[{"kind":"speak","n":1,"title":"Did You Hear the News?","func":"Reporting and reacting to news","func_ar":"نقل الأخبار والتفاعل معها","kagan":["Mix-Pair-Share","RoundRobin"],"model":[{"sp":"BEN","name":"Ben","text":"Did you hear the news about our school?","audio":"g6/u3/s1/01.mp3"},{"sp":"ADAM","name":"Adam","text":"No, what happened?","audio":"g6/u3/s1/02.mp3"},{"sp":"BEN","name":"Ben","text":"Yesterday, the principal announced that our school won the national reading competition!","audio":"g6/u3/s1/03.mp3"},{"sp":"ADAM","name":"Adam","text":"Really? That's fantastic! Which students took part?","audio":"g6/u3/s1/04.mp3"},{"sp":"BEN","name":"Ben","text":"Twenty students from Grade 6. They read more than three hundred books in two months.","audio":"g6/u3/s1/05.mp3"},{"sp":"ADAM","name":"Adam","text":"Wow! Did they get a prize?","audio":"g6/u3/s1/06.mp3"},{"sp":"BEN","name":"Ben","text":"Yes, they did. According to Mr. Hassan, the school received ten thousand riyals for the library.","audio":"g6/u3/s1/07.mp3"},{"sp":"ADAM","name":"Adam","text":"That's great news. I'm going to read more books this term!","audio":"g6/u3/s1/08.mp3"}],"roles":["BEN","ADAM"],"chunks":[{"en":"Did you hear the news about ___?","ar":"","audio":"g6/u3/s1/c1.mp3"},{"en":"What happened?","ar":"","audio":"g6/u3/s1/c2.mp3"},{"en":"The principal announced that ___.","ar":"","audio":"g6/u3/s1/c3.mp3"},{"en":"According to ___, ___.","ar":"","audio":"g6/u3/s1/c4.mp3"},{"en":"That's great news!","ar":"","audio":"g6/u3/s1/c5.mp3"}],"sound":{"type":"sort","title":"-ed in the news: /t/, /d/ or /ɪd/?","cats":[{"key":"/t/","label":"/t/ announced"},{"key":"/d/","label":"/d/ opened"},{"key":"/ɪd/","label":"/ɪd/ reported"}],"en":"News uses many past verbs. Remember the rule: /t/ after voiceless sounds (announced), /d/ after voiced sounds (opened), and /ɪd/ after t or d (reported).","ar":"تستخدم الأخبار أفعالًا ماضية كثيرة. تذكّر القاعدة: /t/ بعد الأصوات المهموسة مثل announced، و/d/ بعد الأصوات المجهورة مثل opened، و/ɪd/ بعد t أو d مثل reported.","items":[{"text":"announced","key":"/t/","audio":"g6/u3/s1/i1.mp3"},{"text":"opened","key":"/d/","audio":"g6/u3/s1/i2.mp3"},{"text":"reported","key":"/ɪd/","audio":"g6/u3/s1/i3.mp3"},{"text":"finished","key":"/t/","audio":"g6/u3/s1/i4.mp3"},{"text":"arrived","key":"/d/","audio":"g6/u3/s1/i5.mp3"},{"text":"collected","key":"/ɪd/","audio":"g6/u3/s1/i6.mp3"},{"text":"helped","key":"/t/","audio":"g6/u3/s1/i7.mp3"},{"text":"discovered","key":"/d/","audio":"g6/u3/s1/i8.mp3"},{"text":"celebrated","key":"/ɪd/","audio":"g6/u3/s1/i9.mp3"}]},"task":{"prompt":"Report a piece of real or invented school news to your group. Your group reacts and asks one question.","frame":"Did you hear the news? Yesterday, ___. According to ___, ___."},"cando":["I can report news.","I can react to news.","I can say -ed endings in news reports."],"teach":"\"According to...\" tells the listener where information comes from. Encourage students to always name their source — the start of good media habits.","id":"g6u3s1","track":"g6/u3/s1/track.mp3"},{"kind":"speak","n":2,"title":"Is That a Fact?","func":"Discussing facts and opinions","func_ar":"مناقشة الحقائق والآراء","kagan":["Think-Pair-Share","Showdown"],"model":[{"sp":"NOOR","name":"Noor","text":"Lina, look at this advert. It says, \"Sparkle toothpaste is the best toothpaste in the world.\"","audio":"g6/u3/s2/01.mp3"},{"sp":"LINA","name":"Lina","text":"Hmm, that's not a fact. That's an opinion.","audio":"g6/u3/s2/02.mp3"},{"sp":"NOOR","name":"Noor","text":"How do you know?","audio":"g6/u3/s2/03.mp3"},{"sp":"LINA","name":"Lina","text":"Because nobody can prove that it's the best. A fact is something you can check, like \"It costs twelve riyals.\"","audio":"g6/u3/s2/04.mp3"},{"sp":"NOOR","name":"Noor","text":"I see. So \"Our photographer took this photo in Jeddah\" is a fact?","audio":"g6/u3/s2/05.mp3"},{"sp":"LINA","name":"Lina","text":"Yes, if it's true! But \"It's the most beautiful photo ever\" is an opinion.","audio":"g6/u3/s2/06.mp3"},{"sp":"NOOR","name":"Noor","text":"That's interesting. I think I'll check adverts more carefully from now on.","audio":"g6/u3/s2/07.mp3"},{"sp":"LINA","name":"Lina","text":"Good idea. Don't believe everything you hear!","audio":"g6/u3/s2/08.mp3"}],"roles":["NOOR","LINA"],"chunks":[{"en":"That's not a fact.","ar":"","audio":"g6/u3/s2/c1.mp3"},{"en":"That's an opinion.","ar":"","audio":"g6/u3/s2/c2.mp3"},{"en":"How do you know?","ar":"","audio":"g6/u3/s2/c3.mp3"},{"en":"You can check it.","ar":"","audio":"g6/u3/s2/c4.mp3"},{"en":"Don't believe everything you hear!","ar":"","audio":"g6/u3/s2/c5.mp3"}],"sound":{"type":"sort","title":"Word families: where's the strong beat?","cats":[{"key":"Ooo","label":"Ooo"},{"key":"oOoo","label":"oOoo"},{"key":"ooOo","label":"ooOo"}],"en":"In word families, the strong beat can move! PHO-to-graph (Ooo), pho-TO-gra-pher (oOoo), pho-to-GRA-phic (ooOo).","ar":"في عائلات الكلمات قد ينتقل المقطع القوي! PHO-to-graph بنمط Ooo، وpho-TO-gra-pher بنمط oOoo، وpho-to-GRA-phic بنمط ooOo.","items":[{"text":"photograph","key":"Ooo","audio":"g6/u3/s2/i1.mp3"},{"text":"photographer","key":"oOoo","audio":"g6/u3/s2/i2.mp3"},{"text":"photographic","key":"ooOo","audio":"g6/u3/s2/i3.mp3"},{"text":"history","key":"Ooo","audio":"g6/u3/s2/i4.mp3"},{"text":"historian","key":"oOoo","audio":"g6/u3/s2/i5.mp3"},{"text":"energetic","key":"ooOo","audio":"g6/u3/s2/i6.mp3"},{"text":"energy","key":"Ooo","audio":"g6/u3/s2/i7.mp3"},{"text":"economy","key":"oOoo","audio":"g6/u3/s2/i8.mp3"},{"text":"economic","key":"ooOo","audio":"g6/u3/s2/i9.mp3"}]},"task":{"prompt":"Bring an advert (or invent one). Your partner finds one fact and one opinion in it.","frame":"This is a fact because you can check it. This is an opinion because ___."},"cando":["I can tell the difference between facts and opinions.","I can explain my reasons.","I can hear the strong beat move in word families."],"teach":"Showdown: read sentences aloud; every student holds up \"F\" (fact) or \"O\" (opinion) at the same time. Discuss any sentence where the class is divided.","id":"g6u3s2","track":"g6/u3/s2/track.mp3"}],"check":[{"type":"mcq","q":"What can students sit on in the reading corner?","ref":"L1#3","opts":["new sofas","wooden chairs","soft carpets","comfortable bean bags"],"ans":3,"audio":"g6/u3/l1/03.mp3","line":"Our first story: the school library has opened a new reading corner. It has more than five hundred new books in English and Arabic, and some comfortable bean bags. It's open every day during break.","speaker":"Yusuf"},{"type":"mcq","q":"When did the basketball team win?","ref":"L1#4","opts":["last Thursday","last month","last Sunday","yesterday"],"ans":0,"audio":"g6/u3/l1/04.mp3","line":"In sports news, our basketball team won the city tournament last Thursday. They beat Al-Faisal School by forty-two points to thirty-eight. Congratulations, team!","speaker":"Adam"},{"type":"mcq","q":"What will the high temperature be in Jeddah?","ref":"L2#4","opts":["nineteen degrees","thirty-nine degrees","twenty-five degrees","twenty-nine degrees"],"ans":3,"audio":"g6/u3/l2/04.mp3","line":"On the west coast, Jeddah will be warm and humid, with a high of twenty-nine degrees. The sea will be rough on Saturday, so swimming isn't a good idea.","speaker":"Weather Presenter"},{"type":"mcq","q":"What did Noor learn about slime?","ref":"L3#3","opts":["how to color it","how to sell it","why it's sticky","where it comes from"],"ans":2,"audio":"g6/u3/l3/03.mp3","line":"I went last year, and it was the best day ever! I made my own slime and learned why it's sticky.","speaker":"Noor"}],"id":"g6u3"},{"n":4,"title":"Saving Our Environment","ar":"حماية بيئتنا","emoji":"♻️","goals":["I can understand a project report and a talk with numbers and reasons.","I can make predictions about the future.","I can persuade others to take action."],"listen":[{"kind":"listen","n":1,"title":"The Recycling Project","skill":"Listening to a report of results","skill_ar":"الاستماع إلى تقرير عن النتائج","kagan":["Numbered Heads Together","RallyCoach"],"vocab":[{"w":"recycle","ar":"يعيد التدوير","emoji":"♻️","ex":"We recycle paper and plastic.","audio":"g6/u4/l1/v1.mp3"},{"w":"waste","ar":"نفايات / مخلّفات","emoji":"🍂","ex":"The green bin is for food waste.","audio":"g6/u4/l1/v2.mp3"},{"w":"weigh","ar":"يزن","emoji":"⚖️","ex":"Two students weighed the rubbish.","audio":"g6/u4/l1/v3.mp3"},{"w":"assembly","ar":"الطابور الصباحي","emoji":"🏫","ex":"We talked in the morning assembly.","audio":"g6/u4/l1/v4.mp3"},{"w":"compost","ar":"سماد عضوي","emoji":"🌱","ex":"We made compost for the garden.","audio":"g6/u4/l1/v5.mp3"},{"w":"canteen","ar":"المقصف المدرسي","emoji":"🥪","ex":"The bottle bin will be next to the canteen.","audio":"g6/u4/l1/v6.mp3"}],"script":[{"sp":"SAMI","name":"Sami","text":"Good morning. Our class started a recycling project three months ago, and today I'd like to share our results.","audio":"g6/u4/l1/01.mp3"},{"sp":"SAMI","name":"Sami","text":"First, we put three bins in every classroom: blue for paper, yellow for plastic and green for food waste.","audio":"g6/u4/l1/02.mp3"},{"sp":"SAMI","name":"Sami","text":"Then, every Thursday, two students collected the bins and weighed the rubbish. At the beginning, we only recycled about five kilograms a week.","audio":"g6/u4/l1/03.mp3"},{"sp":"SAMI","name":"Sami","text":"After we made posters and talked in the morning assembly, things changed. By the third month, we were recycling more than twenty kilograms a week!","audio":"g6/u4/l1/04.mp3"},{"sp":"SAMI","name":"Sami","text":"We also used the food waste to make compost for the school garden. Our tomatoes have never been bigger!","audio":"g6/u4/l1/05.mp3"},{"sp":"SAMI","name":"Sami","text":"The biggest problem was plastic bottles. Many students still throw them in the wrong bin. So next term, we're going to put a special bottle bin next to the canteen.","audio":"g6/u4/l1/06.mp3"},{"sp":"SAMI","name":"Sami","text":"Remember: if every student recycles one bottle a day, our school can save more than ten thousand bottles a year. Thank you!","audio":"g6/u4/l1/07.mp3"}],"tasks":[{"type":"mcq","q":"What color is the bin for plastic?","opts":["yellow","green","red","blue"],"ans":0},{"type":"mcq","q":"How much did they recycle each week at the beginning?","opts":["about ten kilograms","about two kilograms","about five kilograms","about twenty kilograms"],"ans":2},{"type":"mcq","q":"What helped to change things?","opts":["posters and talks in the morning assembly","a visit from the mayor","prizes for the best class","new rules from the principal"],"ans":0},{"type":"mcq","q":"What did they make from food waste?","opts":["new paper","compost for the school garden","food for animals","electricity"],"ans":1},{"type":"mcq","q":"Where will the special bottle bin go?","opts":["next to the main gate","in every classroom","next to the canteen","in the school garden"],"ans":2},{"type":"tf","s":"Plastic bottles were the easiest thing to recycle.","ans":false},{"type":"tf","s":"Two students collected the bins every Thursday.","ans":true},{"type":"gap","s":"The project started ___ months ago.","ans":["three","3"]},{"type":"gap","s":"The school can save more than ten ___ bottles a year.","ans":["thousand"]}],"predict":{"en":"Sami presents the results of his class's recycling project. What do you think the class did?","ar":""},"tip":{"en":"Reports of results use numbers to show change. Listen for \"at the beginning\", \"after\" and \"by the third month\".","ar":"تستخدم تقارير النتائج الأعداد لإظهار التغيير. استمع لعبارات مثل at the beginning وafter وby the third month."},"speak":{"prompt":"Suggest a project to make our school greener. Explain the steps.","frame":"First, we could ___. Then, ___. If we ___, we can ___."},"teach":"Draw a simple line graph on the board showing 5 kg rising to 20 kg. Ask students to describe it in English: \"It went up after the posters.\"","id":"g6u4l1","track":"g6/u4/l1/track.mp3"},{"kind":"listen","n":2,"title":"Every Drop Counts","skill":"Listening to a talk with numbers and reasons","skill_ar":"الاستماع إلى محاضرة فيها أعداد وأسباب","kagan":["Talking Chips","Showdown"],"vocab":[{"w":"drop","ar":"قطرة","emoji":"💧","ex":"Every drop counts.","audio":"g6/u4/l2/v1.mp3"},{"w":"desalination","ar":"تحلية المياه","emoji":"🏭","ex":"Desalination plants take the salt out.","audio":"g6/u4/l2/v2.mp3"},{"w":"tap","ar":"صنبور","emoji":"🚰","ex":"Turn off the tap.","audio":"g6/u4/l2/v3.mp3"},{"w":"drip","ar":"يقطر / يسرّب","emoji":"💦","ex":"Fix dripping taps.","audio":"g6/u4/l2/v4.mp3"},{"w":"shower","ar":"دُش / استحمام","emoji":"🚿","ex":"Take a short shower.","audio":"g6/u4/l2/v5.mp3"},{"w":"on average","ar":"في المتوسط","emoji":"📊","ex":"On average, one person uses 250 liters a day.","audio":"g6/u4/l2/v6.mp3"}],"script":[{"sp":"WOMAN","name":"Engineer Huda","text":"Hello, everyone. I work for the National Water Company. Did you know that Saudi Arabia is one of the driest countries in the world? We have no rivers that flow all year.","audio":"g6/u4/l2/01.mp3"},{"sp":"WOMAN","name":"Engineer Huda","text":"Much of our drinking water comes from the sea. We take the salt out in big desalination plants, and that uses a lot of energy and money.","audio":"g6/u4/l2/02.mp3"},{"sp":"WOMAN","name":"Engineer Huda","text":"That's why every drop counts. Here are some easy ways to save water.","audio":"g6/u4/l2/03.mp3"},{"sp":"WOMAN","name":"Engineer Huda","text":"Turn off the tap while you brush your teeth. This can save up to twelve liters every time!","audio":"g6/u4/l2/04.mp3"},{"sp":"WOMAN","name":"Engineer Huda","text":"Take a short shower instead of a bath. A five-minute shower uses about forty liters, but a bath can use more than one hundred.","audio":"g6/u4/l2/05.mp3"},{"sp":"WOMAN","name":"Engineer Huda","text":"Fix dripping taps. One dripping tap can waste more than fifteen liters a day.","audio":"g6/u4/l2/06.mp3"},{"sp":"WOMAN","name":"Engineer Huda","text":"And when you make wudu, use only the water you need. The Prophet, peace be upon him, taught us not to waste water, even at a flowing river.","audio":"g6/u4/l2/07.mp3"},{"sp":"BEN","name":"Ben","text":"How much water does one person use in a day here?","audio":"g6/u4/l2/08.mp3"},{"sp":"WOMAN","name":"Engineer Huda","text":"On average, more than two hundred and fifty liters. That's higher than in many countries, so we can all do better.","audio":"g6/u4/l2/09.mp3"}],"tasks":[{"type":"mcq","q":"Where does much of Saudi Arabia's drinking water come from?","opts":["rivers","rain","the sea","lakes"],"ans":2},{"type":"mcq","q":"Why is desalination a problem?","opts":["It uses a lot of energy and money.","It takes many years.","It's bad for fish.","It makes the water salty."],"ans":0},{"type":"mcq","q":"How much water can you save by turning off the tap while you brush?","opts":["up to two liters","up to forty liters","up to twelve liters","up to one hundred liters"],"ans":2},{"type":"mcq","q":"How much water does a five-minute shower use?","opts":["about forty liters","about fourteen liters","about one hundred liters","about twelve liters"],"ans":0},{"type":"mcq","q":"What does the engineer say about water use in Saudi Arabia?","opts":["It's going down quickly.","It's higher than in many countries.","It's lower than in most countries.","It's the same as everywhere."],"ans":1},{"type":"tf","s":"One dripping tap can waste more than fifteen liters a day.","ans":true},{"type":"tf","s":"A bath uses less water than a five-minute shower.","ans":false},{"type":"gap","s":"Saudi Arabia is one of the ___ countries in the world.","ans":["driest"]},{"type":"gap","s":"On average, one person uses more than two hundred and ___ liters a day.","ans":["fifty","50"]}],"predict":{"en":"An engineer from the National Water Company talks about saving water. Why is water so precious in Saudi Arabia?","ar":""},"tip":{"en":"The speaker gives tips with numbers. Match each tip with its number: tap → ?, shower → ?, dripping tap → ?.","ar":"تقدّم المتحدثة نصائح مع أرقام. اربط كل نصيحة برقمها."},"speak":{"prompt":"Make a family \"water promise\". Tell your partner three things your family will do.","frame":"We will ___. We won't ___. We'll try to ___."},"teach":"Link to Islamic values: the Prophet ﷺ taught moderation in water use, even during wudu. Students calculate how much water the class could save in a week if everyone turned off the tap while brushing.","id":"g6u4l2","track":"g6/u4/l2/track.mp3"},{"kind":"listen","n":3,"title":"Planting Trees in Al-Hada","skill":"Listening for hidden reasons","skill_ar":"الاستماع إلى الأسباب غير المباشرة","kagan":["Three-Step Interview","Mix-Pair-Share"],"vocab":[{"w":"volunteer","ar":"متطوّع","emoji":"🙋","ex":"Volunteers are working in groups.","audio":"g6/u4/l3/v1.mp3"},{"w":"initiative","ar":"مبادرة","emoji":"🌱","ex":"It's part of the Saudi Green Initiative.","audio":"g6/u4/l3/v2.mp3"},{"w":"tools","ar":"أدوات","emoji":"🧰","ex":"They'll give us the tools.","audio":"g6/u4/l3/v3.mp3"},{"w":"sunscreen","ar":"واقي الشمس","emoji":"🧴","ex":"Bring sunscreen.","audio":"g6/u4/l3/v4.mp3"},{"w":"shade","ar":"ظلّ","emoji":"🌳","ex":"There isn't much shade.","audio":"g6/u4/l3/v5.mp3"},{"w":"pick up","ar":"يقلّ (شخصًا بالسيارة)","emoji":"🚗","ex":"We'll pick you up at half past six.","audio":"g6/u4/l3/v6.mp3"}],"script":[{"sp":"ADAM","name":"Adam","text":"Hi, Sami! Are you free on Saturday morning?","audio":"g6/u4/l3/01.mp3"},{"sp":"SAMI","name":"Sami","text":"I think so. Why?","audio":"g6/u4/l3/02.mp3"},{"sp":"ADAM","name":"Adam","text":"There's a tree-planting event in Al-Hada. It's part of the Saudi Green Initiative. They want to plant ten billion trees across the country!","audio":"g6/u4/l3/03.mp3"},{"sp":"SAMI","name":"Sami","text":"Ten billion? That's incredible! How many trees are we planting on Saturday?","audio":"g6/u4/l3/04.mp3"},{"sp":"ADAM","name":"Adam","text":"About five hundred. Volunteers are working in groups of four, and each group plants about twenty trees.","audio":"g6/u4/l3/05.mp3"},{"sp":"SAMI","name":"Sami","text":"What should I bring?","audio":"g6/u4/l3/06.mp3"},{"sp":"ADAM","name":"Adam","text":"Wear old clothes and a hat, and bring gloves. They'll give us the tools and water. Oh, and bring sunscreen — there isn't much shade.","audio":"g6/u4/l3/07.mp3"},{"sp":"SAMI","name":"Sami","text":"What time does it start?","audio":"g6/u4/l3/08.mp3"},{"sp":"ADAM","name":"Adam","text":"At seven o'clock, before it gets hot. My dad can drive us. We'll pick you up at half past six.","audio":"g6/u4/l3/09.mp3"},{"sp":"SAMI","name":"Sami","text":"That's early, but okay! I'm sure my grandpa will want to come too. He loves trees.","audio":"g6/u4/l3/10.mp3"},{"sp":"ADAM","name":"Adam","text":"Great! The more, the better!","audio":"g6/u4/l3/11.mp3"}],"tasks":[{"type":"mcq","q":"Where is the tree-planting event?","opts":["in Riyadh","at the school","in Al-Rudaf Park","in Al-Hada"],"ans":3},{"type":"mcq","q":"How many trees does the Saudi Green Initiative want to plant across the country?","opts":["ten billion","ten million","five hundred","ten thousand"],"ans":0},{"type":"mcq","q":"How many people are in each group?","opts":["ten","four","twenty","five"],"ans":1},{"type":"mcq","q":"Why does the event start at seven o'clock?","opts":["because Adam's dad works later","because the tools arrive then","to start before it gets hot","to finish before lunch"],"ans":2},{"type":"mcq","q":"Why does Sami think Grandpa will want to come?","opts":["He has a farm in Al-Hada.","He works for the Green Initiative.","He loves trees.","He wants to drive them."],"ans":2},{"type":"tf","s":"Volunteers must bring their own tools.","ans":false},{"type":"tf","s":"Adam's dad will pick Sami up at half past six.","ans":true},{"type":"gap","s":"Each group plants about ___ trees.","ans":["twenty","20"]},{"type":"gap","s":"Sami should bring sunscreen because there isn't much ___.","ans":["shade"]}],"predict":{"en":"Adam invites Sami to a tree-planting event. What do volunteers need to know before an event like this?","ar":""},"tip":{"en":"Some answers aren't said directly. \"Before it gets hot\" explains why the event starts early. Listen for reasons hidden in the details.","ar":"بعض الإجابات لا تُقال مباشرة. عبارة before it gets hot تشرح سبب البدء مبكرًا. استمع للأسباب المخفية في التفاصيل."},"speak":{"prompt":"Invite your partner to a volunteering event. Give the details and answer his questions.","frame":"There's a ___ on ___. It starts at ___. Bring ___. Would you like to come?"},"teach":"The Saudi Green Initiative is a real national project. Ask students whether they have ever planted a tree, and plan a small class planting if possible.","id":"g6u4l3","track":"g6/u4/l3/track.mp3"}],"speak":[{"kind":"speak","n":1,"title":"What Will It Be Like?","func":"Making predictions","func_ar":"التنبؤ بالمستقبل","kagan":["Timed Pair Share","Corners"],"model":[{"sp":"YUSUF","name":"Yusuf","text":"What do you think our city will be like in twenty years?","audio":"g6/u4/s1/01.mp3"},{"sp":"SAMI","name":"Sami","text":"I think there'll be more trees. The Green Initiative will make Taif greener.","audio":"g6/u4/s1/02.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"I hope so! Do you think we'll have flying cars?","audio":"g6/u4/s1/03.mp3"},{"sp":"SAMI","name":"Sami","text":"Maybe. But I don't think they'll be cheap. Most people will still drive normal cars — electric ones.","audio":"g6/u4/s1/04.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"Electric cars will help the air, too. What about schools?","audio":"g6/u4/s1/05.mp3"},{"sp":"SAMI","name":"Sami","text":"I think students will learn with robots and virtual reality. But we'll still need teachers!","audio":"g6/u4/s1/06.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"Definitely. And I'll probably be an engineer by then.","audio":"g6/u4/s1/07.mp3"},{"sp":"SAMI","name":"Sami","text":"And I'll be your doctor if you work too hard!","audio":"g6/u4/s1/08.mp3"}],"roles":["YUSUF","SAMI"],"chunks":[{"en":"What do you think ___ will be like?","ar":"","audio":"g6/u4/s1/c1.mp3"},{"en":"I think there'll be ___.","ar":"","audio":"g6/u4/s1/c2.mp3"},{"en":"I don't think ___ will ___.","ar":"","audio":"g6/u4/s1/c3.mp3"},{"en":"Maybe. / Probably. / Definitely.","ar":"","audio":"g6/u4/s1/c4.mp3"},{"en":"I hope so!","ar":"","audio":"g6/u4/s1/c5.mp3"}],"sound":{"type":"pairs","title":"\"I go\" or \"I'll go\"?","en":"\"I'll\" is short for \"I will\". The /l/ is very small and soft, so it's easy to miss! Listen carefully, because it changes the time: \"I go\" (every day) — \"I'll go\" (in the future).","ar":"كلمة I'll اختصار I will، وصوت /l/ فيها صغير وخفيف ويسهل أن يفوتك. استمع جيدًا لأنه يغيّر الزمن: I go تعني كل يوم، وI'll go تعني في المستقبل.","pairs":[["I go by bus.","I'll go by bus."],["We plant trees.","We'll plant trees."],["They recycle paper.","They'll recycle paper."],["You need water.","You'll need water."],["We walk to school.","We'll walk to school."]],"audio":[["g6/u4/s1/p1a.mp3","g6/u4/s1/p1b.mp3"],["g6/u4/s1/p2a.mp3","g6/u4/s1/p2b.mp3"],["g6/u4/s1/p3a.mp3","g6/u4/s1/p3b.mp3"],["g6/u4/s1/p4a.mp3","g6/u4/s1/p4b.mp3"],["g6/u4/s1/p5a.mp3","g6/u4/s1/p5b.mp3"]]},"task":{"prompt":"Make five predictions about life in 2050. Your group says if they agree.","frame":"I think ___ will ___. I don't think ___ will ___. — I agree. / I'm not sure, because ___."},"cando":["I can make predictions with will and won't.","I can say how sure I am.","I can hear \"I'll\", \"we'll\" and \"they'll\"."],"teach":"Put \"Definitely\", \"Probably\", \"Maybe\" and \"Definitely not\" in four corners. Read a prediction; students walk to the corner that shows how sure they are and explain why.","id":"g6u4s1","track":"g6/u4/s1/track.mp3"},{"kind":"speak","n":2,"title":"We Should Use Cloth Bags","func":"Persuading others","func_ar":"إقناع الآخرين","kagan":["Talking Chips","Carousel Feedback"],"model":[{"sp":"LINA","name":"Lina","text":"Noor, our class needs to choose a project for Environment Week. Any ideas?","audio":"g6/u4/s2/01.mp3"},{"sp":"NOOR","name":"Noor","text":"I think we should stop using plastic bags in the school shop. If we sell cloth bags, we can reduce plastic a lot.","audio":"g6/u4/s2/02.mp3"},{"sp":"LINA","name":"Lina","text":"That's a good idea, but cloth bags cost more money.","audio":"g6/u4/s2/03.mp3"},{"sp":"NOOR","name":"Noor","text":"True, but they last for years. And if we decorate them, students will want to buy them!","audio":"g6/u4/s2/04.mp3"},{"sp":"LINA","name":"Lina","text":"You've persuaded me! What about the price?","audio":"g6/u4/s2/05.mp3"},{"sp":"NOOR","name":"Noor","text":"We could sell them for ten riyals each. It's a fair price, and the money can buy more trees for the garden.","audio":"g6/u4/s2/06.mp3"},{"sp":"LINA","name":"Lina","text":"Perfect. Let's present the idea to the class tomorrow.","audio":"g6/u4/s2/07.mp3"}],"roles":["LINA","NOOR"],"chunks":[{"en":"We should ___.","ar":"","audio":"g6/u4/s2/c1.mp3"},{"en":"If we ___, we can ___.","ar":"","audio":"g6/u4/s2/c2.mp3"},{"en":"That's a good idea, but ___.","ar":"","audio":"g6/u4/s2/c3.mp3"},{"en":"True, but ___.","ar":"","audio":"g6/u4/s2/c4.mp3"},{"en":"You've persuaded me!","ar":"","audio":"g6/u4/s2/c5.mp3"}],"sound":{"type":"pairs","title":"Final /s/ or /z/?","en":"At the end of a word, /s/ is only air (price), and /z/ uses your voice (prize). The vowel before /z/ is a little longer, too.","ar":"في آخر الكلمة يكون /s/ هواءً فقط كما في price، أما /z/ فيُنطق مع اهتزاز الصوت كما في prize، والحركة قبل /z/ أطول قليلًا.","pairs":[["price","prize"],["rice","rise"],["place","plays"],["bus","buzz"],["peace","peas"]],"audio":[["g6/u4/s2/p1a.mp3","g6/u4/s2/p1b.mp3"],["g6/u4/s2/p2a.mp3","g6/u4/s2/p2b.mp3"],["g6/u4/s2/p3a.mp3","g6/u4/s2/p3b.mp3"],["g6/u4/s2/p4a.mp3","g6/u4/s2/p4b.mp3"],["g6/u4/s2/p5a.mp3","g6/u4/s2/p5b.mp3"]]},"task":{"prompt":"Persuade your group to choose your environment project. Give two reasons and answer one objection.","frame":"We should ___ because ___. If we ___, we'll ___. — True, but ___."},"cando":["I can persuade others with reasons.","I can answer someone who disagrees.","I can hear final /s/ and /z/."],"teach":"Good persuaders answer objections. After each pitch, the group must give one \"but...\" and the speaker must answer it with \"True, but...\".","id":"g6u4s2","track":"g6/u4/s2/track.mp3"}],"check":[{"type":"mcq","q":"What does Sami say about the school tomatoes?","ref":"L1#5","opts":["They didn't grow.","They are all red.","Students ate them all.","They have never been bigger."],"ans":3,"audio":"g6/u4/l1/05.mp3","line":"We also used the food waste to make compost for the school garden. Our tomatoes have never been bigger!","speaker":"Sami"},{"type":"mcq","q":"Where does the engineer work?","ref":"L2#1","opts":["at the National Water Company","at a university","at a school","at a hospital"],"ans":0,"audio":"g6/u4/l2/01.mp3","line":"Hello, everyone. I work for the National Water Company. Did you know that Saudi Arabia is one of the driest countries in the world? We have no rivers that flow all year.","speaker":"Engineer Huda"},{"type":"mcq","q":"What did the Prophet ﷺ teach about water?","ref":"L2#7","opts":["to share it with animals","not to waste it, even at a flowing river","to drink it slowly","to keep it cold"],"ans":1,"audio":"g6/u4/l2/07.mp3","line":"And when you make wudu, use only the water you need. The Prophet, peace be upon him, taught us not to waste water, even at a flowing river.","speaker":"Engineer Huda"},{"type":"mcq","q":"What should Sami wear?","ref":"L3#7","opts":["his school uniform","sandals","a sports kit","old clothes and a hat"],"ans":3,"audio":"g6/u4/l3/07.mp3","line":"Wear old clothes and a hat, and bring gloves. They'll give us the tools and water. Oh, and bring sunscreen — there isn't much shade.","speaker":"Adam"}],"id":"g6u4"},{"n":5,"title":"Science and Discovery","ar":"العلوم والاكتشاف","emoji":"🔬","goals":["I can understand facts and explanations in a science talk.","I can follow and give instructions for an experiment.","I can ask for repetition and clarification."],"listen":[{"kind":"listen","n":1,"title":"Journey Through the Solar System","skill":"Listening for facts and explanations","skill_ar":"الاستماع إلى الحقائق والتفسيرات","kagan":["Numbered Heads Together","Line-Ups"],"vocab":[{"w":"solar system","ar":"المجموعة الشمسية","emoji":"🪐","ex":"Let's travel through the solar system.","audio":"g6/u5/l1/v1.mp3"},{"w":"star","ar":"نجم","emoji":"⭐","ex":"The Sun is a star.","audio":"g6/u5/l1/v2.mp3"},{"w":"surface","ar":"سطح","emoji":"🌍","ex":"Earth has liquid water on its surface.","audio":"g6/u5/l1/v3.mp3"},{"w":"soil","ar":"تربة","emoji":"🟤","ex":"The soil on Mars contains iron.","audio":"g6/u5/l1/v4.mp3"},{"w":"iron","ar":"حديد","emoji":"🔩","ex":"Iron looks like rust.","audio":"g6/u5/l1/v5.mp3"},{"w":"rings","ar":"حلقات","emoji":"💍","ex":"Saturn is famous for its rings.","audio":"g6/u5/l1/v6.mp3"}],"script":[{"sp":"MOM","name":"Planetarium Host","text":"Welcome to the planetarium! Sit back, look up, and let's travel through our solar system.","audio":"g6/u5/l1/01.mp3"},{"sp":"MOM","name":"Planetarium Host","text":"At the center is the Sun. It's a star, and it's so big that more than one million Earths could fit inside it!","audio":"g6/u5/l1/02.mp3"},{"sp":"MOM","name":"Planetarium Host","text":"The closest planet to the Sun is Mercury. It's the smallest planet, and one year there lasts only eighty-eight days.","audio":"g6/u5/l1/03.mp3"},{"sp":"MOM","name":"Planetarium Host","text":"Our home, Earth, is the third planet. It's the only planet we know with liquid water on its surface and living things.","audio":"g6/u5/l1/04.mp3"},{"sp":"MOM","name":"Planetarium Host","text":"Mars is called the Red Planet because its soil contains iron, which looks like rust. Scientists hope that humans will travel to Mars one day.","audio":"g6/u5/l1/05.mp3"},{"sp":"MOM","name":"Planetarium Host","text":"Jupiter is the largest planet. It has a giant storm called the Great Red Spot, and that storm is bigger than Earth!","audio":"g6/u5/l1/06.mp3"},{"sp":"MOM","name":"Planetarium Host","text":"Saturn is famous for its beautiful rings, which are made of ice and rock.","audio":"g6/u5/l1/07.mp3"},{"sp":"ADAM","name":"Adam","text":"Which planets are the coldest?","audio":"g6/u5/l1/08.mp3"},{"sp":"MOM","name":"Planetarium Host","text":"Great question! Uranus and Neptune are the coldest. They can be colder than minus two hundred degrees.","audio":"g6/u5/l1/09.mp3"}],"tasks":[{"type":"mcq","q":"How many Earths could fit inside the Sun?","opts":["about one thousand","exactly ten thousand","about one hundred","more than one million"],"ans":3},{"type":"mcq","q":"How long is one year on Mercury?","opts":["eight months","eighty years","eighty-eight days","eighteen days"],"ans":2},{"type":"mcq","q":"Why is Mars called the Red Planet?","opts":["Its soil contains iron, which looks like rust.","It's very hot.","It's close to the Sun.","It has red clouds."],"ans":0},{"type":"mcq","q":"What is the Great Red Spot?","opts":["a giant storm on Jupiter","a crater on Mars","a ring around Saturn","a hot area on Mercury"],"ans":0},{"type":"mcq","q":"What are Saturn's rings made of?","opts":["gas and dust","sand and ice","ice and rock","iron and water"],"ans":2},{"type":"tf","s":"Mercury is the largest planet.","ans":false},{"type":"tf","s":"Jupiter's storm is smaller than Earth.","ans":false},{"type":"gap","s":"The Sun is a ___.","ans":["star"]},{"type":"gap","s":"Uranus and Neptune can be colder than minus two ___ degrees.","ans":["hundred"]}],"predict":{"en":"You are at a planetarium show about the solar system. What facts do you already know about the planets?","ar":""},"tip":{"en":"Science talks give a fact and then a reason or an example. Listen for \"because\", \"which\" and \"so... that\".","ar":"تقدّم المحاضرات العلمية حقيقة ثم سببًا أو مثالًا. استمع لكلمات مثل because وwhich وso... that."},"speak":{"prompt":"Choose a planet. Tell your partner three facts about it without saying its name. He guesses.","frame":"This planet is ___. It has ___. It's the ___est planet. Which planet is it?"},"teach":"Make a human solar system: eight students hold planet names and stand in order from a \"Sun\". Each one says one fact from the talk.","id":"g6u5l1","track":"g6/u5/l1/track.mp3"},{"kind":"listen","n":2,"title":"A Volcano in the Lab","skill":"Following the steps of an experiment","skill_ar":"اتباع خطوات تجربة علمية","kagan":["RallyCoach","Line-Ups"],"vocab":[{"w":"experiment","ar":"تجربة","emoji":"🧪","ex":"Today, we're doing an experiment.","audio":"g6/u5/l2/v1.mp3"},{"w":"safety glasses","ar":"نظارات السلامة","emoji":"🥽","ex":"Put on your safety glasses.","audio":"g6/u5/l2/v2.mp3"},{"w":"pour","ar":"يصبّ","emoji":"🫗","ex":"Pour the vinegar slowly.","audio":"g6/u5/l2/v3.mp3"},{"w":"baking soda","ar":"بيكربونات الصوديوم","emoji":"🧂","ex":"Add two spoons of baking soda.","audio":"g6/u5/l2/v4.mp3"},{"w":"vinegar","ar":"خلّ","emoji":"🍶","ex":"Pour half a cup of vinegar.","audio":"g6/u5/l2/v5.mp3"},{"w":"reaction","ar":"تفاعل","emoji":"💥","ex":"It's a chemical reaction.","audio":"g6/u5/l2/v6.mp3"}],"script":[{"sp":"MAN","name":"Mr. Faisal","text":"Today, we're going to make a simple volcano to see a chemical reaction. Please put on your safety glasses first.","audio":"g6/u5/l2/01.mp3"},{"sp":"MAN","name":"Mr. Faisal","text":"Step one: put the small plastic bottle in the middle of the tray. The tray will catch the \"lava\".","audio":"g6/u5/l2/02.mp3"},{"sp":"MAN","name":"Mr. Faisal","text":"Step two: pour two spoons of baking soda into the bottle. Use the funnel, so you don't make a mess.","audio":"g6/u5/l2/03.mp3"},{"sp":"MAN","name":"Mr. Faisal","text":"Step three: add a few drops of red food coloring and a little dish soap. The soap will make more bubbles.","audio":"g6/u5/l2/04.mp3"},{"sp":"MAN","name":"Mr. Faisal","text":"Step four — and this is the exciting part — slowly pour half a cup of vinegar into the bottle, then step back quickly!","audio":"g6/u5/l2/05.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"Wow! It's coming out! Why does it happen?","audio":"g6/u5/l2/06.mp3"},{"sp":"MAN","name":"Mr. Faisal","text":"When vinegar and baking soda mix, they make a gas called carbon dioxide. The gas needs space, so it pushes the liquid up and out of the bottle.","audio":"g6/u5/l2/07.mp3"},{"sp":"BEN","name":"Ben","text":"Can we do it again with more vinegar?","audio":"g6/u5/l2/08.mp3"},{"sp":"MAN","name":"Mr. Faisal","text":"Yes, but first, write down what you saw in your science notebook. Good scientists always record their results.","audio":"g6/u5/l2/09.mp3"}],"tasks":[{"type":"mcq","q":"What must students do first?","opts":["pour the vinegar","write in their notebooks","add the soap","put on their safety glasses"],"ans":3},{"type":"mcq","q":"Why do they use a tray?","opts":["to measure the vinegar","to catch the \"lava\"","to mix the powder","to keep the bottle warm"],"ans":1},{"type":"mcq","q":"Why do they use a funnel?","opts":["so they don't make a mess","to measure the baking soda","so the reaction is faster","to make bubbles"],"ans":0},{"type":"mcq","q":"What does the dish soap do?","opts":["It cleans the bottle.","It changes the color.","It makes the gas.","It makes more bubbles."],"ans":3},{"type":"mcq","q":"What gas do vinegar and baking soda make?","opts":["hydrogen","carbon dioxide","oxygen","steam"],"ans":1},{"type":"tf","s":"Students should pour the vinegar quickly.","ans":false},{"type":"tf","s":"The teacher asks students to record their results before trying again.","ans":true},{"type":"gap","s":"Pour two ___ of baking soda into the bottle.","ans":["spoons","spoonfuls"]},{"type":"gap","s":"Slowly pour half a cup of ___ into the bottle.","ans":["vinegar"]},{"type":"order","items":["Put the bottle on the tray.","Add the baking soda.","Add food coloring and soap.","Pour in the vinegar."]}],"predict":{"en":"Your teacher is going to show you how to make a model volcano. What do you think you need?","ar":""},"tip":{"en":"Instructions are in order: step one, step two... Listen for the verb at the start of each step: put, pour, add.","ar":"تأتي التعليمات بالترتيب: step one وstep two... استمع للفعل في بداية كل خطوة مثل put وpour وadd."},"speak":{"prompt":"Explain a simple experiment or recipe to your partner, step by step.","frame":"Step one: ___. Step two: ___. Be careful not to ___."},"teach":"Do the experiment! It's safe and memorable. Students give the instructions in English while one volunteer follows them exactly.","id":"g6u5l2","track":"g6/u5/l2/track.mp3"},{"kind":"listen","n":3,"title":"A Young Scientist's Discovery","skill":"Listening for feelings and reasons","skill_ar":"الاستماع إلى المشاعر والأسباب","kagan":["Three-Step Interview","Think-Pair-Share"],"vocab":[{"w":"hike","ar":"يتنزّه سيرًا في الطبيعة","emoji":"🥾","ex":"I was hiking in the mountains.","audio":"g6/u5/l3/v1.mp3"},{"w":"unusual","ar":"غير عادي","emoji":"❓","ex":"I saw something unusual.","audio":"g6/u5/l3/v2.mp3"},{"w":"lizard","ar":"سحلية","emoji":"🦎","ex":"It was a small blue lizard.","audio":"g6/u5/l3/v3.mp3"},{"w":"professor","ar":"أستاذ جامعي","emoji":"👩‍🏫","ex":"A professor called us.","audio":"g6/u5/l3/v4.mp3"},{"w":"record","ar":"يسجّل / يوثّق","emoji":"📝","ex":"Nobody had recorded it there before.","audio":"g6/u5/l3/v5.mp3"},{"w":"proud","ar":"فخور","emoji":"🏅","ex":"I felt really proud.","audio":"g6/u5/l3/v6.mp3"}],"script":[{"sp":"ANNOUNCER","name":"Presenter","text":"Today on Science Today, we're talking to a twelve-year-old with an amazing story. Yusuf, tell us what happened.","audio":"g6/u5/l3/01.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"Well, last spring, I was hiking with my family in the mountains near Abha. I always take my camera with me, because I love taking photos of animals.","audio":"g6/u5/l3/02.mp3"},{"sp":"ANNOUNCER","name":"Presenter","text":"And you saw something unusual?","audio":"g6/u5/l3/03.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"Yes. I saw a small blue lizard on a rock. I'd never seen one like it before, so I took about twenty photos.","audio":"g6/u5/l3/04.mp3"},{"sp":"ANNOUNCER","name":"Presenter","text":"What did you do next?","audio":"g6/u5/l3/05.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"At first, I wasn't sure it was important. But my dad said, \"Let's send the photos to the university.\" Two weeks later, a professor called us. She was very excited!","audio":"g6/u5/l3/06.mp3"},{"sp":"ANNOUNCER","name":"Presenter","text":"Why was she excited?","audio":"g6/u5/l3/07.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"Because nobody had recorded this kind of lizard in that area before. Now scientists are going to study it.","audio":"g6/u5/l3/08.mp3"},{"sp":"ANNOUNCER","name":"Presenter","text":"How did you feel?","audio":"g6/u5/l3/09.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"Honestly, I was shocked at first! Then I felt really proud. It showed me that you don't have to be an adult to help science.","audio":"g6/u5/l3/10.mp3"},{"sp":"ANNOUNCER","name":"Presenter","text":"Great message. What's next for you?","audio":"g6/u5/l3/11.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"The university invited me to join their nature camp this summer. I can't wait!","audio":"g6/u5/l3/12.mp3"}],"tasks":[{"type":"mcq","q":"Where was Yusuf hiking?","opts":["in the mountains near Abha","in a park in Taif","on the coast near Jeddah","in the desert near Riyadh"],"ans":0},{"type":"mcq","q":"Why does Yusuf always take his camera?","opts":["He sells his photos.","He loves taking photos of animals.","His dad asks him to.","He wants to be a scientist."],"ans":1},{"type":"mcq","q":"How did Yusuf feel about the lizard at first?","opts":["He was frightened.","He was bored.","He was very excited.","He wasn't sure it was important."],"ans":3},{"type":"mcq","q":"Why was the professor excited?","opts":["Nobody had recorded this lizard in that area before.","Yusuf's photos were beautiful.","She knew Yusuf's dad.","The lizard was dangerous."],"ans":0},{"type":"mcq","q":"What did the experience teach Yusuf?","opts":["Scientists don't listen to children.","Photos are more important than science.","Lizards are dangerous.","You don't have to be an adult to help science."],"ans":3},{"type":"tf","s":"The lizard was blue.","ans":true},{"type":"tf","s":"The professor called them two months later.","ans":false},{"type":"gap","s":"Yusuf took about ___ photos of the lizard.","ans":["twenty","20"]},{"type":"gap","s":"This summer, Yusuf is going to join the university's nature ___.","ans":["camp"]}],"predict":{"en":"A twelve-year-old boy made a discovery that excited scientists. What do you think he found?","ar":""},"tip":{"en":"Feelings can change in a story. Listen for \"at first\" and \"then\", and for words like shocked, proud and excited.","ar":"قد تتغير المشاعر خلال القصة. استمع لعبارتي at first وthen ولكلمات مثل shocked وproud وexcited."},"speak":{"prompt":"Tell your partner about a time you discovered or learned something surprising. How did you feel?","frame":"Once, I ___. At first, I felt ___. Then, ___. I learned that ___."},"teach":"This links back to Yusuf's photography hobby in Grade 5. Celebrate \"citizen science\": students can photograph birds or plants near home and share them with the class.","id":"g6u5l3","track":"g6/u5/l3/track.mp3"}],"speak":[{"kind":"speak","n":1,"title":"How Does a Solar Panel Work?","func":"Describing a process","func_ar":"وصف عملية","kagan":["RallyCoach","Timed Pair Share"],"model":[{"sp":"BEN","name":"Ben","text":"Adam, do you know how a solar panel works?","audio":"g6/u5/s1/01.mp3"},{"sp":"ADAM","name":"Adam","text":"Kind of. First, the sun shines on the panel. The panel is made of special cells.","audio":"g6/u5/s1/02.mp3"},{"sp":"BEN","name":"Ben","text":"And then?","audio":"g6/u5/s1/03.mp3"},{"sp":"ADAM","name":"Adam","text":"Then the cells change the sunlight into electricity. After that, the electricity goes through wires into a battery.","audio":"g6/u5/s1/04.mp3"},{"sp":"BEN","name":"Ben","text":"Why do you need a battery?","audio":"g6/u5/s1/05.mp3"},{"sp":"ADAM","name":"Adam","text":"So you can use the electricity at night, when there's no sun. Finally, the battery gives power to the lights in the house.","audio":"g6/u5/s1/06.mp3"},{"sp":"BEN","name":"Ben","text":"That's clever. Saudi Arabia has so much sun — we should use solar energy everywhere!","audio":"g6/u5/s1/07.mp3"},{"sp":"ADAM","name":"Adam","text":"We already do. There are huge solar farms in the desert!","audio":"g6/u5/s1/08.mp3"}],"roles":["BEN","ADAM"],"chunks":[{"en":"First, ___.","ar":"","audio":"g6/u5/s1/c1.mp3"},{"en":"Then, ___.","ar":"","audio":"g6/u5/s1/c2.mp3"},{"en":"After that, ___.","ar":"","audio":"g6/u5/s1/c3.mp3"},{"en":"Finally, ___.","ar":"","audio":"g6/u5/s1/c4.mp3"},{"en":"That's clever!","ar":"","audio":"g6/u5/s1/c5.mp3"}],"sound":{"type":"pairs","title":"Short /ɪ/ or long /iː/?","en":"You learned these sounds in Grade 3. Now try harder pairs: \"fill\" is short and relaxed; \"feel\" is long — smile and stretch it.","ar":"تعلّمت هذين الصوتين في الصف الثالث. جرّب الآن أزواجًا أصعب: fill قصيرة ومرتخية، وfeel طويلة؛ ابتسم ومدّ الصوت.","pairs":[["fill","feel"],["still","steal"],["live","leave"],["chip","cheap"],["rich","reach"]],"audio":[["g6/u5/s1/p1a.mp3","g6/u5/s1/p1b.mp3"],["g6/u5/s1/p2a.mp3","g6/u5/s1/p2b.mp3"],["g6/u5/s1/p3a.mp3","g6/u5/s1/p3b.mp3"],["g6/u5/s1/p4a.mp3","g6/u5/s1/p4b.mp3"],["g6/u5/s1/p5a.mp3","g6/u5/s1/p5b.mp3"]]},"task":{"prompt":"Explain a process to your group (how bread is made, how rain forms or how a plant grows). Use four sequence words.","frame":"First, ___. Then, ___. After that, ___. Finally, ___."},"cando":["I can describe a process in order.","I can explain why each step is needed.","I can hear short /ɪ/ and long /iː/ in harder words."],"teach":"Groups draw the process as a four-box comic strip, then explain it using the sequence words while pointing to each box.","id":"g6u5s1","track":"g6/u5/s1/track.mp3"},{"kind":"speak","n":2,"title":"Sorry, Could You Repeat That?","func":"Asking for repetition and clarification","func_ar":"طلب الإعادة والتوضيح","kagan":["Inside-Outside Circle","RallyRobin"],"model":[{"sp":"MAN","name":"Mr. Faisal","text":"For homework, please read pages forty to forty-five and answer the questions on page fifty.","audio":"g6/u5/s2/01.mp3"},{"sp":"SAMI","name":"Sami","text":"Sorry, Mr. Faisal. Could you repeat that, please?","audio":"g6/u5/s2/02.mp3"},{"sp":"MAN","name":"Mr. Faisal","text":"Of course. Read pages forty to forty-five.","audio":"g6/u5/s2/03.mp3"},{"sp":"SAMI","name":"Sami","text":"Did you say forty or fourteen?","audio":"g6/u5/s2/04.mp3"},{"sp":"MAN","name":"Mr. Faisal","text":"Forty. Four, zero.","audio":"g6/u5/s2/05.mp3"},{"sp":"SAMI","name":"Sami","text":"Thank you. And what do you mean by \"a summary\"? It's in question three.","audio":"g6/u5/s2/06.mp3"},{"sp":"MAN","name":"Mr. Faisal","text":"A summary is a short version of the text in your own words. About fifty words.","audio":"g6/u5/s2/07.mp3"},{"sp":"SAMI","name":"Sami","text":"So, I don't copy the sentences from the book?","audio":"g6/u5/s2/08.mp3"},{"sp":"MAN","name":"Mr. Faisal","text":"Exactly. Use your own words. Any other questions?","audio":"g6/u5/s2/09.mp3"},{"sp":"SAMI","name":"Sami","text":"No, that's clear now. Thanks!","audio":"g6/u5/s2/10.mp3"}],"roles":["SAMI","MAN"],"chunks":[{"en":"Sorry, could you repeat that, please?","ar":"","audio":"g6/u5/s2/c1.mp3"},{"en":"Did you say ___ or ___?","ar":"","audio":"g6/u5/s2/c2.mp3"},{"en":"What do you mean by ___?","ar":"","audio":"g6/u5/s2/c3.mp3"},{"en":"So, ___?","ar":"","audio":"g6/u5/s2/c4.mp3"},{"en":"That's clear now.","ar":"","audio":"g6/u5/s2/c5.mp3"}],"sound":{"type":"sort","title":"/p/, /b/ or /v/?","cats":[{"key":"/p/","label":"/p/ pest"},{"key":"/b/","label":"/b/ best"},{"key":"/v/","label":"/v/ vest"}],"en":"When you're not sure what you heard, check! These three sounds are very close. /p/ is a puff of air, /b/ uses your voice, and /v/ uses your top teeth on your bottom lip.","ar":"عندما لا تكون متأكدًا مما سمعت، تحقّق! هذه الأصوات الثلاثة متقاربة جدًا: /p/ دفعة هواء، و/b/ مع اهتزاز الصوت، و/v/ بوضع الأسنان العليا على الشفة السفلى.","items":[{"text":"vet","key":"/v/","audio":"g6/u5/s2/i1.mp3"},{"text":"pet","key":"/p/","audio":"g6/u5/s2/i2.mp3"},{"text":"bet","key":"/b/","audio":"g6/u5/s2/i3.mp3"},{"text":"van","key":"/v/","audio":"g6/u5/s2/i4.mp3"},{"text":"pan","key":"/p/","audio":"g6/u5/s2/i5.mp3"},{"text":"ban","key":"/b/","audio":"g6/u5/s2/i6.mp3"},{"text":"vest","key":"/v/","audio":"g6/u5/s2/i7.mp3"},{"text":"pest","key":"/p/","audio":"g6/u5/s2/i8.mp3"},{"text":"best","key":"/b/","audio":"g6/u5/s2/i9.mp3"}]},"task":{"prompt":"Your partner gives you instructions with numbers and new words. Ask him to repeat and explain.","frame":"Sorry, could you repeat that? — Did you say ___ or ___? — What do you mean by ___?"},"cando":["I can ask someone to repeat.","I can check numbers and meanings.","I can tell /p/, /b/ and /v/ apart."],"teach":"Asking for clarification is a strength, not a weakness. Give students a \"Clarify\" card; anyone who uses a clarification chunk in a real lesson that week earns a class point.","id":"g6u5s2","track":"g6/u5/s2/track.mp3"}],"check":[{"type":"mcq","q":"What makes Earth special?","ref":"L1#4","opts":["It's the largest planet.","It has liquid water and living things.","It's the closest to the Sun.","It has rings."],"ans":1,"audio":"g6/u5/l1/04.mp3","line":"Our home, Earth, is the third planet. It's the only planet we know with liquid water on its surface and living things.","speaker":"Planetarium Host"},{"type":"mcq","q":"What do scientists hope?","ref":"L1#5","opts":["that Mars has rings","that Jupiter's storm will stop","that humans will travel to Mars one day","that Mars will become green"],"ans":2,"audio":"g6/u5/l1/05.mp3","line":"Mars is called the Red Planet because its soil contains iron, which looks like rust. Scientists hope that humans will travel to Mars one day.","speaker":"Planetarium Host"},{"type":"mcq","q":"What should students do after pouring the vinegar?","ref":"L2#5","opts":["add more soap","stir the bottle","close the bottle","step back quickly"],"ans":3,"audio":"g6/u5/l2/05.mp3","line":"Step four — and this is the exciting part — slowly pour half a cup of vinegar into the bottle, then step back quickly!","speaker":"Mr. Faisal"},{"type":"mcq","q":"Whose idea was it to send the photos to the university?","ref":"L3#6","opts":["the professor","Yusuf's dad","Yusuf","Yusuf's teacher"],"ans":1,"audio":"g6/u5/l3/06.mp3","line":"At first, I wasn't sure it was important. But my dad said, \"Let's send the photos to the university.\" Two weeks later, a professor called us. She was very excited!","speaker":"Yusuf"}],"id":"g6u5"},{"n":6,"title":"Celebrations and Cultures","ar":"الاحتفالات والثقافات","emoji":"🎉","goals":["I can understand talks about national days and festivals.","I can describe a celebration and compare traditions.","I can plan an event and give a short presentation."],"listen":[{"kind":"listen","n":1,"title":"Saudi National Day","skill":"Listening for dates and events","skill_ar":"الاستماع إلى التواريخ والأحداث","kagan":["Numbered Heads Together","RallyRobin"],"vocab":[{"w":"celebrate","ar":"يحتفل","emoji":"🎉","ex":"We celebrate Saudi National Day.","audio":"g6/u6/l1/v1.mp3"},{"w":"unification","ar":"التوحيد","emoji":"🤝","ex":"The king announced the unification of the Kingdom.","audio":"g6/u6/l1/v2.mp3"},{"w":"flag","ar":"علم","emoji":"🏳️","ex":"Green is the color of our flag.","audio":"g6/u6/l1/v3.mp3"},{"w":"fireworks","ar":"ألعاب نارية","emoji":"🎆","ex":"There are fireworks in many cities.","audio":"g6/u6/l1/v4.mp3"},{"w":"air show","ar":"عرض جوي","emoji":"✈️","ex":"We watched the air show.","audio":"g6/u6/l1/v5.mp3"},{"w":"play (n.)","ar":"مسرحية","emoji":"🎭","ex":"Grade 6 will present a short play.","audio":"g6/u6/l1/v6.mp3"}],"script":[{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"Next week, on the twenty-third of September, we'll celebrate Saudi National Day. Do you know why we celebrate on this day?","audio":"g6/u6/l1/01.mp3"},{"sp":"ADAM","name":"Adam","text":"Is it the day King Abdulaziz united the country?","audio":"g6/u6/l1/02.mp3"},{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"Exactly. In 1932, King Abdulaziz announced the unification of the Kingdom of Saudi Arabia.","audio":"g6/u6/l1/03.mp3"},{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"Don't mix it up with Founding Day, which is on the twenty-second of February. Founding Day remembers the first Saudi state in 1727.","audio":"g6/u6/l1/04.mp3"},{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"On National Day, you'll see green everywhere — on buildings, cars and clothes. Green is the color of our flag.","audio":"g6/u6/l1/05.mp3"},{"sp":"BEN","name":"Ben","text":"What do people do to celebrate?","audio":"g6/u6/l1/06.mp3"},{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"Families go out together, there are fireworks in many cities, and there are air shows with jets in the sky. Many people also wear traditional clothes.","audio":"g6/u6/l1/07.mp3"},{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"At our school, we'll have a special assembly on Thursday morning. Grade 6 will present a short play about the history of the Kingdom, and there will be traditional food for everyone.","audio":"g6/u6/l1/08.mp3"},{"sp":"SAMI","name":"Sami","text":"Can we wear green?","audio":"g6/u6/l1/09.mp3"},{"sp":"MR_HASSAN","name":"Mr. Hassan","text":"Of course! Green T-shirts or green scarves are perfect.","audio":"g6/u6/l1/10.mp3"}],"tasks":[{"type":"mcq","q":"When is Saudi National Day?","opts":["on the twenty-third of February","on the first of January","on the twenty-third of September","on the twenty-second of February"],"ans":2},{"type":"mcq","q":"What happened in 1932?","opts":["The first school opened.","Diriyah became the capital.","King Abdulaziz announced the unification of the Kingdom.","The first Saudi state started."],"ans":2},{"type":"mcq","q":"What does Founding Day remember?","opts":["the first Saudi state in 1727","the first flag","the first school","the unification in 1932"],"ans":0},{"type":"mcq","q":"Why do people use green?","opts":["It's a school rule.","It's the color of nature.","It's the color of the flag.","It's the king's favorite color."],"ans":2},{"type":"mcq","q":"What will Grade 6 present at the assembly?","opts":["a science project","a poem competition","a sports show","a short play about the history of the Kingdom"],"ans":3},{"type":"tf","s":"The school assembly will be on Sunday morning.","ans":false},{"type":"tf","s":"There are air shows with jets on National Day.","ans":true},{"type":"gap","s":"Founding Day is on the twenty-second of ___.","ans":["February"]},{"type":"gap","s":"Students can wear green T-shirts or green ___.","ans":["scarves","scarfs"]}],"predict":{"en":"Mr. Hassan talks about an important national day. What do you know about Saudi National Day?","ar":""},"tip":{"en":"Don't mix up similar facts! Two dates and two events are mentioned. Write each date next to its event.","ar":"لا تخلط بين الحقائق المتشابهة! ذُكر تاريخان وحدثان، فاكتب كل تاريخ بجانب حدثه."},"speak":{"prompt":"Tell your partner how your family celebrates National Day.","frame":"On National Day, my family ___. We usually ___. My favorite part is ___."},"teach":"Students often confuse National Day and Founding Day. After listening, write two short lists on the board — \"National Day: 23 September, 1932, unification\" and \"Founding Day: 22 February, 1727, first Saudi state\".","id":"g6u6l1","track":"g6/u6/l1/track.mp3"},{"kind":"listen","n":2,"title":"Eid Around the World","skill":"Listening for local words and explanations","skill_ar":"الاستماع إلى الكلمات المحلية وشرحها","kagan":["Three-Step Interview","Fan-N-Pick"],"vocab":[{"w":"forgiveness","ar":"المسامحة / طلب العفو","emoji":"🤲","ex":"We ask our parents for forgiveness.","audio":"g6/u6/l2/v1.mp3"},{"w":"festival","ar":"عيد / مهرجان","emoji":"🎊","ex":"It's called the Sugar Festival.","audio":"g6/u6/l2/v2.mp3"},{"w":"respect","ar":"احترام","emoji":"🙏","ex":"We kiss their hands to show respect.","audio":"g6/u6/l2/v3.mp3"},{"w":"forehead","ar":"جبهة","emoji":"🧑","ex":"We touch their hands to our foreheads.","audio":"g6/u6/l2/v4.mp3"},{"w":"huge","ar":"ضخم","emoji":"🐘","ex":"We go to a huge Eid prayer.","audio":"g6/u6/l2/v5.mp3"},{"w":"tradition","ar":"تقليد / عادة","emoji":"📿","ex":"That's a beautiful tradition.","audio":"g6/u6/l2/v6.mp3"}],"script":[{"sp":"WOMAN","name":"Radio Host","text":"Today on our program, three young Muslims tell us how they celebrate Eid al-Fitr in their countries. Let's start with Aisha, from Indonesia.","audio":"g6/u6/l2/01.mp3"},{"sp":"LINA","name":"Aisha","text":"In Indonesia, we call Eid \"Lebaran\". Millions of people travel back to their home villages to be with their families. We call this \"mudik\". On Eid morning, we ask our parents for forgiveness, and we eat ketupat — rice cooked in little baskets made of palm leaves.","audio":"g6/u6/l2/02.mp3"},{"sp":"WOMAN","name":"Radio Host","text":"That sounds lovely. Now, Emre, from Türkiye.","audio":"g6/u6/l2/03.mp3"},{"sp":"YUSUF","name":"Emre","text":"In Türkiye, Eid al-Fitr is also called \"Şeker Bayramı\", which means \"the Sugar Festival\".","audio":"g6/u6/l2/04.mp3"},{"sp":"YUSUF","name":"Emre","text":"Children go from house to house to wish people a happy Eid, and they get sweets and sometimes a little money. We also kiss the hands of older people and touch them to our foreheads to show respect.","audio":"g6/u6/l2/05.mp3"},{"sp":"WOMAN","name":"Radio Host","text":"And finally, Ben, who lives in London.","audio":"g6/u6/l2/06.mp3"},{"sp":"BEN","name":"Ben","text":"In London, Muslims come from many different countries, so Eid is very colorful! My family goes to a huge Eid prayer in a park. Then we visit friends and eat food from Pakistan, Somalia, Türkiye and Morocco. It's like a world festival!","audio":"g6/u6/l2/07.mp3"},{"sp":"WOMAN","name":"Radio Host","text":"Thank you all. Eid Mubarak, everyone!","audio":"g6/u6/l2/08.mp3"}],"tasks":[{"type":"mcq","q":"What do Indonesians call Eid?","opts":["Bayram","Mudik","Ketupat","Lebaran"],"ans":3},{"type":"mcq","q":"What is \"mudik\"?","opts":["traveling back to home villages","a type of sweet","a special rice dish","asking for forgiveness"],"ans":0},{"type":"mcq","q":"What does \"Şeker Bayramı\" mean?","opts":["the Big Prayer","the Family Festival","the Rice Festival","the Sugar Festival"],"ans":3},{"type":"mcq","q":"How do children in Türkiye show respect to older people?","opts":["They visit them at night.","They bow to them.","They give them sweets.","They kiss their hands and touch them to their foreheads."],"ans":3},{"type":"mcq","q":"Why is Eid in London \"very colorful\"?","opts":["Muslims come from many different countries.","There are fireworks in the park.","People only wear colorful clothes.","It's always in summer."],"ans":0},{"type":"tf","s":"Ketupat is rice cooked in little baskets made of palm leaves.","ans":true},{"type":"tf","s":"Ben's family prays the Eid prayer in a mosque.","ans":false},{"type":"gap","s":"In Türkiye, children sometimes get sweets and a little ___.","ans":["money"]},{"type":"gap","s":"Ben says Eid in London is like a world ___.","ans":["festival"]}],"predict":{"en":"Three young Muslims from different countries describe Eid al-Fitr. How do you think Eid is different around the world?","ar":""},"tip":{"en":"Each speaker uses a local word. Listen for the explanation after it: \"which means...\" or \"we call it...\".","ar":"يستخدم كل متحدث كلمة محلية. استمع للشرح الذي يأتي بعدها مثل which means... أو we call it..."},"speak":{"prompt":"Tell your partner about Eid in your family. Compare it with one country from the recording.","frame":"In my family, we ___. In ___, they ___. It's similar / different because ___."},"teach":"Find Indonesia, Türkiye and the UK on a map. Students notice that the Muslim world shares Eid but celebrates it in different and beautiful ways.","id":"g6u6l2","track":"g6/u6/l2/track.mp3"},{"kind":"listen","n":3,"title":"Planning the Class Celebration","skill":"Following a discussion and its decisions","skill_ar":"متابعة نقاش وقراراته","kagan":["Corners","RoundRobin"],"vocab":[{"w":"decide","ar":"يقرّر","emoji":"✅","ex":"Let's decide on the place.","audio":"g6/u6/l3/v1.mp3"},{"w":"choice","ar":"اختيار","emoji":"🔀","ex":"The garden is the best choice.","audio":"g6/u6/l3/v2.mp3"},{"w":"suggest","ar":"يقترح","emoji":"💡","ex":"I suggest the school hall.","audio":"g6/u6/l3/v3.mp3"},{"w":"compromise","ar":"حلّ وسط","emoji":"🤝","ex":"That's a great compromise!","audio":"g6/u6/l3/v4.mp3"},{"w":"balance","ar":"توازن","emoji":"⚖️","ex":"We need a balance of food.","audio":"g6/u6/l3/v5.mp3"},{"w":"slideshow","ar":"عرض صور","emoji":"🖼️","ex":"We could show a slideshow.","audio":"g6/u6/l3/v6.mp3"}],"script":[{"sp":"SAMI","name":"Sami","text":"Okay, everyone, let's plan the end-of-year celebration. We have three things to decide: the place, the food and the activities.","audio":"g6/u6/l3/01.mp3"},{"sp":"ADAM","name":"Adam","text":"For the place, I think the school garden is the best choice. It's big, and it's nice in the evening.","audio":"g6/u6/l3/02.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"But what if it's too hot? I suggest the school hall. It has air conditioning.","audio":"g6/u6/l3/03.mp3"},{"sp":"BEN","name":"Ben","text":"How about both? We can start in the hall and move to the garden after sunset.","audio":"g6/u6/l3/04.mp3"},{"sp":"SAMI","name":"Sami","text":"Great compromise! Does everyone agree? Okay. Now, the food.","audio":"g6/u6/l3/05.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"Let's ask each student to bring one dish from home. Then we'll have lots of different food.","audio":"g6/u6/l3/06.mp3"},{"sp":"ADAM","name":"Adam","text":"That's a good idea, but some people might bring only sweets. We need a list, so we get a balance of food.","audio":"g6/u6/l3/07.mp3"},{"sp":"SAMI","name":"Sami","text":"Agreed. Ben, can you make the list?","audio":"g6/u6/l3/08.mp3"},{"sp":"BEN","name":"Ben","text":"Sure. I'll send it on the class group by Monday.","audio":"g6/u6/l3/09.mp3"},{"sp":"SAMI","name":"Sami","text":"Finally, the activities. Any ideas?","audio":"g6/u6/l3/10.mp3"},{"sp":"ADAM","name":"Adam","text":"A quiz about our year, with prizes!","audio":"g6/u6/l3/11.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"And we could show a slideshow of our class photos. I've taken hundreds!","audio":"g6/u6/l3/12.mp3"},{"sp":"SAMI","name":"Sami","text":"Perfect. So: the hall first, then the garden; a food list from Ben; a quiz; and Yusuf's slideshow. The date is the eighteenth of June. Meeting finished!","audio":"g6/u6/l3/13.mp3"}],"tasks":[{"type":"mcq","q":"Why does Adam choose the school garden?","opts":["It's cheap.","It's close to the hall.","It has air conditioning.","It's big, and it's nice in the evening."],"ans":3},{"type":"mcq","q":"What is Yusuf worried about?","opts":["Nobody will come.","It might be too hot in the garden.","The hall is too small.","There won't be enough food."],"ans":1},{"type":"mcq","q":"What is Ben's compromise?","opts":["Have the party in the morning.","Cancel the activities.","Start in the hall and move to the garden after sunset.","Use only the garden."],"ans":2},{"type":"mcq","q":"Why does Adam want a food list?","opts":["to save money","to get a balance of food","to know who is coming","to choose a restaurant"],"ans":1},{"type":"mcq","q":"What will Yusuf show?","opts":["a slideshow of class photos","a film","a quiz","a science project"],"ans":0},{"type":"tf","s":"Each student will bring one dish from home.","ans":true},{"type":"tf","s":"Sami summarizes the decisions at the end.","ans":true},{"type":"gap","s":"Ben will send the list on the class ___ by Monday.","ans":["group","chat","group chat"]},{"type":"gap","s":"The celebration is on the eighteenth of ___.","ans":["June"]}],"predict":{"en":"A class committee plans an end-of-year celebration. What do they need to decide?","ar":""},"tip":{"en":"In discussions, people suggest, disagree and then decide. Listen for the final decision — it often comes at the end in a summary.","ar":"في النقاشات يقترح الناس ويختلفون ثم يقرّرون. استمع للقرار النهائي، فهو غالبًا يأتي في النهاية على شكل ملخّص."},"speak":{"prompt":"Plan a class celebration with your group. Decide the place, the food and one activity.","frame":"I suggest ___. — That's a good idea, but ___. — How about ___? — Agreed!"},"teach":"Point out Sami's summary at the end — good leaders summarize decisions. Every group must finish its planning with a one-sentence summary.","id":"g6u6l3","track":"g6/u6/l3/track.mp3"}],"speak":[{"kind":"speak","n":1,"title":"How Does Your Family Celebrate?","func":"Describing a celebration","func_ar":"وصف احتفال","kagan":["Inside-Outside Circle","Three-Step Interview"],"model":[{"sp":"BEN","name":"Ben","text":"Sami, how does your family celebrate Eid al-Adha?","audio":"g6/u6/s1/01.mp3"},{"sp":"SAMI","name":"Sami","text":"It's my favorite celebration! On the morning of Eid, we wear new clothes and go to the Eid prayer together.","audio":"g6/u6/s1/02.mp3"},{"sp":"BEN","name":"Ben","text":"What happens after the prayer?","audio":"g6/u6/s1/03.mp3"},{"sp":"SAMI","name":"Sami","text":"We visit my grandparents. My whole family gathers at their house — about thirty people!","audio":"g6/u6/s1/04.mp3"},{"sp":"BEN","name":"Ben","text":"Thirty? That's a lot! What do you eat?","audio":"g6/u6/s1/05.mp3"},{"sp":"SAMI","name":"Sami","text":"We share a big meal of rice and meat. We also give some of the meat to poor families. It's an important part of Eid al-Adha.","audio":"g6/u6/s1/06.mp3"},{"sp":"BEN","name":"Ben","text":"That's a beautiful tradition. What's the best part for you?","audio":"g6/u6/s1/07.mp3"},{"sp":"SAMI","name":"Sami","text":"Being together. Everyone is happy and thankful, and the children play all day.","audio":"g6/u6/s1/08.mp3"}],"roles":["BEN","SAMI"],"chunks":[{"en":"How does your family celebrate ___?","ar":"","audio":"g6/u6/s1/c1.mp3"},{"en":"On the morning of ___, we ___.","ar":"","audio":"g6/u6/s1/c2.mp3"},{"en":"My whole family gathers at ___.","ar":"","audio":"g6/u6/s1/c3.mp3"},{"en":"It's an important part of ___.","ar":"","audio":"g6/u6/s1/c4.mp3"},{"en":"The best part is ___.","ar":"","audio":"g6/u6/s1/c5.mp3"}],"sound":{"type":"sort","title":"/θ/ like \"think\" or /ð/ like \"this\"?","cats":[{"key":"/θ/","label":"/θ/ think"},{"key":"/ð/","label":"/ð/ this"}],"en":"For both sounds, put your tongue between your teeth. /θ/ is only air, like ث. /ð/ uses your voice, like ذ.","ar":"في الصوتين يوضع اللسان بين الأسنان. /θ/ هواء فقط مثل الثاء، و/ð/ مع اهتزاز الصوت مثل الذال.","items":[{"text":"thankful","key":"/θ/","audio":"g6/u6/s1/i1.mp3"},{"text":"together","key":"/ð/","audio":"g6/u6/s1/i2.mp3"},{"text":"thirty","key":"/θ/","audio":"g6/u6/s1/i3.mp3"},{"text":"gather","key":"/ð/","audio":"g6/u6/s1/i4.mp3"},{"text":"month","key":"/θ/","audio":"g6/u6/s1/i5.mp3"},{"text":"clothes","key":"/ð/","audio":"g6/u6/s1/i6.mp3"},{"text":"thousand","key":"/θ/","audio":"g6/u6/s1/i7.mp3"},{"text":"brother","key":"/ð/","audio":"g6/u6/s1/i8.mp3"}]},"task":{"prompt":"Describe a family celebration to your group. Say what happens, what you eat and what the best part is.","frame":"On ___, my family ___. We eat ___. The best part is ___."},"cando":["I can describe a celebration and its traditions.","I can ask about other people's celebrations.","I can say /θ/ and /ð/ correctly."],"teach":"Students put a hand on their throat: no buzz for /θ/ (thirty), a buzz for /ð/ (together). Celebrating \"thankful\" and \"together\" is a nice way to end the program's pronunciation journey.","id":"g6u6s1","track":"g6/u6/s1/track.mp3"},{"kind":"speak","n":2,"title":"Today I'm Going to Talk About...","func":"Giving a short presentation","func_ar":"تقديم عرض قصير","kagan":["Carousel Feedback","Timed Pair Share"],"model":[{"sp":"YUSUF","name":"Yusuf","text":"Good morning, everyone. Today, I'm going to talk about the Taif Rose Festival.","audio":"g6/u6/s2/01.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"First, let me tell you when it happens. The festival takes place every spring, usually in April, when the roses bloom.","audio":"g6/u6/s2/02.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"Next, I'll explain what visitors can do. They can visit rose farms, watch how rose water is made and buy rose products.","audio":"g6/u6/s2/03.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"There are also art shows and activities for children, like painting and making rose crafts.","audio":"g6/u6/s2/04.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"Finally, why is it important? The festival helps local farmers, and it shows the world that Taif is the City of Roses.","audio":"g6/u6/s2/05.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"To sum up, the Taif Rose Festival is a beautiful celebration of nature and tradition. Thank you for listening. Do you have any questions?","audio":"g6/u6/s2/06.mp3"},{"sp":"SAMI","name":"Sami","text":"Yes. How many roses does Taif produce?","audio":"g6/u6/s2/07.mp3"},{"sp":"YUSUF","name":"Yusuf","text":"Hundreds of millions every year! That's why you can smell roses everywhere in April.","audio":"g6/u6/s2/08.mp3"}],"roles":["YUSUF","SAMI"],"chunks":[{"en":"Today, I'm going to talk about ___.","ar":"","audio":"g6/u6/s2/c1.mp3"},{"en":"First, let me tell you ___.","ar":"","audio":"g6/u6/s2/c2.mp3"},{"en":"Next, I'll explain ___.","ar":"","audio":"g6/u6/s2/c3.mp3"},{"en":"Finally, ___.","ar":"","audio":"g6/u6/s2/c4.mp3"},{"en":"To sum up, ___.","ar":"","audio":"g6/u6/s2/c5.mp3"}],"sound":{"type":"sort","title":"How many words?","cats":[{"key":"5","label":"5 words"},{"key":"6","label":"6 words"},{"key":"7","label":"7 words"}],"en":"In presentations, speak in chunks and pause between them. Listen and count the words in each chunk.","ar":"في العروض التقديمية تحدّث على شكل مجموعات كلمات وتوقّف بينها. استمع وعدّ الكلمات في كل مجموعة.","items":[{"text":"Let me start with history.","key":"5","audio":"g6/u6/s2/i1.mp3"},{"text":"I'm going to talk about Eid.","key":"6","audio":"g6/u6/s2/i2.mp3"},{"text":"Today I'm going to talk about Eid.","key":"7","audio":"g6/u6/s2/i3.mp3"},{"text":"Thank you for listening today.","key":"5","audio":"g6/u6/s2/i4.mp3"},{"text":"Do you have any questions now?","key":"6","audio":"g6/u6/s2/i5.mp3"},{"text":"First of all, let me show you.","key":"7","audio":"g6/u6/s2/i6.mp3"},{"text":"It's a very special day.","key":"5","audio":"g6/u6/s2/i7.mp3"},{"text":"To sum up, it's a celebration.","key":"6","audio":"g6/u6/s2/i8.mp3"},{"text":"Families visit each other on that day.","key":"7","audio":"g6/u6/s2/i9.mp3"}]},"task":{"prompt":"Give a one-minute presentation about a celebration or festival. Use the five signpost phrases.","frame":"Today, I'm going to talk about ___. First, ___. Next, ___. Finally, ___. To sum up, ___."},"cando":["I can give a short, organized presentation.","I can use signpost phrases.","I can speak in clear chunks."],"teach":"This is the program's final speaking task. Record the presentations (with permission) and compare them with a recording from Grade 3 or the start of the year, so students can hear their progress.","id":"g6u6s2","track":"g6/u6/s2/track.mp3"}],"check":[{"type":"mcq","q":"What do many people wear on National Day?","ref":"L1#7","opts":["costumes","traditional clothes","sports clothes","school uniforms"],"ans":1,"audio":"g6/u6/l1/07.mp3","line":"Families go out together, there are fireworks in many cities, and there are air shows with jets in the sky. Many people also wear traditional clothes.","speaker":"Mr. Hassan"},{"type":"mcq","q":"Which country's food does Ben NOT mention?","ref":"L2#7","opts":["Morocco","India","Somalia","Pakistan"],"ans":1,"audio":"g6/u6/l2/07.mp3","line":"In London, Muslims come from many different countries, so Eid is very colorful! My family goes to a huge Eid prayer in a park. Then we visit friends and eat food from Pakistan, Somalia, Türkiye and Morocco. It's like a world festival!","speaker":"Ben"},{"type":"mcq","q":"What will the quiz be about?","ref":"L3#11","opts":["Eid","sports","science","their year at school"],"ans":3,"audio":"g6/u6/l3/11.mp3","line":"A quiz about our year, with prizes!","speaker":"Adam"},{"type":"mcq","q":"How many class photos has Yusuf taken?","ref":"L3#12","opts":["about twenty","fifty","a thousand","hundreds"],"ans":3,"audio":"g6/u6/l3/12.mp3","line":"And we could show a slideshow of our class photos. I've taken hundreds!","speaker":"Yusuf"}],"id":"g6u6"}],"level":"A2+","band":"Summit","speed":1.0}],"speakers":{"NARRATOR":"Narrator","SAMI":"Sami","NOOR":"Noor","BEN":"Ben","ADAM":"Adam","LINA":"Lina","YUSUF":"Yusuf","MR_HASSAN":"Mr. Hassan","MS_GREEN":"Ms. Green","MOM":"Mom","DAD":"Dad","GRANDPA":"Grandpa","MAN":"Man","WOMAN":"Woman","ANNOUNCER":"Announcer"}};
